-- translation-es-firered · diálogo FireRed
return {
  ["g3:08172255"] = "¡Vine aquí con unos amigos!\\p¡Van en busca de combates\nPOKéMON!",
  ["g3:081722c7"] = "¡Eh! ¡Tienes POKéMON!\n¡Sí!\\l¡Al ataque!",
  ["g3:081722f9"] = "¡No!\n¡Mi CATERPIE no pudo más!",
  ["g3:08172315"] = "¡Ssh!\n¡Vas a espantar a los bichos!...",
  ["g3:0817234a"] = "¡Eh!\n¡Hay que tener disciplina para ser\\lENTRENADOR POKéMON!",
  ["g3:0817237d"] = "¿Será posible?\n¡No me quedan más POKéMON!",
  ["g3:08172398"] = "¡Vaya!\n¡Voy a atrapar unos más fuertes!",
  ["g3:081723d4"] = "¡Eh, espera!\n¿Por qué tienes tanta prisa?",
  ["g3:08172402"] = "¡Me rindo!\n¡Eres demasiado fuerte!",
  ["g3:0817241f"] = "¡A veces puedes encontrar cosas\nen el suelo!\\p¡Estoy buscando los objetos\nque se me cayeron!",
  ["g3:08172482"] = "No soy especialmente grande, ¡pero\ntampoco soy ningún enclenque!",
  ["g3:081724bf"] = "Vaya, pues se ve que tampoco\nsoy demasiado fuerte...",
  ["g3:081724dc"] = "Así no hay forma de ahorrar...",
  ["g3:081724f9"] = "¿Sabes que los POKéMON\nevolucionan?",
  ["g3:0817251b"] = "¡Oh! ¡He perdido!",
  ["g3:08172527"] = "Los POKéMON evolucionan\nmuy rápido. ¡Son geniales!",
  ["g3:08172559"] = "¡Me quedé sin POKé BALLS con\nlas que atrapar a los POKéMON!\\p¡Deberías llevar algunas extra!",
  ["g3:081725c7"] = "PISTAS ENTRENADOR\\pSi quieres evitar los combates,\n¡aléjate de las zonas de hierba!",
  ["g3:08172629"] = "¡Usa ANTÍDOTO contra el veneno!\n¡Lo conseguirás en las TIENDAS\\lPOKéMON!",
  ["g3:0817265c"] = "PISTAS ENTRENADOR\\p¡Para evaluar tu POKéDEX, llama\nal PROF. OAK vía PC!",
  ["g3:081726a3"] = "PISTAS ENTRENADOR\\p¡No robes los POKéMON de otros\nENTRENADORES!\\p¡Captura sólo POKéMON salvajes\ncon las POKé BALLS!",
  ["g3:0817271d"] = "PISTAS ENTRENADOR\\p¡Debilita a los POKéMON antes\nde intentar capturarlos!\\p¡Si están fuertes, podrían escapar!",
  ["g3:08172773"] = "SALIENDO DEL BOSQUE VERDE,\nSE ENCUENTRA CIUDAD PLATEADA",
  ["g3:0817279d"] = "¡GUAU!\n¡Me has impresionado!\\l¡Pero si eres muy joven!",
  ["g3:081727cb"] = "¡Uau!\n¡Has vuelto a impresionarme!",
  ["g3:081727df"] = "¡No tienes edad para estar aquí!",
  ["g3:0817281d"] = "¿Estás aquí para explorar?",
  ["g3:08172844"] = "¡Perder es lo peor!",
  ["g3:08172863"] = "¡Vine aquí para impresionar\na las chicas!",
  ["g3:08172896"] = "¡Uau! ¡Esto es mucho más grande\nde lo que creía!",
  ["g3:081728c3"] = "¡Oh!\n¡He perdido!",
  ["g3:081728d2"] = "¿Cómo se sale de aquí?",
  ["g3:0817290b"] = "¡Eh!\n¡No te pases conmigo!",
  ["g3:08172927"] = "¡Mis POKéMON no lo han conseguido!",
  ["g3:0817293c"] = "¡Debo encontrar POKéMON\nmás fuertes!",
  ["g3:08172972"] = "¿Qué?\nEstoy esperando aquí a mis amigos.",
  ["g3:081729a4"] = "¿He perdido?",
  ["g3:081729ac"] = "Dicen que aquí hay unos fósiles\nmuy raros.",
  ["g3:081729ea"] = "En la cueva hay unos hombres\nmuy sospechosos. ¿Y tú, qué?",
  ["g3:08172a1a"] = "¡Me has ganado!",
  ["g3:08172a26"] = "¡Los he visto!\n¡Son del TEAM ROCKET! ¡Seguro!",
  ["g3:08172a55"] = "¡Cruza esta cueva y llegarás\na CIUDAD CELESTE!",
  ["g3:08172a8f"] = "He perdido.",
  ["g3:08172a97"] = "¡ZUBAT es muy fuerte!\n¡Atrapar uno sería muy útil!",
  ["g3:08172ae0"] = "¡Cuidado!\n¡Los ZUBAT son unos chupasangre!",
  ["g3:08172b00"] = "Estoy buscando fósiles en las\nentrañas del MT. MOON.\\pA veces me ayuda BROCK,\ndel GIMNASIO de PLATEADA.",
  ["g3:08172b64"] = "¡No toques nada!\\p¡Yo encontré estos fósiles!\n¡Son míos!",
  ["g3:08172b99"] = "¡De acuerdo!\n¡Los compartiré!",
  ["g3:08172bab"] = "¡Uno para cada!\n¡No hay que ser avaricioso!",
  ["g3:08172bd6"] = "Muy bien.\n¡Pues éste es el mío!",
  ["g3:08172bfb"] = "Muy lejos, en ISLA CANELA, hay\nun LABORATORIO de POKéMON.\\pEn él estudian cómo regenerar\nlos fósiles de POKéMON.",
  ["g3:08172c5a"] = "El TEAM ROCKET encontrará\nlos fósiles, los revivirá ¡y los\\lvenderá!",
  ["g3:08172cb8"] = "¡Argh!\n¡Eres lo peor!",
  ["g3:08172ccb"] = "¡Eres un fastidio! ¡El TEAM ROCKET\nte pondrá en la lista negra!",
  ["g3:08172cfc"] = "¡Nosotros, el TEAM ROCKET,\nsomos los bandidos POKéMON!",
  ["g3:08172d46"] = "¡Lo he hecho fatal!",
  ["g3:08172d51"] = "¿Será posible?\n¡Mis compañeros me vengarán!",
  ["g3:08172d82"] = "¡Nuestro trabajo aquí es muy\nimportante! ¡Lárgate, enclenque!",
  ["g3:08172daf"] = "Pues eres muy fuerte...",
  ["g3:08172dc1"] = "Si encuentras un fósil, ¡dámelo\ny lárgate!",
  ["g3:08172df0"] = "¡Los niños no deberían molestar\na los adultos!",
  ["g3:08172e3e"] = "¡Estoy muy enfadado!",
  ["g3:08172e4b"] = "Los POKéMON vivían aquí mucho\nantes de que llegara la gente.",
  ["g3:08172e77"] = "¿Quieres el FÓSIL DOMO?",
  ["g3:08172e94"] = "¿Quieres el FÓSIL HELIX?",
  ["g3:08172eb2"] = "¡Obtuviste el FÓSIL HELIX!",
  ["g3:08172ecd"] = "¡Obtuviste el FÓSIL DOMO!",
  ["g3:08172ee7"] = "¡Bonjour!\n¡Soy el camarero de este barco!\\p¡Encantado de servirte en todo\nlo que quieras!\\pTienes cara de ser una persona\nfuerte y discreta.",
  ["g3:08172f60"] = "¡Los pasajeros se están\nimpacientando!\\p¡Los que están más aburridos\npodrían retarte!",
  ["g3:08172fc3"] = "¡Este lujoso barco es para\nlos ENTRENADORES!\\p¡En cada puerto celebramos\nuna fiesta para los ENTRENADORES!",
  ["g3:08173035"] = "{RIVAL}:\n¡Bonjour, {PLAYER}!\\p¡Ya sabía yo que te vería por\naquí! ¿{PLAYER}, te han invitado?\\p¿Y qué tal va tu POKéDEX?\\p¡Yo ya tengo 40 POKéMON!\n¡Están por todas partes!\\p¡Adéntrate en las zonas de hierba\nalta!",
  ["g3:08173110"] = "¡Vaya!\\p¡Parece que has entrenado bien\na tus POKéMON!",
  ["g3:08173164"] = "{RIVAL}: Decían que había un\nmaestro del CORTE a bordo.\\p¡Pero sólo era un viejo mareado!\\p¡Sin embargo, la técnica del CORTE\nes muy útil!\\p¡Deberías ir a verle!\n¡Hasta luego!",
  ["g3:0817320c"] = "¡Nuestro CAPITÁN es un maestro\nde la esgrima!\\p¡Dicen que enseña a los POKéMON\nla técnica del CORTE!",
  ["g3:0817326f"] = "¡Se acabó la fiesta!\n¡El barco zarpará pronto!",
  ["g3:081732a2"] = "¡Limpiar las cubiertas es\nun trabajo duro!",
  ["g3:081732c6"] = "¡Uff! Me siento fatal...\\pHe salido a tomar el aire.",
  ["g3:08173308"] = "¡Eh, colega!\\p¡Bailemos una jota!",
  ["g3:0817332b"] = "¡Eres impresionante!",
  ["g3:0817333e"] = "¿Cuántos tipos de POKéMON crees\nque hay?",
  ["g3:08173382"] = "¡Eh, hola!\n¿Tienes mareo?",
  ["g3:081733a0"] = "¡No he estado muy atento!",
  ["g3:081733b5"] = "Mi papá decía que hay 100 tipos\nde POKéMON. Pero yo creo que\\lhay más.",
  ["g3:081733f8"] = "¡Hola, peque!\n¡Ahora estamos ocupados!\\l¡Fuera de aquí!",
  ["g3:08173429"] = "He visto una BAYA muy rara en la\nbasura. No sé de qué tipo será...",
  ["g3:08173462"] = "¡Estoy tan ocupado que me estoy\nmareando!",
  ["g3:081734a0"] = "¿Por qué? ¿Por qué yo?\\p¡Me paso todo el día pelando\npatatas!",
  ["g3:081734d3"] = "¿Has oído hablar de SNORLAX?\\p¡Se pasa todo el día comiendo\ny durmiendo!",
  ["g3:0817353e"] = "Sniff...sniff...\\pYo sólo pelo cebollas...\nSniff...",
  ["g3:08173570"] = "¡Ejem!\n¡Por algo soy el CHEF!\\pEl menú es:",
  ["g3:0817359f"] = "¡Ensalada de salmón!\\p¡Pero puede que los clientes se\nquejen de tanto repetir pescado!",
  ["g3:081735df"] = "¡Anguilas a la barbacoa!\\p¡Me temo que los clientes se van\na amotinar!",
  ["g3:08173611"] = "¡Filetes de ternera!\\pPero ¡¿tengo bastantes filetes\npara todos?!",
  ["g3:08173646"] = "CAPITÁN: ¡Puajj!\nMe siento fatal.\\lMe he mareado...",
  ["g3:08173676"] = "¡{PLAYER} le dio un masaje\nal CAPITÁN!\\p(Scratch)...\n(Scratch)...",
  ["g3:081736a6"] = "CAPITÁN: ¡Uff! ¡Gracias!\nYa me siento mucho mejor...\\p¿Quieres ver mi técnica de CORTAR?\\pTe la mostraría si no estuviera\ntan mareado.\\p¡Ya sé!\n¡Toma esto!\\p¡Enséñasela a tu POKéMON\ny en breve estará CORTANDO!",
  ["g3:081737af"] = "¡{PLAYER} obtuvo la MO01\nde manos del CAPITÁN!",
  ["g3:081737d2"] = "Al usar CORTE, se pueden talar\nárboles pequeños.\\pA lo mejor deberías probarlo con\nlos árboles de CIUDAD CARMÍN.",
  ["g3:08173831"] = "CAPITÁN: ¡Bien!\\p¡Ahora que ya no estoy mareado,\ncreo que deberíamos irnos!\\p¡El S.S. ANNE zarpará pronto!\\p¡Adiós, hasta que volvamos\na CIUDAD CARMÍN!",
  ["g3:081738e6"] = "¡Puaj!\n¡No debería haber mirado!",
  ["g3:08173903"] = "Cómo combatir el mareo...\n¡El CAPITÁN está leyendo esto!",
  ["g3:0817393b"] = "¡Ssh! ¡Soy agente de POLICÍA!\\p¡Estoy siguiendo la pista del\nTEAM ROCKET!",
  ["g3:08173999"] = "¡Me gustan los POKéMON!\n¿Y a ti?",
  ["g3:081739b1"] = "¡Guauu!\n¡Eres genial!",
  ["g3:081739c5"] = "Seamos amigos, ¿vale?\\p¡Y así podremos intercambiar\nPOKéMON!",
  ["g3:08173a1a"] = "¡He atrapado POKéMON por todo\nel mundo!",
  ["g3:08173a4f"] = "¡Vaya!\n¡Con lo que he viajado por ellos!",
  ["g3:08173a7a"] = "¡Les has hecho daño a mis pobres\nPOKéMON!\\p¡¡¡Y exijo que los cures en un\nCENTRO POKéMON!!!",
  ["g3:08173ac5"] = "¡Viajamos en crucero por todo\nel mundo!",
  ["g3:08173afa"] = "¡Los cruceros son tan elegantes\ny acogedores!",
  ["g3:08173b21"] = "¡Siempre viajo con WIGGLYTUFF!",
  ["g3:08173b61"] = "WIGGLYTUFF: ¡Wig, tuuuf, tuuuf!",
  ["g3:08173b79"] = "¡Camarero, me gustaría tomar\nun trozo de tarta de cereza!",
  ["g3:08173ba4"] = "¡Camarera, me gustaría tomar\nun trozo de tarta de cereza!",
  ["g3:08173bd1"] = "¡Oye, tú, impertinente!\n¿Cómo te atreves a entrar aquí?",
  ["g3:08173bfa"] = "¡Oye!\n¡¡No tienes educación!!",
  ["g3:08173c30"] = "¡Me gustaría que me dejaras solo!\n¡¡Fuera de aquí!!",
  ["g3:08173c52"] = "¡Viajo solo!\\p¡Mis POKéMON son mis únicos amigos!",
  ["g3:08173cb4"] = "¡Oh! ¡Mis amigos!",
  ["g3:08173cc4"] = "¡Deberías portarte bien con\nlos amigos!",
  ["g3:08173ce3"] = "¡Durante todos mis viajes jamás\nhabía visto a un POKéMON que\\ldurmiera tanto!\\p¡Era algo así!...",
  ["g3:08173d63"] = "¡Competir contra los jóvenes\nme mantiene como un chaval!",
  ["g3:08173d92"] = "¡Buena pelea!\n¡Vuelvo a sentirme joven!",
  ["g3:08173db6"] = "¡Hace 15 años, yo habría ganado!",
  ["g3:08173ddb"] = "¡Mira lo que he pescado!",
  ["g3:08173df7"] = "¡Estoy acabado!",
  ["g3:08173e04"] = "¿Una fiesta?\\pLa fiesta del crucero debe de\nhaber terminado.",
  ["g3:08173e3a"] = "¡Ah, sí! ¡Vi a unos POKéMON\ntransportando a gente por el agua!",
  ["g3:08173e7b"] = "Los POKéMON pueden CORTAR\npequeños arbustos.\\pPero ten en cuenta que CORTE\nes una técnica de MO.\\pUna vez aprendida, cuesta mucho\nolvidarla.",
  ["g3:08173f07"] = "¿Qué prefieres, un POKéMON fuerte\no uno raro?",
  ["g3:08173f42"] = "¡Debo felicitarte!",
  ["g3:08173f55"] = "¡Prefiero los POKéMON fuertes\ny raros!",
  ["g3:08173f83"] = "No te he visto en la fiesta.",
  ["g3:08173fab"] = "¡Oye!\n¡¡¡No había que ponerse así!!!",
  ["g3:08173fb9"] = "¡Oh!\n¡Adoro a tus fuertes POKéMON!",
  ["g3:08173ff7"] = "¿Has ido a la ZONA del SAFARI\nen CIUDAD FUCSIA?\\p¡Había muchos tipos raros\nde POKéMON!",
  ["g3:0817404f"] = "¡Mi padre y yo pensamos que\nla ZONA del SAFARI es genial!",
  ["g3:081740a1"] = "¡El CAPITÁN parecía muy mareado\ny pálido!",
  ["g3:081740d6"] = "¡Dicen que hay mucha gente que\nse marea!",
  ["g3:081740f6"] = "¡Como pierdas, caminarás\npor el tablón!",
  ["g3:08174123"] = "¡Argh! ¡Derrotado por alguien\nmás joven que yo!",
  ["g3:0817413a"] = "A veces, algunas medusas caen\ndentro del barco.",
  ["g3:08174177"] = "¡Eh, tú!\\p¡No sé si eres de tierra o mar, \npero para y habla conmigo!\\p¡Todos mis POKéMON vienen del mar!",
  ["g3:081741ef"] = "¡Vaya!\n¡He dejado que te escaparas!",
  ["g3:0817420e"] = "¡Yo también te iba a hacer\nmi ayudante!",
  ["g3:08174239"] = "¡Los marineros también tenemos\nPOKéMON!",
  ["g3:0817425c"] = "¡Eres bastante fuerte!",
  ["g3:08174272"] = "¡Pescamos a todos nuestros POKéMON\nen alta mar!",
  ["g3:081742a6"] = "¡Me gusta la gente activa como tú!",
  ["g3:081742c3"] = "¡Argh!\n¡He perdido!",
  ["g3:081742d2"] = "Los POKéMON del mar viven en las\nprofundidades.\\l¡Necesitarás una CAÑA!",
  ["g3:08174315"] = "¡Ya sabes lo que dicen sobre\nlos marineros y las peleas!",
  ["g3:08174348"] = "¡Has peleado muy bien, sí, sí!",
  ["g3:08174362"] = "¡Ajá!\n¿Quieres unirte a los marineros?",
  ["g3:08174385"] = "¡Está en juego mi fama de\nmarinero!",
  ["g3:081743b3"] = "¡Menuda paliza!",
  ["g3:081743c8"] = "¿Viste al GURÚ de los PESCADORES\nen CIUDAD CARMÍN?",
  ["g3:081743f8"] = "¡Mi amigo, MACHOKE,\nes superfuerte!\\p¡Tiene tanta FUERZA que puede\nmover hasta grandes rocas!",
  ["g3:08174444"] = "MACHOKE: ¡Cho! ¡Chokecho!",
  ["g3:0817445b"] = "¡Tienes una cara de agotamiento!\n¿Quieres descansar un ratito?",
  ["g3:08174490"] = "¡Eso ya es otra cosa! ¡Me encanta\nver a todo el mundo descansado!",
  ["g3:081744d0"] = "Bueno, yo lo decía por tu bien.\nEs que me recuerdas a mi hermano\\lpequeño...",
  ["g3:08174515"] = "Bueno, yo lo decía por tu bien.\nEs que me recuerdas a mi hermana\\lpequeña...",
  ["g3:08174559"] = "La gente suele perder cosas\nen esta VÍA SUBTERRÁNEA.",
  ["g3:0817459b"] = "Dicen que hay un POKéMON durmiendo\ncerca de CIUDAD AZULONA.",
  ["g3:081745d9"] = "¡El CENTRO COMERCIAL de AZULONA\ntiene muchas cosas!",
  ["g3:0817462c"] = "Fui al TÚNEL ROCA, pero\nestá oscuro y me da miedo.\\p¡Si el DESTELLO de un POKéMON\npudiera alumbrarlo...!",
  ["g3:081746a7"] = "¡Vaya sorpresa! ¡Los DIGLETT\ncavaron este largo túnel!\\p¡Va a CIUDAD VERDE!",
  ["g3:08174710"] = "¡Me pregunto si eres lo bastante\nfuerte para mí!",
  ["g3:08174738"] = "¡He perdido!",
  ["g3:08174744"] = "¡A mí no me gusta perder, y mucho\nmenos contra alguien tan joven!",
  ["g3:08174784"] = "¡Ya veo que eres fuerte!\n¡Veamos exactamente cuánto!",
  ["g3:081747b8"] = "He perdido la oportunidad...",
  ["g3:081747c8"] = "¡Lo admito, eres mejor que yo!",
  ["g3:081747ef"] = "¡Si puedes pasar por aquí, podrás\nenfrentarte al ALTO MANDO!",
  ["g3:0817482c"] = "¡No!\n¡Increíble!",
  ["g3:0817483e"] = "¡Puedo vencerte en cuanto a\nconocimientos sobre los POKéMON!",
  ["g3:08174877"] = "¡La CALLE VICTORIA es la prueba\nfinal de todo ENTRENADOR!",
  ["g3:081748b4"] = "¡Ayyyy!",
  ["g3:081748bb"] = "¡Prueba a mover las rocas\nsi tienes el paso cortado!",
  ["g3:081748ee"] = "¡Ah!\n¿Quieres desafiar al ALTO MANDO?",
  ["g3:0817491b"] = "¡Me has ganado!",
  ["g3:08174927"] = "¡{RIVAL} también vino por aquí!",
  ["g3:08174942"] = "¡Adelante!\n¡Te daré una paliza!",
  ["g3:0817495a"] = "¡Me has machacado!",
  ["g3:08174969"] = "¡Ahora puedes recorrer la CALLE\nVICTORIA!",
  ["g3:08174995"] = "¿Es muy dura la CALLE VICTORIA?",
  ["g3:081749b0"] = "¡Bien hecho!",
  ["g3:081749bb"] = "¡Muchos de los ENTRENADORES\nse rinden aquí!",
  ["g3:081749f9"] = "Has conseguido abrirte paso por\nla CALLE VICTORIA con mucho\\lvalor; es para alegrarse.\\pComo reconocimiento a tu hazaña,\nte enseñaré DOBLE FILO.\\p¿Quieres?",
  ["g3:08174abc"] = "Bueno, otra vez será.",
  ["g3:08174ae2"] = "¿A qué POKéMON quieres que\nle enseñe DOBLE FILO?",
  ["g3:08174b0c"] = "¡No bajes la guardia para la LIGA\nPOKéMON!\\p¡A por ella, acaba con todos!",
  ["g3:08174b60"] = "¡Los rumores hablan de un\nENTRENADOR espectacular!",
  ["g3:08174b83"] = "¡Los rumores eran ciertos!",
  ["g3:08174b99"] = "¿Derrotaste a GIOVANNI\ndel TEAM ROCKET?",
  ["g3:08174bca"] = "¡Los ENTRENADORES sólo viven para\nbuscar enemigos más fuertes!",
  ["g3:08174bf4"] = "¡Oooooh!\n¡Eres tan fuerte!",
  ["g3:08174c03"] = "¡Librar duros combates te hará\nmás fuerte!",
  ["g3:08174c30"] = "¡Te demostraré lo fuerte que eres\nde verdad!",
  ["g3:08174c5a"] = "¡Argh! ¡Eres increíble!",
  ["g3:08174c67"] = "¡Yo soy la que ha aprendido\nla lección!",
  ["g3:08174c8a"] = "¡Aquí sólo pueden pasar\nlos elegidos!",
  ["g3:08174ca9"] = "¡No me lo puedo creer!",
  ["g3:08174cbd"] = "¡Todos estos ENTRENADORES van a\nparticipar en la LIGA POKéMON!\\p¡Ten cuidado!",
  ["g3:08174d0c"] = "DESI: ¡Juntos lucharemos contra\nquien sea!",
  ["g3:08174d45"] = "DESI: ¡No me lo puedo creer!",
  ["g3:08174d64"] = "DESI: ¡Has acabado con nosotros!",
  ["g3:08174d96"] = "DESI: Acabaríamos contigo\nen un abrir y cerrar de ojos.\\pPara luchar con nosotros, hay\nque tener dos POKéMON.",
  ["g3:08174e08"] = "TULA: ¡Tenemos intención de\nconvertirnos en campeones!",
  ["g3:08174e39"] = "TULA: Eh..., en fin...",
  ["g3:08174e48"] = "TULA: De ti he aprendido la\nverdadera dimensión de la fuerza.",
  ["g3:08174e8d"] = "TULA: No podrás con nosotros\nsi no tienes dos POKéMON.",
  ["g3:08174eca"] = "¿Quién eres tú?\n¿Y cómo has llegado aquí?",
  ["g3:08174eed"] = "¡Auuu!\n¡He perdido!",
  ["g3:08174efa"] = "¿Vas a luchar contra el TEAM\nROCKET?",
  ["g3:08174f2c"] = "¡Has destrozado nuestros planes!",
  ["g3:08174f60"] = "¡Chamuscado!",
  ["g3:08174f66"] = "¡No te vas a salir con la tuya,\nimpresentable!",
  ["g3:08174f94"] = "¡Alerta! ¡Nos invaden!",
  ["g3:08174fa4"] = "¡¡¡No lo he conseguido!!!",
  ["g3:08174fb3"] = "¿El SCOPE SILPH?\n¡No sé dónde está!",
  ["g3:08174fe1"] = "¿Por qué has venido aquí?",
  ["g3:08174ff8"] = "¡Esto no funcionará!",
  ["g3:08175007"] = "¡Vale, hablaré! ¡Toma el ascensor\npara ver a mi JEFE!",
  ["g3:0817503a"] = "¿Te has perdido? Pobre...",
  ["g3:0817505a"] = "¿Por qué...?",
  ["g3:08175060"] = "¡Con tanto lío se ha abierto\nla puerta!",
  ["g3:0817508c"] = "¡El JEFE dijo que se pueden ver\nfantasmas con el SCOPE SILPH!",
  ["g3:081750bf"] = "¡Me rindo!",
  ["g3:081750cc"] = "El CG del TEAM ROCKET tiene\n4 sótanos.\\p¿Podrás llegar al JEFE?",
  ["g3:0817511a"] = "¡Deja de meterte en los asuntos\ndel TEAM ROCKET!",
  ["g3:0817514a"] = "¡Uff!\n¡Me ha machacado!",
  ["g3:0817515b"] = "¿El SCOPE SILPH?\nAh, la máquina que robó el JEFE.\\pDebe de estar por aquí.",
  ["g3:0817519e"] = "¡Nos dijeron desde arriba que\nvenías!",
  ["g3:081751ce"] = "¿Qué?\n¿He perdido? ¡NO!",
  ["g3:081751e0"] = "¡Venga, adelante!\\p¡Pero necesitarás la LLAVE\ndel ASCENSOR!",
  ["g3:08175226"] = "¡Mmm! ¡Estoy muy impresionado\nde que hayas llegado hasta aquí!\\p¡El TEAM ROCKET necesita los\nPOKéMON para financiar sus\\lmalvados planes!\\p¡Yo soy GIOVANNI, su líder!\\p¡Y te las vas a tener que ver\nconmigo, metomentodo!",
  ["g3:08175318"] = "¿QUÉ?\n¡Esto es imposible!",
  ["g3:0817532d"] = "Ya veo que has entrenado a tus\nPOKéMON con mucho cuidado.\\p¡Pero jamás entenderías\ncuáles son mis planes!\\p¡En esta ocasión te dejaré pasar!\\pEspero que nos volvamos a ver.",
  ["g3:081753d0"] = "¡Te conozco! ¡Tú arruinaste\nnuestros planes en MT. MOON!",
  ["g3:081753fe"] = "¡Me han vuelto a machacar!",
  ["g3:0817540c"] = "¿Tienes algo en contra del TEAM\nROCKET?",
  ["g3:08175437"] = "¿Acaso no ves la belleza de\nnuestros actos malvados?",
  ["g3:08175463"] = "¡Ayayay!",
  ["g3:0817546a"] = "¡JEFE!\n¡Siento haberle fallado!",
  ["g3:08175488"] = "¿No funciona el ascensor? ¿Quién\ntiene la LLAVE del ASCENSOR?",
  ["g3:081754b9"] = "¡No!",
  ["g3:081754bd"] = "¡Oh, no! ¡He perdido la LLAVE\ndel ASCENSOR!",
  ["g3:081754dd"] = "Parece que hace falta una llave.",
  ["g3:081754f7"] = "¡Hola!\\p¡El PRESIDENTE está en la sala\nde reuniones del P10!",
  ["g3:08175549"] = "OFICINA CENTRAL DE SILPH S.A.\nPB",
  ["g3:08175562"] = "¡Socorro!\n¡Soy un empleado de SILPH S.A.!",
  ["g3:0817557e"] = "¿Cómo sabías que yo era un\nROCKET?",
  ["g3:0817559f"] = "¡Trabajo para SILPH S.A. y para\nel TEAM ROCKET!",
  ["g3:081755c6"] = "¡Estás en zona prohibida!\n¡Vuelve a casa!",
  ["g3:081755e5"] = "¡Eres genial!",
  ["g3:081755f2"] = "¿Puedes resolver este laberinto?",
  ["g3:0817562d"] = "¡Aquí no pueden entrar los niños!",
  ["g3:0817564a"] = "¡Muy fuerte!",
  ["g3:08175651"] = "¡Las baldosas con forma\nde diamante son puntos\\lde teletransporte!\\p¡Son medios de transporte\nde alta tecnología!",
  ["g3:081756ad"] = "¡Oye, tú!\n¿Qué haces aquí?",
  ["g3:081756d8"] = "¡He metido la pata!",
  ["g3:081756e2"] = "¡SILPH S.A. va a fusionarse\ncon el TEAM ROCKET!",
  ["g3:08175711"] = "¡Socorro!\n¡No! ¡Alto!\\p¿No perteneces al TEAM ROCKET?\nYo pensaba...\\pLo siento...\nEh... ¿te enseño ONDA TRUENO?",
  ["g3:0817579d"] = "Eh...\nONDA TRUENO es muy útil...",
  ["g3:081757c1"] = "¿A qué POKéMON quieres que\nle enseñe ONDA TRUENO?",
  ["g3:081757ec"] = "ONDA TRUENO puede paralizar\nal POKéMON que sufre el ataque.\\pY cuando un POKéMON está\nparalizado en combate es posible\\lque no se mueva.\\pEs un ataque del tipo ELÉCTRICO,\nasí que no funcionará contra\\lalgunos POKéMON.",
  ["g3:08175894"] = "OFICINA CENTRAL DE SILPH S.A.\nP1",
  ["g3:081758ad"] = "Trabajo para SILPH S.A.\n¿Qué debería hacer?",
  ["g3:081758d3"] = "¡{PLAYER}! ¡Tú y tus POKéMON\nnos habéis salvado!",
  ["g3:081758f6"] = "¡Eh, no nos molestes más!",
  ["g3:08175911"] = "¡Me rindo!",
  ["g3:0817591c"] = "¿Una pista? ¡Para abrir las puertas\nutiliza una LLAVE MAGNÉTICA!",
  ["g3:08175948"] = "¡¡¡Apoyo más al TEAM ROCKET\nque a SILPH S.A.!!!",
  ["g3:0817597d"] = "¡Me has derrotado!",
  ["g3:08175990"] = "Mmmm...\\p¡El TEAM ROCKET me dijo que si\nles ayudaba, me dejarían estudiar\\la los POKéMON!",
  ["g3:081759dc"] = "OFICINA CENTRAL DE SILPH S.A.\nP2",
  ["g3:081759f5"] = "¡Sssh! ¿Acaso no ves que me estoy\nescondiendo?",
  ["g3:08175a15"] = "¿Eh?\n¿Que el TEAM ROCKET se ha ido?",
  ["g3:08175a2f"] = "¡El TEAM ROCKET se ha apoderado\nde SILPH S.A.!",
  ["g3:08175a5b"] = "¡Arrgh!",
  ["g3:08175a62"] = "¡Ja, ja, ja!\n¡Mi JEFE buscaba este lugar!",
  ["g3:08175a90"] = "¡Mi POKéMON es mi fiel defensor!",
  ["g3:08175ab0"] = "¡Has debilitado a mi POKéMON!",
  ["g3:08175ac8"] = "¡Las puertas están cerradas\nelectrónicamente!\\p¡Las abre una LLAVE MAGNÉTICA!",
  ["g3:08175b19"] = "¡Nos invaden!",
  ["g3:08175b2b"] = "¿Quién eres tú?",
  ["g3:08175b38"] = "¡Será mejor que se lo diga\nal JEFE del décimo piso!",
  ["g3:08175b57"] = "OFICINA CENTRAL DE SILPH S.A.\nP3",
  ["g3:08175b70"] = "El TEAM ROCKET está buscando\na un intruso.\\pTe buscan a ti, ¿no?",
  ["g3:08175bb3"] = "¡El TEAM ROCKET se ha ido!\n¡Gracias! ¡Eres nuestra salvación!",
  ["g3:08175be5"] = "Dicen que se ha colado alguien...",
  ["g3:08175c09"] = "¡Chamuscado!",
  ["g3:08175c0f"] = "¡No es que sea muy inteligente\nprovocar al TEAM ROCKET!",
  ["g3:08175c40"] = "¡En este piso estudiamos la\ntecnología de las POKé BALL!",
  ["g3:08175c6d"] = "¡Uff!\n¡Vaya!",
  ["g3:08175c7d"] = "¡Trabajamos en una nueva POKé\nBALL capaz de atraparlo todo!",
  ["g3:08175cbd"] = "¿Qué?\\p¡Aquí no debería haber niños!",
  ["g3:08175ceb"] = "¿Cómo me pasa esto a mí?",
  ["g3:08175cf9"] = "¡Sólo has llegado al P4!\n¡Mi JEFE aún está muy lejos!",
  ["g3:08175d28"] = "¡Respeta un poco al TEAM ROCKET!",
  ["g3:08175d4b"] = "(Tos)...\n(Tos)...",
  ["g3:08175d59"] = "Eso me recuerda que...\\p¡KOFFING evoluciona y se\ntransforma en WEEZING!",
  ["g3:08175d89"] = "¡Un INFORME sobre los POKéMON!\\pPORYGON, el primer POKéMON\nvirtual, se creó en el LABORATORIO\\lPOKéMON.",
  ["g3:08175de0"] = "¡Un INFORME sobre los POKéMON!\\p¡Confirmadas más de 350 técnicas\nPOKéMON!",
  ["g3:08175e28"] = "¡Un INFORME sobre los POKéMON!\\pSe ha confirmado que algunos\nPOKéMON evolucionan cuando\\lse realiza un intercambio.",
  ["g3:08175e80"] = "OFICINA CENTRAL DE SILPH S.A.\nP4",
  ["g3:08175e99"] = "Los tipejos esos que se apoderaron\nde nuestro edificio...\\pSu JEFE dijo que estaba buscando\nPOKéMON fuertes.\\pEspero que nuestro PRESIDENTE\nse haya ocupado del tema...",
  ["g3:08175f24"] = "¡Los ROCKET vinieron y se\napoderaron de todo el edificio!",
  ["g3:08175f51"] = "¡Más vale que vuelva al trabajo!",
  ["g3:08175f70"] = "¡Oh, por favor!\n¡Ayúdame!",
  ["g3:08175f93"] = "¡Somos novios!\n¡Jaja!",
  ["g3:08175faa"] = "¡Míralo!\n¡Es tan cobarde!",
  ["g3:08175fd3"] = "¡Me daba tanta pena, que decidí\nocuparme de él!",
  ["g3:08176012"] = "¡El TEAM ROCKET quiere conquistar\nel mundo con sus POKéMON!",
  ["g3:0817604b"] = "¡El TEAM ROCKET se escapó\npor tu culpa!",
  ["g3:0817607e"] = "Deben de haber elegido SILPH\npor nuestros productos POKéMON.",
  ["g3:081760b6"] = "¡Ven a trabajar para SILPH cuando\nseas mayor!",
  ["g3:081760de"] = "¡Soy uno de los 4 HERMANOS\nROCKET!",
  ["g3:08176104"] = "¡Qué paliza!",
  ["g3:0817610f"] = "¡No importa!\n¡Mis hermanos me vengarán!",
  ["g3:08176136"] = "No puedo con el PRESIDENTE...\\p¡No debía haberme enviado a la\nSUCURSAL TIKSI!\\p¡Seguro que el TEAM ROCKET\nnos habría dejado en paz!",
  ["g3:081761bd"] = "¡Estoy acabado!",
  ["g3:081761c4"] = "¿La SUCURSAL TIKSI?\n¡Está en medio de la nada!",
  ["g3:081761f1"] = "¿Te atreves a traicionar al TEAM\nROCKET?",
  ["g3:0817620e"] = "¡Debería darte vergüenza!",
  ["g3:0817621b"] = "¡Si apoyas la justicia, traicionarás\nal malvado!",
  ["g3:0817624d"] = "OFICINA CENTRAL DE SILPH S.A.\nP5",
  ["g3:08176266"] = "¡Hola! ¡Tú no eres de los ROCKET!\n¿Has venido a salvarnos?\\l¡Pues gracias!\\pVoy a darte este POKéMON\npor habernos salvado.",
  ["g3:081762d7"] = "¡{PLAYER} obtuvo un LAPRAS\ndel empleado de SILPH S.A.!",
  ["g3:08176305"] = "Es un LAPRAS.\nEs muy inteligente.\\pLo teníamos en el laboratorio,\npero estará mucho mejor contigo.\\pSeguro que lo entrenarás muy bien.\\pEs muy buen nadador.\n¡Podría llevarte incluso!",
  ["g3:081763dd"] = "¡El JEFE del TEAM ROCKET fue\na la sala del consejo!\\p¿Está bien el PRESIDENTE?",
  ["g3:08176444"] = "¡El TEAM ROCKET buscaba la MASTER\nBALL para poder atrapar cualquier\\ltipo de POKéMON!",
  ["g3:08176486"] = "Cancelamos el proyecto de la\nMASTER BALL por culpa del \\lTEAM ROCKET.",
  ["g3:081764c2"] = "¡Sería horrible que el TEAM\nROCKET se hiciera con SILPH S.A.\\lo con nuestros POKéMON!",
  ["g3:08176501"] = "¡Uauu!\\p¿Echaste tú al TEAM ROCKET?",
  ["g3:08176532"] = "¡Oye!\n¡Este lugar es muy peligroso!\\p¿Has venido a salvarme?\n¡Pues no puedes!",
  ["g3:08176573"] = "¡Por fin a salvo! ¡Muchas gracias!",
  ["g3:08176586"] = "¡Oh, oh!\n¿Qué tenemos por aquí?",
  ["g3:081765a5"] = "¡Luces fuera!",
  ["g3:081765b1"] = "¡No encontrarás a mi JEFE con sólo\nmerodear por ahí!",
  ["g3:081765e2"] = "¡Ejem!\\p¿Me confundiste con un empleado\nde SILPH?",
  ["g3:0817660c"] = "¡Estoy acabado!",
  ["g3:08176616"] = "¡A pesar de tu edad, eres genial\nentrenando POKéMON!",
  ["g3:08176643"] = "¡Soy uno de los 4 HERMANOS\nROCKET!",
  ["g3:08176669"] = "¡Auch!\n¡Hermanos, he perdido!",
  ["g3:08176681"] = "No importa. ¡Mis hermanos\nte devolverán el favor!",
  ["g3:081766b3"] = "¿Que nos invaden?\n¿No serás tú?",
  ["g3:081766d7"] = "¡Vale!\n¡He perdido!",
  ["g3:081766e5"] = "¡Vete a casa antes de que\nse enfade mi JEFE!",
  ["g3:08176710"] = "{RIVAL}: ¿Qué te retrasó,\n{PLAYER}?",
  ["g3:08176727"] = "{RIVAL}: ¡Jaja! ¡Sabía que\naparecerías si esperaba aquí!\\p¡Supongo que el TEAM ROCKET\nte retrasó!\\l¡Aunque no es que me importe!\\p¡Te vi en CIUDAD AZAFRÁN, y\ndecidí esperar a ver si mejorabas!",
  ["g3:081767d0"] = "¡Ajá! Así que ya estás para\nluchar contra el JEFE ROCKET...",
  ["g3:08176827"] = "¡Bien, {PLAYER}!\n¡Sigo mejorando y avanzando!\\p¡Consultando mi POKéDEX puedo\nsaber cuáles son los más fuertes\\ly cómo evolucionan!\\p¡Voy a la LIGA POKéMON para\nderrotar al ALTO MANDO!\\p¡Voy a ser el mejor ENTRENADOR\ndel mundo!\\p¡{PLAYER}, que tengas suerte!\n¡No te des demasiada paliza!\\l¡Hasta luego!",
  ["g3:08176954"] = "OFICINA CENTRAL DE SILPH S.A.\nP6",
  ["g3:0817696d"] = "Me pregunto si SILPH estará\nacabada.",
  ["g3:0817698c"] = "¡Gracias por salvarnos!",
  ["g3:081769a2"] = "¡No podrás ir más lejos!",
  ["g3:081769be"] = "¡No eres tan valiente!",
  ["g3:081769cf"] = "¡Si no retrocedes, pediré\nrefuerzos!",
  ["g3:081769fd"] = "¡Nos estás dando muchos problemas!",
  ["g3:08176a19"] = "¿Qué?\n¿He perdido?",
  ["g3:08176a26"] = "¿Qué opinas del laberinto del\nEDIFICIO SILPH?",
  ["g3:08176a56"] = "¡Soy uno de los 4 HERMANOS\nROCKET!",
  ["g3:08176a7c"] = "¡Ahhhg!\n¡Hermanos! ¡Tenéis que vengarme!",
  ["g3:08176a90"] = "¡Mis hermanos se encargarán de ti!",
  ["g3:08176ab2"] = "OFICINA CENTRAL DE SILPH S.A.\nP7",
  ["g3:08176acb"] = "¡El JEFE del TEAM ROCKET es muy\ncruel!\\pSólo quiere a los POKéMON para\nluchar.\\pNo quiero ni pensar lo que podría\nocurrir si se hiciera con el mando\\lde la compañía...",
  ["g3:08176b54"] = "¡Tienes cara de cansancio!\n¡Deberías echarte una siestecita!",
  ["g3:08176b81"] = "¡No te rindas!",
  ["g3:08176b90"] = "¡Muchísimas gracias!",
  ["g3:08176ba3"] = "¡Tus POKéMON parecen adorarte!",
  ["g3:08176bc8"] = "¡Buaah!",
  ["g3:08176bd0"] = "Si yo hubiera empezado como\nENTRENADOR a tu edad...",
  ["g3:08176bfb"] = "¡Tus POKéMON tienen puntos\ndébiles! ¡Yo puedo verlos!",
  ["g3:08176c2b"] = "¡Me has machacado!",
  ["g3:08176c3c"] = "¡Aprovechar sus puntos débiles\nfunciona! ¡Piensa en los tipos!",
  ["g3:08176c7a"] = "¡Soy uno de los 4 HERMANOS\nROCKET!",
  ["g3:08176ca0"] = "¡Hermanos!\n¡He perdido!",
  ["g3:08176cb8"] = "¡Mis hermanos me vengarán!",
  ["g3:08176cd4"] = "OFICINA CENTRAL DE SILPH S.A.\nP8",
  ["g3:08176ced"] = "¡Hola, éste es el noveno piso!\n¡Me alegra que hayas venido!",
  ["g3:08176d18"] = "¡Estoy aturdido!",
  ["g3:08176d25"] = "¡Bien hecho, pero la sala del\nconsejo está un piso más arriba!",
  ["g3:08176d57"] = "¡Ya está bien de tonterías!",
  ["g3:08176d73"] = "¡Se acabó lo que se daba!",
  ["g3:08176d86"] = "¿Te alegra haberme ganado?\n¡Pues vete a casa!",
  ["g3:08176dba"] = "¡Buaaaa!\n¡Tengo miedo!",
  ["g3:08176dce"] = "¡Por favor, no le digas a nadie\nque he llorado!",
  ["g3:08176df8"] = "OFICINA CENTRAL DE SILPH S.A.\nP9",
  ["g3:08176e12"] = "PRESIDENTE: ¡Gracias por salvar\na SILPH!\\p¡Jamás olvidaré que nos salvaste\nen este peligroso momento!\\p¡Me gustaría agradecértelo\nde alguna forma!\\p¡Yo puedo darte muchas cosas!\\p¡Toma, puede que te interese!",
  ["g3:08176ee7"] = "PRESIDENTE: ¡Gracias por salvar\na SILPH!\\p¡Jamás olvidaré que nos salvaste\nen este peligroso momento!\\p¡Me gustaría agradecértelo\nde alguna forma!\\p¡Yo puedo darte muchas cosas!\\p¡Toma, puede que te interese!",
  ["g3:08176fbd"] = "¡{PLAYER} recibió una MASTER\nBALL del PRESIDENTE!",
  ["g3:08176feb"] = "PRESIDENTE: ¡No puedes comprarla\nen ningún sitio!\\p¡Es nuestro prototipo secreto\nde la MASTER BALL!\\p¡Puede atrapar a cualquier tipo\nde POKéMON!\\pPero mejor que no se lo digas\na nadie.",
  ["g3:0817708e"] = "No tienes sitio para esto.",
  ["g3:081770a9"] = "SECRETARIA: ¡Gracias por\nsalvarnos!\\pTodos los que trabajamos para el\nPRESIDENTE admiramos tu valor.",
  ["g3:08177108"] = "¡Hola, {PLAYER}!\n¡Volvemos a encontrarnos!\\p¡El PRESIDENTE y yo estamos\nhablando de algo muy importante!\\p¡No te metas en los asuntos\nde los mayores!\\p¡O sufrirás mi ira!",
  ["g3:081771ab"] = "¡¡Arr!!\n¿¡He vuelto a perder!?",
  ["g3:081771c2"] = "¡Qué mal! ¡Arruinaste nuestros\nplanes con respecto a SILPH!\\p¡Pero el TEAM ROCKET no caerá\njamás!\\p¡{PLAYER}, no olvides jamás que\ntodos los POKéMON son para\\lel TEAM ROCKET!\\p¡Ahora debo irme, pero volveré!",
  ["g3:0817726a"] = "¡Alto ahí!\n¡No te muevas!",
  ["g3:0817728c"] = "No...\n¡Por favor!",
  ["g3:0817729b"] = "¿¡Qué!?\n¿Quieres ver a mi JEFE?",
  ["g3:081772b8"] = "¡Alto!\n¿Tienes una cita con mi JEFE?",
  ["g3:081772e7"] = "¡Auch!\n¡Me han derribado!",
  ["g3:081772f9"] = "Ten cuidado, ¡Los POKéMON\nde mi JEFE son terribles!",
  ["g3:0817734a"] = "OFICINA CENTRAL DE SILPH S.A.\nP10",
  ["g3:08177364"] = "¿Y tú quién eres?\nAquí no debería haber nadie.",
  ["g3:08177391"] = "¡Auh!",
  ["g3:08177397"] = "¿Una llave? ¡Ni idea de lo que me\nestás hablando!",
  ["g3:081773c6"] = "¡Aaaaaaaaaah! ¡Qué susto!\n¡Pensaba que eras un fantasma!",
  ["g3:081773fd"] = "¡Uf, no hay forma de que gane!",
  ["g3:08177418"] = "Yo estaba aquí tranquilamente\ncurioseando un poco, pero creo\\lque voy a irme.\\pTengo un poco de miedo.",
  ["g3:08177460"] = "Un botón secreto.\\p¿Lo pulso?",
  ["g3:0817747b"] = "¿Y quién no lo haría?",
  ["g3:08177489"] = "¡Todavía no!",
  ["g3:08177498"] = "¡No sé salir! ¡Este viejo lugar\nes un enorme laberinto!",
  ["g3:081774cb"] = "¡Oh, no!\n¡Mi botín!",
  ["g3:081774e3"] = "¡Los botones abren y cierran\nalternativamente los grupos\\lde puertas!",
  ["g3:0817751f"] = "Diario: 5 de julio.\nGuyana, Suramérica.\\pUn nuevo tipo de POKéMON fue\ndescubierto en el interior de la\\lselva.",
  ["g3:08177574"] = "Diario: 10 de julio.\nHemos llamado a este nuevo\\lPOKéMON, MEW.",
  ["g3:081775e7"] = "Este lugar es...\n¡Gigantesco!",
  ["g3:08177602"] = "¡Ayah!",
  ["g3:08177608"] = "Me pregunto adónde habrá ido\nmi compañero.",
  ["g3:08177628"] = "Mi maestro vivió aquí hace tiempo.",
  ["g3:08177643"] = "¡Uau!\n¡Impresionante!",
  ["g3:08177657"] = "¿No sabes por dónde ir?\n¡Tírate por ahí!",
  ["g3:08177685"] = "Diario: 6 de febrero.\nMEW dio a luz.\\pLlamamos al pequeño: MEWTWO.",
  ["g3:081776c0"] = "¡Oh, oh!\n¿Dónde estoy ahora?",
  ["g3:081776d7"] = "¡Vaya!",
  ["g3:081776de"] = "Puedes recoger cosas del suelo.",
  ["g3:08177720"] = "Este lugar es ideal para un\nlaboratorio.",
  ["g3:08177757"] = "¿Era esto lo que querías?",
  ["g3:0817776a"] = "¡Me encanta este sitio! ¡Es muy\napropiado para mis estudios!",
  ["g3:08177798"] = "Diario: 1 de septiembre.\nMEWTWO es demasiado poderoso.\\pNo hemos sabido contener sus malos\ninstintos.",
  ["g3:081777f2"] = "CASA DE REPOSO",
  ["g3:081777fd"] = "PISTAS ENTRENADOR\\p¡Pulsa START para saber cuánto\ntiempo te queda!",
  ["g3:0817782f"] = "ZONA CENTRAL",
  ["g3:0817783b"] = "CASA DE REPOSO",
  ["g3:08177846"] = "PISTAS ENTRENADOR\\p¡El tiempo restante sólo se verá\nreducido cuando camines!",
  ["g3:08177884"] = "ZONA 1\nOESTE: ZONA CENTRAL",
  ["g3:0817789d"] = "CASA DE REPOSO",
  ["g3:081778a8"] = "PISTAS ENTRENADOR\\p¡La CASA SECRETA sigue estando\njusto delante!",
  ["g3:081778d6"] = "ZONA 2",
  ["g3:081778dd"] = "PISTAS ENTRENADOR\\p¡Los POKéMON se ocultan entre la\nalta hierba!\\pZigzaguea por zonas de hierba para\nque salgan.",
  ["g3:08177935"] = "PISTAS ENTRENADOR\\p¡Encuentra la CASA SECRETA\ny ganarás una MO!",
  ["g3:0817796e"] = "CASA DE REPOSO",
  ["g3:08177979"] = "AVISO\\pEncuentra los DIENTES de ORO\nperdidos del GUARDA del SAFARI.\\lEstán por aquí.\\p¡Se ofrece recompensa!\nContactar con el GUARDA.",
  ["g3:081779f8"] = "PISTAS ENTRENADOR\\p¡Operación Exploración de la zona!\n¡La búsqueda de la CASA SECRETA!",
  ["g3:08177a41"] = "ZONA 3\nESTE: ZONA CENTRAL",
  ["g3:08177a5a"] = "SARA: ¿Adónde fue mi amigo\nENRIQUE?",
  ["g3:08177a82"] = "¡Estoy atrapando POKéMON para\nllevarlos a casa como regalos!",
  ["g3:08177aae"] = "¿Cuántos has capturado? ¡Yo estoy\nagotado de tanto trabajar!",
  ["g3:08177ae2"] = "¡Capturé un CHANSEY!\\p¡Y por eso todos mis esfuerzos\nhan merecido la pena!",
  ["g3:08177b16"] = "¡Ufff!\n¡Estoy agotado de tanta diversión!",
  ["g3:08177b38"] = "Puedes quedarte con cualquier\nobjeto encontrado en esta zona.\\p¡Pero te quedarás sin tiempo si\nintentas coger todos a la vez!",
  ["g3:08177bab"] = "Dirígete al ZONA más profunda del\nSAFARI. ¡Ganarás un premio!",
  ["g3:08177bec"] = "¡Mi EEVEE evolucionó y\nse transformó en un FLAREON!\\p¡Pero el EEVEE de un amigo se\ntransformó en un VAPOREON!\\l¿Por qué?",
  ["g3:08177c47"] = "La ZONA del SAFARI es gigante,\n¿no te parece?\\pEl LÍDER del GIMNASIO de FUCSIA,\nKOGA, viene con mucha frecuencia\\lpor esta zona.\\pGracias a él, podemos jugar aquí\nsin miedo.",
  ["g3:08177ceb"] = "Tirar PIEDRAS a los POKéMON\npodría hacerles huir, pero hará\\lque sean más fáciles de atrapar.",
  ["g3:08177d39"] = "Utilizar CEBO te permitirá atrapar\nmás fácilmente a los POKéMON.",
  ["g3:08177d8b"] = "Caminé mucho, pero no he visto\na los POKéMON que quería.",
  ["g3:08177dc1"] = "¡Ah! ¡Por fin!\\p¡Eres la primera persona que llega\na la CASA SECRETA!\\pHe organizado un concurso con\nmotivo de nuestra inauguración.\\pY estaba empezando a preocuparme\nque nadie ganara nuestro premio.\\p¡Enhorabuena!\n¡Has ganado!",
  ["g3:08177e92"] = "¡{PLAYER} recibió una MO03\ndel empleado!",
  ["g3:08177eb7"] = "¡La MO03 es SURF!\\p¡Un POKéMON podrá llevarte\npor el agua!\\p¡Y esta MO puede ser utilizada\nuna y otra vez!\\p¡Tienes muchísima suerte!\n¡Te llevas un fabuloso premio!",
  ["g3:08177f72"] = "¡No tienes sitio para este premio\ntan fabuloso!",
  ["g3:08177f9f"] = "¡Mew!",
  ["g3:08178191"] = "¡Esto no debería ser así!...",
  ["g3:081781b0"] = "¡Eres mejor de lo que yo pensaba!\n¡Adelante!\\p¡Pero la LIGA POKéMON te reserva\notras sorpresas!",
  ["g3:08178409"] = "¿Qué?\n¿Cómo he podido perder?",
  ["g3:08178420"] = "¡Yo ya he hecho mi trabajo!\n¡Te espera tu próximo desafío!",
  ["g3:081786d7"] = "¡Oh, oh!\n¡Eres bastante especial!",
  ["g3:08178700"] = "¡Tú ganas!\\p¡Ya sé por qué ese viejo\ninútil te aprecia tanto!\\p¡No tengo nada más que decir!\n¡Vete ya!",
  ["g3:08178a15"] = "¡Pues sí!\\p¡Odio admitirlo, pero eres una\npasada con los POKéMON!",
  ["g3:08178a52"] = "¡{PLAYER}, sigo sin poder creerme\nque mis dragones hayan sucumbido\\la tus ataques!\\p¡Has ganado la LIGA POKéMON!\\pBueno, casi, porque te espera\notro desafío.\\p¡Deberás luchar contra otro\nENTRENADOR! Su nombre es...\\p¡{RIVAL}!\\p¡Él derrotó al ALTO MANDO antes\nque tú!\\p¡Es el auténtico campeón de la\nLIGA POKéMON!",
  ["g3:08178b6c"] = "{RIVAL}: ¡Hola!\\p¡Estaba deseando verte, {PLAYER}!\\p¡Mi rival debería ser fuerte para\npoder mantenerme en forma!\\p¡Utilizando mi POKéDEX, he buscado\nlos POKéMON más fuertes!\\p¡Y he creado varios equipos que\nderrotarían a cualquier tipo de\\lPOKéMON!\\p¡Y ahora!\\p¡Yo soy el campeón de la LIGA\nPOKéMON!\\p¡{PLAYER}!\n¿Sabes lo que significa eso?\\p¡Te lo diré!\\p¡Yo soy el mejor ENTRENADOR\ndel mundo!",
  ["g3:08178cd4"] = "{RIVAL}: ¡Hola!\\p¡Aquí estás de nuevo, {PLAYER}!\\p¡Mi rival debería ser fuerte para\npoder mantenerme en forma!\\p¡Utilizando mi POKéDEX, he buscado\nlos POKéMON más fuertes!\\p¡Y he creado varios equipos que\nderrotarían a cualquier tipo de\\lPOKéMON!\\p¡Y ahora!\\p¡Yo soy el campeón de la LIGA\nPOKéMON!\\p¡{PLAYER}!\n¿Sabes lo que significa eso?\\p¡Te lo diré!\\p¡Yo soy el mejor ENTRENADOR\ndel mundo!",
  ["g3:08178e3f"] = "¡NO!\n¡Eso es imposible!\\l¡Me has derrotado!\\p¡Tras tantos esfuerzos por\nconvertirme en campeón de LIGA!\\p¿Se ha terminado ya mi reinado?\n¡No es justo!",
  ["g3:08178f2f"] = "¿Qué?\n¿Cómo he podido perder?\\pHe entrenado a mis POKéMON\na la perfección.\\p¡No puedo soportar que hayas\nganado la LIGA POKéMON!\\pAunque no me guste admitirlo.",
  ["g3:08178fc6"] = "OAK: ¡{PLAYER}!",
  ["g3:08178fcf"] = "OAK: ¡Has ganado!\n¡Enhorabuena!\\p¡Has ganado la LIGA POKéMON!\\p¡Has crecido tanto desde que\nte fuiste con {STR_VAR_1} para\\lcompletar tu POKéDEX!\\p¡{PLAYER}, ya eres mayor!",
  ["g3:0817908f"] = "OAK: ¡{RIVAL}!\n¡Estoy desolado!\\p¡Vine en cuanto supe que habías\nderrotado al ALTO MANDO!\\p¡Pero cuando llegué aquí, ya\nte habían vencido!\\p¡{RIVAL}!\n¿Entiendes por qué has perdido?\\p¡Olvidaste tratar a tus POKéMON\ncon cariño y confianza!\\p¡Y sin ellos, jamás volverás\na ganar!",
  ["g3:081791a3"] = "OAK: ¡{PLAYER}!\\p¡Sabes que tu victoria no fue\ndebida sólo a ti!\\p¡El vínculo que mantienes con\ntus POKéMON es maravilloso!\\p¡{PLAYER}!\n¡Ven conmigo!",
  ["g3:0817922f"] = "OAK: ¡Ejem!\n¡Enhorabuena, {PLAYER}!\\p¡En este piso está el HALL de la\nFAMA de los POKéMON!\\p¡Aquí son homenajeados por sus\nhazañas los campeones de la LIGA\\lPOKéMON!\\p¡Sus POKéMON también son\nregistrados en el HALL de la FAMA!\\p¡{PLAYER}!\\p¡Has luchado muchísimo para\nganar la LIGA!\\p¡Enhorabuena, {PLAYER}, tú y tus\nPOKéMON ya sois famosos!",
  ["g3:08179366"] = "¡Este oscuro túnel recorre\nun largo camino!",
  ["g3:08179388"] = "¡Uauu!\n¡Tú ganas!",
  ["g3:08179396"] = "Cuidado con ONIX.\n¡Podría apretarte las tuercas!",
  ["g3:081793f1"] = "Mmm.\nPuede que me haya perdido...",
  ["g3:0817940e"] = "A ver, con calma. \n¿Qué hago?\\l¿Por dónde salgo?",
  ["g3:0817943a"] = "Ese POKéMON dormido de la RUTA 12\nme obligó a desviarme.",
  ["g3:0817947b"] = "¡La gente de fuera como tú\ndebería respetarme!",
  ["g3:081794ac"] = "¡Me rindo!",
  ["g3:081794b4"] = "¡Tienes madera para escalar!",
  ["g3:081794d4"] = "¡Lucha POKéMON!\n¿Empezamos? ¡Pues venga!",
  ["g3:081794ee"] = "¡Se acabó!",
  ["g3:081794f9"] = "¡Conseguiré un ZUBAT por el\ncamino!",
  ["g3:0817951c"] = "¡Oye!\\p¡No hagas tonterías en la\noscuridad!",
  ["g3:08179547"] = "¡Estaba demasiado oscuro!",
  ["g3:08179558"] = "¡Vi a un MACHOP en este túnel!",
  ["g3:08179577"] = "¡Vine hasta aquí por los POKéMON!",
  ["g3:081795a1"] = "¡Me he quedado sin POKéMON!",
  ["g3:081795b5"] = "¡No parecía que tuvieras ni la\nmás mínima agresividad!",
  ["g3:081795e5"] = "¡Tienes POKéMON!\n¡Empecemos!",
  ["g3:08179604"] = "¡No te andas con tonterías!",
  ["g3:08179613"] = "¡Ufff!\n¡Estoy sudando!",
  ["g3:0817962d"] = "TÚNEL ROCA:\nCIUDAD CELESTE - PUEBLO LAVANDA",
  ["g3:08179657"] = "Los montañeros marcan el camino\ncon ramitas.\\pEs la mejor forma de no perderse.",
  ["g3:081796b9"] = "¡Ohhh!\n¡He hecho todo lo posible!",
  ["g3:081796ce"] = "¡Quiero volver a mi casa!",
  ["g3:081796e1"] = "¡Ja, ja, ja!\n¿Crees que puedes ganarme?",
  ["g3:08179700"] = "¡Vaya!\nQué ridículo...",
  ["g3:08179712"] = "¡Prefiero la fuerza, porque no\nme gusta pensar!",
  ["g3:0817973a"] = "¿Tienes una POKéDEX?\n¡Yo también quiero una!",
  ["g3:0817975f"] = "¡Brgg!\n¡Me das tanta envidia!",
  ["g3:08179777"] = "Cuando termines con tu POKéDEX\n¿me la dejarás?",
  ["g3:081797a4"] = "¿Qué sabes de esos jugadores\ndisfrazados?",
  ["g3:081797cb"] = "Pues eso es todo.",
  ["g3:081797de"] = "No hay nada como disfrazarse\nde POKéMON para divertirse.\\pEl mejor es CLEFAIRY.",
  ["g3:08179829"] = "¡Mis técnicas de POKéMON te harán\nllorar!",
  ["g3:08179856"] = "¡Me rindo!\n¡Tus técnicas son mejores!",
  ["g3:0817987a"] = "En las montañas suele haber\nPOKéMON del tipo ROCA.",
  ["g3:081798ad"] = "¡No suelo venir por aquí, pero\nlucharé contigo!",
  ["g3:081798dd"] = "¡Oh! ¡He perdido!",
  ["g3:081798e9"] = "¡Me gustan los POKéMON pequeños!\n¡Los grandes son horribles!",
  ["g3:08179916"] = "¡Lánzame tu mejor ataque!",
  ["g3:08179932"] = "¡Vamos, adelante!",
  ["g3:0817993e"] = "¡Criaré a mis POKéMON para que\nvenzan a los tuyos!",
  ["g3:08179968"] = "Cuando estoy en casa, dibujo a los\nPOKéMON.",
  ["g3:08179997"] = "¡Uf!\n¡Estoy agotado!",
  ["g3:081799ac"] = "Soy un artista, no un guerrero.",
  ["g3:081799e0"] = "En montañas como ésta, hay peligro\nde desprendimientos.\\pImagínate qué horror que empiecen\na caerte rocas encima.\\p¡Aaaaaaaaaaaaaaah!\nUn horror, vamos.\\p¿No te da miedo?\n¿Quieres aprender AVALANCHA?",
  ["g3:08179ac0"] = "Te da miedo, no lo niegues.",
  ["g3:08179ae1"] = "¿A qué POKéMON quieres que\nle enseñe AVALANCHA?",
  ["g3:08179b0a"] = "Yo no lo usaría en un túnel...",
  ["g3:08179b36"] = "¡Las ROCAS pueden cambiar\nel flujo del agua!",
  ["g3:08179b65"] = "¡PELIGRO!\n¡Rápidos!",
  ["g3:08179b7a"] = "La TORRE POKéMON fue erigida\nen memoria de los POKéMON\\lque se han debilitado.",
  ["g3:08179bb8"] = "¿Has venido a rendirles homenaje?\\p¡Qué majo!",
  ["g3:08179bfc"] = "¿Has venido a rendirles homenaje?\\p¡Qué maja!",
  ["g3:08179c41"] = "Vine a rendir homenaje\na mi CLEFAIRY.\\p¡Sniff!\nNo puedo dejar de llorar...",
  ["g3:08179c8c"] = "Mi GROWLITHE... ¿Por qué\nhas tenido que debilitarte?",
  ["g3:08179cab"] = "¡Soy EXORCISTA!\\p¡Hay espíritus muy revoltosos\nen esta TORRE!",
  ["g3:08179cff"] = "{RIVAL}: ¡Oye, {PLAYER}!\n¿Qué haces por aquí?\\l¿Están tus POKéMON debilitados?\\p¡Menos mal!\\p¡Pero yo puedo conseguir que\nse debiliten! ¡Vamos!",
  ["g3:08179d73"] = "¿Qué?\n¡Cómo eres!\\p¡Y te había tomado en serio!",
  ["g3:08179dd4"] = "¿Qué tal va tu POKéDEX?\n¡Acabo de capturar un CUBONE!\\p¡Todavía no he encontrado al\nMAROWAK adulto!\\p¡No creo que quede ninguno!\\p¡Creo que me voy a marchar!\n¡Me queda mucho por hacer!\\p¡Hasta luego!",
  ["g3:08179eae"] = "¡Ni siquiera pudimos identificar\na los GHOST!\\pEl SCOPE SILPH podría\ndesenmascararlos.",
  ["g3:08179f09"] = "Urrg... aaa...\nUuuu... graa...",
  ["g3:08179f21"] = "¡Uauu!\n¡Estoy salvada!",
  ["g3:08179f31"] = "Los GHOST son identificados con\nel SCOPE SILPH.",
  ["g3:08179f62"] = "Gaaaa...\n¡Gaaah!",
  ["g3:08179f72"] = "¿Mmm?\n¿Pero qué hago?",
  ["g3:08179f88"] = "¡Perdona!\n¡Estaba fuera de mí!",
  ["g3:08179fa0"] = "¡Fuera, espíritu malvado!",
  ["g3:08179fbc"] = "¡El espíritu se fue!",
  ["g3:08179fd3"] = "¡Mis amigos también estaban\nfuera de sí!",
  ["g3:0817a004"] = "¡Un GHOST!\n¡No! ¡Guaaah!",
  ["g3:0817a017"] = "¿Dónde está GHOST?",
  ["g3:0817a02b"] = "Debo de haberlo soñado...",
  ["g3:0817a046"] = "¡Te vas a enterar!\n¡Guaaah!",
  ["g3:0817a061"] = "¿Qué?",
  ["g3:0817a067"] = "¡No podemos desvelar la identidad\nde los GHOST!",
  ["g3:0817a096"] = "Uuuuuu...\n¡Vencerme no, tú a mí!",
  ["g3:0817a0ab"] = "¿Eh?\n¿Quién? ¿Qué?",
  ["g3:0817a0bb"] = "¡Que descansen los POKéMON\ndebilitados!",
  ["g3:0817a0e3"] = "¡Ven, ven! ¡Sellé este lugar\ncon magia blanca!\\l¡Aquí puedes descansar!",
  ["g3:0817a11f"] = "Dame...\ntu... esencia...",
  ["g3:0817a132"] = "¿Uh?",
  ["g3:0817a138"] = "¡Estaba fuera de mí!",
  ["g3:0817a150"] = "Ven... con...\nnosotros...",
  ["g3:0817a164"] = "¡Vaya pesadilla!",
  ["g3:0817a176"] = "¡Estaba fuera de mí!",
  ["g3:0817a187"] = "¡Zombis!",
  ["g3:0817a190"] = "¿Ja?",
  ["g3:0817a194"] = "¡He recuperado la razón!",
  ["g3:0817a1aa"] = "¡Oooo!...\n¡Uuuu!...",
  ["g3:0817a1b7"] = "¡Uuuu!",
  ["g3:0817a1bd"] = "¡A pesar de mi entrenamiento\nme atraparon los espíritus!",
  ["g3:0817a1fa"] = "¡Has entrado en una zona de pureza\ny seguridad!\\p¡Los POKéMON de {PLAYER} están\ncurados!",
  ["g3:0817a243"] = "Da... me...\ntu... ser...",
  ["g3:0817a253"] = "¡Grrr!",
  ["g3:0817a25a"] = "Me siento anémica y débil...",
  ["g3:0817a272"] = "Uuff...\n¡Guaa!",
  ["g3:0817a27f"] = "¡Algo se ha caído!",
  ["g3:0817a293"] = "¡No me lo creo!\n¡Era un malvado espíritu!",
  ["g3:0817a2c8"] = "¡¡¡Ki...ki...\nki...ki...ki!!!",
  ["g3:0817a2dc"] = "¡Kiii!",
  ["g3:0817a2e2"] = "¿Qué está pasando aquí?",
  ["g3:0817a2f8"] = "Fuera...\nIntrusos...",
  ["g3:0817a30c"] = "¡Ese GHOST era el inquieto\nespíritu de la madre de CUBONE!",
  ["g3:0817a342"] = "El espíritu de la madre descansa\ntranquilo.\\p¡Y ha partido al más allá!",
  ["g3:0817a380"] = "¿Qué quieres?\n¿Qué haces aquí?",
  ["g3:0817a3a4"] = "¡Me rindo!",
  ["g3:0817a3af"] = "¡Voy a olvidar todo esto!",
  ["g3:0817a3cd"] = "El tipo, que ya tiene unos años,\nse plantó en nuestra GUARIDA.\\pY empezó a decir que estábamos\nhaciendo daño a los POKéMON.\\p¡La cosa es más que seria!",
  ["g3:0817a466"] = "¡Por favor!\n¡Basta!",
  ["g3:0817a477"] = "¡Los POKéMON sólo sirven para\nganar dinero!\\p¡No te metas en nuestros asuntos!",
  ["g3:0817a4cf"] = "¡No vas a salvar a nadie!",
  ["g3:0817a4ee"] = "¡No luches contra nosotros,\nel TEAM ROCKET!",
  ["g3:0817a506"] = "¡No te saldrás con la tuya así\ncomo así!",
  ["g3:0817a529"] = "SR. FUJI: ¿Qué?\n¿Has venido a salvarme?\\p¡Gracias! Pero estoy aquí por mi\npropia voluntad.\\pVine a calmar el espíritu de la\nmadre de CUBONE.\\pCreo que el espíritu de MAROWAK\nya está tranquilo.\\p¡Agradezco tu interés!\\pAcompáñame a mi casa, a la CASA\nPOKéMON, que hay al pie de esta\\ltorre.",
  ["g3:0817a642"] = "¿Te imaginas que este volcán\nentrara en erupción?\\pSería nuestro fin. ¡Qué horror!\\pA todo esto, ¿quieres aprender\nEXPLOSIÓN?",
  ["g3:0817a6ed"] = "Te entiendo, sólo oír el nombre\npone los pelos de punta.",
  ["g3:0817a717"] = "¡Sí, señor!\\p¿A qué POKéMON quieres que\nle enseñe EXPLOSIÓN?",
  ["g3:0817a756"] = "Imagínate lo que tiene que ser\nusar EXPLOSIÓN en este volcán...\\p¡Lo pienso y no sé lo que me\nentra!",
  ["g3:0817a82a"] = "Aquí, aquí.\nVamos a intentar cavar aquí.\\pYo creo que el tesoro del que\nhablaban los ADMINISTRADORES\\lestá aquí.",
  ["g3:0817a88c"] = "Pero...\n¿Te quieres quitar de aquí?",
  ["g3:0817a8b4"] = "¡Por fin lo hemos conseguido!\n¡A por el tesoro!",
  ["g3:0817a8ee"] = "Cosa que encontremos, cosa que\nllevamos al ALMACÉN, ¿eh?\\pEh... ¿y cuáles eran las\ncontraseñas?\\lMe refiero a las del ALMACÉN...",
  ["g3:0817a970"] = "¿No te acuerdas de la contraseña?\nBueno, en realidad son dos.\\pLa primera es “ARON ama\na NORA”.\\pY la segunda...",
  ["g3:0817a9e1"] = "¡Eh, que por aquí se están\nquedando con la copla! ¡Cotilla!",
  ["g3:0817aa06"] = "Has estado espiándonos, ¿eh?",
  ["g3:0817aa34"] = "¿Qué ha pasado?",
  ["g3:0817aa3f"] = "¿Por qué me has ganado?",
  ["g3:0817aa56"] = "¿Te crees que vas a pillar cacho\nde nuestro tesoro? ¡Ni lo sueñes!",
  ["g3:0817aa8a"] = "¡Ahora quien está soñando soy yo!",
  ["g3:0817aa99"] = "Hazme un favorcito, olvídate de lo\nque has oído, anda.",
  ["g3:0817aad7"] = "¡Menudo revés!...\n¡Vámonos con el resto!\\p¡Tú, no te atrevas a entrar!\\p¡Te lo digo por tu bien!\n¡Ni te lo plantees!",
  ["g3:0817ab73"] = "Se dice que un volcán está activo,\ncuando entra en erupción o está\\la punto.",
  ["g3:0817abaa"] = "Guau... ¡qué pasada!\n¡Me ha entrado un calor!",
  ["g3:0817abd8"] = "Dicen que hay unos 1.500 volcanes\nactivos en todo el mundo.\\pCada vez que lo pienso, ¡me entra\nuna cosa!",
  ["g3:0817ac55"] = "¿Sabes cómo se forman las cuevas\nen el interior de los volcanes?",
  ["g3:0817ac82"] = "¡Aaaah!\n¡Eres increíble!",
  ["g3:0817aca2"] = "Cuando la lava de la superficie se\nsolidifica, aún puede quedar magma\\lpor salir.\\pY son los conductos que abre\nen su camino al exterior, los que\\lpasan a ser las cuevas.",
  ["g3:0817ad06"] = "He estado entrenándome para\nrecuperar mi fuerza interior...\\p¡Y lo que sin duda he conseguido\nha sido ponerme en forma!",
  ["g3:0817ad6b"] = "Creo que he exagerado...",
  ["g3:0817ad89"] = "Luchando me recuerdas a mi antiguo\nnoviete...",
  ["g3:0817adc5"] = "¡{PLAYER} encontró un RUBÍ!",
  ["g3:0817add6"] = "PEDRITA: Buuuua... ¡BUAAAA!...\n¡Ayúdame, ayúdame!\\pPOKéMON ho-horrible...\nMmme he sustado ucho...\\pBuaaaaa... Sustado a PEDRITA...\\pTeno miedo...\nQuiedo id a casa...",
  ["g3:0817ae8e"] = "¡Ta ahí, ta ahí!\n¡Fuela, fuela! ¡Teno miedo!\\p¡Buaaaaaaaaa!\n¡Papiiiiiiiiii!",
  ["g3:0817aee1"] = "Aaaah... POKéMON malo...\n¡Acias!\\pPEDRITA quedía BAYAS.\\pToma, cara ti.",
  ["g3:0817af3b"] = "¿Quién ede?\\pPEDRITA sustada, lleva a casa\ncon papi a PEDRITA.\\p¡A casa con papi!\n¡Con papi!",
  ["g3:0817af9f"] = "El SACO de las BAYAS está lleno.",
  ["g3:0817afd6"] = "Éste es el BOSQUE BAYA.\\p¡Hay que compartir BAYAS\ncon la gente y los POKéMON!",
  ["g3:0817b029"] = "Atención:\nPresencia de POKéMON salvajes\\ldevoradores de BAYAS.",
  ["g3:0817b04f"] = "LORELEI: ¡Ni te acerques a los\nPOKéMON que hay en la cueva!\\pSi no, te las tendrás que ver\nconmigo.",
  ["g3:0817b0b9"] = "Venga ya, señora, no incordie.\\p¡Chicos, sigamos a lo nuestro!",
  ["g3:0817b109"] = "LORELEI: ¡¿{PLAYER}?!\n¿Qué haces aquí?\\pBueno, ya charlaremos después.\nAyúdame con estos elementos.\\pNecesito que me eches una mano\npara frenar a esta gentuza.\\pHan estado atrapando POKéMON\naquí, y vendiéndolos por ahí.\\p¿Vas a ayudarme?\n¡Pues adelante!",
  ["g3:0817b20b"] = "¿Perdón?\\p¿Quién dice aquí lo que podemos\no no podemos hacer con los\\lPOKéMON que atrapamos?",
  ["g3:0817b251"] = "¡No me esperaba yo esto!",
  ["g3:0817b269"] = "LORELEI: Ja.\nQué cosa más endeble...\\pA ver, tú.\nDime.\\p¿Dónde tenéis a los POKéMON\nque habéis capturado?\\pDímelo ahora mismo si no quieres\nque te dé una zurra.",
  ["g3:0817b2ef"] = "¡Ni en broma!\n¡No pienso decírtelo!",
  ["g3:0817b313"] = "LORELEI: Como no me lo digas,\n¡acabarás congelado!\\pMi LAPRAS está que trina por lo\nque les habéis hecho a sus amigos.\\p¡Venga, LAPRAS!\n¡RAYO HIELO!...",
  ["g3:0817b399"] = "¡Aaaaah!\n¡Para, para, que te lo digo!\\pLos POKéMON están en el ALMACÉN\nROCKET de ISLA INTA.\\p¡Hala, ya lo he dicho!\n¡Vámonos ya de aquí!\\p¡Pero que sepas que dudo mucho\nque puedas entrar en el ALMACÉN\\lROCKET!\\p¡Ja, ja, ja!",
  ["g3:0817b457"] = "{PLAYER}, gracias.\nHa sido horrible...\\pYo he nacido aquí y he pasado\ntoda mi vida en estas islas.\\pNo sabía que esos golfos\nestuvieran por aquí sueltos...",
  ["g3:0817b4e3"] = "Hay un montón de POKéMON\nencerrados en el cobertizo...",
  ["g3:0817b512"] = "La puerta está abierta.\nSe ve que los POKéMON han huido.",
  ["g3:0817b54d"] = "¿Has venido hasta aquí sabiendo\nque era el ALMACÉN ROCKET?",
  ["g3:0817b585"] = "Pero bueno, ¿tú qué te crees?",
  ["g3:0817b5a6"] = "¿Que si el TEAM ROCKET se ha\nseparado?\\lPero ¿tú de qué planeta vienes?",
  ["g3:0817b5d6"] = "Tus POKéMON parecen muy fuertes.\n¿No te gustaría venderlos?\\p¡Ah, que quieres luchar!",
  ["g3:0817b62f"] = "Ufff...\nHa sido mucha paliza...",
  ["g3:0817b642"] = "¡Oye, te podemos pagar mucho\npor tus POKéMON!",
  ["g3:0817b677"] = "Me han hablado mucho de ti.\\p¡Ante nuestro JEFE GIOVANNI\nno vas a poder hacer nada!",
  ["g3:0817b6d9"] = "No... te... rías... Grrr...",
  ["g3:0817b6ef"] = "¡No deberías meter las narices en\nlas cosas de los mayores, cotilla!",
  ["g3:0817b72d"] = "Ni sé ni me importa si lo que hago\nestá bien o no...\\pYo confío en GIOVANNI y cumplo\ncon lo que se me dice.",
  ["g3:0817b79c"] = "Es-estoy... sin aliento...",
  ["g3:0817b7ae"] = "Entiendo que lo que haces responde\na tus principios.\\pAhora lo entiendo.",
  ["g3:0817b7fa"] = "He dejado esto así para que\npuedas volver a entrar.\\p¿No quieres descansar antes de\ncontinuar con lo que te queda?\\pEl ADMINISTRADOR que me sigue\nes mejor ENTRENADOR que yo.\\pMás vale que te prepares para\nun difícil encuentro.",
  ["g3:0817b8da"] = "Ya está bien de ir de guay.\\pLo de contar que el TEAM ROCKET\nse ha separado es...\\pun intento descarado de causar\nel desconcierto entre nosotros.\\pPero afortunadamente no somos\nlelos y no nos tragamos semejantes\\lchorradas.\\p¡Te vas a enterar de lo que llegan\na molestar estas cosas!",
  ["g3:0817b9fb"] = "Grrrrrr...\n¡Eres demasiado fuerte!...\\p¡Eh!...\n¡Ésa es la MEDALLA de GIOVANNI!\\pEntonces, ¿es verdad que el TEAM\nROCKET se ha disuelto?",
  ["g3:0817ba64"] = "¡Nos iremos del ALMACÉN!...\\pPero no te pienses que la cosa\nse queda ahí. ¡Ya me ocuparé yo!\\pIré a buscar a GIOVANNI y reuniré\nal TEAM ROCKET. ¡Ya lo verás!\\p¡Hasta entonces, ya nos veremos!",
  ["g3:0817bb15"] = "Hay un informe con gráficos\ny anotaciones en el monitor del PC.\\p“La influencia de las ondas\nmagnéticas en la evolución de los\\lPOKéMON”...\\p... ... ... ... ... ...\\pCualquiera entiende esto...",
  ["g3:0817bbaf"] = "He estado a punto de vender\nel ZAFIRO por un buen pellizco...\\p¡Y vas tú y apareces justo cuando\niba a cerrar el trato!\\p¡Grrrrrrrrrrrrrrrrr...!\n¡No tienes perdón!",
  ["g3:0817bc55"] = "¡Ufff! ¿Será posible?\n¡Grrrrrrr!",
  ["g3:0817bc6c"] = "Si no voy a poder venderlo, no lo\nquiero para nada. ¡Quédatelo tú!",
  ["g3:0817bca3"] = "¿Y ahora qué?\n¿Quieres dejarme ya en paz?",
  ["g3:0817bcd7"] = "Pero ¿otra vez tú?\\pTú... tú no eres el retoño\nde GIOVANNI, ¿verdad?\\pNo, no puede ser, el retoño\nde GIOVANNI es pelirrojo.\\pBueno, ¿y por qué me incordias?\nDéjame, anda.",
  ["g3:0817bd82"] = "¡{PLAYER} encontró un ZAFIRO!",
  ["g3:0817bd97"] = "Bien... Estupendo...\nJusto lo que pensaba.\\pHe hecho bien en seguirte.",
  ["g3:0817bdd4"] = "Sabía que había un ZAFIRO aquí,\n¡así que para mí!\\p¡Se lo venderé al TEAM ROCKET\npor una buena cantidad!\\pEh... no me mi-mires así.\\pSi lo quieres, ¿por qué no vas a\npor él cuando lo venda?\\pTe diré una de las contraseñas\ndel ALMACÉN ROCKET y todo...\\pLa contraseña que yo conozco es\n“HO-OH es ese HO-OH”.\\pHala, yo ya estoy.\n¡No te mosquees conmigo!",
  ["g3:0817bf3a"] = "Oye, que me pica la curiosidad,\n¿cómo crías a tus POKéMON?",
  ["g3:0817bf66"] = "¡Veo que con mucho cariño!",
  ["g3:0817bf97"] = "Hay que criarlos con el mismo\ncariño con el que una madre cría\\la sus pequeños.",
  ["g3:0817bfeb"] = "Yo me encargo de preservar el\nentorno natural de los POKéMON.",
  ["g3:0817c028"] = "¡Para la edad que tienes,\neres increíble!",
  ["g3:0817c056"] = "¡Yo no he dicho que no debas\natrapar POKéMON!\\pSólo quiero que la gente los críe\nde forma responsable.",
  ["g3:0817c0be"] = "He atrapado un POKéMON del tipo\nBICHO que sólo vive por aquí.",
  ["g3:0817c0f2"] = "Je, je, je...\n¿No es impresionante mi POKéMON?",
  ["g3:0817c113"] = "Hay una chica cerca del arbusto,\nque mide las fuerzas de HERACROSS.",
  ["g3:0817c155"] = "¿Sabes? Si no uso POKéMON del tipo\nBICHO, no disfruto los combates.",
  ["g3:0817c196"] = "No pasa nada, perder tiene también\nsu encanto.",
  ["g3:0817c1d0"] = "A todo esto, lo del “encanto”\nlo digo porque hay que saber\\lganar y perder.\\pEs como el blanco y el negro,\ncomo el día y la noche. ¿No?",
  ["g3:0817c246"] = "¡Mira qué POKéMON del tipo BICHO\ntengo! ¡Sí, señor!",
  ["g3:0817c275"] = "¡Me han ganado en plena euforia!",
  ["g3:0817c2a4"] = "La próxima vez, me vengo con mi\nhermano pequeño.",
  ["g3:0817c2d9"] = "¡Mira al suelo!\nQué dibujos más raros... ¿verdad?",
  ["g3:0817c30d"] = "¡Increíble!",
  ["g3:0817c31c"] = "Los dibujos tan raros del suelo...\\p¡Se parecen al estampado de\nla ropa de mi abuelo!",
  ["g3:0817c373"] = "Crees que soy inofensivo, ¿eh?",
  ["g3:0817c3a5"] = "Crees que soy débil, ¿no?",
  ["g3:0817c3ce"] = "La gente de ciudad siempre viene\ndándose demasiados aires...\\pAunque a mí no me vendrían\nmal unos pocos...",
  ["g3:0817c42b"] = "¡Mmmm, respira hondo!\nQué aire tan puro...",
  ["g3:0817c458"] = "Si quieres, puedo enseñarte\ntécnicas de respiración.",
  ["g3:0817c490"] = "Espira...\nHasta que no te quede aire...\\pCuando no puedas espirar más,\n¡inspira!\\p¿No es una sensación de frescor\nfantástica?",
  ["g3:0817c4fe"] = "Me encantan los POKéMON del tipo\nBICHO. Por eso estoy siempre aquí.\\pSupongo que no seré la única...",
  ["g3:0817c552"] = "No pienso perder la sonrisa.\nSupongo que no soy la única...",
  ["g3:0817c590"] = "Voy a seguir coleccionando\nPOKéMON del tipo BICHO.\\pSupongo que no soy la única...",
  ["g3:0817c5db"] = "Este sitio es estupendo.\nVoy a colocar la tienda aquí.",
  ["g3:0817c609"] = "Qué paliza...",
  ["g3:0817c615"] = "Me quedaré aquí para observar\nlas estrellas.",
  ["g3:0817c63e"] = "¡Ay!\nCreo que me ha picado algo...",
  ["g3:0817c660"] = "No ha sido ningún bicho, me he\ncortado con el césped.",
  ["g3:0817c68e"] = "Un cortecillo así...\nSe cura con un poco de saliva.",
  ["g3:0817c6c9"] = "¿Has visto algo raro por aquí?",
  ["g3:0817c6fb"] = "Yo que tú, miraría bien\npor el suelo.",
  ["g3:0817c728"] = "Hay sitios en el BOSQUEJO,\nen los que no crece la hierba.\\p¿Por qué será?",
  ["g3:0817c794"] = "¡Hola!\\p¡Ésta es la TORRE DESAFÍO, punto\nde encuentro de ENTRENADORES\\lde todos sitios!",
  ["g3:0817c7d9"] = "Aquí vienen ENTRENADORES de todo\nel mundo para luchar.\\pA ver, ahora mismo...\\pHay ENTRENADORES hasta\nel piso {STR_VAR_1}.",
  ["g3:0817c850"] = "Hay ENTRENADORES esperándote\npara luchar hasta el octavo piso.",
  ["g3:0817c88d"] = "¿Quieres enfrentarte a ellos?",
  ["g3:0817c8bf"] = "Muy bien, voy a poner el reloj\nen hora. ¡A por todas!\\pA sus puestos...\\pPreparados..., listos...\\p¡Ya!",
  ["g3:0817c91d"] = "¡Vuelve cuando quieras!",
  ["g3:0817c937"] = "Qué pena...\\pLa verdad es que te has esforzado\nmucho.\\p¡Bueno, otra vez será!",
  ["g3:0817c9a2"] = "¡Demuestra lo que sabes!",
  ["g3:0817c9c0"] = "Cuando los ENTRENADORES se\ncambian de sitio, organizan una...\\ltremenda.\\pPara evitar tanto follón pusimos\nla recepción aquí.\\pDisculpa las molestias.",
  ["g3:0817ca5a"] = "Hola.\\pSoy el dueño de esta TORRE.\\pLa forma en que el cielo se\nextiende por encima de nosotros...\\pLa manera en que nos acaricia\nel viento...\\p¡Es una maravilla!...\\pY la forma en que has luchado...\nes también espectacular...",
  ["g3:0817cb09"] = "Esto es para ti...",
  ["g3:0817cb1a"] = "¡Estupendo!\n¡Maravilloso!\\p¡Es extraordinario que hayas\nllegado tan rápido!\\pLa cosa es que lo has conseguido\nen tiempo récord...\\pVoy a ponerlo junto a uno de los\nmostradores de la recepción.",
  ["g3:0817cbc0"] = "Se ve que no te has dado mucha\nprisa en llegar hasta aquí...",
  ["g3:0817cbf5"] = "Me gustaría ver que consigues\nun tiempo mejor...\\pEspero que no me defraudes.\\pNos vemos.",
  ["g3:0817cc73"] = "Esto es un combate doble.\\pSi no tienes dos POKéMON,\nno podrás participar.",
  ["g3:0817ccc9"] = "En la TORRE DESAFÍO, se lucha\na CONTRARRELOJ.\\pCronometraremos lo que tardes\nen alcanzar al DUEÑO en el último\\lpiso, en cuanto dejes la recepción.\\pLos mejores tiempos podrán verse\nen el marcador.\\pCompite con tus amigos para ver\nquién tarda menos.\\p¡Ah, piensa que aquí no se ganan\npuntos de EXP. ni dinero!",
  ["g3:0817ce1f"] = "¡Gracias por participar!",
  ["g3:0817ce38"] = "Yo he venido para ver lo fuerte\nque soy.\\p¿Cómo serán los ENTRENADORES con\nlos que me tendré que enfrentar?\\p¡Qué nervios!",
  ["g3:0817ce9f"] = "Uffffff...\nEstoy agotado...\\p¡No por los combates, no!\n¡Es por las escaleras!...\\l¡Son peores que las peleas!",
  ["g3:0817cef5"] = "¡Ay, mamaíta, qué miedo!\\pYo pensaba que en estas ruinas tan\nantiguas no había nada de nada,\\l¡pero creo que hay fantasmas!",
  ["g3:0817cf42"] = "¡Aaaaaah!\n¡Estoy temblando de miedo!",
  ["g3:0817cf54"] = "Estoy intentando salir de aquí,\npero siempre llego al mismo sitio.\\pYo creo que el número de piedras\nque hay, quiere decir algo...",
  ["g3:0817cfc1"] = "A mí me parece que en esta cueva\nse está cociendo algo.",
  ["g3:0817cffb"] = "Como no tomes el túnel adecuado,\nno conseguirás avanzar.",
  ["g3:0817d037"] = "Hace poco entró una señora\nen las cuevas de ahí.",
  ["g3:0817d062"] = "¿Qué qui-quieres de mí?",
  ["g3:0817d086"] = "Qué susto, no sabía muy bien\nlo que querías.",
  ["g3:0817d0b2"] = "Me alegro de que hayas venido.\\pEstaba ya aburridísima y cansada\nde tanto andar.\\p¿Te importaría llevarme a casa?",
  ["g3:0817d13b"] = "Eh, ¿qué tal?\\p¿Que qué hago aquí?\nPues estoy buscando oro.\\pCuando consiga una fortuna,\nme compraré una casita en KANTO.",
  ["g3:0817d1c9"] = "Eh, ¿cómo lo llevas?\n¿Sabes qué? ¡He encontrado oro!\\p¿Recuerdas que te dije que estaba\nbuscando?\\p¡No te puedes ni imaginar lo feliz\nque soy!\\pToma, anda.\nCompartiré un poco contigo.",
  ["g3:0817d28c"] = "Es una PEPITA.\\pNo puedo darte pepitas de la\nsabiduría, ¡sólo esto!",
  ["g3:0817d2dc"] = "Vaya, tienes la MOCHILA hasta\narriba... Bueno, otra vez será.",
  ["g3:0817d31b"] = "Se ha oído un estruendo procedente\nde un lugar lejano.",
  ["g3:0817d34a"] = "¡Mmmmm!\n¡Qué maravilla!\\p¡Ooooooooh! ¡Esto es vida!\n¡Es de lo más reconfortante!\\p¡No me digas que no!\\pQuédate aquí un ratito y relájate.\nQué agradable sentir el calor...",
  ["g3:0817d3de"] = "La mejor parte del baño viene\ncuando me salgo del agua.\\pNo hay nada como tomar un buen\nplato de sopa de pescado caliente\\lpara conservar el calorcito. Mmm...",
  ["g3:0817d450"] = "El agua está en su punto.\nTiene la temperatura ideal...\\p¡{PLAYER} y sus POKéMON están\nen forma de nuevo!",
  ["g3:0817d4aa"] = "Dicen que los baños termales\nson terapéuticos.",
  ["g3:0817d4e3"] = "¿Has visto cómo tengo la piel?\nSuave y tersa como la de un bebé.\\p¡Las aguas termales me están\ndejando hecha una rosa!",
  ["g3:0817d550"] = "Tras un duro día de entrenamiento,\nno hay nada como un buen baño\\ltermal.\\pBRUNO, ejemplo al que sigo, viene\nal BALNEARIO cada vez que puede.\\pNo sólo para recuperarse él,\ntambién lo hace por sus POKéMON.",
  ["g3:0817d622"] = "Las aguas termales tienen una\nrelación estrecha con los volcanes.\\pYo fui quien montó el BALNEARIO\nASCUAS hace unos años.\\pEn enormes cantos que había,\nhice las piscinas termales picando\\lla piedra con mis propias manos.\\pEntonces, usé esto. Creo que\nya puedo desprenderme de ello.",
  ["g3:0817d6f3"] = "Podrás destrozar rocas como\nsi fueran nueces.",
  ["g3:0817d72c"] = "OAK: ¡Eh! ¡Alto!\n¡No te vayas!",
  ["g3:0817d74a"] = "OAK: ¡Cuidado! ¡En la hierba viven\nPOKéMON salvajes!\\p¡Necesitas a tu propio POKéMON\ncomo protección!\\p¡Vente conmigo, anda!",
  ["g3:0817d7c8"] = "¡Yo también entreno a mis POKéMON!\\p¡Cuando se hagan fuertes me\nprotegerán!",
  ["g3:0817d80d"] = "¡La tecnología es increíble!\\p¡Ahora puedes guardar y sacar\nobjetos y POKéMON, vía PC!",
  ["g3:0817d866"] = "LABORATORIO DE INVESTIGACIÓN\nDE POKéMON DEL PROFESOR OAK",
  ["g3:0817d87f"] = "Casa de {PLAYER}",
  ["g3:0817d88a"] = "Casa de {RIVAL}",
  ["g3:0817d895"] = "PUEBLO PALETA\n¡Un lienzo en blanco de tu viaje!",
  ["g3:0817d8bf"] = "OAK: ¡Ah, {PLAYER}!\n¡Has vuelto!\\p¿Qué tal va tu POKéDEX?\\p¿Me dejas que le eche un vistazo?\\pA ver...",
  ["g3:0817d925"] = "Llevas {STR_VAR_2}...\\pSe ve que te estás esforzando\nmucho.\\pVen a verme cuando consigas más.",
  ["g3:0817d9aa"] = "Llevas... ¿¡{STR_VAR_2}!?\n¡Impresionante!\\pQuiero preguntarte algo, {PLAYER}.\\pVen.\nSígueme.",
  ["g3:0817da16"] = "OAK: ¡Eh, {PLAYER}! Estás\ndisfrutando de tu aventura, ¿eh?\\pConociéndote, {PLAYER}, imagino que\nvas a ir a más lugares exóticos\\lde los que te gustan.\\pPues nada, nada.\n¡A mí me parece estupendo!",
  ["g3:0817dabb"] = "¿Llevas POKé BALLS?\n¡Entonces tú tienes POKéMON!\\p¡Es genial poder llevar y usar los\nPOKéMON en cualquier momento\\ly lugar!",
  ["g3:0817db39"] = "Este GIMNASIO POKéMON está\nsiempre cerrado.\\pMe pregunto quién será su LÍDER.",
  ["g3:0817db78"] = "¡El LÍDER del GIMNASIO VERDE\nha vuelto!",
  ["g3:0817db98"] = "¿Quieres saber algo sobre los 2\ntipos de orugas POKéMON?",
  ["g3:0817dbd5"] = "Vale, pues nada.",
  ["g3:0817dbe4"] = "¡CATERPIE no tiene veneno; pero\nWEEDLE, sí!\\p¡Cuidado con su PICOTAZO\nVENENOSO!",
  ["g3:0817dc4e"] = "¡Oh, abuelo!\n¡No seas tan malo!\\pLo siento, todavía no se ha tomado\nun café...",
  ["g3:0817dc99"] = "¡Cuando voy de compras a\nCIUDAD PLATEADA, tomo el sinuoso\\lcamino del BOSQUE VERDE!",
  ["g3:0817dd03"] = "¡No puedes pasar por aquí!\\p¡Es propiedad privada!",
  ["g3:0817dd4e"] = "Lo bien que me sienta tomarme\nun cafelito... ¡me pone las pilas!\\p¿Y esa caja roja que llevas ahí?\\pAh, así que estás trabajando\nen tu POKéDEX...\\pPues deja que te diga algo.\\pCuando atrapes un POKéMON,\nla POKéDEX actualizará sus datos\\lde forma automática.\\p¿Cómo? ¿Que no sabes atrapar\nPOKéMON?\\p¡Pues haber empezado por ahí!",
  ["g3:0817de9b"] = "Bueno, no me dirás que no ha sido\nilustrativo, ¿eh?\\pAnda, toma, esto es para ti.",
  ["g3:0817deeb"] = "Úsala cuando haya alguna cosilla\nque no entiendas.\\pTe explicará muy bien lo básico\npara ser buen ENTRENADOR POKéMON.",
  ["g3:0817df61"] = "Lo bien que me sienta tomarme\nun cafelito... ¡me pone las pilas!\\pAunque..., creo que estaba muy\ncargado... Me duele la cabeza.\\pA todo esto, ¿estás completando\nla POKéDEX?\\pNo olvides que conviene agotar\ntodo lo posible a los POKéMON\\lantes de intentar atraparlos.",
  ["g3:0817e046"] = "Lo bien que me sienta tomarme\nun cafelito... ¡me pone las pilas!\\pAunque..., creo que estaba muy\ncargado... Me duele la cabeza.\\pA todo esto, ¿te está sirviendo\nmi vieja POKé TELE?",
  ["g3:0817e0ea"] = "¡No me extraña, el chico es\nmi nieto!\\p¡Con él aprende hasta el menos\nespabilado, je!",
  ["g3:0817e14e"] = "Mmm... Supongo que será porque\nno tienes apenas tiempo de\\lencenderla...\\pEl tiempo es oro, tú sabrás cómo\nlo administras...",
  ["g3:0817e1bb"] = "CIUDAD VERDE\nEl paraíso del eterno verdor.",
  ["g3:0817e1e7"] = "PISTAS ENTRENADOR\\p¡Atrapa los POKéMON y amplía\ntu colección!\\p¡Cuantos más tengas, más fácil\nte será luchar!",
  ["g3:0817e24d"] = "PISTAS ENTRENADOR\\pLos ataques de los POKéMON\ndependen de sus PUNTOS de PODER\\lo PP.\\p¡Para rellenar tus PP, deja que\ntus cansados POKéMON descansen\\len un CENTRO POKéMON!",
  ["g3:0817e2db"] = "GIMNASIO POKéMON DE CIUDAD VERDE",
  ["g3:0817e2f5"] = "Las puertas del GIMNASIO están\ncerradas...",
  ["g3:0817e316"] = "¡Uaaaahuuh...!\nDebo de haberme dormido al sol...\\pHe soñado que un DROWZEE\nse comía mi sueño.\\p¡¡Y he aprendido a comer sueños!!\n¡¡¡Qué miedo!!!\\p¿Quieres que se lo enseñe\na un POKéMON?",
  ["g3:0817e3e9"] = "Pues vaya... Zz... Zzzzzz...",
  ["g3:0817e3f1"] = "¿A qué POKéMON quieres que\nle enseñe COME SUEÑOS?",
  ["g3:0817e41b"] = "Yo... Ya no puedo comer más...\nZz... Zzzzz...",
  ["g3:0817e436"] = "¡Dicen que los CLEFAIRY vinieron\nde la Luna!\\p¡Aparecieron tras la caída de\nvarias PIEDRAS LUNARES\\len el MT. MOON!",
  ["g3:0817e49f"] = "¡No hay muchos ENTRENADORES\nde POKéMON por aquí!\\p¡Todos parecen CAZABICHOS, salvo\nBROCK, del GIMNASIO de PLATEADA!",
  ["g3:0817e53e"] = "¿Has estado en el MUSEO?",
  ["g3:0817e55c"] = "¿No eran geniales esos fósiles\ndel MT. MOON?",
  ["g3:0817e589"] = "¿De verdad?\n¡Pues tienes que ir!",
  ["g3:0817e5ac"] = "¡Está aquí mismo!\\p¡Hay que pagar para entrar, pero\nvale la pena! ¡Hasta luego!",
  ["g3:0817e602"] = "¡Pssss!\n¿Sabes lo que estoy haciendo?",
  ["g3:0817e626"] = "¡Eso es!\n¡Un trabajo tremendo!",
  ["g3:0817e644"] = "¡Utilizo el REPELENTE para echar\nde mi jardín a los POKéMON!",
  ["g3:0817e67e"] = "¿Entrenas POKéMON?\\p¡BROCK está buscando a nuevos\nadversarios! ¡Sígueme!",
  ["g3:0817e6c7"] = "¡Si eres valiente, pelearás contra\nBROCK!",
  ["g3:0817e6f6"] = "PISTAS ENTRENADOR\\p¡Todo POKéMON que luche en un\ncombate ganará EXPERIENCIA!",
  ["g3:0817e748"] = "¡AVISO!\\p¡Unos ladrones han robado fósiles\nde POKéMON del MT. MOON!\\p¡Avisad a la POLICÍA de CIUDAD\nPLATEADA si sabéis algo!",
  ["g3:0817e7c5"] = "MUSEO DE LA CIENCIA DE\nCIUDAD PLATEADA",
  ["g3:0817e7de"] = "LÍDER del GIMNASIO POKéMON\nde PLATEADA: BROCK\\l¡Es fuerte como una roca!",
  ["g3:0817e824"] = "CIUDAD PLATEADA\nUna ciudad de roca grisácea.",
  ["g3:0817e90c"] = "Menos mal que te pillo, soy\nAYUDANTE del PROF. OAK.\\pMe han pedido que te diera una\ncosa, aquí tienes.",
  ["g3:0817e970"] = "¡{PLAYER} recibió las DEPORTIVAS\nde manos del AYUDANTE!",
  ["g3:0817e99d"] = "{PLAYER} se ha puesto las\nDEPORTIVAS.",
  ["g3:0817e9c7"] = "Para correr, pulsa el Botón B,\n¡pero sólo donde haya sitio!",
  ["g3:0817ea06"] = "Bueno, tengo que volver al\nLABORATORIO.\\pHasta luego.",
  ["g3:0817ea36"] = "Vienen con una notita...\\p{PLAYER}, cielo:\\pAquí tienes un par de DEPORTIVAS,\nadorable valiente.\\pPiensa que siempre voy a estar\naquí para apoyarte, ¡ánimo!\\pMamá",
  ["g3:0817ead7"] = "{RIVAL}: ¡Hola, {PLAYER}!\\p¿Qué, esto es más difícil de lo\nque te pensabas, eh?\\p¡Pues a mí me va de escándalo!\n¡He atrapado un montón de listos\\ly fuertes POKéMON!\\p¡Bueno, {PLAYER}, vamos a ver qué\nhas atrapado!",
  ["g3:0817eb71"] = "¡Oye!\n¡Calma!\\l¡Ya has ganado!",
  ["g3:0817eb95"] = "{RIVAL}: ¿Sabes qué me pasó?\\p¡Estuve con BILL y conseguí que\nme enseñara sus raros POKéMON!\\p¡Y eso añadió muchas páginas a mi\nPOKéDEX!\\p¡Por algo BILL es mundialmente \nconocido como POKéMANÍACO!\\p¡Él fue también el que inventó el\nSistema de Almacenamiento de\\lPOKéMON para PC!\\p¡Ya que estás usando su sistema,\ndeberías darle las gracias!\\p¡En fin, sigo con lo mío!\n¡Hasta luego!",
  ["g3:0817ecd4"] = "En el fondo...\\pEn el fondo me das pena, te lo\ndigo en serio. Siempre vas a\\ltrancas y barrancas detrás de mí.\\pToma, te voy a dar un regalito\nporque me da no sé qué.",
  ["g3:0817ed5d"] = "Yo creo que esto es perfecto para\nalguien tan cotilla como tú...\\pA mí no me hace falta, porque\nyo voy a mi bola.\\pBueno, me piro, vampiro.",
  ["g3:0817ee70"] = "SOLDADO: ¡Alto! ¡Me rindo!\n¡Me iré tranquilamente!",
  ["g3:0817ee9c"] = "¡Vale!\n¡Devolveré la MT que robé!",
  ["g3:0817eebf"] = "¡{PLAYER} recuperó\nla MT28!",
  ["g3:0817eeed"] = "¡Yo me voy de aquí!\n¡Adiós!",
  ["g3:0817ef07"] = "¡Hazle sitio a esto! ¡No puedo\nirme hasta que no te lo dé!",
  ["g3:0817ef3f"] = "¿También entrenas POKéMON?\\pAtrapar, luchar, ¡qué vida tan\ndura la nuestra!",
  ["g3:0817ef89"] = "Los POKéMON pueden CORTAR\npequeños arbustos.\\pPor ejemplo, el que está casi\nenfrente de la tienda, también.\\pCon todo, creo que se puede dar\nun rodeo...",
  ["g3:0817f01d"] = "Si ese SLOWBRO no estuviera ahí,\npodrías CORTAR el arbusto.\\pAsí podrías pasar al otro lado.\\pCon todo, creo que se puede dar\nun rodeo...",
  ["g3:0817f0b2"] = "¿Estás haciendo una enciclopedia\nde los POKéMON? ¡Qué increíble!",
  ["g3:0817f0f1"] = "A esta gente le han robado.\\p¡Seguro que el TEAM ROCKET guarda\nrelación con esta barbaridad!\\p¡Hasta nuestra POLICÍA tiene\nproblemas con los ROCKET!",
  ["g3:0817f183"] = "¡BIEN! ¡SLOWBRO!\n¡Usa BOMBA SÓNICA!",
  ["g3:0817f1a1"] = "¡Venga, SLOWBRO, presta atención!",
  ["g3:0817f1c2"] = "¡SLOWBRO, dale un puñetazo!",
  ["g3:0817f1d2"] = "¡No!\n¡Has vuelto a fallar!",
  ["g3:0817f1e9"] = "¡SLOWBRO, REFUGIO!",
  ["g3:0817f1fc"] = "¡No! ¡Qué mal!\\p¡Es tan difícil controlar a los\nPOKéMON!\\p¡La obediencia de tus POKéMON\ndepende de tus habilidades como\\lENTRENADOR!",
  ["g3:0817f270"] = "SLOWBRO se durmió...",
  ["g3:0817f287"] = "SLOWBRO está holgazaneando...",
  ["g3:0817f2a2"] = "SLOWBRO se alejó...",
  ["g3:0817f2b7"] = "SLOWBRO ignoró las órdenes...",
  ["g3:0817f2cf"] = "Quiero una bonita BICICLETA roja.\\p¡La guardaré en casa para que no\nse ensucie!",
  ["g3:0817f319"] = "¡Ésta es la CUEVA CELESTE!\\p¡En ella viven unos POKéMON\nsuperfuertes!\\p¡Sólo pueden entrar ENTRENADORES\nque sean realmente especiales!\\pPara llegar a ser CAMPEÓN de la\nLIGA POKéMON, hay que ser muy,\\lmuy fuerte.\\pLa LIGA supone un gran desafío.",
  ["g3:0817f420"] = "¡CIUDAD CELESTE!\n¡Una misteriosa aura azulada la\\lrodea!",
  ["g3:0817f453"] = "PISTAS ENTRENADOR\\pA los POKéMON se les puede\nentregar objetos.\\pAdemás, pueden llegar a usarlos\nen combate.",
  ["g3:0817f4c5"] = "TIENDA DE BICIS\n¡Césped y cuevas bajo control!",
  ["g3:0817f4ef"] = "LÍDER del GIMNASIO POKéMON\nde CELESTE: MISTY\\l¡La sirena distorsionada!",
  ["g3:0817f52e"] = "¿Crees en los GHOST?",
  ["g3:0817f548"] = "¿De verdad?\nHay quien no cree...",
  ["g3:0817f568"] = "¡Jajaja! Yo tampoco.\\pEsa mano blanca en tu hombro no es\nreal.",
  ["g3:0817f5b6"] = "A este pueblo se lo conoce como\nel lugar de reposo de los POKéMON.\\pLos homenajes se celebran en la\nTORRE POKéMON.",
  ["g3:0817f614"] = "Los GHOST aparecieron en la TORRE\nPOKéMON.\\pCreo que son espíritus de POKéMON\ndebilitados por los ROCKET.",
  ["g3:0817f676"] = "PUEBLO LAVANDA\nEl noble pueblo púrpura.",
  ["g3:0817f69a"] = "SILPH S.A.\\p¡El nuevo SCOPE SILPH!\n¡Hace visible lo invisible!",
  ["g3:0817f6d6"] = "CASA POKéMON DE VOLUNTARIOS\nDE PUEBLO LAVANDA",
  ["g3:0817f6f7"] = "TORRE POKéMON: Que las almas de\nlos POKéMON descansen en paz.",
  ["g3:0817f723"] = "¡Nos preocupa la contaminación!\\p¡Dicen que GRIMER se convierte\nen cantidades enormes de residuos\\ltóxicos!",
  ["g3:0817f776"] = "¿Viste al S.S. ANNE anclado en el\npuerto?",
  ["g3:0817f7a6"] = "¡El S.S. ANNE ha zarpado!\nVolverá a CARMÍN en un año.",
  ["g3:0817f7fd"] = "Voy a construir un edificio en este\ntrozo de tierra.\\pMi POKéMON está apisonando\nel terreno.",
  ["g3:0817f871"] = "MACHOP: ¡Chop! ¡Chop!",
  ["g3:0817f888"] = "¡Un MACHOP está apisonando\nel terreno!",
  ["g3:0817f8ac"] = "El S.S. ANNE es un famoso y lujoso\ncrucero.\\pVisitamos CARMÍN una vez al año.",
  ["g3:0817f8fb"] = "CIUDAD CARMÍN\nEl puerto de los ocasos exquisitos.",
  ["g3:0817f928"] = "¡AVISO!\\pLa RUTA 12 podría estar bloqueada\npor un POKéMON dormido.\\pDesvíate a través del TÚNEL ROCA\na PUEBLO LAVANDA.\\pPOLICÍA de CARMÍN",
  ["g3:0817f9a1"] = "CLUB DE FANS DE POKéMON\n¡Bienvenidos todos!",
  ["g3:0817f9cc"] = "LÍDER del GIMNASIO POKéMON\nde CARMÍN: LT. SURGE\\l¡El Rayo americano!",
  ["g3:0817fa11"] = "PUERTO CARMÍN",
  ["g3:0817fa22"] = "¡Éste es el S.S. ANNE!",
  ["g3:0817fa3c"] = "¡Éste es el S.S. ANNE!\\pDisculpe, ¿tiene su ticket?",
  ["g3:0817fb10"] = "El barco zarpó.",
  ["g3:0817fb23"] = "Ah, tienes el TRI-TICKET.\\p¿Quieres subir a bordo del\nSURCAMAR?",
  ["g3:0817fb67"] = "Estupendo, todo en regla.\\pEl SURCAMAR VELOCE 7\nva a zarpar en breve.",
  ["g3:0817fbb8"] = "Ah, tienes el IRIS-TICKET.\\p¿Quieres subir a bordo del\nSURCAMAR?",
  ["g3:0817fc00"] = "¡Anda, el MISTI-TICKET!\n¡Qué curioso!\\pEstaremos encantados de llevarte\na ROCA OMBLIGO cuando quieras.",
  ["g3:0817fc5f"] = "¡Anda, el ORI-TICKET!\n¡Qué curioso!\\pEstaremos encantados de llevarte\na ISLA ORIGEN cuando quieras.",
  ["g3:0817fcc1"] = "¿Quieres subir a bordo del\nSURCAMAR?",
  ["g3:0817fcec"] = "Estupendo, todo está listo para\nque subas a bordo de un ferry\\lmuy especial.\\pEl SURCAMAR VELOCE 10\nva a zarpar en breve.",
  ["g3:0817fd5f"] = "Estupendo, todo está listo para\nque subas a bordo de un ferry\\lmuy especial.\\pEl SURCAMAR VELOCE 12\nva a zarpar en breve.",
  ["g3:0817fdd2"] = "¡Hola, {PLAYER}!\n¿Qué tal lo llevas?\\pSoy uno de los AYUDANTES\ndel PROF. OAK.\\p¿Has visto ya al otro AYUDANTE?\\pTenía algo que entregarte de parte\ndel PROF. OAK, {PLAYER}.\\pComentó que iría a buscarte por\nla RUTA 2, {PLAYER}.\\pSi pasas por la RUTA 2, búscalo.",
  ["g3:0817fec3"] = "¡Conseguí a mi KOFFING en\nCIUDAD CANELA!\\p¡Es muy simpático, pero echa\nveneno cuando se enfada!",
  ["g3:0817ff1c"] = "¡Jeje! ¡Este GIMNASIO es genial!\n¡Está lleno de chicas!",
  ["g3:0817ff4a"] = "AZULONA presume de estar bonita\ny cuidada.\\p¡El CASINO no es bueno para la\nimagen de nuestra ciudad!",
  ["g3:0817ffc5"] = "¡Ayyy! ¡Lo he perdido todo\nen las tragaperras!\\p¡Debería haber cambiado todas\nmis fichas por premios!",
  ["g3:0818001b"] = "¡Éste es mi fiel compañero,\nPOLIWRATH!\\p¡Evolucionó del POLIWHIRL al usar\nla PIEDRA AGUA!",
  ["g3:08180075"] = "POLIWRATH: ¡Poli, poli!",
  ["g3:0818008c"] = "¿Qué estás mirando?",
  ["g3:081800c2"] = "¡No te cruces en el camino del\nTEAM ROCKET!",
  ["g3:081800e1"] = "PISTAS ENTRENADOR\\p¡PRECISIÓN X aumenta la precisión\nde los ataques!\\p¡El DIRECTO aumenta la posibilidad\nde golpes críticos!\\p¡Compra tus objetos en el\nCENTRO COMERCIAL de AZULONA!",
  ["g3:0818017a"] = "CIUDAD AZULONA\nLa ciudad de los sueños de\\larco iris.",
  ["g3:081801a2"] = "LÍDER del GIMNASIO POKéMON\nde AZULONA: ERIKA\\l¡Princesa amante de la Naturaleza!",
  ["g3:081801e5"] = "MANSIÓN AZULONA",
  ["g3:081801f5"] = "¡Compra lo que necesites en el\nCENTRO COMERCIAL de AZULONA!",
  ["g3:08180224"] = "PISTAS ENTRENADOR\\p¡PROTECCIÓN ESP. protege a tus\nPOKéMON de ataques como el agua y\\lel fuego!\\p¡Compra tus objetos en el CENTRO\nCOMERCIAL de AZULONA!",
  ["g3:081802a4"] = "CAMBIO DE PREMIOS\n¡Se cambian fichas por premios!",
  ["g3:081802cf"] = "CASINO ROCKET\n¡El parque de los adultos!",
  ["g3:08180300"] = "¡Aaaagh, ayyyy...!\n¡Me he achicharrado la lengua!\\pLa ancianita tan agradable que hay\nen la MANSIÓN, me ha dado un TÉ.\\p¡Pero está hirviendo!\nVoy a esperar a ver si se enfría...",
  ["g3:08180388"] = "¡Hola!\\p¡Te había visto, pero nunca había\npodido hablar contigo!\\pYo creo que ha sido la suerte\nla que nos ha vuelto a reunir.\\pPara celebrarlo, me gustaría\nenseñarte AMORTIGUADOR.",
  ["g3:0818043f"] = "Bueno, aquí me tienes para cuando\nte haga falta.",
  ["g3:08180484"] = "¿A qué POKéMON quieres que\nle enseñe AMORTIGUADOR?",
  ["g3:081804c4"] = "¡Que te vaya muy bien!",
  ["g3:081804e1"] = "¿Qué voy a hacer ahora?...\\p¡Nos han robado el SILPH SCOPE!\\pQuien haya sido, vino por aquí.\nDe eso no me cabe duda.\\p¡Pero no sé por dónde se fue!\n¡No tengo ni idea!",
  ["g3:0818056e"] = "¿Has probado el JUEGO del SAFARI?\\pAlgunos POKéMON sólo pueden ser\natrapados allí.",
  ["g3:081805c6"] = "En la ZONA del SAFARI hay un zoo\ndelante de la entrada.\\p¡En su interior está el JUEGO del\nSAFARI, para atrapar POKéMON!",
  ["g3:0818062c"] = "ENRIQUE: ¿Dónde estará SARA?\nQuedamos en vernos aquí.",
  ["g3:0818065a"] = "Ese objeto redondo de ahí...\n¿Lo quieres?\\p¡Yo también! ¡Anda, es un POKéMON!",
  ["g3:081806ab"] = "¡Mirad CIUDAD FUCSIA!\n¡La pasión rosa!",
  ["g3:081806d3"] = "ZONA SAFARI:\nPARAÍSO-POKéMON",
  ["g3:081806f0"] = "JUEGO DEL SAFARI:\n¡ATRAPA-POKéMON!",
  ["g3:0818070d"] = "CASA DEL GUARDA\nDEL SAFARI",
  ["g3:08180768"] = "LÍDER del GIMNASIO POKéMON\nde FUCSIA: KOGA\\lEl venenoso maestro ninja.",
  ["g3:081807a9"] = "Nombre: CHANSEY\n¡Atrapar uno es una cuestión\\lde suerte!",
  ["g3:081807d9"] = "Nombre: VOLTORB\nLa viva imagen de una POKé BALL.",
  ["g3:08180806"] = "Nombre: KANGASKHAN\nUn POKéMON maternal que cría a sus\\lhijos en una bolsa de su barriga.",
  ["g3:08180859"] = "Nombre: SLOWPOKE\nSimpático y de movimientos\\lmuy lentos.",
  ["g3:08180887"] = "Nombre: LAPRAS\nTambién conocido como el rey\\lde los mares.",
  ["g3:081808ae"] = "Nombre: OMANYTE\nUn POKéMON que fue regenerado\\la partir de un fósil.",
  ["g3:081808fa"] = "Nombre: KABUTO\nUn POKéMON que fue regenerado\\la partir de un fósil.",
  ["g3:08180948"] = "Me encantaría ser el bebé\nde un KANGASKHAN.\\pNo me importaría nada ocupar\nel lugar del bebé...\\pY acurrucarme en la bolsa de la\nbarriga de KANGASKHAN.\\pPero los POKéMON son los únicos\nque pueden usar SUSTITUTO...\\p¿Quieres que le enseñe SUSTITUTO\na uno de tus POKéMON?",
  ["g3:08180a32"] = "¿En serio?\n¡Pero si SUSTITUTO está genial!",
  ["g3:08180a57"] = "¿A qué POKéMON quieres que\nle enseñe SUSTITUTO?",
  ["g3:08180a80"] = "¡Ay, lo que daría por acurrucarme\nen la panza de un KANGASKHAN!",
  ["g3:08180abd"] = "Mi padre es el LÍDER del GIMNASIO\nde este pueblo.\\pYo me estoy entrenando para usar\nPOKéMON del tipo VENENO igual\\lque hace mi padre.",
  ["g3:08180b20"] = "La puerta está cerrada...",
  ["g3:08180b34"] = "BLAINE, del GIMNASIO CANELA,\nes un hombre raro que lleva años\\lviviendo aquí.\\pAntes de que construyeran el\nLABORATORIO, ya vivía aquí.",
  ["g3:08180ba0"] = "Los científicos experimentan\nen el edificio quemado.\\pEs el mismo edificio al que llaman\nMANSIÓN POKéMON.",
  ["g3:08180c0d"] = "ISLA CANELA\nLa feroz ciudad del ardiente\\ldeseo.",
  ["g3:08180c3e"] = "LABORATORIO POKéMON",
  ["g3:08180c4a"] = "LÍDER del GIMNASIO POKéMON\nde CANELA: BLAINE\\l¡El maestro de los acertijos!",
  ["g3:08180c90"] = "¡Anda!\n¡Pero si es {PLAYER}!",
  ["g3:08180caa"] = "Eh, soy BILL.\n¡Qué de tiempo!\\pEspero que sigas usando mi sistema\npara PC.\\pOye, ya que hemos coincidido,\n¿qué tal si te quedas un rato?\\pHay una islita hacia el sur,\nllamada ISLA PRIMA.\\pUn colega mío me ha dicho\nque fuera.\\p¿Qué te parece?\n¿Te apetece venirte conmigo?",
  ["g3:08180ddd"] = "Guay, pues venga.",
  ["g3:08180df8"] = "¿No tienes tiempo o qué?\\pBueno, pues vale. De todas formas\nel barco no ha llegado aún.\\pVoy a esperar en el CENTRO\nPOKéMON de ahí.\\pCuando hayas acabado de hacer\ntus cosas, ya sabes dónde estoy.",
  ["g3:08180ead"] = "Anda, el barco de mi amigo\nha llegado también...\\p¡Lo ha mandado expresamente\na CANELA para que pueda ir\\la verlo!",
  ["g3:08180f09"] = "Eh, menudo viajecito, ¿eh?\\pCreo que le has caído genial\na mi colega CELIO.\\pSeguro que le encantará que\nvuelvas a verlo en otra ocasión.\\pSi tienes un TRI-TICKET, puedes\nir siempre en ferry desde el\\lPUERTO de CARMÍN.\\p¡Bueno, gracias por la compañía!",
  ["g3:08181003"] = "¿Qué quieres?\n¡Lárgate!",
  ["g3:0818101f"] = "¡El JEFE dice que invadirá esta\nciudad en nombre del TEAM ROCKET!",
  ["g3:0818105a"] = "¡Fuera de mi camino!\n¡Te lo digo por las buenas!",
  ["g3:08181087"] = "¡AZAFRÁN es del TEAM ROCKET!",
  ["g3:081810a7"] = "¡Ser así me hace sentir tan vivo!",
  ["g3:081810d5"] = "¡Au!\n¡Cuidado por donde caminas!",
  ["g3:081810f5"] = "¡Con SILPH bajo control, podemos\nexplotar a los POKéMON de todo el\\lmundo!\\p¡Nos vamos a forrar, je, je!",
  ["g3:08181159"] = "¿Venciste sin ayuda al TEAM\nROCKET? ¡Qué increíble!",
  ["g3:08181189"] = "¡El TEAM ROCKET se ha marchado!\n¡Ahora podemos salir otra vez!",
  ["g3:081811bf"] = "La gente salió huyendo de aquí\ncuando llegó el TEAM ROCKET.\\pPero ahora todo el mundo puede\nregresar a AZAFRÁN.",
  ["g3:08181225"] = "Vine volando con mi PIDGEOT\ncuando supe lo de SILPH.\\p¿Ya se ha acabado todo?\nMe pierdo las mejores...",
  ["g3:08181286"] = "PIDGEOT: ¡Pid, pid!",
  ["g3:08181299"] = "Vi al JEFE ROCKET escapando\ndel edificio SILPH.",
  ["g3:081812ca"] = "Soy el guarda de seguridad.\\p¡No permito entrar a gente\nsospechosa!",
  ["g3:08181302"] = "Grfiiiuuu...\\p¡Ja! ¡Está durmiendo la siesta!",
  ["g3:08181326"] = "CIUDAD AZAFRÁN\nLa brillante y dorada tierra del\\lcomercio.",
  ["g3:08181354"] = "DOJO-KARATE",
  ["g3:08181362"] = "LÍDER del GIMNASIO POKéMON\nde AZAFRÁN: SABRINA\\l¡Genio de los POKéMON PSÍQUICOS!",
  ["g3:081813aa"] = "PISTAS ENTRENADOR\\pCURA TOTAL cura todo malestar,\ncomo el sueño y las quemaduras.\\pCuesta un poco más, pero merece\nla pena.",
  ["g3:08181452"] = "PISTAS ENTRENADOR\\pLa nueva SUPERBALL ofrece\nmayor velocidad de captura.\\pPruébala con los POKéMON\ndifíciles de atrapar.",
  ["g3:081814b9"] = "EDIFICIO-OFICINAS DE SILPH S.A.",
  ["g3:081814d3"] = "CASA DEL SR. PSÍQUICO",
  ["g3:081814e7"] = "¡Lo último de SILPH!\\pLanzado para ser decisivo...",
  ["g3:08181519"] = "CLUB DE FANS DE ENTRENADORES\nPOKéMON\\pEn el cartel hay garabateados\nun montón de nombres de\\lENTRENADORES...",
  ["g3:08181569"] = "¡En este CLUB de FANS hay gente...\nque de POKéMON nada entiende!\\pNadie tiene ni idea de que LANCE\nes quien mejor pelea.\\p¡Es justo!\n¡Es admirado!\\l¡Todos quieren estar a su lado!",
  ["g3:0818161b"] = "BILL: Bueno, ya estamos aquí.\nEsto es ISLA PRIMA.\\pComo indica su nombre,\nno es la única isla de por aquí.\\pMi amigo CELIO fue el que\nenvió el barco.\\pÉl es el encargado de la red\nlocal de la isla. Se pasa el día\\lcon eso.\\pBueno, que me enrollo como las\npersianas, ¡vamos a ver a CELIO!",
  ["g3:08181726"] = "¡Hola, caracola!\n¿Adónde vamos?",
  ["g3:0818174e"] = "La verdad es que esta isla está\nplantada en medio de la nada,\\lpero bueno...\\pMenos mal que tenemos a un\nchicarrón hecho y derecho como\\lCELIO.\\pMi nieta estaba un poco nerviosa\ncon la llegada del amigo de CELIO.\\p¿Será un POKéMANÍACO?\\pEn fin..., yo lo que sé es que\nestamos encantados con CELIO.",
  ["g3:08181858"] = "Mi nieta estaba un poco nerviosa\npor un reciente descubrimiento.\\pSegún dijo, ahora tenemos conexión\nvía PC con la gente de KANTO.\\pEn fin..., yo lo que sé es que\nestamos encantados con CELIO.",
  ["g3:08181901"] = "Mi nieta estaba un poco nerviosa\npor un reciente descubrimiento.\\pSegún dijo, ahora tenemos conexión\nvía PC con la gente de HOENN.\\pEn fin..., yo lo que sé es que\nestamos encantados con CELIO.\\p¡La verdad es que sería el marido\nperfecto para mi nieta!",
  ["g3:081819e1"] = "ISLA PRIMA\nPunto de encuentro para todos.",
  ["g3:08181a0a"] = "CENTRO DE RED POKéMON\n¡Un mundo POKéMON en conexión!",
  ["g3:08181a4a"] = "¿Qué? ¿Disfrutando del paisaje?\nEl tiempo es fabuloso, ¿eh?",
  ["g3:08181a88"] = "ISLA SECUNDA\nIsla ideal para dos.",
  ["g3:08181aa7"] = "RECREATIVOS\n¡Salta y atrapa!",
  ["g3:08181ac8"] = "¡PELIGRO! ¡FUERTES RÁPIDOS!\nQueda terminantemente prohibido\\lpescar y bañarse.",
  ["g3:08181afe"] = "¡Hola!\n¡Ésta es mi tienda!\\pHemos abierto hace muy poco.\\pAún no tenemos mucha variedad\nde artículos, pero espero que\\lencuentres lo que buscas.",
  ["g3:08181b7c"] = "No sabes cómo te agradecemos\nque hayas rescatado a PEDRITA.\\pGracias a ti, la gente de ISLA\nTERA, tiene otra actitud hacia\\llos habitantes de KANTO.\\pY yo soy de KANTO, ¿sabes?\\pPor los habitantes de ISLA TERA,\nhe aumentado el número\\lde artículos.",
  ["g3:08181c77"] = "¡Eh, yo aquí hago lo que puedo!\n¡Espero que tú, también, {PLAYER}!",
  ["g3:08181cae"] = "¡Hola, {PLAYER}!\n¿Qué tal?\\pHe estado importando artículos\nde otras islas de por ahí.\\pY tengo unas cosas rarísimas.\n¡Échales un vistazo!",
  ["g3:08181d2f"] = "Ese tipo de ahí, vino de CIUDAD\nAZULONA para instalarse aquí.\\pMontó una tienda con su hermano\npequeño.\\pMe parece a mí que no sabía en\nlo que se metía.",
  ["g3:08181dca"] = "El hermano del tendero encontró\ntrabajo en los RECREATIVOS.\\pY pretende ahorrar dinero\npara comprar más artículos\\lpara la tienda.",
  ["g3:08181e47"] = "Oye, oye, ¿sabes una cosa?\\pHace poco, vino un ENTRENADOR\na la ISLA.\\pEra uno de los miembros del ALTO\nMANDO. Se llamaba BRUNO.\\pPero se fue decepcionado cuando\nvio que no quedaban bastones de\\lcaramelo superfuertes.",
  ["g3:08181f28"] = "¡El experto ENTRENADOR sabe\ncomprar objetos raros!",
  ["g3:08181f5d"] = "Hay una señora que vive en una\ncasita en el cabo.\\pEs un poco desconcertante,\n¡le tira los tejos a los POKéMON!",
  ["g3:08181fce"] = "¡Boing! ¡Boing!\n¿Has probado el juego de los\\lsaltos?\\pLos POKéMON que pueden\nparticipar...\\l¡Boing! ¡Boing!\\p¡Algunos dan saltos!\\p¡Y otros, dan saaaaaaaaaaaltos!\\p¿Lo sabías?\n¡Boing! ¡Boing!",
  ["g3:08182061"] = "ISLA TERA\nIsla familiar para familiares.",
  ["g3:0818208b"] = "¡Eeeeeh!\\p¡A partir de hoy, esta isla\nnos pertenece!",
  ["g3:081820c0"] = "¡Aquí no queremos a nadie que nos\nmoleste y nos traiga problemas!\\p¡MARCHAOS A KANTO!",
  ["g3:08182125"] = "Vete a chillar a otra parte,\nnuestro jefe está en camino.\\p¡Cuando llegue, vas a ver de lo\nque somos capaces con las motos!\\p¡Vas a flipar!",
  ["g3:081821a9"] = "¿Cómo? ¡Ni se os ocurra!\n¡FUERA DE LA ISLA AHORA MISMO!",
  ["g3:081821dc"] = "¿Porque tú lo digas?",
  ["g3:081821f1"] = "¿Eres tú el jefe?\n¡A KANTO ahora mismo!",
  ["g3:0818221f"] = "Eh, que yo acabo de llegar,\ncolega.\\pNo entiendo por qué te pones tan\nborde. ¡Menuda bienvenida, majo!",
  ["g3:08182275"] = "Tu pandillita se ha puesto en plan\nchulo con las motos y se ha pasado\\lun pelín.\\pY a la gente de la isla no le ha\nhecho nada de gracia.",
  ["g3:081822fb"] = "Me dejas a cuadros.\\p¡Pero si aquí se aburren hasta\nlas piedras!\\pDeberíais estar agradecidos de\nque hayamos dado vidilla a este\\lmuermo de isla.\\pPero bueno, si insistes en que\nnos vayamos...",
  ["g3:081823c7"] = "Grrrr... Sois unos cobardes...\nY unos pesados...",
  ["g3:081823ed"] = "Pero ¿qué miras? ¿Nunca te han\ndicho que no se debe mirar tan\\ldescaradamente a nadie?\\p¿Quieres algo o qué?",
  ["g3:08182453"] = "Estupendo. Así me gusta, que\nte mantengas al margen de esto.",
  ["g3:0818247d"] = "Eh, eres muy valiente.\nVas a salir perdiendo, pero...",
  ["g3:081824b7"] = "¡¿Qué?!...\nPero ¿tú de dónde sales?",
  ["g3:081824cf"] = "¡Que no se te ocurra reírte!",
  ["g3:081824ef"] = "Pero ¿tú no eres de KANTO?\n¡Pues deberías estar de nuestro\\llado!",
  ["g3:08182521"] = "Bueno, ¡ya está bien!",
  ["g3:08182536"] = "Pero ¿a ti qué te pasa?\n¡Ya te vale!",
  ["g3:08182582"] = "Le dijimos a nuestro jefe que\nviniera ¡y tú incordiando!\\p¡Eres un petardo!",
  ["g3:081825d4"] = "Ufff...",
  ["g3:081825e2"] = "Jefe, ¡no podemos dejar que\nnos saquen los colores!",
  ["g3:08182623"] = "He estado observándote y creo que\nte has pasado.\\p¿Pero tú, de parte de quién estás?\\pAhora te las quieres ver conmigo,\n¿no?",
  ["g3:081826b7"] = "Mira, ya me tienes harto.\n¡Nos piramos!\\p¡Estábamos deseando\nmarcharnos!",
  ["g3:0818271d"] = "¡Hala, que te lo pases bien\nen este petardo de isla!",
  ["g3:0818275a"] = "¡Muchas gracias! ¡La gentuza esa\nha revolucionado al personal!\\pAnda, tus POKéMON están heridos\npor mi culpa...",
  ["g3:081827be"] = "{PLAYER} recibió un RESTAU. TODO.",
  ["g3:081827db"] = "Vaya...\nLa MOCHILA está llena...",
  ["g3:081827f1"] = "Tienes unos POKéMON\nespectaculares.",
  ["g3:08182823"] = "Sería estupendo que alguien como\ntú viviera aquí.\\pEspero que te quedes un tiempo\nal menos.\\p¿Cómo?\n¿Que estás buscando a PEDRITA?\\pPEDRITA se fue en dirección al\nPUENTE UNIÓN hace un rato...",
  ["g3:081828eb"] = "ISLA TERA es la isla más poblada\nde esta zona.\\pVale que no sea la más animada,\npero mejor así que tener a los\\lsalvajes de las motos por aquí.",
  ["g3:0818298a"] = "Voy a entrenar a mi DODUO en el\nBOSQUE BAYA.\\pCuando evolucione, participaré\nen algún juego en ISLA SECUNDA.",
  ["g3:081829f4"] = "DODUO: ¡Dodu, odudodu!",
  ["g3:08182a03"] = "ISLA QUARTA\nLa isla cálida, azul y rara.",
  ["g3:08182a2b"] = "LORELEI ha vuelto.\\pCreo que la vida de la ciudad le\nresultaba demasiado estresante...",
  ["g3:08182a75"] = "LORELEI ha vuelto.\\pCreo que el LAPRAS que tiene,\nes el mismo que atrapó de pequeña.\\pYo creo que se hizo con él\nen la CUEVA GLACIADA...\\pMe parece que lo tiene desde\nentonces.",
  ["g3:08182b37"] = "{RIVAL}: ¡Eh, {PLAYER}!\\p¿Qué estás haciendo en\nARCHI7?\\pDeberías dejar de copiarte de todo\nlo que hago.\\pBueno, yo ya tengo mi HUEVO\nPOKéMON, así que no me queda\\lnada más que hacer en esta isla.\\pNo sé ni para qué te cuento esto,\nseguro que no tienes ni idea de\\llo que es un HUEVO POKéMON.\\pAsí no vas a completar la POKéDEX\nNACIONAL en la vida.\\pPor cierto, he visto a alguien a\nquien conocemos en la isla.\\p¿No te das una vuelta a ver\nquién es?\\l¿No te pica la curiosidad?\\pYo me largo, no tengo tiempo.\\p¡Nos vemos!",
  ["g3:08182ce3"] = "¡Me has encontrado!\n¡No se lo digas a LORELEI!\\p¿Sabías que LORELEI tiene un\nmontón de muñecos de peluche?\\p¡Cada vez que vuelve a ISLA\nQUARTA, aumenta la colección!",
  ["g3:08182d8e"] = "¡Uyyy, qué fresquito!\\pMe he hecho un granizado con\nhielo de la CUEVA GLACIADA.\\p¡Está fresquito y riquísimo!",
  ["g3:08182deb"] = "CASA DE LORELEI",
  ["g3:08182dfb"] = "ISLA INTA\nIsla que marca el paso del tiempo.",
  ["g3:08182e26"] = "Uf, qué rollo, yo quería jugar\nen el PRADO...\\pPero han puesto un raro edificio\nen medio y ya no hay dónde jugar.",
  ["g3:08182e96"] = "Últimamente ha habido mucho\nmovimiento por aquí...\\pY la pesca no ha sido buena...\nMmmm...",
  ["g3:08182f01"] = "Son pocos los que vienen\na esta zona.\\pSi me pusiera a entrenar aquí,\nseguro que me haría superfuerte.\\pSí, requetefuerte-fortísimo.\\p¿Quieres aprender el movimiento\nDANZA ESPADA?",
  ["g3:08182fc1"] = "Bueno, como quieras.",
  ["g3:08182fd9"] = "¿A qué POKéMON quieres que\nse lo enseñe?",
  ["g3:0818300d"] = "Lo suyo sería que cada vez nos\nhiciéramos más y más fuertes, ¿eh?",
  ["g3:08183046"] = "ISLA SÉTIMA\nIsla de aventura infinita.",
  ["g3:0818306c"] = "A estas islas las llamamos ARCHI7\nporque son siete, je.\\pO, por lo menos, es lo que la\ngente joven cree.\\pPero en realidad es porque las\nislas se crearon en siete días.",
  ["g3:08183143"] = "Esta isla es prácticamente virgen,\napenas ha sufrido modificaciones.\\pPor ello, es peligroso y difícil\nhacer escalada por aquí.",
  ["g3:081831c6"] = "ISLA EXTA\nIsla de la fortuna y el saber.",
  ["g3:081831ef"] = "Si sigues por aquí, llegarás a la\nVÍA ACUÁTICA.\\pCuando alcances la VÍA,\nve hacia el sur si quieres ir\\lal VALLE de las RUINAS.",
  ["g3:08183255"] = "Al estar tan lejos de las ciudades,\npor la noche el cielo se ve muy\\ldespejado.",
  ["g3:0818329d"] = "¡Hola!\nTrabajo en una TIENDA POKéMON.\\pTenemos muchas cosas. Visítanos\nen CIUDAD VERDE.\\p¡Mira, te daré una muestra!\n¡Aquí tienes!",
  ["g3:08183347"] = "¡También tenemos POKé BALLS\npara capturar los POKéMON!",
  ["g3:08183387"] = "{PLAYER} puso la POCIÓN\nen el BOLSILLO de OBJETOS\\lde la MOCHILA.",
  ["g3:081833b9"] = "¿Ves esos bordes del camino?\\pDan miedo, pero puedes saltar\npor encima de ellos.\\p¡De esa forma podrás volver más\nrápidamente a PUEBLO PALETA!",
  ["g3:0818343a"] = "RUTA 1:\nPUEBLO PALETA - CIUDAD VERDE",
  ["g3:0818345e"] = "RUTA 2:\nCIUDAD VERDE - CIUDAD PLATEADA",
  ["g3:08183482"] = "CUEVA DE DIGLETT",
  ["g3:08183491"] = "¡Uff!... Voy a descansar.\nUfff...\\p¡Ese túnel a CELESTE es agotador!",
  ["g3:081834e6"] = "¡Nos vimos en el BOSQUE VERDE!",
  ["g3:08183509"] = "¡Has ganado otra vez!",
  ["g3:0818351c"] = "¡Hay otros tipos de POKéMON\ndiferentes a los del bosque!",
  ["g3:08183560"] = "¡Hola!\n¡Me gustan los pantalones cortos!\\p¡Son muy cómodos!",
  ["g3:081835a0"] = "¡No me lo puedo creer!",
  ["g3:081835b4"] = "¿Estás guardando a tus POKéMON\nen el PC?\\p¡Cada CAJA puede tener 30\nPOKéMON!",
  ["g3:08183616"] = "Estabas mirándome, ¿verdad?",
  ["g3:0818363f"] = "¡Eres de lo que no hay!",
  ["g3:0818364c"] = "¡Deja de mirarme si no quieres\nluchar!",
  ["g3:08183682"] = "¿Entrenas POKéMON?\n¡Pues luchemos!",
  ["g3:081836b3"] = "¡Con nuevos POKéMON te habría\nganado!",
  ["g3:081836d9"] = "¡Si una CAJA de POKéMON del PC\nestá llena, cambia a otra CAJA!",
  ["g3:0818371b"] = "¡Esa mirada tuya fue de lo más\nmisteriosa!",
  ["g3:08183746"] = "¡Sé amable!",
  ["g3:0818374f"] = "¡Para evitar luchar, procura que\nno te vean!",
  ["g3:08183786"] = "¡Oye!\n¡No llevas pantalón corto!",
  ["g3:081837bd"] = "¡He perdido!\n¡He perdido!",
  ["g3:081837cf"] = "Llevo pantalones cortos hasta\nen invierno.",
  ["g3:08183807"] = "¡Puedes luchar contra mis nuevos\nPOKéMON!",
  ["g3:08183837"] = "¡Estoy acabado!",
  ["g3:08183849"] = "¡Los POKéMON entrenados son más\nfuertes que los salvajes!",
  ["g3:0818387a"] = "¡Oye!\n¿Por qué me has tocado?",
  ["g3:08183891"] = "¿Eso es todo?",
  ["g3:0818389c"] = "La RUTA 4 está debajo del MT.\nMOON.",
  ["g3:081838c0"] = "RUTA 3:\nHACIA EL MT. MOON",
  ["g3:081838d7"] = "¡Auch! ¡Tropecé con un POKéMON\nrocoso, GEODUDE!",
  ["g3:08183906"] = "¡Vine a recoger mis hongos\nPOKéMON!",
  ["g3:08183938"] = "¡Oh! ¡Mi pobre hongo POKéMON!",
  ["g3:08183957"] = "¡Puede que no haya más hongos\npor aquí!\\pCreo que ya los tengo todos.",
  ["g3:0818399b"] = "MT. MOON:\nEntrada al túnel",
  ["g3:081839b4"] = "RUTA 4:\nMT. MOON - CIUDAD CELESTE",
  ["g3:081839d5"] = "¡Un puñetazo con rabia\ncontenida!\\p¡Condimentado con fuerza\ndescomunal!\\p¡Cuando no queda energía,\nMEGAPUÑO es el ataque definitivo!\\p¿Qué?\n¿Se lo enseño a algún POKéMON?",
  ["g3:08183a83"] = "¡Cuando comprendas el significado\nde MEGAPUÑO, volverás!",
  ["g3:08183abf"] = "¿A qué POKéMON quieres que se\nlo enseñe?",
  ["g3:08183ae2"] = "¡Ya usamos los puños de la\nmisma forma!\\p¡Hala, vete antes de que le entren\nganas de luchar a mi colega:\\les un flipado de las patadas!",
  ["g3:08183b74"] = "¡Una buena patada con rabia\ncontenida!\\p¡Condimentada con fuerza\ndescomunal!\\p¡Cuando no quede energía,\nMEGAPATADA es el ataque\\ldefinitivo!\\p¿Qué?\n¿Se lo enseño a algún POKéMON?",
  ["g3:08183c25"] = "¡Cuando comprendas el significado\nde MEGAPATADA, volverás llorando!",
  ["g3:08183c68"] = "¿A qué POKéMON quieres que se\nlo enseñe?",
  ["g3:08183c94"] = "¡Ya damos patadas de la\nmisma forma!\\p¡Hala, vete antes de que le entren\nganas de luchar a mi colega:\\les un flipado de los puñetazos!",
  ["g3:08183d26"] = "¡Anda, la MEDALLA ROCA!\nTe la ha dado BROCK, ¿no?\\pBROCK es, además de fuerte, guay.\nTodos lo respetan y admiran mucho.\\pYo quiero ser LÍDER de GIMNASIO\ncomo él.",
  ["g3:08183dd4"] = "VÍA SUBTERRÁNEA:\nCIUDAD CELESTE - CIUDAD CARMÍN",
  ["g3:08183e04"] = "¿Quién está ahí?\n¡Deja de espiarnos!",
  ["g3:08183e2a"] = "¡Sencillamente, no puedo ganar!",
  ["g3:08183e3c"] = "(Pues sí que...)",
  ["g3:08183e4e"] = "¡Perdona!\n¡Esta conversación es privada!",
  ["g3:08183e79"] = "¡Odio perder!",
  ["g3:08183e8d"] = "(Pues sí que...)",
  ["g3:08183e9f"] = "No hay muchos bichos por aquí.",
  ["g3:08183ec0"] = "¡No!\n¿Estás de broma?",
  ["g3:08183ed4"] = "Me gustan los bichos. Voy a\nregresar al BOSQUE VERDE.",
  ["g3:08183f07"] = "¿Qué?\n¿Quieres hablar conmigo?",
  ["g3:08183f24"] = "¡Has empezado tú!",
  ["g3:08183f51"] = "Debería llevar más POKéMON\npara protegerme.",
  ["g3:08183f90"] = "¿Yo?\nPues vale. ¡Jugaré!",
  ["g3:08183fab"] = "¡No ha podido ser!",
  ["g3:08183fc4"] = "¡Quiero ser más fuerte!\n¿Cuál es tu secreto?",
  ["g3:08183ff0"] = "¡Jamás te había visto por aquí!\n¿Eres fuerte?",
  ["g3:0818401a"] = "¡Eres demasiado fuerte!",
  ["g3:0818402b"] = "¿Es débil mi POKéMON o soy yo\nmuy malo?",
  ["g3:08184067"] = "VÍA SUBTERRÁNEA:\nCIUDAD CELESTE - CIUDAD CARMÍN",
  ["g3:08184097"] = "VÍA SUBTERRÁNEA:\nCIUDAD AZULONA - PUEBLO LAVANDA",
  ["g3:081840c5"] = "Parece que sabes mucho sobre\nPOKéMON, pero...\\l¿Qué tal en química?",
  ["g3:08184100"] = "¡Ah!\n¡Fusión nuclear!",
  ["g3:0818410e"] = "¡Se me da mejor en el cole!",
  ["g3:0818412f"] = "¡Muy bien!\n¡Echemos los dados!",
  ["g3:0818414d"] = "¡Vaya!\n¡Me he quedado corto!",
  ["g3:08184162"] = "¡Hoy no es mi día de suerte!",
  ["g3:0818417c"] = "¡Necesitas una buena estrategia!",
  ["g3:081841b6"] = "¡No es lógico!",
  ["g3:081841c8"] = "Usa a GRIMER primero... y...\ny... después...",
  ["g3:081841ed"] = "¡Me gustan los NIDORAN\ny por eso los colecciono!",
  ["g3:08184210"] = "Pero ¿por qué?",
  ["g3:0818421b"] = "¡Cuando los POKéMON crecen\nse vuelven muy feos!\\l¡No me gustan cuando evolucionan!",
  ["g3:08184257"] = "¡Me gusta el colegio, y los\nPOKéMON!",
  ["g3:0818427a"] = "Prefiero el colegio, está claro\nque se me da mucho mejor.",
  ["g3:081842b3"] = "Querría darme una vuelta, pero...\\pLa entrada a AZAFRÁN está\nbloqueada...",
  ["g3:08184321"] = "¡MEOWTH es muy mono, meow, meow!",
  ["g3:08184346"] = "¡Meow!",
  ["g3:08184350"] = "¡Creo que PIDGEY y RATTATA\ntambién son muy monos!",
  ["g3:0818437a"] = "¡Debemos de tener un aspecto muy\ntonto!",
  ["g3:081843a6"] = "¡Mira lo que has hecho!",
  ["g3:081843d2"] = "El guardián de la entrada a\nAZAFRÁN no nos dejará pasar.\\p¡Sé que hace su trabajo,\npero es que es lo peor!",
  ["g3:08184432"] = "¡Soy un jugón errante!",
  ["g3:0818444f"] = "¡He perdido el gran premio!",
  ["g3:08184466"] = "¡Cuando juego y entreno POKéMON\nno puedo parar!",
  ["g3:081844ac"] = "¿Qué POKéMON es mono, redondo\ny blando?",
  ["g3:081844d6"] = "¡Ya basta!\\p¡No seas cruel con mis CLEFAIRY!",
  ["g3:081844fd"] = "He leído que CLEFAIRY evoluciona\ncuando es expuesto a una PIEDRA\\lLUNAR.\\pLo leí en el DIARIO POKéMON.\n¿Será verdad?",
  ["g3:08184576"] = "VÍA SUBTERRÁNEA:\nCIUDAD AZULONA - PUEBLO LAVANDA",
  ["g3:081845a4"] = "TITA: La fuerza que tienen los\nhermanos gemelos es enorme,\\l¿lo sabías?",
  ["g3:081845d0"] = "TITA: Pero si hemos unido nuestras\nfuerzas...",
  ["g3:081845f2"] = "TITA: Yo atrapé mi POKéMON\ncon LIN.",
  ["g3:08184616"] = "TITA: Si no tienes dos POKéMON,\nno podemos luchar contigo.",
  ["g3:0818464a"] = "LIN: ¡No vas a poder con estas\ngemelas!",
  ["g3:08184675"] = "LIN: Pues sí que has podido...",
  ["g3:0818468b"] = "LIN: Yo crío a mi POKéMON\ncon TITA.",
  ["g3:081846af"] = "LIN: Nos gustaría luchar contigo,\npero necesitas dos POKéMON.",
  ["g3:081846e2"] = "¡Mi moto está como una moto!",
  ["g3:081846fc"] = "No sé qué me ha pasado...",
  ["g3:08184719"] = "Se me ha enganchado césped\nen los radios de las ruedas...",
  ["g3:08184742"] = "Apártate si no quieres que te pase\npor encima.",
  ["g3:08184767"] = "Tú vas en serio, ¿no?",
  ["g3:0818477a"] = "Tampoco te pongas en plan tonto\npor haber ganado.",
  ["g3:081847b7"] = "¡Tienes algunos POKéMON!\n¡En guardia!",
  ["g3:081847df"] = "¡Me has dejado...!",
  ["g3:081847f0"] = "El túnel que hay cerca de aquí\nestá muy oscuro.\\pNecesitarás DESTELLO para poder\ncruzarlo sin problemas.",
  ["g3:08184844"] = "¿Quién anda por ahí con esos\nPOKéMON con tan buen aspecto?",
  ["g3:0818487e"] = "¡Esto se acabó!",
  ["g3:08184890"] = "¡Sigue caminando!",
  ["g3:0818489e"] = "¡Tomaré el TÚNEL ROCA para ir\na PUEBLO LAVANDA!",
  ["g3:081848cc"] = "¡Soy muy malo! ¡Buaaa!",
  ["g3:081848de"] = "¿Vas a ir también al TÚNEL ROCA?",
  ["g3:081848ff"] = "¡No te andes con contemplaciones!",
  ["g3:0818491c"] = "¡Eres demasiado!",
  ["g3:08184931"] = "¡Tienes madera!\n¡Buena suerte!",
  ["g3:0818495e"] = "¡Ja!\n¡Qué bien! ¡Me estaba aburriendo!",
  ["g3:0818497f"] = "¡Sigue luchando!\\pEspera, ¡si no tengo más POKéMON!",
  ["g3:081849b0"] = "¡Debes de ser muy valiente para\ndesafiarme!",
  ["g3:081849df"] = "¡Eh!\n¿Me enseñas la fuerza que tienes?",
  ["g3:08184a04"] = "¿Qué ha pasado?",
  ["g3:08184a11"] = "¡Vaya, sí que tienen fuerza\nlos niños de hoy!",
  ["g3:08184a2f"] = "¡Madrugo todos los días para\ncuidar a mis POKéMON CAPULLO!",
  ["g3:08184a6a"] = "¿QUÉ?\\p¡Qué gran pérdida de tiempo!",
  ["g3:08184a8c"] = "Tengo que recoger algo más que\nbichos para ser más fuerte...",
  ["g3:08184abe"] = "¡Jajajaja!\n¡Vamos, adelante!",
  ["g3:08184ad5"] = "¡Jajajaja!\n¡Me has ganado!",
  ["g3:08184af1"] = "¡Jajaja!\n¡Los más fuertes siempre reímos!",
  ["g3:08184b18"] = "¡Adelante mis geniales POKéMON\nBICHO!",
  ["g3:08184b32"] = "Mis bichos...",
  ["g3:08184b3b"] = "Desde luego a ti no te gustan\nlos POKéMON BICHO...",
  ["g3:08184b66"] = "RUTA 9:\nCIUDAD CELESTE - TÚNEL ROCA",
  ["g3:08184b8a"] = "¿Eres como los POKéMANÍACOS?\n¿Quieres ver mi colección?",
  ["g3:08184be5"] = "¿Qué?\n¡No estoy enfadado!",
  ["g3:08184bfb"] = "¡En casa tengo más POKéMON\nsuperraros!",
  ["g3:08184c1d"] = "¡A-aa-a-a!",
  ["g3:08184c2d"] = "¡A-aa!\n¡No me estoy riendo!\\l¡Es a-a-a-lergia! ¡A-a-a-chús!",
  ["g3:08184c60"] = "¡A-a-a-chús!\n¡A-chús!\\lUfff...",
  ["g3:08184c86"] = "¡Eh, hola!\n¿Quieres ver mis POKéMON?",
  ["g3:08184ca7"] = "¡Oh, no!\n¡Mis POKéMON!",
  ["g3:08184cbb"] = "¡No me gustas cuando ganas!",
  ["g3:08184cf1"] = "He estado varias veces en un\nGIMNASIO POKéMON.\\p¡Y he perdido siempre!",
  ["g3:08184d31"] = "¡Volví a perder!",
  ["g3:08184d4d"] = "Hay algunos POKéMANÍACOS por ahí.\\pY la verdad, creo que no pintan\nnada en la montaña, ¿no?",
  ["g3:08184daa"] = "¡Ah!\n¡Me encanta el aire de montaña!",
  ["g3:08184dce"] = "¡Me has espabilado!",
  ["g3:08184de4"] = "A mí el aire de la montaña\nme atonta.",
  ["g3:08184e04"] = "¡Me siento débil tras la escalada!",
  ["g3:08184e3b"] = "No estaba lo suficientemente\npreparada...",
  ["g3:08184e5e"] = "¡Estos POKéMON son tan toscos!\\p¡Debería haber alguno rosa con\nbonitas flores!",
  ["g3:08184ec5"] = "TÚNEL ROCA\nDesvío hacia PUEBLO LAVANDA.",
  ["g3:08184ee9"] = "TÚNEL ROCA",
  ["g3:08184ef5"] = "CENTRAL ENERGÍA",
  ["g3:08184f01"] = "¡Gana, pierde o empata!",
  ["g3:08184f15"] = "¡Vale!\n¡Has ganado!",
  ["g3:08184f2e"] = "¡Los POKéMON son vida!\n¡Y vivir es jugar!",
  ["g3:08184f5d"] = "¡Competición!\n¡No me canso de competir!",
  ["g3:08184f7e"] = "¡He perdido la oportunidad!",
  ["g3:08184f8e"] = "¡No se puede ser cobarde\nen el mundo de los POKéMON!",
  ["g3:08184fbd"] = "¡Vamos allá, pero no hagas\ntrampas!",
  ["g3:08184fd8"] = "¿Qué?\n¡No puede ser!",
  ["g3:08184fef"] = "¡He hecho lo que he podido!\n¡Y no me arrepiento!",
  ["g3:08185011"] = "¡Cuidado!\n¡Estoy colocando unos cables!",
  ["g3:08185037"] = "¡Electrizante!",
  ["g3:0818504a"] = "¡Di a todos que ahorren energía!",
  ["g3:0818506a"] = "¡Me acabo de hacer ENTRENADOR!\n¡Pero creo que puedo ganar!",
  ["g3:0818509b"] = "¡Mis POKéMON han perdido!",
  ["g3:081850cf"] = "¿Qué quieres?\n¡Déjame en paz!",
  ["g3:081850e9"] = "¡Ja, ja, ja!\n¡No he perdido nunca!",
  ["g3:08185105"] = "¡La primera vez que pierdo!",
  ["g3:08185114"] = "¡Has tenido mucha suerte!",
  ["g3:08185135"] = "Nunca he ganado...",
  ["g3:0818514e"] = "Lo veía venir...",
  ["g3:08185161"] = "Has tenido mucha suerte.",
  ["g3:0818517b"] = "¡Soy el mejor de mi clase!",
  ["g3:081851ac"] = "¡Vaya! ¡Mis POKéMON deberían\nser más fuertes!",
  ["g3:081851d2"] = "Hay un POKéMON muy gordo\nque baja de las montañas.\\pSeguro que es muy fuerte.",
  ["g3:08185236"] = "¡Cuidado con esos cables!",
  ["g3:08185250"] = "¡Uaauu!\n¡Vaya chispazo!",
  ["g3:08185266"] = "¡Más vale que vuelva al trabajo!",
  ["g3:08185285"] = "¡Mis POKéMON ya deberían\nestar listos!",
  ["g3:081852c1"] = "¡Soy demasiado joven!",
  ["g3:081852e3"] = "¡Voy a buscarme unos más fuertes!",
  ["g3:08185308"] = "CUEVA DE DIGLETT",
  ["g3:08185317"] = "¡Un POKéMON dormido bloquea\nel camino!",
  ["g3:08185354"] = "¡SNORLAX se ha despertado!\\p¡Se ha enfadado mucho\ny te quiere atacar!",
  ["g3:08185383"] = "SNORLAX se ha calmado.\n¡Y tras bostezar se ha marchado\\la las montañas!",
  ["g3:081853cc"] = "¿Quieres usar la POKé FLAUTA?",
  ["g3:081853e8"] = "{PLAYER} tocó la POKé FLAUTA.",
  ["g3:08185402"] = "¡Bien!\n¡Ha picado algo!",
  ["g3:0818541b"] = "¡Bah!\n¡Era muy pequeñajo!",
  ["g3:08185432"] = "¡Alto!\n¡Mi sedal está enganchado!",
  ["g3:0818544e"] = "¡Ten paciencia!\n¡Pescar requiere tiempo!",
  ["g3:08185475"] = "¡Ése se escapó!",
  ["g3:08185488"] = "¡Con una CAÑA mejor podría pescar\nmejores POKéMON!",
  ["g3:081854b9"] = "¿Has encontrado una PIEDRA LUNAR?",
  ["g3:081854ed"] = "¡Auuuu!",
  ["g3:081854f2"] = "¡Podría haber transformado a mis\nPOKéMON con una PIEDRA LUNAR!\\p¡Y podría haber ganado!",
  ["g3:08185547"] = "¡Soy un experto en electricidad!\\pPero no sé nada sobre los POKéMON\nde mar.",
  ["g3:0818559b"] = "¡Se acabó!",
  ["g3:081855a6"] = "El agua conduce la electricidad.\n¡Deberías poder atrapar a los\\lPOKéMON de mar!",
  ["g3:081855e1"] = "¡El PESCADOR LOCO contra alguien\nque no tiene idea sobre POKéMON!",
  ["g3:08185606"] = "¡Te has pasado!",
  ["g3:08185616"] = "¡Me has ganado con los POKéMON,\npero yo soy muy bueno pescando!\\pSupongo que hay que hacer lo que\nmejor se le da a cada uno...",
  ["g3:08185682"] = "A mí me encanta pescar, ¡pero\nes que no pican ni a la de tres!",
  ["g3:081856d0"] = "No es fácil...",
  ["g3:081856df"] = "Está bien.\nPerder ya no me importa.",
  ["g3:0818570e"] = "¡Nunca se sabe lo que puedes\npescar!",
  ["g3:08185744"] = "¡He perdido!",
  ["g3:0818574d"] = "Es fácil pescar MAGIKARP,\n¡son tan débiles!",
  ["g3:08185797"] = "RUTA 12:\nLAVANDA, al norte",
  ["g3:081857b3"] = "ZONA DE PESCA",
  ["g3:081857c5"] = "ARE: Si gano, le pediré a AGA\nque se case conmigo.",
  ["g3:081857f1"] = "ARE: ¿Puedes dejarnos ganar,\npor favor?",
  ["g3:0818581f"] = "ARE: AGA, ¡lo siento, cariño!",
  ["g3:08185842"] = "ARE: AGA y yo vamos a estar juntos\ntoda la vida.\\p¡Y no lucharemos hasta que no\ntengas dos POKéMON!",
  ["g3:081858a6"] = "AGA: Oye, ARE...\\pSi ganamos, ¡me caso contigo!",
  ["g3:081858d0"] = "AGA: Oh... ¿Por qué?",
  ["g3:081858e2"] = "AGA: ¡ARE, eres medio lelo! ¡Todo\nse ha fastidiado por tu culpa!",
  ["g3:08185908"] = "AGA: ¡No pienso luchar sin mi ARE!\\p¿No tienes dos POKéMON?",
  ["g3:08185955"] = "¡Mis pájaros POKéMON quieren\npelear!",
  ["g3:0818597e"] = "¿Perdió mi combinación de pájaros?",
  ["g3:081859a2"] = "Mis POKéMON parecen felices\naunque hayan perdido.",
  ["g3:081859cf"] = "¡Dicen que soy muy buena\npara ser tan pequeña!",
  ["g3:081859ec"] = "¡Oh!\n¡He perdido!",
  ["g3:081859f9"] = "Quiero ser una gran ENTRENADORA.\nVoy a entrenarme mucho.",
  ["g3:08185a37"] = "¡Qué chulas son tus MEDALLAS!",
  ["g3:08185a56"] = "¡No he estado a la altura!",
  ["g3:08185a62"] = "¡Sé que lograste esas MEDALLAS\nde los LÍDERES del GIMNASIO!",
  ["g3:08185a91"] = "Mis simpáticos POKéMON quieren\nconocerte.",
  ["g3:08185ac1"] = "¡Uauu!\n¡Me has machacado!",
  ["g3:08185ade"] = "¡Tienes que hacer luchar a tus\nPOKéMON para fortalecerlos!",
  ["g3:08185b12"] = "¡Una vez encontré CARBURANTE\nen una cueva!",
  ["g3:08185b48"] = "¡Lo he hecho fatal!",
  ["g3:08185b67"] = "El CARBURANTE aumentó la\nVELOCIDAD de mis POKéMON.",
  ["g3:08185b8f"] = "No voy a perder.\n¡El viento sopla en mi dirección!",
  ["g3:08185bca"] = "¡El viento ha cambiado!",
  ["g3:08185bdb"] = "He perdido. Creo que usaré\nVOLAR para ir a casa.",
  ["g3:08185bfc"] = "¡Claro que jugaré contigo!",
  ["g3:08185c1f"] = "¡Oh!\n¡Qué salvaje eres!",
  ["g3:08185c35"] = "¿Cuál es más fuerte, un POKéMON\nmacho o hembra?",
  ["g3:08185c69"] = "¿Quieres jugar conmigo\na POKéMON?",
  ["g3:08185c95"] = "¿Ya se ha terminado?",
  ["g3:08185ca8"] = "¡No sé nada sobre los POKéMON!\n¡Me gustan los más chulos!",
  ["g3:08185d05"] = "¿Y tú qué miras?",
  ["g3:08185d1d"] = "¡Vaya!\n¡Qué patinazo!",
  ["g3:08185d33"] = "¡Olvídame!",
  ["g3:08185d3d"] = "¡Me encantan los pájaros POKéMON!",
  ["g3:08185d7b"] = "¡Me he quedado sin energía!",
  ["g3:08185d89"] = "Ojalá pudiera volar como PIDGEY\ny PIDGEOTTO...",
  ["g3:08185db7"] = "PISTAS ENTRENADOR\\p¡Mira a la izquierda de ese poste!",
  ["g3:08185def"] = "PISTAS ENTRENADOR\\p¡Usa SELECT para cambiar objetos\nen la ventana OBJETOS!",
  ["g3:08185e2c"] = "RUTA 13:\nPUENTE SILENCIO, al norte",
  ["g3:08185e4d"] = "¡Usa las MT para enseñar a tus\nPOKéMON buenos movimientos!",
  ["g3:08185e81"] = "¡No lo he hecho muy bien!",
  ["g3:08185e9c"] = "Tienes MO, ¿no? Los POKéMON\njamás olvidarán esos movimientos.",
  ["g3:08185edf"] = "Mis pájaros POKéMON deberían\npoder luchar.",
  ["g3:08185f0b"] = "¡No estoy listo!",
  ["g3:08185f1a"] = "Necesitan saber mejores ataques.",
  ["g3:08185f46"] = "¡Se venden MT en AZULONA!\n¡Pero pocas personas tienen MO!",
  ["g3:08185fae"] = "¡Ayy! ¡Qué mal!",
  ["g3:08185fbb"] = "Enseña a tus POKéMON ataques\nde sus mismos tipos para conseguir\\lmás potencia.",
  ["g3:08186021"] = "¿Has enseñado a VOLAR a tus\npájaros POKéMON?\\p¡Es genial para ir por el cielo!",
  ["g3:0818607c"] = "¡Qué forma de perder!",
  ["g3:08186091"] = "¡Adoro a los pájaros POKéMON!\n¡Son los que me gusta criar!",
  ["g3:081860d9"] = "¿Has oído hablar de los\nmisteriosos seres alados?",
  ["g3:0818610a"] = "¿Qué?\n¿Cómo he podido perder?",
  ["g3:0818611d"] = "Los misteriosos seres alados son\nlegendarios pájaros POKéMON.\\pHay tres: ARTICUNO, ZAPDOS\ny MOLTRES.",
  ["g3:0818618e"] = "¡No me apetece!\nPero vale.",
  ["g3:081861b3"] = "¡Lo sabía!",
  ["g3:081861be"] = "¡No es que sea tan importante\nganar o perder!",
  ["g3:081861f7"] = "¡Venga, venga!\n¡Vamos, vamos! ¡Adelante!",
  ["g3:08186223"] = "¡Arg!\n¡He perdido! ¡Lárgate!",
  ["g3:08186239"] = "¿Qué, qué, qué?\n¿Qué quieres?",
  ["g3:08186263"] = "¡Perfecto!\n¡Así pasaré el rato!",
  ["g3:08186291"] = "¿Qué?\n¿¡Tú!?",
  ["g3:0818629d"] = "¡Entrenar POKéMON es un rollo!",
  ["g3:081862bd"] = "¡Salimos por aquí porque hay\nmás espacio!",
  ["g3:081862ef"] = "¡Descalificado!",
  ["g3:081862f8"] = "¡Muy bien!\n¡Tus POKéMON son superfuertes!\\p¡La fuerza mola!\n¡Y tú lo sabes!",
  ["g3:08186344"] = "¿Quieres pelear con tus POKéMON?\n¡Pues vale!",
  ["g3:08186362"] = "¡Pulverizado!",
  ["g3:0818636e"] = "¡Ya sabes quién ganaría\nsi peleáramos tú y yo!",
  ["g3:08186399"] = "RUTA 14:\nCIUDAD FUCSIA, al oeste",
  ["g3:081863b7"] = "LENA: TEA, vamos a poner todo\nde nuestra parte.",
  ["g3:081863ea"] = "LENA: Vaya, snif, snif...\nHemos perdido, ¿verdad?",
  ["g3:0818640d"] = "LENA: ¿Hemos perdido por mi culpa?",
  ["g3:0818642e"] = "LENA: Lucharemos cuando tengas\ndos POKéMON.",
  ["g3:0818645b"] = "TEA: LENA, ¡vamos allá!\n¡A por todas!",
  ["g3:08186487"] = "TEA: ¡Eeeh! ¡No es justo!",
  ["g3:0818649c"] = "TEA: ¡LENA, no llores! ¡Ya lo\nharemos mejor la próxima vez!",
  ["g3:081864d3"] = "TEA: ¿Quieres luchar?\n¡Te hacen falta dos POKéMON!",
  ["g3:0818650b"] = "¡Déjame probar los POKéMON\nque acabo de cambiar!",
  ["g3:08186549"] = "¡No ha sido suficiente!",
  ["g3:0818655a"] = "No puedes variar el mote de ningún\nPOKéMON que hayas cambiado.\\p¡El ENTRENADOR original es el\núnico que puede!",
  ["g3:081865d3"] = "¡Pareces manejable!\n¡Creo que podría vencerte!\\p¡Voy a intentarlo!",
  ["g3:08186612"] = "No, ¡muy mal!",
  ["g3:0818661d"] = "¡Me dan miedo los MOTORISTAS,\nson gamberros, horribles!",
  ["g3:0818664f"] = "¡Silbando puedo llamar a los\npájaros POKéMON!",
  ["g3:0818667a"] = "¡Ooh!\n¡Qué tragedia!",
  ["g3:0818668d"] = "Puede que no esté hecho para\nluchar contra otros.",
  ["g3:081866d1"] = "Mis pájaros están temblando.\nEres muy fuerte, ¿no?",
  ["g3:08186707"] = "¡Lo que pensaba!",
  ["g3:0818671a"] = "No sé si decirte esto, supongo\nque ya lo sabes...\\p¿Sabías que los movimientos\ncomo TERREMOTO o FISURA\\lno afectan a los pájaros?",
  ["g3:0818678b"] = "¡Oh!\n¡Mira qué encanto!",
  ["g3:081867c1"] = "¡Pensaba que eras un encanto!",
  ["g3:081867da"] = "¡Te perdono!\n¡Eres adorable!",
  ["g3:0818680c"] = "¡Cuido POKéMON porque vivo sola\ny hacen que me sienta segura!",
  ["g3:08186841"] = "¡Yo no quería un final así!",
  ["g3:0818686f"] = "¡Me gusta ir a casa para estar\ncon mis POKéMON!\\pEs una tranquilidad...",
  ["g3:081868b6"] = "¡Oye! ¡Ven aquí!\n¡Mira esto!",
  ["g3:081868e8"] = "¡No sé qué decir!",
  ["g3:081868f1"] = "¡Sólo se vive una vez, y yo vivo\ncomo un forajido!\\l¡NORMAS del TEAM ROCKET!",
  ["g3:08186936"] = "¡Mira, colega, si pierdes contra\nmí, todo tu dinero será mío!",
  ["g3:08186968"] = "¡No puede ser!",
  ["g3:0818697c"] = "¡Oye, que lo del dinero era broma!\n¡No me hagas caso!",
  ["g3:081869ba"] = "¿Qué mola?\n¡Cambiar POKéMON!",
  ["g3:081869e6"] = "¡He dicho cambiar!",
  ["g3:081869f4"] = "¡Cambio POKéMON con mis amigos!",
  ["g3:08186a22"] = "¿Quieres jugar con mis POKéMON?",
  ["g3:08186a40"] = "¡Estaba demasiado impaciente!",
  ["g3:08186a55"] = "¡Me entrenaré con gente más débil!",
  ["g3:08186a77"] = "RUTA 15:\nCIUDAD FUCSIA, al oeste",
  ["g3:08186a95"] = "TINA: Eres genial. ¿Luchamos para\nque aprenda mi hermano?",
  ["g3:08186acb"] = "TINA: ¡TIN, concéntrate! ¡Hay que\nconcentrarse en lo que se hace!",
  ["g3:08186b0a"] = "TINA: Tenemos que hacer algo,\n¡debemos entrenarnos más!",
  ["g3:08186b46"] = "TINA: ¿Quieres desafiarnos?\n¡Pues necesitas dos POKéMON!",
  ["g3:08186b89"] = "TIN: Mi hermana se asusta cuando\nperdemos.",
  ["g3:08186bb1"] = "TIN: Vaya, hermanita, lo siento...",
  ["g3:08186bd2"] = "TIN: Mi hermana se pone un poco\npesada...",
  ["g3:08186bfe"] = "TIN: ¿Te gustaría luchar\ncon nosotros?\\p¡Pues vente con dos POKéMON!",
  ["g3:08186c4d"] = "¿Qué quieres?",
  ["g3:08186c5f"] = "¡No te atrevas a reírte!",
  ["g3:08186c75"] = "Nos gusta correr por aquí.\n¿Y a ti?",
  ["g3:08186ca2"] = "¡Bonita BICI!\n¡Dámela!",
  ["g3:08186cbb"] = "¡Fuera de combate!",
  ["g3:08186cc5"] = "¡Olvídalo, nadie necesita tu BICI!",
  ["g3:08186ce5"] = "¡Baja de ahí y lucha, enclenque!",
  ["g3:08186d06"] = "¡Eres lo peor!",
  ["g3:08186d16"] = "¡Odio perder!\n¡No te acerques a mí!",
  ["g3:08186d39"] = "¡Oye! ¡Me has dado!",
  ["g3:08186d52"] = "¡Qué golpe!",
  ["g3:08186d5a"] = "Te guste o no, de aquí no nos\nva a echar nadie.\\pA FUCSIA puedes llegar también\ndesde CARMÍN, por la costa.",
  ["g3:08186dd9"] = "¡Tengo hambre y no estoy\nde humor!",
  ["g3:08186e0d"] = "¡Mal, mal, muy mal!",
  ["g3:08186e1c"] = "¡Me gustan mis fuertes POKéMON!\n¡Son tremendos contra mis enemigos!",
  ["g3:08186e86"] = "¡Eh, vamos a echar el rato!",
  ["g3:08186eb4"] = "¡No me fastidies!",
  ["g3:08186ec7"] = "Yo me parto tomándole el pelo\na la gente con mis POKéMON.\\p¡Son los mejores para asustar\na la gente y, además, muerden!",
  ["g3:08186f3d"] = "¡Un POKéMON dormido bloquea\nel camino!",
  ["g3:08186f7a"] = "CAMINO DE BICIS\n¡Buen descenso!",
  ["g3:08186f98"] = "RUTA 16:\nCIUDAD AZULONA - CIUDAD FUCSIA",
  ["g3:08186fbd"] = "JOEL: Nuestro amor no conoce\nlímites.\\pEstamos enamorados y no lo\nocultamos.",
  ["g3:08186ffa"] = "JOEL: ¡He perdido, pero no\nen el amor!",
  ["g3:08187027"] = "JOEL: ¡Oye, LIZ, no te quedes\nembobada conmigo!",
  ["g3:08187057"] = "JOEL: ¿Sólo tienes un POKéMON?\n¿Y no te da pena?",
  ["g3:08187097"] = "LIZ: ¡A veces, pienso en todo\nlo que nos queremos y se me pone\\lla carne de gallina!",
  ["g3:081870cc"] = "LIZ: ¡JOEL me gusta hasta cuando\npierde!",
  ["g3:081870f9"] = "LIZ: Lo siento, pero no hay nadie\ncomo JOEL.",
  ["g3:08187120"] = "LIZ: ¿No tienes dos POKéMON?\\p¿Y no os sentís solos?",
  ["g3:0818717e"] = "¡No compensa luchar con niños!",
  ["g3:081871ae"] = "¡Qué chasco!",
  ["g3:081871ba"] = "¡Por el CAMINO de BICIS\nhay cosas estupendas!\\p¡Se puede ganar mucha pasta\nvendiendo lo que se encuentra!",
  ["g3:08187228"] = "¿Y tú qué quieres?",
  ["g3:08187254"] = "¡Uuuu!",
  ["g3:0818725a"] = "¡Podría echarte de aquí de\nun barrigazo!",
  ["g3:0818727d"] = "¿Te diriges a CIUDAD FUCSIA?",
  ["g3:08187295"] = "¡Destrozado y vencido!",
  ["g3:081872a5"] = "Me gusta pedalear cuesta abajo.",
  ["g3:081872bd"] = "¡Somos los MOTORISTAS!\n¡Las estrellas de la autopista!",
  ["g3:081872e3"] = "¡Qué trompazo!",
  ["g3:081872eb"] = "¿Vas en busca de aventuras?",
  ["g3:0818730a"] = "¡Deja que VOLTORB te dé un poco\nde su energía!",
  ["g3:08187325"] = "¡Qué bajón!",
  ["g3:08187333"] = "¡Atrapé mis VOLTORB en la\nCENTRAL de ENERGÍA abandonada!",
  ["g3:08187362"] = "¡Mi POKéMON no evoluciona!\n¿Por qué será?",
  ["g3:08187395"] = "¡Tú tienes la culpa!",
  ["g3:0818739f"] = "Puede que ciertos POKéMON\nnecesiten PIEDRAS para\\levolucionar.",
  ["g3:081873d1"] = "¡Necesito un poco de ejercicio!",
  ["g3:081873eb"] = "¡Ufff!\n¡Qué buen entrenamiento!",
  ["g3:081873ff"] = "¡Seguro que he perdido peso!",
  ["g3:0818741d"] = "¡Sé rebelde!",
  ["g3:08187429"] = "¡Aaaargh!",
  ["g3:08187432"] = "¡Prepárate para luchar\npor tus ideas!",
  ["g3:08187456"] = "¡Bonita BICI!\n¿Cómo se conduce?",
  ["g3:08187472"] = "¡Estoy acabado!",
  ["g3:08187479"] = "¡La pendiente dificulta\nla conducción!",
  ["g3:0818749b"] = "¡Lárgate!\n¡Estoy agotado!",
  ["g3:081874b6"] = "¿Te has quedado a gusto?",
  ["g3:081874c9"] = "¡Tengo que recuperar sueño\natrasado!",
  ["g3:081874e4"] = "¡Aviso!\\p¡Ojo con las cosas que hay\npor el suelo!",
  ["g3:08187512"] = "PISTAS ENTRENADOR\\pTodo POKéMON es único.\\pHasta los POKéMON del mismo tipo\ny nivel crecen a diferente ritmo.",
  ["g3:0818757b"] = "PISTAS ENTRENADOR\\pPulsa el Botón B para no moverte\nsobre una pendiente.",
  ["g3:081875be"] = "RUTA 17:\nCIUDAD AZULONA - CIUDAD FUCSIA",
  ["g3:081875e3"] = "¡Aviso!\\p¡No tires el juego, mejor tira\nPOKé BALLS!",
  ["g3:08187622"] = "CAMINO DE BICIS\n¡La pendiente termina aquí!",
  ["g3:08187640"] = "Compruebo siempre las zonas de\nhierba en busca de nuevos POKéMON.",
  ["g3:08187672"] = "¡Tch!",
  ["g3:08187677"] = "¡Ojalá tuviera una BICICLETA!",
  ["g3:0818768c"] = "¡Cucu, cucu!\n¿Te gusta el reclamo de mi pájaro?",
  ["g3:081876b3"] = "¡No he podido contigo!",
  ["g3:081876c5"] = "¡También recojo POKéMON del mar\nlos fines de semana!",
  ["g3:08187704"] = "¡Es mi césped!\n¡Fuera de aquí!",
  ["g3:08187726"] = "¡Qué rabia!",
  ["g3:0818772c"] = "¡Es mi zona preferida para atrapar\nPOKéMON!",
  ["g3:08187757"] = "RUTA 18:\nCIUDAD AZULONA - CIUDAD FUCSIA",
  ["g3:0818777c"] = "CAMINO DE BICIS\n¡Prohibido el paso a los peatones!",
  ["g3:081877a3"] = "¡Tengo que calentar antes\nde nadar!",
  ["g3:081877df"] = "¡Ahora es cuando me encuentro\nen forma!",
  ["g3:081877ee"] = "¡Gracias!\n¡Ya puedo nadar!",
  ["g3:08187811"] = "¡Alto!\n¡Te va a dar algo!",
  ["g3:0818783e"] = "¡¡Auuu!!\n¡Cómo me has dejado!",
  ["g3:08187852"] = "¡Cuidado con TENTACOOL!\n¡Como te pique, no veas!",
  ["g3:08187884"] = "¡Me gusta nadar!\n¿Y a ti?",
  ["g3:081878a5"] = "¡Vaya planchazo!",
  ["g3:081878b1"] = "¡Puedo ganar a los POKéMON\nnadando!",
  ["g3:081878dd"] = "¿Qué habrá más allá del horizonte?",
  ["g3:081878f8"] = "¡Glup!",
  ["g3:081878fe"] = "¡Veo un par de islas!",
  ["g3:08187925"] = "¡He buceado en busca de POKéMON,\npero no he visto nada!",
  ["g3:08187955"] = "¡Socorro!",
  ["g3:0818795b"] = "¡Tienes que pescar a los POKéMON\ndel mar!",
  ["g3:08187985"] = "¡Miro al mar para olvidar!",
  ["g3:081879c3"] = "¡Oooooh!\n¡Qué humillación!",
  ["g3:081879d3"] = "¡Miro al mar para olvidar!",
  ["g3:08187a11"] = "¡Qué POKéMON tan guay!\n¿Me lo darás si gano?",
  ["g3:08187a44"] = "¡Oh! ¡He perdido!",
  ["g3:08187a50"] = "Queda un largo camino hasta\nlas ISLAS ESPUMA...\\pYo quiero volver a FUCSIA...",
  ["g3:08187a9e"] = "¡Nadar es genial! ¡Pero no me\ngusta quemarme al sol!",
  ["g3:08187ac1"] = "¡Qué horror!",
  ["g3:08187aca"] = "Mi novio quería nadar hasta\nlas ISLAS ESPUMA.",
  ["g3:08187afa"] = "¡Estas aguas son traicioneras!",
  ["g3:08187b25"] = "¡Qué peligro!",
  ["g3:08187b35"] = "¡Me ha dado un calambre! ¡Glup!",
  ["g3:08187b5d"] = "He venido nadando hasta aquí,\npero ya me he cansado.",
  ["g3:08187b85"] = "Estoy agotada...",
  ["g3:08187b94"] = "Si tuviera que montarme en un\nPOKéMON para surcar el mar,\\lelegiría a LAPRAS.\\pLAPRAS es enorme, si te subes\nencima, seguro que no te mojas.",
  ["g3:08187c06"] = "RUTA MARINA 19:\nCIUDAD FUCSIA - ISLAS ESPUMA",
  ["g3:08187c32"] = "CATI: Yo cuido de mi hermano.\nAcaba de hacerse ENTRENADOR.",
  ["g3:08187c6f"] = "CATI: ¡Ésa no es forma de tratar\na mi hermanito!",
  ["g3:08187c9e"] = "CATI: ¿Tienes un hermano pequeño?\\pEspero que le enseñes cosas.",
  ["g3:08187cf2"] = "CATI: A mi hermano y a mí nos\ngustaría luchar contigo.\\p¿Tienes dos POKéMON?",
  ["g3:08187d45"] = "TEC: Mi hermana mayor me ha\nenseñado a nadar y a entrenar\\lPOKéMON.",
  ["g3:08187d7e"] = "TEC: ¡Hala, alguien más fuerte\nque mi hermana!",
  ["g3:08187dad"] = "TEC: ¡Mi hermana mayor es muy\nfuerte y simpática! ¡Es guay!",
  ["g3:08187de8"] = "TEC: Si no es con mi hermana,\nno lucharé contigo.\\pAdemás, necesitas dos POKéMON.",
  ["g3:08187e40"] = "El agua es poco profunda aquí.\nHay mucha gente nadando.",
  ["g3:08187e7b"] = "¡Splash!",
  ["g3:08187e83"] = "¡Ojalá pudiera subirme a mi\nPOKéMON!",
  ["g3:08187ebb"] = "¡Las ISLAS ESPUMA son una fácil\nsalida!",
  ["g3:08187eed"] = "¡Déjalo ya!",
  ["g3:08187ef6"] = "Hay una enorme caverna debajo\nde esta isla.",
  ["g3:08187f24"] = "¡Me gusta flotar en el agua\nrodeada de peces!",
  ["g3:08187f5a"] = "¡Auchh!",
  ["g3:08187f61"] = "¿Quieres flotar conmigo?",
  ["g3:08187f78"] = "¿También estás de vacaciones?",
  ["g3:08187f92"] = "¡Qué insensible eres!",
  ["g3:08187fa3"] = "¡Las ISLAS ESPUMA eran antes\nuna sola isla!",
  ["g3:08187fdb"] = "¡Mira que cuerpazo tengo!",
  ["g3:08187ff7"] = "¡Qué ridículo!",
  ["g3:08187ffe"] = "¡No debería haber presumido tanto!",
  ["g3:0818802e"] = "¿Por qué te has subido a un\nPOKéMON? ¿No sabes nadar?",
  ["g3:0818805c"] = "¡Auch!\n¡Qué fracaso!",
  ["g3:0818806d"] = "¡Subirse a un POKéMON es muy\ndivertido!",
  ["g3:0818808e"] = "¡He venido sobre uno de mis\npájaros POKéMON!",
  ["g3:081880ab"] = "¡Oh, no!",
  ["g3:081880c8"] = "¡Mis pájaros están hechos polvo\npara VOLAR de nuevo!",
  ["g3:081880f8"] = "¡Mi novio me dio unas perlas\nmuy grandes!",
  ["g3:08188119"] = "¡Ni te acerques a mis perlas!",
  ["g3:08188139"] = "¿Crecerán más mis perlas dentro\nde un CLOYSTER?",
  ["g3:08188165"] = "¡Vengo nadando desde ISLA\nCANELA! ¡Qué paliza!",
  ["g3:081881a3"] = "¡Estoy tan decepcionada!",
  ["g3:081881b8"] = "¡Los POKéMON invadieron una casa\nabandonada en ISLA CANELA!\\pEs la que llaman MANSIÓN\nPOKéMON.",
  ["g3:08188218"] = "En ISLA CANELA, al oeste, hay\nun LABORATORIO POKéMON.\\pMi papi trabaja allí.",
  ["g3:0818825c"] = "¡Espera!\n¡Vas demasiado deprisa!",
  ["g3:0818827b"] = "¡ISLA CANELA es volcánica!\\pDicen que surgió tras la erupción\nde un volcán.",
  ["g3:081882d1"] = "ISLAS ESPUMA",
  ["g3:081882e1"] = "Por aquí hay muchos ENTRENADORES\nfuertes y POKéMON del tipo AGUA.\\pDicen que MISTY, del GIMNASIO\nde CELESTE, se entrena por aquí.",
  ["g3:0818835a"] = "¿Quieres saber si los peces pican?",
  ["g3:08188383"] = "¡Vale, vale!",
  ["g3:08188389"] = "¡No puedo pescar nada bueno!\n¡No hay ni un POKéMON bueno!",
  ["g3:081883c6"] = "¡Tengo una gran red!\n¿Quieres probarla?",
  ["g3:081883e9"] = "¡MAGIKARP, qué bochorno!",
  ["g3:0818841d"] = "¡Se ve que sólo pesco MAGIKARP!",
  ["g3:0818843c"] = "¡El mar limpia mi cuerpo y mi\nalma!",
  ["g3:0818845f"] = "¡Ayah!",
  ["g3:08188465"] = "¡A mí también me gusta la montaña!",
  ["g3:081884d4"] = "¡He conseguido a mi POKéMON\nen el mar, y aquí lo entreno!",
  ["g3:081884f0"] = "¡Splash!",
  ["g3:081884ff"] = "¿Dónde atrapaste tus POKéMON?",
  ["g3:0818851f"] = "¡Ahora estoy en un encuentro\nde triatlón!",
  ["g3:08188543"] = "Ufff...\nUfff... Ufff...",
  ["g3:08188555"] = "¡Me has ganado! ¡Pero aún falta\nel ciclismo y la maratón!",
  ["g3:08188592"] = "¡Ah!\n¡Siente el sol y el viento!",
  ["g3:081885b2"] = "¡Auuu!\n¡He perdido!",
  ["g3:081885bf"] = "¡Estoy totalmente quemado!",
  ["g3:081885d8"] = "¡Eh!\n¡No asustes a los peces!",
  ["g3:081885f8"] = "¡Perdona!\n¡No lo hice adrede!",
  ["g3:08188632"] = "¡Estaba enfadado porque no\nhabía pescado nada!",
  ["g3:0818868c"] = "¡Quédate conmigo hasta que lo\nconsiga!",
  ["g3:081886ae"] = "Qué forma de matar el tiempo...",
  ["g3:081886c5"] = "¡Eh!\n¡Algo ha picado! ¡Sí!",
  ["g3:081886e2"] = "ÍA: ¿Cómo, que quieres luchar?\nIGOR, ¿cómo lo ves?",
  ["g3:08188712"] = "ÍA: ¿Eso es lo que querías,\nque perdiéramos?",
  ["g3:08188734"] = "ÍA: Estoy cansada, ¿nos vamos ya\na casa?",
  ["g3:0818875e"] = "ÍA: ¿Luchar? Con sólo un POKéMON\nno nos vamos a tomar la molestia.",
  ["g3:081887b4"] = "IGOR: Mi hermana no se cansa\nde hacer ejercicio, por eso viene.",
  ["g3:081887f1"] = "IGOR: ¡Hermanita, no pasa nada!",
  ["g3:08188812"] = "IGOR: ¡Hermanita, así no hay forma\nde perder peso!",
  ["g3:08188850"] = "IGOR: ¡A nosotros nos gusta luchar\ncon dos POKéMON, así que...!",
  ["g3:08188890"] = "{RIVAL}: ¡Eh! ¡{PLAYER}!\\p¿Vas a la LIGA POKéMON?\\p¡Olvídalo! ¡Seguro que no tienes\nninguna MEDALLA!\\p¡El guardia no te dejará pasar!\\pDime, ¿ya son más fuertes tus\nPOKéMON?",
  ["g3:08188959"] = "¡Auuu!\n¡Has tenido mucha suerte!",
  ["g3:08188974"] = "¡Dicen que los ENTRENADORES de la\nLIGA POKéMON son muy fuertes!\\p¡Tengo que buscar una forma de\nvencerles!\\p¡Deja de perder el tiempo y\nmuévete!",
  ["g3:08188a3c"] = "{RIVAL}: ¿Qué? ¡{PLAYER}!\n¡Qué sorpresa verte aquí!\\p¿Vas a ir a la LIGA POKéMON?\\p¿Y tienes todas las MEDALLAS?\n¡Genial!\\p¡Lucharé contra ti, {PLAYER}, como\npreparación para la LIGA POKéMON!\\p¡Vamos allá!",
  ["g3:08188b08"] = "¿¡Qué!?\\p¡Es que no he tenido cuidado!",
  ["g3:08188b29"] = "¡Qué buen calentamiento!\n¡Listo para la LIGA POKéMON!\\p¡{PLAYER}, necesitas más práctica!\\p¡Ya lo sabes! ¡Yo me largo!\n¡Hasta luego!",
  ["g3:08188bff"] = "LIGA POKéMON\nPuerta delantera",
  ["g3:08188c19"] = "PUERTA VICTORIA - LIGA POKéMON",
  ["g3:08188c3c"] = "¡Enhorabuena! ¡Has ganado\na nuestros 5 ENTRENADORES!\\p¡Has ganado un premio fabuloso!",
  ["g3:08188c93"] = "¡{PLAYER} obtuvo una PEPITA\nde manos del ENTRENADOR\\lmisterioso!",
  ["g3:08188cc2"] = "¡No te queda sitio!",
  ["g3:08188cdb"] = "¿Te gustaría unirte al TEAM\nROCKET?\\p¡Somos un grupo dedicado a hacer\nmaldades con los POKéMON!\\p¿Te interesa?\\p¿Seguro?\\pÚnete a nosotros.\\p¡Ya te he dicho que te unas\na nosotros!\\pNecesitas que te convenza.\\p¡Te haré una oferta que no podrás\nrechazar!",
  ["g3:08188ddc"] = "¡Arrgh!\n¡Eres genial!",
  ["g3:08188df1"] = "¡Con tu capacidad podrías ser\nlíder del TEAM ROCKET!\\p¡Piénsatelo, sería una buena\noportunidad para ti!",
  ["g3:08188e74"] = "¡Vi tu hazaña desde la hierba!",
  ["g3:08188e94"] = "¡Creía que no me ibas a ganar!",
  ["g3:08188ea3"] = "¡Me oculté porque me asustaron\nlos del puente!",
  ["g3:08188ed9"] = "¡Yo soy el 5.º!\n¡Voy a acabar contigo!",
  ["g3:08188efa"] = "¡Uauu!\n¡Ha sido mucha tela!",
  ["g3:08188f0a"] = "¡He hecho lo que he podido!",
  ["g3:08188f2c"] = "¡Yo soy la 4.ª!\n¿Te quedan fuerzas?",
  ["g3:08188f46"] = "¡También he perdido!",
  ["g3:08188f53"] = "¡He hecho lo que he podido!",
  ["g3:08188f76"] = "¡Yo soy el 3.º!\n¡Te va a costar!",
  ["g3:08188f95"] = "¡Oye!\n¡Me has machacado!",
  ["g3:08188fa7"] = "¡He hecho lo que he podido!",
  ["g3:08188fc9"] = "¡Yo soy la 2.ª!\n¡En guardia!",
  ["g3:08188fe7"] = "¿Cómo he podido perder?",
  ["g3:08188ff9"] = "¡He hecho lo que he podido!",
  ["g3:0818901b"] = "¡Éste es el PUENTE PEPITA!\n¡Derrótanos a los 5 y gana un\\lfabuloso premio!\\p¿Crees que puedes hacerlo?",
  ["g3:0818908c"] = "¡Uau!\n¡Bien hecho!",
  ["g3:0818909e"] = "¡He hecho lo que he podido!",
  ["g3:081890c0"] = "¡Los ENTRENADORES de la zona\nvienen aquí a practicar!",
  ["g3:081890e6"] = "Eres espectacular.",
  ["g3:081890f5"] = "Todo POKéMON tiene sus puntos\ndébiles.\\pLo suyo es entrenar varios tipos.",
  ["g3:08189165"] = "¡Mi padre me llevó a una gran\nfiesta en el S.S. ANNE, en\\lCIUDAD CARMÍN!",
  ["g3:081891a6"] = "¡No estoy enfadado!",
  ["g3:081891b3"] = "En el S.S. ANNE vi a ENTRENADORES\nde todo el mundo.",
  ["g3:081891eb"] = "Soy un buen chico.\n¡Y tengo novia!",
  ["g3:08189212"] = "Vaya...",
  ["g3:0818921d"] = "Bueno, mi chica me animará.",
  ["g3:08189247"] = "¡Hola!\n¡Mi chico es genial!",
  ["g3:08189261"] = "¡No estaba en muy buena forma!",
  ["g3:08189281"] = "¡Ojalá mi chico fuera tan bueno\ncomo tú!",
  ["g3:081892a9"] = "¡Sabía que tendría que luchar\ncontigo!",
  ["g3:081892d9"] = "¡Sabía que iba a perder!",
  ["g3:081892ef"] = "Si tu POKéMON sufre confusión, lo\nmejor es que lo cambies por otro.\\pEs la mejor táctica.",
  ["g3:08189333"] = "Mi amigo tiene unos POKéMON\nmuy monos. ¡Qué envidia!",
  ["g3:08189364"] = "¡No estoy enfadada!",
  ["g3:08189378"] = "¿Vienes del MT. MOON?\n¿Me das un CLEFAIRY?",
  ["g3:081893a7"] = "¡Acabo de bajar del MT. MOON,\npero estoy listo!",
  ["g3:081893ea"] = "¡Te has esforzado mucho!",
  ["g3:081893fb"] = "¡Aaaaaaargh!\nMe ha mordido un ZUBAT.",
  ["g3:08189423"] = "¡Estoy buscando a un coleccionista\nde POKéMON en el cabo!",
  ["g3:08189459"] = "¡Me has ganado!",
  ["g3:0818947e"] = "El coleccionista tiene muchos\nPOKéMON raros.",
  ["g3:081894de"] = "¿Vas a ver a BILL?\n¡Pues luchemos primero!",
  ["g3:0818950a"] = "¡Me rindo!",
  ["g3:0818951c"] = "La ruta de abajo es un atajo\na CIUDAD CELESTE.",
  ["g3:0818954c"] = "LA CASA del MAR\n¡BILL vive aquí!",
  ["g3:08189569"] = "En este cabo queda mucha gente.\\pMISTY, la LÍDER del GIMNASIO,\nsuele venir por aquí.",
  ["g3:081895c2"] = "¿Has venido sin nadie\nque te acompañe?\\pSi estás en el cabo de CELESTE,\n¡deberías aprovechar para buscar\\lcompañía!...",
  ["g3:0818961f"] = "¡Hace un día espléndido!\n¡El tiempo ideal para luchar!",
  ["g3:0818964d"] = "¡Ayyyyyy!",
  ["g3:08189657"] = "¡Bueno, por lo menos no me\nhas quitado el maquillaje!",
  ["g3:0818968c"] = "Me estoy empezando a quemar...",
  ["g3:081896ac"] = "¡Eres lo peor!",
  ["g3:081896c1"] = "Me gusta la ropa que llevas. Igual\nme convendría ponerme algo...",
  ["g3:081896f9"] = "Si lo miras desde aquí, parece\nque el MT. ASCUAS toca el cielo.",
  ["g3:08189728"] = "¡Ufff, eres fuerte!",
  ["g3:08189740"] = "El cielo se puede observar muy\nbien en esta zona.",
  ["g3:08189767"] = "¿Y he dejado de nadar para\nenfrentarme contigo?",
  ["g3:081897a4"] = "¡Oye, oye, realmente eres\nimpresionante!",
  ["g3:081897c5"] = "Te recomiendo que nades de vez en\ncuando y que no uses tanto SURF.",
  ["g3:081897ff"] = "¡Eh, un momento!\n¡Acaba de picar uno enorme!",
  ["g3:08189833"] = "¡Lo he vuelto a perder!",
  ["g3:0818984b"] = "¡No sólo he perdido, también me he\nquedado sin el ejemplar de antes!",
  ["g3:08189883"] = "¿Me echas una mano con mi\nentrenamiento?",
  ["g3:081898ab"] = "Me has ganado por muy poco.",
  ["g3:081898c4"] = "Está claro que sabes lo que haces.\n¡Te admiro!",
  ["g3:081898f0"] = "No hay un solo día en el que no\nme entrene.",
  ["g3:0818991b"] = "¡Qué forma tan tonta de perder!",
  ["g3:0818992c"] = "¡A partir de ahora me entrenaré\nmás!",
  ["g3:08189950"] = "Cada mañana, antes de desayunar,\nrodeo a nado la isla.",
  ["g3:0818998c"] = "Agggg...\nAgggg...",
  ["g3:08189998"] = "He perdido porque esta mañana\ncorrí mucho y estoy cansado.",
  ["g3:081899ce"] = "Para luchar hay que ir vestido\nen condiciones, ¡y no como tú!",
  ["g3:08189a0a"] = "¡¿Por qué?!",
  ["g3:08189a13"] = "Hasta los profesionales de las\nartes marciales nos preocupamos\\lde la moda últimamente.",
  ["g3:08189a53"] = "Cuando se está al aire libre,\ntodo sabe mucho mejor.",
  ["g3:08189a92"] = "¡Hala!",
  ["g3:08189a9f"] = "¿Sabías que el agua de las zonas\nvolcánicas es muy buena?",
  ["g3:08189acb"] = "La comida ha sido demasiado\nabundante. ¿Luchamos?",
  ["g3:08189b0b"] = "¡Sí que he quemado calorías!",
  ["g3:08189b24"] = "¿Qué hago?\n¡Otra vez tengo hambre!",
  ["g3:08189b4d"] = "PÍA: ¡Mi hermano mayor y yo\nhacemos un equipo increíble!",
  ["g3:08189b84"] = "PÍA: ¡No me lo puedo creer!",
  ["g3:08189ba3"] = "PÍA: ¿Cómo puede haber alguien\nmejor que mi hermano?",
  ["g3:08189bde"] = "PÍA: Para luchar con nosotros,\nnecesitas al menos dos POKéMON.",
  ["g3:08189c33"] = "FER: ¡Junto a PÍA no tengo miedo\nde nada!",
  ["g3:08189c62"] = "FER: ¡Buaaaah, eres demasiado!",
  ["g3:08189c7e"] = "FER: ¿Cómo ha podido fallar\nnuestro equipo?",
  ["g3:08189cab"] = "FER: ¿Quieres luchar con nosotros?\\pPues vuelve con dos POKéMON\npor lo menos.",
  ["g3:08189d02"] = "Éste es el CAMINO CANDENTE.\\pConduce al MT. ASCUAS.",
  ["g3:08189d32"] = "BALNEARIO ASCUAS\nEnciende la llama que hay en ti.",
  ["g3:08189d5a"] = "¡Me encanta quedarme flotando\ny notar el movimiento de las olas!",
  ["g3:08189d8b"] = "¡He perdido!\n¡Eso ya no me gusta nada!",
  ["g3:08189da3"] = "El mar tiene una temperatura\nincreíble en esta zona.",
  ["g3:08189dce"] = "Muchas veces la marea trae objetos\nde gran valor a la playa.\\pPor eso vengo con frecuencia\na peinar la arena.",
  ["g3:08189e42"] = "El intenso olor a sal del mar,\naaaah... me llega al corazón.",
  ["g3:08189e72"] = "Pero ahora me huele... ¡a derrota!",
  ["g3:08189e9e"] = "¿No serán tus POKéMON los que\nhuelen mal?",
  ["g3:08189ed4"] = "¿Por qué vas con tanta prisa?",
  ["g3:08189efa"] = "¡Estás entrenando a tus POKéMON\nde maravilla!",
  ["g3:08189f21"] = "Si sigues el camino que llevas,\nllegarás al BOSQUE BAYA.",
  ["g3:08189f63"] = "Mi mami me ha dicho que no debo\nnadar sin flotador.",
  ["g3:08189f9a"] = "¡Buaaaaa!\n¡Buaaaaaaaaaaa!",
  ["g3:08189fa8"] = "Este año, seguro que aprendo\na nadar sola.",
  ["g3:08189fdb"] = "¡POKéMON, POKéMON!\n¡A mí me gustan los POKéMON!",
  ["g3:08189fee"] = "¿Qué ha pasado?",
  ["g3:0818a000"] = "¿Mis POKéMON me han fallado?",
  ["g3:0818a01f"] = "¡No, no, déjame, por favor!\n¡Déjame en paz!",
  ["g3:0818a053"] = "Vale, has ganado, ¿te irás ahora?",
  ["g3:0818a082"] = "¡Un POKéMON me ha enganchado\npor el bañador!\\p¡No me puedo mover!",
  ["g3:0818a0c4"] = "FELI: Te vamos a enseñar cuál es\nnuestro POKéMON preferido.",
  ["g3:0818a0f7"] = "FELI: Oh..., MATI...",
  ["g3:0818a106"] = "FELI: Bueno, me lo he pasado bien.\nEspero que podamos repetirlo.",
  ["g3:0818a138"] = "FELI: Con un POKéMON no tienes\nnada que hacer.\\pPara eso, lucho con MATI.",
  ["g3:0818a179"] = "MATI: Te vamos a enseñar cuál es\nnuestro POKéMON favorito.",
  ["g3:0818a1a3"] = "MATI: Oh..., FELI...",
  ["g3:0818a1b2"] = "MATI: FELI, ¿te lo has pasado\nbien?",
  ["g3:0818a1cd"] = "MATI: Con un POKéMON no tienes\nnada que hacer.\\pPara eso, lucho con FELI.",
  ["g3:0818a210"] = "HACIA EL BOSQUE BAYA",
  ["g3:0818a223"] = "PUENTE UNIÓN\nCrucen con cuidado.\\pHACIA EL BOSQUE BAYA",
  ["g3:0818a261"] = "FEDERACIÓN MOTORISTA de KANTO\n¡Rrruuunn! ¡Rrruuun! ¡Rruunnn!\\p¡Mi moto no es muy potente,\npor eso hago los ruidos yo mismo!",
  ["g3:0818a2d8"] = "¡Eh, señora! ¡Déjese caer\ny denos algo de pasta!",
  ["g3:0818a307"] = "¡Aaaaaaah!\\pPero ¿qui-qui-quiénes sois?\nVoy a... ¡a llamar a la policía!",
  ["g3:0818a339"] = "¡Dichosos MOTORISTAS!...\n¿Se han marchado ya?\\p¡Menos mal!\n¡Me han dado un susto tremendo!",
  ["g3:0818a38b"] = "Bueno, ya no hay problema.\nLos MOTORISTAS se han marchado\\py PEDRITA ha aparecido sana y\nsalva, ¡eso es lo importante!",
  ["g3:0818a3e2"] = "¡Con mis manos, crearé mi propia\nvictoria!",
  ["g3:0818a40e"] = "Qué vergüenza...\nEstoy como un tomate...",
  ["g3:0818a430"] = "¡Se me han caído todos los tubos\nde pintura!",
  ["g3:0818a461"] = "Perdona, estoy pintando,\n¿te puedes quitar de ahí?",
  ["g3:0818a49e"] = "Qué forma de perder...\nEstoy abatida.",
  ["g3:0818a4c6"] = "GALENIA, por favor gira un poco\nla cabeza. ¡Así, perfecto!",
  ["g3:0818a50e"] = "Mmm...\nEste ángulo no es el mejor...",
  ["g3:0818a535"] = "Oh... Qué tristeza tan profunda...",
  ["g3:0818a555"] = "El mar y el cielo son tan...\nvolubles.\\lEs difícil plasmarlos en el lienzo.",
  ["g3:0818a5b9"] = "Estoy de visita en la zona de\nrecreo, para tu información.",
  ["g3:0818a5ee"] = "¡Qué fuerte eres!",
  ["g3:0818a601"] = "Es un auténtico placer combatir\ndisfrutando de la brisa marina.",
  ["g3:0818a645"] = "Estoy pensando en construir una\npiscina para mis POKéMON.",
  ["g3:0818a67f"] = "¡Aaaaaaah! ¡Qué bochorno!",
  ["g3:0818a699"] = "Una piscina no estaría nada mal,\npero un solárium sería fabuloso.",
  ["g3:0818a6da"] = "No hay nadie que corra más rápido\nque yo.",
  ["g3:0818a6fe"] = "¡Vaya, la velocidad no lo es todo!",
  ["g3:0818a715"] = "Cuando corro en el sentido del\nviento es como si volara.",
  ["g3:0818a74a"] = "La fauna marina de esta zona\nme fascina.",
  ["g3:0818a786"] = "¡Que me pase esto a mí!",
  ["g3:0818a7ac"] = "Me parece que te lo has tomado\ndemasiado en serio.",
  ["g3:0818a7db"] = "CONSU: Gracias.\\pYa te puedes ir.",
  ["g3:0818a7fe"] = "CASA de CONSU",
  ["g3:0818a80d"] = "Vas de aquí para allá, ¿no?\\p¿Y no es mucha paliza para\ntus POKéMON?\\pVoy a echarles un vistazo.\n... ... ... ... ... ...",
  ["g3:0818a88f"] = "Mmm...\nYa veo...",
  ["g3:0818a8a6"] = "Impresionante.\nTratas muy bien a los POKéMON.\\pNo hace falta que te diga nada.\\pToma, quiero darte esto.",
  ["g3:0818a91f"] = "¡{PLAYER} recibió un HUEVO!",
  ["g3:0818a940"] = "Vaya, qué lástima..., tu equipo\nestá completo.\\pVuelve a recogerlo en otro\nmomento.",
  ["g3:0818a9c0"] = "A mí me dieron ese HUEVO cuando\nestuve fuera.\\pMe alegro de haber encontrado\na alguien como tú.",
  ["g3:0818aa0c"] = "Hola, ¿qué tal?\n¡Qué {STR_VAR_2} tan mono!\\pAl verlo me acuerdo de una niña a\nla que vi cuando estaba de viaje.\\pLa chiquilla cuidaba con mimo a un\nPOKéMON. Era un angelito, la cría.\\pLo que no recuerdo es el nombre...\nBueno, creo que era DALIA.",
  ["g3:0818aad5"] = "Éste es un sitio estupendo\npara criar POKéMON.",
  ["g3:0818ab0b"] = "¡Tus POKéMON van de maravilla!",
  ["g3:0818ab37"] = "Creo que eres genial criando\nPOKéMON.",
  ["g3:0818ab8e"] = "{PLAYER} introdujo una contraseña.\\p“GARON ama a NORA”.\\p... ... ... ... ... ...\\pPara abrir la puerta hace falta\notra contraseña más...",
  ["g3:0818abf4"] = "{PLAYER} introdujo dos contraseñas.\\p“ARON ama a NORA”.\n“HO-OH es ese HO-OH”.\\p... ... ... ... ... ...\\p¡La puerta del ALMACÉN\nse ha abierto!",
  ["g3:0818ac62"] = "La puerta del ALMACÉN\nya está abierta.",
  ["g3:0818ac88"] = "¡Ésta es una zona privada!\n¡Fuera de aquí!",
  ["g3:0818acb3"] = "¿Por qué me pasa esto a mí?",
  ["g3:0818acc5"] = "Aquí no tienes nada que hacer.\n¡Vete a casa!",
  ["g3:0818acf0"] = "Esto no es más que nuestro\nALMACÉN.\\pNo entiendo qué te trae por aquí.",
  ["g3:0818ad39"] = "No entiendo cómo he podido\nperder...",
  ["g3:0818ad59"] = "¿Tienes curiosidad por ver qué hay\nen el ALMACÉN?\\pYo creo que es mejor que no lo\nsepas. Por tu propio bien...",
  ["g3:0818adc6"] = "Aunque me ganaras, estarías\nperdiendo el tiempo.",
  ["g3:0818adfb"] = "¡Agggrrr! ¡Qué fastidio!",
  ["g3:0818ae16"] = "Bueno, de todas formas no vas\na poder entrar sin las contraseñas.",
  ["g3:0818ae50"] = "Soy el mayor de los HERMANOS\nPÁJARO.\\pLo mejor que tienen los pájaros\ndebe de ser el pico.",
  ["g3:0818aea8"] = "¡Eso sí que ha sido como\nun picotazo!",
  ["g3:0818aeb6"] = "Desde aquí se puede ir volando\na ISLA QUARTA.",
  ["g3:0818aedc"] = "Soy el mediano de los HERMANOS\nPÁJARO.\\pLo mejor que tienen los pájaros\ndeben de ser las alas.",
  ["g3:0818af39"] = "¡Qué batida!",
  ["g3:0818af45"] = "Más adelante hay un tipo de lo\nmás extraño.",
  ["g3:0818af72"] = "Soy el pequeño de los HERMANOS\nPÁJARO.\\pLo mejor que tienen los pájaros\ndeben de ser las plumas.",
  ["g3:0818afcc"] = "Con tanta pluma me he\ndespistado...",
  ["g3:0818aff2"] = "A mí me encanta ver pájaros\nPOKéMON jugueteando tan contentos.",
  ["g3:0818b02e"] = "Mmm, así me gusta, que esté\nreluciente...",
  ["g3:0818b03c"] = "Hola, tus POKéMON tienen\nuna pinta estupenda.",
  ["g3:0818b05e"] = "Aquí descansa mi ONIX...\nSe llamaba TECTONIX...",
  ["g3:0818b095"] = "“Aquí yace TECTONIX”, pone\nen una piedra.\\pEnfrente, hay una LIMONADA\na modo de ofrenda.",
  ["g3:0818b105"] = "¿Quieres dejar otra LIMONADA\na modo de ofrenda?",
  ["g3:0818b13e"] = "{PLAYER} colocó una LIMONADA\nfrente a la piedra.",
  ["g3:0818b171"] = "Gra-gracias...\\pEra el refresco preferido\nde mi TECTONIX...\\pNo sé, pero el detalle que has\ntenido me ha animado un poco.\\pDeja que te lo agradezca\ncon esto.",
  ["g3:0818b219"] = "Tú también deberías comportarte \ncon tus POKéMON.",
  ["g3:0818b23e"] = "Si no te queda sitio, te la\nguardaré para cuando vuelvas.",
  ["g3:0818b282"] = "Anda, si eres tú...\\pAquí tengo lo que quería darte\ncomo muestra de mi agradecimiento.",
  ["g3:0818b2da"] = "Yo creo que se ve bastante\nlimpia...\\p... ... ...\nMi TECTONIX...",
  ["g3:0818b2f8"] = "Cantos y rocas apilados de manera\nordenada forman una especie\\lde monumento.\\p“Aquí yace TECTONIX”, pone\nen una piedra.",
  ["g3:0818b35a"] = "Por aquí no hay ni un sólo\nPOKéMON raro. ¡Ni uno!\\p¡Estoy hasta el gorro de buscar!\n¡Te ha tocado pagar el mosqueo,\\llo siento!",
  ["g3:0818b3c2"] = "¡¿Qué?!",
  ["g3:0818b3c8"] = "Tú no has visto ningún POKéMON\nraro, ¿no?",
  ["g3:0818b400"] = "¡Qué mala suerte tengo hoy!\n¡Igual la cosa cambia si luchamos!",
  ["g3:0818b43b"] = "Nada, hoy no es mi día.",
  ["g3:0818b451"] = "¡Pero es que no puedo volver\na casa con las manos vacías!",
  ["g3:0818b48f"] = "Ufff... Ufff...\\pVengo nadando desde el PUERTO\nde ISLA EXTA sin parar.",
  ["g3:0818b4c5"] = "Agggg...\nAgggg...",
  ["g3:0818b4d1"] = "Voy por la mitad...\nY ya no puedo más...",
  ["g3:0818b4fa"] = "No es fácil sacar POKéMON mientras\nse nada, ¿lo sabías?",
  ["g3:0818b539"] = "He perdido, pero seguro que\nnadando no me ganas.",
  ["g3:0818b573"] = "¿Vas a la isla que hay al norte?\nYo no vi nada de interés.",
  ["g3:0818b5c8"] = "ALI: ¡Vamos a echarnos un combate\ndisfrutando de la brisa marina!",
  ["g3:0818b5f4"] = "ALI: ¡Eres increíble! ¡Además\nno te hace falta nadie de apoyo!",
  ["g3:0818b62e"] = "ALI: Prefiero mil veces el mar\nantes que la piscina.",
  ["g3:0818b660"] = "ALI: ¿Quieres luchar con nosotros?\\pPues te hacen falta dos POKéMON\npor lo menos para luchar.",
  ["g3:0818b6c1"] = "ROS: Hermanita, ¡ayuda!\n¡Lucha conmigo!",
  ["g3:0818b6ef"] = "ROS: Hermanita, ¡qué fuerte es!",
  ["g3:0818b720"] = "ROS: Yo me agarro a mi hermanita,\nporque no hago pie.",
  ["g3:0818b762"] = "ROS: ¡Lucha con mi hermanita\ny conmigo!\\pAh..., ¿no tienes dos POKéMON?\nEntonces, no.",
  ["g3:0818b7b0"] = "¿Mmm?...\\pMe pareció haber elegido mi casa\ncon TELETRANSPORTE, pero...\\l¿dónde estoy?",
  ["g3:0818b7f0"] = "¡Auuuuuch!",
  ["g3:0818b7fd"] = "No sé muy bien dónde estoy...\\pDebo centrarme en TELETRANSPORTE\npara volver a mi casa...",
  ["g3:0818b84d"] = "VÍA VERDE\nHACIA EL BOSQUEJO",
  ["g3:0818b86b"] = "VÍA VERDE\n¡Hay que tener respeto\\lhasta por el último seto!",
  ["g3:0818b896"] = "He llegado hasta aquí dejándome\nllevar por un agradable aroma.",
  ["g3:0818b8c8"] = "Ganas en encanto cuando muestras\nla fuerza que tienes.",
  ["g3:0818b8f7"] = "Me gustaría ir al bosque que hay\npor ahí, pero...\\pEstá lleno de POKéMON del tipo\nBICHO, y me dan mucho miedo.",
  ["g3:0818b959"] = "Practico en secreto para que\nno me vea nadie.",
  ["g3:0818b988"] = "No me habrá visto nadie, ¿no?",
  ["g3:0818b9a5"] = "Como artista, no me gusta\nque nadie me vea cuando ensayo.",
  ["g3:0818b9ec"] = "¿Perdona? ¿Que no te gusta\nla gente que hace natación\\lcomo yo?\\p¡No fastidies!",
  ["g3:0818ba47"] = "¡Vale, me queda claro!",
  ["g3:0818ba57"] = "Vaya, no he conseguido dejar alto\nel pabellón de natación...",
  ["g3:0818ba86"] = "Como mi chico está siempre liado,\nme voy a nadar yo sola.",
  ["g3:0818bac0"] = "¡Sabía que acabaría así!",
  ["g3:0818bae0"] = "Cuando mi chico está ocupado,\nme entretengo con los POKéMON\\lque me dio.",
  ["g3:0818bb2d"] = "Oye, ¿dónde están las montañas\nde esta zona?",
  ["g3:0818bb62"] = "¡Me he perdido con tanta lucha!",
  ["g3:0818bb8b"] = "¿Hay montañas por aquí o no?",
  ["g3:0818bbba"] = "MARU: ¡Queridos POKéMON!\n¡Vamos a jugar!",
  ["g3:0818bbe2"] = "MARU: ¡Nooooo!\n¡Mamiiiiiii!",
  ["g3:0818bbf6"] = "MARU: Cuando pierdo me pongo\nmuy triste...",
  ["g3:0818bc24"] = "MARU: MÍA y yo somos gemelas.\nNos encanta luchar juntas.",
  ["g3:0818bc5a"] = "MÍA: ¡Queridos POKéMON!\n¡Vamos a luchar!",
  ["g3:0818bc84"] = "MÍA: ¡Hay que ver cómo eres!\n¡No está bien que ganes!",
  ["g3:0818bcae"] = "MÍA: Ooooh...\nLo siento, queridos POKéMON...",
  ["g3:0818bccf"] = "MÍA: ¿Sólo tienes un POKéMON?\\p¿Y no te da pena?",
  ["g3:0818bd0c"] = "Se busca el cuerno perdido.",
  ["g3:0818bd27"] = "VÍA ACUÁTICA\nLLEVA AL VALLE DE LAS RUINAS",
  ["g3:0818bd47"] = "No tengo ni idea de cómo puedo\nentrar.",
  ["g3:0818bd7a"] = "Para tu información, fui yo quien\nencontró este lugar.\\pTampoco es para que pongas\nesa cara de envidia...",
  ["g3:0818bdc0"] = "La puerta no cede ni un milímetro.\n¿Quieres examinarla un poco?",
  ["g3:0818bdf9"] = "{PLAYER} dejó tranquila la puerta.",
  ["g3:0818be11"] = "Tras mirarla con más detenimiento,\nvio que estaba punteada...",
  ["g3:0818be4b"] = "La puerta está abierta.",
  ["g3:0818be5d"] = "Creo que en este mundo quedan\nmisterios por resolver.",
  ["g3:0818be9b"] = "Mmmm...",
  ["g3:0818bea0"] = "Creo que también deberías dedicar\nun tiempo a pensar en la cantidad\\lde cosas que hay por averiguar.",
  ["g3:0818bf05"] = "Oye, ¿qué te trae hasta aquí?",
  ["g3:0818bf33"] = "Llevo tanto sin luchar que no\ntengo reflejos...",
  ["g3:0818bf6c"] = "Hay varias ruinas en ARCHI7.\\pLa mayoría datan de tiempos\ninmemoriales.",
  ["g3:0818bfc5"] = "Dicen que hay misteriosas piedras\nen esta isla.\\pSupongo que tendrán algo que ver\ncon las ruinas de aquí.",
  ["g3:0818c03b"] = "Eh... muy interesante.",
  ["g3:0818c04c"] = "Las ruinas de ahí...\\pSon rarísimas, yo no he conseguido\nentrar todavía.",
  ["g3:0818c09c"] = "¿Luchar contigo?\n¡Ahora mismo!",
  ["g3:0818c0bb"] = "No soporto el sabor de la derrota\nante ti...",
  ["g3:0818c0ea"] = "Deberías hacer escalada.",
  ["g3:0818c10a"] = "Yo me conozco bien toda esta\nzona.",
  ["g3:0818c140"] = "Tampoco es para ponerse así.\nPuedes preguntarme lo que quieras.",
  ["g3:0818c17a"] = "La entrada a las ruinas...\nTiene unos dibujos extrañísimos\\lgrabados.\\pY no tengo ni idea de lo que\nsignifican.",
  ["g3:0818c1ed"] = "He notado que te acercabas.",
  ["g3:0818c205"] = "Me rindo...",
  ["g3:0818c20e"] = "Siento que te vas a encontrar\ncon mucha gente.\\pEstablecerás cierta conexión\nmediante una extraña fuerza.",
  ["g3:0818c283"] = "En alguna parte de esta isla,\nhay extraños POKéMON durmiendo.",
  ["g3:0818c2bc"] = "¡Tú sí que sabes entrenar POKéMON!",
  ["g3:0818c2d5"] = "En alguna parte de esta isla,\nhay extraños POKéMON durmiendo.\\p¿Te estarán esperando?",
  ["g3:0818c338"] = "ENTRADA A LA TORRE DESAFÍO\n¡A por todas, ENTRENADORES!",
  ["g3:0818c370"] = "HACIA LA TORRE DESAFÍO",
  ["g3:0818c3bc"] = "¡Voy a acabar contigo en un abrir\ny cerrar de ojos!",
  ["g3:0818c3e7"] = "¡Ufff... demasiado para mí!",
  ["g3:0818c3ff"] = "¿Cómo? ¿Que las apariencias\nengañan?\\p¡Eh, es parte de mi estrategia!",
  ["g3:0818c44b"] = "¡Hola, cara de bola!\n¿Eres de mi club de fans?",
  ["g3:0818c473"] = "O sea, que de fan nada...\\pPues ¿qué le vamos a hacer?\n¿Y si te canto un poco?",
  ["g3:0818c4ba"] = "Oye el boom, boom...\\pOye el boom, boom, boom, de mis\nPOKéMON, ven y dime tú, no me\\ldigas no...",
  ["g3:0818c500"] = "Esta isla tiene una extensión muy\nparticular, no es fácil patrullar.",
  ["g3:0818c543"] = "Vaya...",
  ["g3:0818c54b"] = "Los ENTRENADORES de ciudad,\ncomo tú, deben de ser fuertes.\\pTú irás a la TORRE, ¿no?",
  ["g3:0818c5aa"] = "¡La gente que se pasa con los\nPOKéMON se las ve conmigo!",
  ["g3:0818c5cd"] = "¡Tú te portas como debe ser!",
  ["g3:0818c5f5"] = "Si tratas a los POKéMON con\namabilidad, reaccionarán bien.",
  ["g3:0818c632"] = "ELE: Yo formo equipo con RUS\npara luchar.",
  ["g3:0818c662"] = "ELE: Pues hemos perdido RUS\ny yo, je.",
  ["g3:0818c683"] = "ELE: Tengo que entrenarme más con\nRUS.",
  ["g3:0818c6ab"] = "ELE: Junto a RUS, me gustaría\nluchar contra ti.\\p¡Pero necesitas al menos dos\nPOKéMON!",
  ["g3:0818c700"] = "RUS: Cuando estoy con ELE,\ncreo que no voy a perder nunca.",
  ["g3:0818c73b"] = "RUS: Cuando estoy con ELE,\nno tengo sensación de derrota.",
  ["g3:0818c773"] = "RUS: Cuando estoy con ELE,\nme da igual ganar o perder.\\p¡Es una sensación inexplicable!",
  ["g3:0818c7bd"] = "RUS: Si es junto a ELE,\nme encantará luchar contra ti.\\p¡Pero para eso, tendrás que tener\nal menos dos POKéMON!",
  ["g3:0818c82d"] = "ENTRADA AL CAÑÓN SÉTANO\\pSe ruega a los ENTRENADORES\nrespetar la vegetación del CAÑÓN.",
  ["g3:0818c887"] = "¡Estoy realmente en forma!",
  ["g3:0818c8a6"] = "¿Mmm?\nAquí hay algo que falla...",
  ["g3:0818c8c2"] = "Así no puedo presentarme a la\nTORRE DESAFÍO...",
  ["g3:0818c8fd"] = "Da igual que tengas los POKéMON\nmás fuertes...\\p¡Lo importante es saber cómo\ntratarlos!",
  ["g3:0818c980"] = "Sabes bien lo que haces...",
  ["g3:0818c999"] = "Hay mucho ENTRENADOR por ahí\nsuelto con POKéMON increíbles y sin\\lidea de cómo hay que tratarlos.\\pAntes de entrenar POKéMON,\nson los propios ENTRENADORES los\\lque deben crecer como personas.",
  ["g3:0818ca2f"] = "Yo protejo el medio ambiente\ny él me protege a mí.",
  ["g3:0818ca6f"] = "¡Buah, eres fuerte!\n¿Y a mí quién me protege ahora?",
  ["g3:0818ca9c"] = "Visto desde las estrellas, nuestro\nplaneta es un granito de arena.\\pY debemos proteger ese granito\nde arena por el bien de todos.",
  ["g3:0818cb16"] = "Tienes unos zapatos muy llamativos.",
  ["g3:0818cb3e"] = "¡Cualquiera diría que eres tan\nfuerte! ¡No lo aparentas!",
  ["g3:0818cb6c"] = "¿Te ha comprado tu mamá esas\nDEPORTIVAS tan chulas?\\p¡Debe de adorarte!",
  ["g3:0818cbb4"] = "¡Pareces fuerte!\n¡Vamos a luchar, anda!",
  ["g3:0818cbe0"] = "¡Lo sabía!\n¡Sabía que eras increíble!",
  ["g3:0818cc09"] = "La forma de luchar que tienes\ndice mucho de ti.\\p¡Gracias!",
  ["g3:0818cc4f"] = "He recibido la mejor educación\npara tener la fuerza que tengo.\\p¡No pienso perder ante nadie!",
  ["g3:0818ccae"] = "Gracias, ya no tengo la presión\nde antes.",
  ["g3:0818ccea"] = "La cosa más mínima, me ponía\nde mal humor.\\pAhora, con respirar hondo,\nse me pasa.",
  ["g3:0818cd49"] = "LINO: Mi adorada ABA, ¡no hay\nnadie que pueda con nosotros!",
  ["g3:0818cd75"] = "LINO: Me parece que he bajado\nla guardia...",
  ["g3:0818cd9c"] = "LINO: Creo que ha sido una buena\nexperiencia para ABA. Gracias.",
  ["g3:0818cde2"] = "LINO: ¿Podrías luchar con los dos\na la vez?",
  ["g3:0818ce20"] = "ABA: Me esforzaré mucho para no\ndefraudar a mi maestro LINO.",
  ["g3:0818ce5a"] = "ABA: Oooh... Lo siento...",
  ["g3:0818ce78"] = "ABA: Creo que voy a necesitar que\nLINO me tutele y me oriente más...\\pLINO, ¿te parece bien?...",
  ["g3:0818cef4"] = "ABA: Lo siento, pero queremos\nluchar dos contra dos.",
  ["g3:0818cf2b"] = "CAÑÓN SÉTANO\nHACIA LAS RUINAS SETE",
  ["g3:0818cf4d"] = "Entrenarse uno mismo no está mal.\\pPero tampoco está mal buscar\nuna buena pareja de combate.\\pFíjate en BRUNO...\nÉl se entrenó con un tal MARCIAL.",
  ["g3:0818cffb"] = "¿Sabes algo de esta cámara\nde piedra?",
  ["g3:0818d02a"] = "Oye, tampoco había que recurrir\na la fuerza.",
  ["g3:0818d061"] = "Las RUINAS SETE tienen unos\n1.500 años.\\pPero nadie ha conseguido averiguar\ncuál es su razón de ser.",
  ["g3:0818d0d9"] = "Dicen que aquí dentro duerme\nun mítico POKéMON.",
  ["g3:0818d108"] = "A mí lo de los combates no se me\nda bien.",
  ["g3:0818d125"] = "Yo he oído que hay otras ruinas\ncomo éstas.\\p¿Serán lugares de descanso de\notros míticos POKéMON?",
  ["g3:0818d18f"] = "CLEN está enseñándome a pintar.",
  ["g3:0818d1b5"] = "Igual nos llaman la atención\npor haber hecho tanto ruido.",
  ["g3:0818d1e3"] = "Yo quería pintar un edificio\nantiguo.\\pPor eso me trajo CLEN hasta aquí.",
  ["g3:0818d22f"] = "Hoy, como complemento a la clase,\nhemos venido a visitar la cámara.",
  ["g3:0818d26d"] = "Qué barbaridad...",
  ["g3:0818d284"] = "Así que tú estudias a los POKéMON\npor tu cuenta...\\pLa verdad es que es digno\nde admiración...",
  ["g3:0818d2f0"] = "MAMÁ: En fin...\nTodos los niños se van de casa\\lalgún día. ¡Así es la vida!\\pAh, nuestro vecino, el PROF. OAK,\nquería verte.",
  ["g3:0818d360"] = "MAMÁ: En fin...\nTodos los niños se van de casa\\lalgún día. ¡Así es la vida!\\pAh, nuestro vecino, el PROF. OAK,\nquería verte.",
  ["g3:0818d3d1"] = "MAMÁ: ¡{PLAYER}!\nDeberías tomarte un descanso.",
  ["g3:0818d3f8"] = "MAMÁ: ¡Muy bien! ¡Tú y tus\nPOKéMON estáis en plena forma!\\l¡Cuídate!",
  ["g3:0818d43e"] = "Están poniendo una peli...\nSalen cuatro niños caminando\\lpor las vías del tren...\\pBueno, voy a ponerme en marcha.",
  ["g3:0818d492"] = "Están poniendo una peli...\nSale una chica con coletas andando\\lpor una calle empedrada...\\pBueno, voy a ponerme en marcha.",
  ["g3:0818d4f9"] = "¡Ay! Me he equivocado de lado.",
  ["g3:0818d50b"] = "¡{PLAYER} está jugando a la NES!\\pBueno, más vale que me ponga\nen marcha.",
  ["g3:0818d53b"] = "Anda, una nota...\\pSi no sabes qué hacer, busca\nAYUDA. Pulsa el Botón L o R.",
  ["g3:0818d58c"] = "DALIA: ¡Hola, {PLAYER}!\\p¡{RIVAL} está en el laboratorio\ndel abuelo!",
  ["g3:0818d5c4"] = "DALIA: {PLAYER}, he oído que has\nluchado contra {RIVAL}.\\p¡Me hubiera encantado estar ahí!",
  ["g3:0818d60a"] = "¿Te encargó algo el abuelo?\\p¡Toma esto!\n¡Te ayudará!",
  ["g3:0818d661"] = "¡{PLAYER} recibió el MAPA\nde manos de DALIA!",
  ["g3:0818d684"] = "Llevas demasiadas cosas\nen la MOCHILA.",
  ["g3:0818d6af"] = "Usa el MAPA para saber dónde\nte encuentras.",
  ["g3:0818d701"] = "DALIA: Los POKéMON son seres que\nsienten, igual que las personas.\\pCuando se cansen, deberás dejar\nque se recuperen.",
  ["g3:0818d763"] = "¡Es un gran mapa de KANTO!\n¡Qué útil!",
  ["g3:0818d7a1"] = "¡Está totalmente llena de libros\nsobre los POKéMON!",
  ["g3:0818d7d3"] = "DALIA: ¡Hola, {PLAYER}!\n¡Llegas a tiempo!\\pIba a tomarme un té.\n¿Quieres uno?\\pTus POKéMON están un poco sucios.\n¿Quieres que limpie a alguno?",
  ["g3:0818d875"] = "¿No quieres que limpie a ningún\nPOKéMON?\\lBueno, vamos a tomarnos el té.",
  ["g3:0818d8b2"] = "¿A qué POKéMON limpio?",
  ["g3:0818d8cc"] = "DALIA: Vale, verás lo mono\nque se queda.",
  ["g3:0818d97b"] = "Lo siento, yo no sé limpiar HUEVOS.",
  ["g3:0818d9a5"] = "DALIA: Si crías a tus POKéMON\ncon cariño, te querrán mucho.\\p{PLAYER}, ¿me dejas ver a tu primer\nPOKéMON?",
  ["g3:0818da16"] = "Desde luego, no podría quererte\nmás.\\p¡No hay palabras para expresar\nlo mucho que se ve que te quiere!",
  ["g3:0818da73"] = "Se le ve muy feliz.\\pOjalá {RIVAL} pudiera verlo y\naprender cómo se hacen las cosas.",
  ["g3:0818dabe"] = "Se ve que se lleva muy bien\ncontigo. ¡Que no decaiga!",
  ["g3:0818daf3"] = "Se ve que te está tomando\ncariño. Debes darle confianza.",
  ["g3:0818db2e"] = "No se ha adaptado del todo a ti.\\pLos POKéMON son muy recelosos\ncuando los atrapas. Dale tiempo.",
  ["g3:0818db88"] = "Oye, {PLAYER}, no me gusta nada\ncómo te mira...\\pDeberías ser más amable.",
  ["g3:0818dbdd"] = "Eh... siento decírtelo, pero...\\p¿Qué has hecho para que te tenga\ntanta tirria?",
  ["g3:0818dc47"] = "El cariñoso y dulce\nCLEFAIRY.",
  ["g3:0818dc67"] = "{RIVAL}: ¡Hola, {PLAYER}!\n¡El abuelo no está!",
  ["g3:0818dc94"] = "{RIVAL}: ¡Abuelo!\n¡Estoy harto de esperar!",
  ["g3:0818dcb9"] = "{RIVAL}: ¡Oye abuelo!\n¿Y yo qué?",
  ["g3:0818dce2"] = "{RIVAL}: ¡Yo no soy tan egoísta\ncomo tú!\\p¡Venga, elige uno, {PLAYER}!",
  ["g3:0818dd34"] = "{RIVAL}: ¡Pues éste para mí!",
  ["g3:0818dd52"] = "¡{RIVAL} recibió el {STR_VAR_1}\nde manos del PROF. OAK!",
  ["g3:0818dd75"] = "{RIVAL}: Mi POKéMON parece mucho\nmás fuerte.",
  ["g3:0818dda4"] = "{RIVAL}: ¡Espera, {PLAYER}!\n¡Probemos a nuestros POKéMON!\\p¡Adelante, luchemos!",
  ["g3:0818ddea"] = "¿QUÉ?\n¡Increíble!\\l¡Tu POKéMON es mejor que el mío!",
  ["g3:0818de1a"] = "{RIVAL}: ¡Bien!\n¿No soy el mejor?",
  ["g3:0818de38"] = "{RIVAL}: ¡Vale! ¡Haré luchar a mi\nPOKéMON para fortalecerlo!\\p¡{PLAYER}! ¡Abuelo!\n¡Hasta luego!",
  ["g3:0818de8d"] = "{RIVAL}: ¡Abuelo!",
  ["g3:0818de99"] = "{RIVAL}: ¿Qué quieres de mí?",
  ["g3:0818dec8"] = "{RIVAL}: ¡No te preocupes,\nabuelo!\\l¡Déjalo en mis manos!",
  ["g3:0818def3"] = "¡{PLAYER}, que quede claro que no\nte necesito!\\p¡Le pediré a mi hermana su MAPA!\\p¡Y le diré que no te dé ninguno\na ti! ¡Ja, ja, ja!",
  ["g3:0818dfbc"] = "OAK: ¿{RIVAL}?\nDéjame pensar...\\p¡Ah, sí! Te pedí que vinieras.\nEspera...\\p¡{PLAYER}, toma!\\p¡Aquí hay tres POKéMON!\\p¡Bien!\\p¡Están dentro de las POKé BALLS!\\p¡Cuando yo era joven, era un\nbuen ENTRENADOR de POKéMON!\\pPero ahora sólo me quedan tres.\nTe daré uno. ¿Cuál quieres?",
  ["g3:0818e0ea"] = "OAK: ¡Tranquilo, {RIVAL}!\n¡Te daré otro a ti!",
  ["g3:0818e116"] = "OAK: A ver, {PLAYER}.\\pEsas tres POKé BALLS contienen\nun POKéMON cada una.\\p¿Cuál quieres para ti?",
  ["g3:0818e177"] = "OAK: ¡Oye!\n¡No te vayas aún!",
  ["g3:0818e194"] = "¡Así que CHARMANDER!\nPues ten paciencia con él.\\pBueno, {PLAYER}, entonces ¿quieres\nel POKéMON tipo FUEGO CHARMANDER?",
  ["g3:0818e207"] = "¡Así que SQUIRTLE!\nMerece la pena, sí, sí.\\pBueno, {PLAYER}, entonces ¿quieres\nel POKéMON tipo AGUA SQUIRTLE?",
  ["g3:0818e272"] = "¡Así que BULBASAUR!\nResulta muy fácil criarlo.\\pBueno, {PLAYER}, entonces ¿quieres\nel POKéMON tipo PLANTA BULBASAUR?",
  ["g3:0818e2e5"] = "¡Ese POKéMON tiene mucha energía!",
  ["g3:0818e30d"] = "¡{PLAYER} recibió el {STR_VAR_1}\nde manos del PROF. OAK!",
  ["g3:0818e330"] = "OAK: ¡Si aparece un POKéMON\nsalvaje, tu POKéMON podrá luchar\\lcontra él!\\pJunto a él, no te será difícil\nllegar a la siguiente ciudad.",
  ["g3:0818e3ad"] = "OAK: ¡{PLAYER}, entrena a tu joven\nPOKéMON luchando!",
  ["g3:0818e405"] = "OAK: ¡{PLAYER}!\n¿Cómo va tu POKéMON?\\p¡Creo que te quiere mucho!\\p¡Pareces ser muy hábil\nentrenando POKéMON!\\p¿Qué? ¿Tienes algo para mí?",
  ["g3:0818e4af"] = "{PLAYER} entregó el CORREO de OAK.",
  ["g3:0818e4ca"] = "¡Ah, sí! ¡Es la POKé BALL que\nhabía encargado! ¡Gracias!",
  ["g3:0818e508"] = "OAK: ¡Ah, sí!\nQuería pediros un favor.",
  ["g3:0818e536"] = "¡En la mesa hay un invento mío,\nla POKéDEX!\\p¡Registra automáticamente datos\nsobre los POKéMON que vayáis\\lviendo o capturando!\\p¡Es una tecno-enciclopedia!",
  ["g3:0818e5c5"] = "OAK: ¡{PLAYER} y {RIVAL}!\n¡Tomad las POKéDEX!",
  ["g3:0818e5ea"] = "¡{PLAYER} obtuvo una POKéDEX\nde manos del PROF. OAK!",
  ["g3:0818e612"] = "OAK: ¡No se aprenden cosas sobre\nlos POKéMON con sólo verlos!\\p¡Hay que atraparlos!\\pEsto es lo que hace falta\npara atraparlos...",
  ["g3:0818e6b3"] = "¡{PLAYER} obtuvo 5 POKé BALLS!",
  ["g3:0818e6d0"] = "Cuando aparezca un POKéMON\nsalvaje, lo suyo es luchar\\lcontra él.\\p¡Hay que lanzarle una POKé BALL\npara capturarlo!\\p¡Pero esto no siempre funciona!\\p¡Un POKéMON sano podría huir!\n¡También cuenta la suerte!",
  ["g3:0818e784"] = "Quería hacer una guía de todos\nlos POKéMON del mundo...\\p¡Era mi sueño!\\p¡Pero ya soy muy viejo y no puedo\nhacerlo!\\p¡Por eso quiero que vosotros\nhagáis realidad ese sueño!\\p¡Adelante, id en su busca!\\p¡Será una gran proeza en la\nhistoria de los POKéMON!",
  ["g3:0818e871"] = "¡{PLAYER}, los POKéMON del mundo\nte esperan!",
  ["g3:0818e89c"] = "¡Hola, {PLAYER}!\n¿Qué tal llevas la POKéDEX?\\p{RIVAL} ya ha atrapado algunos\nPOKéMON y ha añadido sus datos.\\pVenga, {PLAYER}, deja que vea tu\nPOKéDEX.\\p¡Pero bueno!... ¿Qué pasa?\n¡Pero si no hay datos!\\pToma, anda, pon un poco\nde tu parte.",
  ["g3:0818e98e"] = "OAK: Ven a verme de vez en\ncuando.\\p¡Mantenme informado sobre cómo\nte va con tu POKéDEX!",
  ["g3:0818e9e5"] = "¡Es como una enciclopedia, pero\nlas páginas están en blanco!",
  ["g3:0818ea19"] = "¡Eso de ahí son las POKé BALLS!\n¡Dentro de ellas hay POKéMON!",
  ["g3:0818ea45"] = "¡Ése es el último POKéMON del\nPROF. OAK!",
  ["g3:0818ea66"] = "¡Pulsa START para abrir el menú!",
  ["g3:0818ea84"] = "En la pantalla del menú está\nla opción GUARDAR.",
  ["g3:0818eab6"] = "Todo POKéMON tiene sus puntos\ndébiles y fuertes frente al resto.",
  ["g3:0818eaf4"] = "¡Hay un correo electrónico!\\p...\\p¡Aviso a todos los ENTRENADORES\nde POKéMON!\\p¡Los ENTRENADORES de élite de la\nLIGA POKéMON están listos para\\ldesafiaros a todos!\\p¡Traed a vuestros mejores POKéMON\npara ver lo buenos que sois!\\pCG de la LIGA POKéMON, MESETA\nAÑIL\\pPD: ¡PROF. OAK, visítenos por\nfavor!...",
  ["g3:0818ebe6"] = "Estudio a los POKéMON.\n¡Soy ayudante del PROF. OAK!",
  ["g3:0818ec0b"] = "Hola, {PLAYER}. Seguro que has\nhecho buenas migas con tus\\lPOKéMON.\\pA todo esto, ¿conoces a DALIA?\\pSi le enseñas a DALIA tus POKéMON,\nsabrá decirte si les gustas o no.\\pY puede que les dé un lavado de\ncara para que estén presentables.\\lPero no vayas diciéndolo por ahí.",
  ["g3:0818ed15"] = "El PROF. OAK va a tener pronto\nsu propio programa de radio.\\pSerá el SEMINARIO sobre POKéMON\ndel PROF. OAK.",
  ["g3:0818ed81"] = "¡El PROF. OAK es un experto\nen POKéMON!\\p¡Es admirado por muchos de los\nENTRENADORES POKéMON!",
  ["g3:0818edf5"] = "¡Ah, una cosa importante!\n{PLAYER}, tengo que pedirte otro\\lgran favor.\\pNecesito que prestes atención.",
  ["g3:0818ee60"] = "Hace poco, se han visto especies\nde POKéMON raros.\\pEs decir, POKéMON que jamás\nse han visto en KANTO.\\pMe encantaría comprobarlo con mis\npropios ojos, pero ya soy mayor.\\pYa que yo no puedo, ¿podrías ir tú\nen mi lugar, {PLAYER}?",
  ["g3:0818ef59"] = "{RIVAL}: ¡Eh, lo he oído todo!\\p¡Ya está bien de favoritismos!\n¡Prefieres a {PLAYER} antes que\\la mí, abuelo!\\p¡Yo he atrapado más POKéMON,\ny en menos tiempo!\\p¡Deberías dejar que yo me ocupe\nde todo!",
  ["g3:0818f004"] = "OAK: No, hombre, no te pongas así.\nTú también me ayudas mucho, majo.\\pA ver, enseñadme vuestras\nPOKéDEX.",
  ["g3:0818f062"] = "PROF. OAK tomó las dos POKéDEX.",
  ["g3:0818f085"] = "... ... ... ... ... ...\\p... ... ... ... ... ...\\p...¡Listo!\\pAhora podrán guardar datos\nde muchos más POKéMON.",
  ["g3:0818f0e8"] = "¡La POKéDEX de {PLAYER} tiene\nahora más capacidad!",
  ["g3:0818f103"] = "Bueno, {PLAYER} y {RIVAL},\nya está.\\pAhora tenéis que trabajar mucho\ny completar las POKéDEX.\\p¡Serán las mejores y las más\ncompletas de todos los tiempos!\\p¡Vamos a dar un paso de gigante\nen la historia de los POKéMON!",
  ["g3:0818f1db"] = "{RIVAL}: Tranqui, abuelo, que te\nva a dar algo...\\pYo completaré mi POKéDEX,\nno te preocupes.\\pCreo que iré a ISLA PRIMA,\nen primer lugar.\\pBueno, me piro, vampiro.",
  ["g3:0818f292"] = "Inventarse motes es divertido, pero\ndifícil.\\pEs más fácil recordar nombres\nsencillos.",
  ["g3:0818f30f"] = "¡A mi padre también le gustan los\nPOKéMON!",
  ["g3:0818f32c"] = "SPEARY: ¡Spe-pe-peeary!",
  ["g3:0818f33d"] = "SPEAROW\nNombre: SPEARY",
  ["g3:0818f4a2"] = "¡He perdido, ya no soy digno\nde dirigir a mis secuaces!\\p¡Se acabó el TEAM ROCKET!\\p¡Dedicaré mi vida al estudio\nde los POKéMON!\\p¡Espero que nos volvamos a ver!\n¡Adiós!",
  ["g3:0818f586"] = "¡Con la MEDALLA TIERRA, todos\nlos POKéMON te obedecerán!\\p¡Es una prueba de tu maestría\nentrenando POKéMON!\\p¡Con ella podrás acceder\na la LIGA POKéMON!\\p¡Es mi regalo por desafiar\na la LIGA POKéMON!",
  ["g3:0818f675"] = "¡{PLAYER} obtuvo la MT26\nde manos de GIOVANNI!",
  ["g3:0818f695"] = "¡La MT26 es TERREMOTO!\\p¡Es muy potente, causa un\ntemblor devastador!\\pLa inventé cuando dirigía este\nGIMNASIO, hace ya mucho tiempo...",
  ["g3:0818f71b"] = "¡Llevas muchas cosas!",
  ["g3:0818f73b"] = "¡Oye!\nYa no debe de quedarte nada\\lde energía, ¿no?",
  ["g3:0818f769"] = "¡Me he quedado sin fuerza!",
  ["g3:0818f77b"] = "¡Necesitas potencia para luchar\ncontra el LÍDER del GIMNASIO!",
  ["g3:0818f7ad"] = "¡Groaar!\n¡Me estoy mosqueando!",
  ["g3:0818f7d6"] = "¡Rargh!",
  ["g3:0818f7dd"] = "¡No me merezco nada!",
  ["g3:0818f7f3"] = "¡Mis POKéMON y yo hacemos\nmuy buena música!",
  ["g3:0818f824"] = "¡Estás en perfecta armonía!",
  ["g3:0818f840"] = "¿Sabes quién es el LÍDER de\nnuestro GIMNASIO?",
  ["g3:0818f86c"] = "¡El karate es lo máximo en artes\nmarciales!",
  ["g3:0818f899"] = "¡Ayyyy!",
  ["g3:0818f8a0"] = "Si mis POKéMON fueran buenos\nkaratekas...",
  ["g3:0818f8cb"] = "¡Los más hábiles ganan con estilo!",
  ["g3:0818f8ee"] = "¡He perdido el control!",
  ["g3:0818f8fe"] = "¡El LÍDER me va a reñir!",
  ["g3:0818f92c"] = "¡Soy el REY del KARATE!\n¡Te tengo en mis manos!",
  ["g3:0818f95a"] = "¡Ayah!",
  ["g3:0818f960"] = "¿La LIGA POKéMON? ¿Tú?\n¿Pero quién te crees que eres?",
  ["g3:0818f98a"] = "¡Tus POKéMON se arrodillarán\nde un solo latigazo!",
  ["g3:0818f9bb"] = "¡Auch!\n¡Vaya latigazo!",
  ["g3:0818f9cc"] = "¡Espera!\n¡No he tenido ningún cuidado!",
  ["g3:0818f9e7"] = "¡El GIMNASIO de VERDE estuvo\ncerrado mucho tiempo, pero nuestro\\lLÍDER ha vuelto!",
  ["g3:0818fa2d"] = "¿Me has ganado?",
  ["g3:0818fa3b"] = "¡Accederás a la LIGA POKéMON\nsi ganas a nuestro LÍDER!",
  ["g3:0818fa81"] = "¡Hola, aspirante al título!\\p¡Ni yo conozco la identidad del\nLÍDER de VERDE!\\p¡Debe de ser el más duro de todos\nlos LÍDERES de GIMNASIO!\\p¡Dicen que estos ENTRENADORES usan\nlos POKéMON del tipo TIERRA!",
  ["g3:0818fb56"] = "¿Qué dices? ¿Que GIOVANNI era\nel LÍDER del GIMNASIO?",
  ["g3:0818fb8d"] = "LÍDER del GIMNASIO POKéMON\nde CIUDAD VERDE: (?)\\pENTRENADOR GANADOR:\n{RIVAL}",
  ["g3:0818fbc1"] = "LÍDER del GIMNASIO POKéMON\nde CIUDAD VERDE: GIOVANNI\\pENTRENADORES GANADORES:\n{RIVAL} y {PLAYER}",
  ["g3:0818fc00"] = "Estoy intentando memorizar todos\nmis apuntes.",
  ["g3:0818fc2b"] = "¡Muy bien!\\p¡No olvides leer la pizarra con\nmucha atención!",
  ["g3:0818fc65"] = "A ver qué pone en el cuaderno...\\pPrimera página...\\pLas POKé BALLS son para atrapar\na los POKéMON.\\pPuedes llevar hasta 6 POKéMON.\\pLos ENTRENADORES son la gente\nque entrena y hace pelear a sus\\lPOKéMON.",
  ["g3:0818fd23"] = "Segunda página...\\p¡Un POKéMON sano no es tan fácil\nde atrapar, conviene debilitarlo\\lprimero!\\p¡Los venenos, las quemaduras y\notros daños son muy efectivos!",
  ["g3:0818fda8"] = "Tercera página...\\pLos ENTRENADORES POKéMON luchan\ncontra otros, en combates POKéMON.\\pLo cierto es que la victoria tiene\nun sabor muy dulce.\\pEn los GIMNASIOS siempre se están\nlibrando combates POKéMON.",
  ["g3:0818fe5c"] = "Cuarta página...\\pEl objetivo de todo ENTRENADOR\nes derrotar a los 8 mejores\\lLÍDERES de GIMNASIO.\\pSi lo consigue, podrá desafiar...\\p¡Al ALTO MANDO de la LIGA\nPOKéMON!",
  ["g3:0818ff19"] = "¿Paso la página?",
  ["g3:0818ff28"] = "NIÑA: ¡Oye!\n¡No mires mis apuntes!",
  ["g3:0818ff4b"] = "La pizarra indica los cambios de\nlas CARACTERÍSTICAS de los\\lPOKéMON durante los combates.",
  ["g3:0818ff88"] = "¿Sobre qué tema te gustaría leer?",
  ["g3:0818ffa9"] = "¡Un POKéMON no puede atacar si\nestá dormido!\\p¡Los POKéMON seguirán dormidos\nincluso después de pelear!\\p¡Usa DESPERTAR y se despertarán!",
  ["g3:08190025"] = "Toda quemadura reduce la fuerza\ndel ATAQUE y va restando PS.\\pLas quemaduras permanecerán tras\nel combate.\\p¡ANTIQUEMAR curará las\nquemaduras!",
  ["g3:0819009f"] = "Todo POKéMON envenenado\nseguirá perdiendo energía.\\pEl veneno sigue haciendo efecto\ntras el combate.\\p¡Usa un ANTÍDOTO para curar\nel envenenamiento!",
  ["g3:0819010f"] = "¡Todo POKéMON congelado no podrá\nmoverse!\\pY permanecerá congelado tras el\ncombate.\\p¡Usa el ANTIHIELO para\ndescongelar a los POKéMON!",
  ["g3:08190199"] = "¡La parálisis podría anular ciertos\nmovimientos!\\pY permanece tras el combate.\\pUsa ANTIPARALIZAR para liberar a\nlos POKéMON que estén paralizados.",
  ["g3:0819021a"] = "¡Oye!\n¿Vienes de PUEBLO PALETA?",
  ["g3:0819023a"] = "¿Conoces al PROFESOR OAK?\\pTiene correo.\n¿Se lo puedes llevar?",
  ["g3:08190289"] = "¡El empleado de la TIENDA PKMN le\ndio a {PLAYER} el CORREO de OAK!",
  ["g3:081902bf"] = "¡Bueno, gracias!\n¡Saluda al PROF. OAK de mi parte!",
  ["g3:081902f5"] = "En esta tienda venden muchos\nANTÍDOTOS, creo.",
  ["g3:0819032c"] = "Yo tengo algunas POCIONES.\\pNunca sabes cuándo pueden\nnecesitarlas tus POKéMON.",
  ["g3:08190384"] = "Puedes usar ese PC de la esquina.\\p¡Me lo dijo la recepcionista!\n¡Es muy amable!",
  ["g3:081903e5"] = "Hay un CENTRO POKéMON en todas\nlas ciudades.\\p¡Y todos son gratuitos!",
  ["g3:08190450"] = "¡Los CENTROS POKéMON curan a tus\nPOKéMON heridos o debilitados!",
  ["g3:081904f9"] = "¡Hasta pronto!",
  ["g3:0819051c"] = "No tienes suficiente dinero.",
  ["g3:08190539"] = "Disfruta de la visita.",
  ["g3:08190550"] = "¡No puedes entrar por detrás!\\p¡Bueno, da igual!\n¿Sabes qué es el ÁMBAR?",
  ["g3:081905b1"] = "¿Y sabías que el ÁMBAR contiene\nmaterial genético de los POKéMON?\\pDicen que hay un LABORATORIO\ndonde intentan revivir a viejos\\lPOKéMON a partir del ÁMBAR.",
  ["g3:08190627"] = "El ÁMBAR es, en realidad, savia\nde árbol fosilizada.",
  ["g3:081906b4"] = "¡Qué golpe de suerte!\\p¡Nunca pensé que conseguiría\nver huesos de dragón!",
  ["g3:08190717"] = "¡Ssh! Voy a contarte un secreto.\\p¡Creo que este trozo de ÁMBAR\ncontiene ADN de POKéMON!\\p¡Sería un descubrimiento científico\nincreíble si se pudiera revivir a\\llos POKéMON con esto!\\p¡Pero mis colegas no me hacen\nni caso! ¡Por eso te voy a pedir\\lun favor!\\p¡Lleva esto al LABORATORIO\nPOKéMON para que lo analicen!",
  ["g3:08190866"] = "¡{PLAYER} recibió el ÁMBAR VIEJO\nde manos del hombre!",
  ["g3:0819088e"] = "¡Ssh!\n¡Haz que analicen el ÁMBAR VIEJO!",
  ["g3:081908ae"] = "¡No tienes sitio para esto!",
  ["g3:081908cd"] = "¡Tenemos dos fósiles de unos\nPOKéMON muy raros y prehistóricos!",
  ["g3:0819090a"] = "¡El ÁMBAR es transparente y de\ncolor oro!",
  ["g3:08190945"] = "Fósil AERODACTYL.\nUn primitivo y raro POKéMON.",
  ["g3:08190975"] = "Fósil KABUTOPS.\nUn primitivo y raro POKéMON.",
  ["g3:081909a3"] = "Los secretos del espacio...\nLos misterios de la tierra...\\pHay tantas cosas de las que\nsabemos tan poco...\\pPero eso debería movernos a\ninvestigar más y no tirar la toalla.\\pY hablando de movimiento...\\p¿Conoces el MOV. SÍSMICO?\n¿Quieres que se lo enseñe a algún\\lPOKéMON?",
  ["g3:08190aa9"] = "¿Ah, no?\nSeguro que vuelves a pedírmelo.",
  ["g3:08190ad5"] = "¿A qué POKéMON quieres que\nle enseñe MOV. SÍSMICO?",
  ["g3:08190b00"] = "Espero que no tires la toalla.\nSigue así.",
  ["g3:08190b30"] = "¿La PIEDRA LUNAR?\\p¿Por qué es tan especial?\nYo no le veo nada del otro mundo.",
  ["g3:08190bf3"] = "Ahora tenemos una exposición sobre\nel espacio.",
  ["g3:08190c1e"] = "¡Quiero un PIKACHU!\n¡Es tan mono!\\p¡Le pedí a mi padre que me\natrapara uno!",
  ["g3:08190c60"] = "¡Sí, pronto tendrás a tu\nPIKACHU!... ",
  ["g3:08190c81"] = "NAVE ESPACIAL",
  ["g3:08190c8f"] = "Meteorito caído en el MT. MOON.\n(¿PIEDRA LUNAR?)",
  ["g3:08190fc1"] = "¡Espera!\n¡Lleva esto contigo!",
  ["g3:08190fdb"] = "¡{PLAYER} obtuvo la MT39\nde manos de BROCK!",
  ["g3:08190ff8"] = "¡La MT incluye un ataque que\npuede ser enseñado a los POKéMON!\\p¡Pero sólo puedes usarla una vez!\\p¡Así que elige con cuidado a qué\nPOKéMON se la enseñas!\\p¡La MT39 contiene TUMBA ROCAS!\\p¡Podrás lanzar rocas al rival\ny bajar su VELOCIDAD!",
  ["g3:0819110f"] = "¡En el mundo hay todo tipo de\nENTRENADORES!\\p¡Pareces ser muy hábil\nentrenando POKéMON!\\p¡Vete al GIMNASIO de CELESTE y\npon a prueba tus habilidades!",
  ["g3:081911ce"] = "¡No tienes sitio para esto!",
  ["g3:081911ec"] = "¡Alto ahí, enclenque!\\p¡Todavía estás a años luz de retar\na BROCK!",
  ["g3:08191237"] = "¡Vaya!\\p¡Años luz no suponen tiempo!\n¡Miden distancia!",
  ["g3:0819126b"] = "¡Eres bastante fuerte, pero no\ntanto como BROCK!",
  ["g3:08191298"] = "¡Puedo decirte lo que se requiere\npara ser un campeón de POKéMON!\\p¡No soy ENTRENADOR, pero puedo\ndecirte cómo ganar!\\p¡Déjame que te lleve a la\nvictoria!",
  ["g3:0819133c"] = "¡Muy bien!\n¡Vamos allá!",
  ["g3:08191412"] = "¡Es gratis!\n¡Venga!",
  ["g3:0819143c"] = "¡Lo sabía!\n¡Tienes madera!",
  ["g3:0819146e"] = "LÍDER del GIMNASIO POKéMON\nde PLATEADA: BROCK\\pENTRENADOR GANADOR:\n{RIVAL}",
  ["g3:081914a4"] = "LÍDER del GIMNASIO POKéMON\nde PLATEADA: BROCK\\pENTRENADORES GANADORES:\n{RIVAL} y {PLAYER}",
  ["g3:08191541"] = "¡Podrían suceder cosas buenas si\nentrenaras rápidamente a tus\\lPOKéMON, hasta a los más débiles!",
  ["g3:081915bb"] = "NIDORAN♂: ¡Nidor!",
  ["g3:081915cd"] = "¡Siéntate, NIDORAN!",
  ["g3:081915db"] = "Nuestro POKéMON es forastero,\ny es difícil de manejar.\\pUn forastero es un POKéMON\nintercambiado con otro jugador.\\p¡Crece deprisa, pero a veces\nno hace caso a los ENTRENADORES\\lnovatos en combates!\\p¡Ojalá tuviéramos algunas\nMEDALLAS!",
  ["g3:081916a9"] = "¿¡Qué!?\\p¿Que el TEAM ROCKET está en el\nMT. MOON?\\p¡Estoy hablando por teléfono!\n¿Será posible?",
  ["g3:081916ea"] = "JIGGLYPUFF: ¡Puf! ¡Puuuff!",
  ["g3:08191701"] = "Aaah..., qué sueño...\\pCuando JIGGLYPUFF canta, los\nPOKéMON se duermen...\\pY yo también...\nQué sueño...",
  ["g3:08191743"] = "¡Yo quiero un PIKACHU, así que\nvoy a intercambiar a mi CLEFAIRY\\lpor uno!",
  ["g3:08191780"] = "Voy a intercambiar mi POKéMON\ncon ese chico de ahí.\\pComo tengo dos PIKACHU,\nvoy a pasarle uno.",
  ["g3:081917e4"] = "¡Los POKéMON aprenden nuevos\nataques a medida que crecen!\\p¡Pero hay ciertos ataques que\nhay que enseñarles!",
  ["g3:08191840"] = "¡Los POKéMON serán más fáciles\nde atrapar si están heridos o\\ldormidos!\\p¡Pero no siempre es así!",
  ["g3:081918e7"] = "Sólo tienen MEDALLAS los\nENTRENADORES más hábiles.\\pYa veo que tienes una por lo\nmenos.\\p¡Esas MEDALLAS guardan secretos\nincreíbles!",
  ["g3:08191967"] = "Dime...\\p¿Cuál de las 8 MEDALLAS debería\ndescribirte?",
  ["g3:0819199e"] = "Ven a verme cuando quieras.",
  ["g3:081919be"] = "Hace que aumente un poco\nel ATAQUE de los POKéMON.\\pY permite usar DESTELLO siempre\nque quieras.",
  ["g3:08191a31"] = "Hace que te obedezcan los POKéMON\nde nivel inferior a 30.\\pY no sólo los tuyos, sino también\nlos forasteros obtenidos\\lpor intercambio.\\p¡Los de nivel superior, serán\nincontrolables!\\pTambién permite usar CORTAR\nfuera del combate.",
  ["g3:08191af9"] = "Hace que aumente un poco\nla VELOCIDAD de los POKéMON.\\pY permite usar VOLAR siempre\nque quieras.",
  ["g3:08191b69"] = "Hace que te obedezcan los POKéMON\nde nivel inferior a 50.\\pY no sólo los tuyos, sino también\nlos forasteros obtenidos\\lpor intercambio.\\p¡Los de nivel superior, serán\nincontrolables!\\pTambién permite usar FUERZA\nfuera del combate.",
  ["g3:08191c36"] = "Hace que aumente un poco\nla DEFENSA de los POKéMON.\\pY permite usar SURF siempre\nque quieras.",
  ["g3:08191ca9"] = "Hace que te obedezcan los POKéMON\nde nivel inferior a 70.\\pY no sólo los tuyos, sino también\nlos forasteros obtenidos\\lpor intercambio.\\p¡Los de nivel superior, serán\nincontrolables!\\pTambién permite usar GOLPE\nROCA fuera del combate.",
  ["g3:08191d78"] = "Hace que aumenten un poco\nel AT. ESP. y la DEF. ESP.\\lde los POKéMON.\\pY permite usar CASCADA siempre\nque quieras.",
  ["g3:08191df8"] = "¡Todos los POKéMON te obedecerán!",
  ["g3:08191e13"] = "¡Esos dichosos ROCKET!\\p¡Mira lo que hicieron aquí!\\p¡Robaron una MT para enseñar a\nlos POKéMON cómo EXCAVAR hoyos!\\pYo que quería enseñárselo a\nMANKEY o a SANDSHREW... \\p¡Menuda faena!",
  ["g3:08191ed8"] = "¡Lo perdido, perdido está!\\p¡He decidido enseñar a DIGLETT\ncómo EXCAVAR sin tener una MT!",
  ["g3:08191f2a"] = "¡El TEAM ROCKET estará intentando\nEXCAVAR para hacer alguna de las\\lsuyas!",
  ["g3:08191f64"] = "¡El TEAM ROCKET abrió una nueva\nsalida!",
  ["g3:08191f80"] = "A mi marido le gusta intercambiar\nPOKéMON.\\pSi eres coleccionista, ¿podrías\nintercambiar con él?\\p¡Te vendría de perlas para tu\nPOKéDEX!",
  ["g3:08191ffb"] = "¡Este BILL!\\p¡Dicen que haría lo que fuera para\nconseguir POKéMON raros!",
  ["g3:08192079"] = "¿Has oído hablar de BILL?\\p¡Dicen que es un POKéMANÍACO!\\pPero yo creo que la gente le tiene\nmucha envidia.\\p¿Quién no querría presumir de sus\nPOKéMON?",
  ["g3:08192116"] = "¡BILL tiene muchísimos POKéMON!\n¡Y algunos son muy raros!",
  ["g3:0819214c"] = "¿Por qué no subes e intercambias\nPOKéMON con tus amigos?\\p¡Así se pueden conseguir POKéMON\nmuy distintos!\\pAdemás, los que consigues por\nintercambio, crecen antes.",
  ["g3:081922bf"] = "¡La MT03 enseña HIDROPULSO!\\p¡Úsala con los POKéMON del tipo\nAGUA!",
  ["g3:081922f7"] = "¡La MEDALLA CASCADA obligará a\ntodos los POKéMON por debajo del\\lnivel 30 a obedecer!\\p¡Incluidos los forasteros!\\p¡Y podrás usar CORTAR siempre que\nquieras!\\p¡Puedes CORTAR pequeños arbustos\npara abrir nuevos caminos!\\p¡Voy a darte mi MT favorita!",
  ["g3:081923f1"] = "¡{PLAYER} obtuvo la MT03\nde manos de MISTY!",
  ["g3:0819240e"] = "¡Más vale que le hagas sitio!",
  ["g3:0819242d"] = "¡Uauuu!\n¡Eres demasiado!\\p¡Muy bien!\\p¡Toma la MEDALLA CASCADA para que\ntodos sepan que me has ganado!",
  ["g3:08192481"] = "¡Soy demasiado buena para ti!\\p¡MISTY puede esperar!",
  ["g3:081924d0"] = "¡Me has machacado!",
  ["g3:081924e4"] = "Tienes que luchar contra otros\nENTRENADORES para saber lo fuerte\\lque eres.",
  ["g3:08192524"] = "¡Splash!\\p¡Soy el primero!\n¡Al ataque!",
  ["g3:08192547"] = "¡No puede ser!",
  ["g3:08192556"] = "¡MISTY es cada vez más fuerte!\\p¡No perderá con alguien como tú!",
  ["g3:081925ac"] = "¡Hola, aspirante al título!\\p¡Un consejo!\\p¡La LÍDER, MISTY, es profesional\ny usa POKéMON acuáticos!\\p¡Puedes absorber toda su agua con\nlos POKéMON del tipo PLANTA!\\p¡O dejarlos hechos polvo usando\nPOKéMON del tipo ELÉCTRICO!",
  ["g3:08192688"] = "¡Has ganado a MISTY!\n¡No sé qué decirte!\\p¡Tú y yo formaríamos un equipo\ninvencible!",
  ["g3:081926e1"] = "LÍDER del GIMNASIO POKéMON\nde CELESTE: MISTY\\pENTRENADOR GANADOR:\n{RIVAL}",
  ["g3:08192719"] = "LÍDER del GIMNASIO POKéMON\nde CELESTE: MISTY\\pENTRENADORES GANADORES:\n{RIVAL} y {PLAYER}",
  ["g3:08192755"] = "¡Ésta es la TIENDA de BICIS!\\p¡Tenemos la BICI que buscabas!",
  ["g3:08192796"] = "¡Lo siento!\n¡No tienes dinero para pagarla!",
  ["g3:081927b2"] = "Anda, pero si tienes...\\p¡Un BONO para una BICICLETA!\\p¡Muy bien!\n¡Toda tuya!",
  ["g3:081927e1"] = "{PLAYER} cambió el BONO por una\nBICICLETA.",
  ["g3:0819280e"] = "¡Vuelve cuando quieras!",
  ["g3:08192833"] = "¿Te gusta tu nueva BICICLETA?\\p¡Puedes usarla por el CAMINO\nde BICIS y por las cuevas!",
  ["g3:081928cf"] = "¡Sólo necesito una BICICLETA\nnormal!\\p¡No puedes poner una cesta en una\nMOTOCICLETA!",
  ["g3:08192937"] = "¡Estas BICIS son geniales, pero\nmuy caras!",
  ["g3:08192968"] = "¡Uauu!\n¡Vaya BICI tan chula!",
  ["g3:081929ad"] = "¡Una BICI nueva y reluciente!",
  ["g3:081929c2"] = "Usa el REPELENTE para evitar a los\nbichos y a los POKéMON débiles.\\p¡Pon a tu POKéMON más fuerte el\nprimero de la lista para conseguir\\lmejores resultados!\\pSi tu primer POKéMON es fuerte,\nel REPELENTE tendrá mayor efecto.",
  ["g3:08192a79"] = "¿Has visto algún CARAMELORARO?\\p¡Dicen que los POKéMON suben\nun nivel si se comen uno!",
  ["g3:08192af0"] = "Uff... Tengo tanto tiempo\ny tan poco que hacer...\\p¿No hay nada divertido cociéndose\npor ahí?",
  ["g3:08192b43"] = "¡Anda, hay novedades!\n¡Un boletín informativo!\\pA ver, a ver...\\p¡Interesante!\n¡Interesantísimo!\\pMuy bien, me encanta que la gente\njoven como tú se interese por las\\lnoticias.\\pQuiero agradecerte el haberme\ntraído estas noticias, toma.",
  ["g3:08192c07"] = "¡Por fin!\n¡Un boletín informativo!\\pA ver, a ver...\\p¡Maravilloso!\n¡Maravillosísimo!\\pHacía tiempo que no leía nada\nigual.\\pGracias por traerme semejantes\nnoticias, toma, unas BAYITAS.",
  ["g3:08192cd5"] = "Sería una pena no compartir estas\nnoticias...\\pMe encantaría poder pasárselas\na alguien...\\lCompártelas con más gente...",
  ["g3:08192d4b"] = "¿Has pasado las noticias\na más gente?\\p¡Las buenas noticias hay que\ncompartirlas con quien se pueda!\\pGracias por pasárselas a otras\npersonas, toma, anda.",
  ["g3:08192de3"] = "¿Has pasado las noticias\na más gente todavía?\\p¡Las propias noticias deben\nde estar encantadas de la vida!\\p¡Lo que yo te diga!\\p¡En mi nombre y en nombre\nde las propias noticias, toma!\\p¡Voy a darte más BAYITAS\nque de costumbre!",
  ["g3:08192ec5"] = "Yo me lo paso pipa leyendo\nnoticias. Todas me gustan, todas.\\p¡Ya estoy contento! ¡Voy a estar\nentretenido para rato!",
  ["g3:08192f2a"] = "Vaya, tienes el SACO de las BAYAS\nhasta arriba. Vuelve a por ellas\\lcuando tengas sitio.",
  ["g3:08192f67"] = "Yo hago una especie de medicina\na partir del POLVO de BAYA.\\pY si el POLVO de BAYA es bueno,\nhago unos mejunjes espectaculares.\\pBueno, a todo esto, ¿te gustan\nlas BAYAS?",
  ["g3:08193003"] = "Ah, estupendo, pues voy a darte\nuna cosita.",
  ["g3:08193033"] = "Hay algo nuevo en el primer piso\nde los CENTROS POKéMON, en la\\lZONA DIRECTA.\\pSe ha instalado una máquina para\nConectores inalámbricos de GBA,\\lque permite MACHACAR BAYAS.\\p¿Que para qué te cuento esto?\\pPues porque tengo que pedirte\nun favor. Sólo tú puedes ayudarme.\\p¿Podrías hacer POLVO de BAYA\nusando esa máquina?\\pRecuerda, la máquina está en la\nZONA DIRECTA de los CENTROS\\lPOKéMON.\\pSi me traes el POLVO de BAYA,\nelaboraré una medicina para ti.\\p¡Hala, MACHACA algunas BAYAS\ny tráeme el POLVO de BAYAS!",
  ["g3:0819321d"] = "¿Por qué me mientes?\\p¿Cuántas BAYAS tienes?\n¡Ni una!",
  ["g3:0819325e"] = "¡A ti las BAYAS te importan\nun pimiento!\\pPues debes saber que hay que\ntener interés por todas las cosas.",
  ["g3:081932c5"] = "¡Eh! ¿Me has traído POLVO\nde BAYA?",
  ["g3:081932f4"] = "¿Por qué quieres que te lo cambie?",
  ["g3:0819331e"] = "Vale, te cambio el POLVO de BAYA\npor una unidad de {STR_VAR_1}.",
  ["g3:08193352"] = "¿Mm? No tienes suficiente POLVO\nde BAYA.",
  ["g3:0819337a"] = "Este POLVO de BAYA es excelente.\nVa a salir una medicina buenísima.\\p¿Quieres cambiar más POLVO\nde BAYA por otra cosa más?",
  ["g3:081933fb"] = "Muy bien, muy bien.\nHasta la próxima.",
  ["g3:0819342f"] = "Ven a verme cuando quieras cambiar\nPOLVO de BAYA por otra cosa.",
  ["g3:08193465"] = "¡El TEAM ROCKET hará lo que sea\npor el oro!\\p¡No hay trabajo sucio ni actos\nvandálicos que no sean capaces\\lde hacer!",
  ["g3:081934de"] = "¡Vi a la madre de CUBONE\nintentando huir del TEAM ROCKET!\\pLa pobre no lo consiguió...",
  ["g3:0819353a"] = "Los CUBONE llevan cráneos,\n¿verdad?\\p¡La gente pagaría mucho por uno\nde ellos!",
  ["g3:0819358e"] = "Acabo de mudarme a este pueblo.\\pHe oído que el SR. FUJI tampoco\nes de por aquí.",
  ["g3:081935ed"] = "El SR. FUJI no está aquí.\n¡Qué raro! ¿Adónde ha ido?",
  ["g3:0819361d"] = "El SR. FUJI estaba rindiendo\nhomenaje a la madre de CUBONE.",
  ["g3:08193652"] = "Ésta es la casa del SR. FUJI.\\p¡Es muy amable!\\p¡Cuida de los POKéMON huérfanos\ny abandonados!",
  ["g3:081936b4"] = "¡Es tan bonito abrazar a los\nPOKéMON!",
  ["g3:081936de"] = "NIDORINO: ¡Nidor!",
  ["g3:081936ee"] = "PSYDUCK: ¡Psydu!",
  ["g3:081936ff"] = "SR. FUJI: {PLAYER}.\\pTe va a costar mucho esfuerzo\ncompletar la POKéDEX.\\pSi no adoras a tus POKéMON,\nte resultará difícil finalizarla.\\pCreo que esto te ayudará.",
  ["g3:081937bd"] = "¡{PLAYER} obtuvo la POKé FLAUTA\nde manos del SR. FUJI!",
  ["g3:081937e5"] = "Cuando escuchen la POKé FLAUTA,\nlos POKéMON dormidos se\\ldespertarán.\\pFunciona con todos los POKéMON\ndormidos.",
  ["g3:0819385b"] = "¡No tienes sitio para esto!",
  ["g3:08193878"] = "SR. FUJI: ¿Te ayudó mi POKé\nFLAUTA?",
  ["g3:081938a0"] = "REVISTA POKéMON\n¡Gran concurso mensual de dibujo\\lPOKéMON!\\pEl formulario de inscripción está\nen...\\p¡Anda, se lo han llevado!\n¡Se ha debido de inscribir alguien!",
  ["g3:0819392b"] = "¡Revistas de los POKéMON!\\p¡Cuadernos de los POKéMON!\\p¡Dibujos de los POKéMON!",
  ["g3:0819396b"] = "CUBONE: ¡Cubon!",
  ["g3:0819397d"] = "¡Odio a esos horribles ROCKET!\\pLa pobre madre de CUBONE...\\p¡Intentó escapar del TEAM ROCKET,\npero no lo consiguió!...",
  ["g3:081939f8"] = "¡El GHOST de la TORRE POKéMON\nse ha ido!\\p¡Alguien debe de haber calmado\nsu atormentada alma!",
  ["g3:08193a4b"] = "¡Je, je! ¡Hola!\n¡Soy el INSPECTOR de los MOTES!\\l¡El adivinador de nombres!\\pEstaré encantado de evaluar\nel nombre de tu POKéMON, je, je.",
  ["g3:08193aa6"] = "¿Qué nombre de POKéMON\nquieres que adivine y evalúe?",
  ["g3:08193ad2"] = "Mmmmm... {STR_VAR_1}, ¿a que sí?\nNo está mal, no está mal...\\pPero ¿no crees que podríamos\nencontrar un nombre aún mejor?",
  ["g3:08193b36"] = "Así me gusta. A ver... \n¿Cuál será el nuevo nombre?",
  ["g3:08193b66"] = "¡Ya está! ¡A partir de ahora,\nel nombre de este POKéMON\\lserá {STR_VAR_1}!\\pEs un nombre mucho mejor que\nel anterior, ¡qué suerte tienes!",
  ["g3:08193bd4"] = "Muy bien...\nEntonces vuelve cuando quieras.",
  ["g3:08193bf0"] = "¡Ya está! ¡A partir de ahora,\nel nombre de este POKéMON\\lserá {STR_VAR_1}!\\pNo parece muy diferente\ndel anterior y, sin embargo,\\les muchísimo mejor.\\p¡Qué suerte tienes!",
  ["g3:08193c82"] = "¿{STR_VAR_1}?\n¡Ese nombre es perfecto!\\p¡Cuida bien de {STR_VAR_1}!",
  ["g3:08193cc4"] = "Pero vamos a ver...\n¡Esto es sólo un HUEVO!",
  ["g3:08193ce5"] = "Estoy buscando algunos objetos que\naumenten las habilidades de los\\lPOKéMON en un sólo combate.\\pEstoy buscando ATAQUE X,\nDEFENSA X, VELOCIDAD X y\\lESPECIAL X.\\p¿Sabes dónde encontrarlos?",
  ["g3:08193db6"] = "¿Conoces REVIVIR?\nDevuelve la energía a los POKéMON\\ldebilitados.",
  ["g3:08193df1"] = "A veces, coincidirás con parejas\nde ENTRENADORES que te retarán\\lcon dos POKéMON a la vez.\\pCuando esto ocurra, para luchar\ntú también necesitarás dos POKéMON.",
  ["g3:08193ec1"] = "¡Yo soy el GURÚ PESCADOR!\\p¡Me encanta pescar!\n¡Es lo más!\\pY a ti, ¿te gusta pescar?",
  ["g3:08193f2a"] = "¡Fenomenal!\n¡Me gusta tu estilo!\\p¡Toma esto y pesca, anda!",
  ["g3:08193f81"] = "¡{PLAYER} recibió una CAÑA VIEJA\nde manos del GURÚ PESCADOR!",
  ["g3:08193faf"] = "¡La pesca es una forma de vida!\n¡Es un arte!\\p¡En el mar, en los ríos, da igual,\nhay que pescar el más grande!",
  ["g3:08194028"] = "Oh...\nEstoy tan decepcionado...",
  ["g3:08194045"] = "¡Hola, {PLAYER}!\\p¿Cómo va esa pesca?",
  ["g3:0819406f"] = "¡Oh, no!\\p¡Tenía un regalo para ti, pero no\ntienes sitio!",
  ["g3:081940af"] = "Aunque sean del mismo nivel, los\nPOKéMON pueden tener diferentes\\lhabilidades.\\pUn POKéMON entrenado es más fuerte\nque uno salvaje.",
  ["g3:08194145"] = "¡Mi POKéMON fue envenenado y\nse debilitó mientras caminábamos!",
  ["g3:08194180"] = "Es cierto que un POKéMON de un\nnivel superior es más fuerte.\\pPero todos los POKéMON son\nvulnerables ante ciertos tipos.\\pEs decir, que no hay POKéMON\ninvulnerables.",
  ["g3:08194234"] = "Esa necesidad de luchar de nuevo\ncon gente a la que ya te has\\lenfrentado...\\p¿Sabes a lo que me refiero?\nSeguro que la has sentido alguna\\lvez.\\pYo quería luchar una y otra vez\ncon mis antiguos rivales.\\pY me dieron esto.\n¡Toma uno para ti!",
  ["g3:0819430f"] = "Usa este dispositivo para ver qué\nENTRENADOR quiere luchar de\\lnuevo contigo.\\pTen en cuenta que debes cargar\nla batería.",
  ["g3:08194381"] = "¿Que cómo se usa el BUSCAPELEA?\nNo tiene mayor misterio.\\pAl usarlo, emitirá un ruidito que\nalertará a los ENTRENADORES\\lque haya por la zona.\\pSi alguno quisiera luchar otra\nvez contigo, te lo hará saber\\lde inmediato.\\pCarga la batería y úsalo cuando\nvayas por ahí.",
  ["g3:0819446f"] = "¿No te gusta la adorable cola\nde mi PIKACHU?",
  ["g3:0819449c"] = "¡Mi PIKACHU es el doble\nde gracioso que ése!",
  ["g3:081944cc"] = "¡Me encanta mi SEEL!\\p¡Chilla cuando lo abrazo!",
  ["g3:08194518"] = "¡Por favor!\\p¡Mi SEEL es mucho más atractivo!\n¡El doble de atractivo!",
  ["g3:0819455a"] = "PIKACHU: ¡Chu! ¡Pika, pika!",
  ["g3:08194571"] = "SEEL: ¡Eeel!",
  ["g3:0819457e"] = "¡Yo presido el Club de Fans de los\nPOKéMON!\\p¡Tengo más de 100 POKéMON!\\p¡Soy muy exigente en todo lo que\nse refiere a los POKéMON!\\pBueno...\\p¿Has venido para saber más cosas\nde mis POKéMON?",
  ["g3:08194628"] = "¡Muy bien!\n¡Pues escucha!\\pMi preferido es RAPIDASH...\\pEs... gracioso... cariñoso... veloz\ne increíble... ¿No crees?...\\lEs sorprendente... simpático...\\l¡Yo lo adoro!\\pSi lo abrazas... cuando duerme...\nes tan cálido... y mimoso... es\\lespectacular... encantador...\\l¡Hala, mira qué hora es!\\l¡Hablo demasiado!\\p¡Gracias por escucharme!\n¡Toma esto!",
  ["g3:0819474e"] = "¡{PLAYER} recibió el BONO BICI\nde manos del PRESIDENTE!",
  ["g3:0819477c"] = "¡Cámbialo por una BICICLETA\nen la TIENDA de BICIS de CIUDAD\\lCELESTE!\\p¡Es gratis!\\p¡No te apures por mí, mi FEAROW\nme lleva VOLANDO a donde sea!\\p¡No necesito BICICLETA!\\p¡Espero que te guste pedalear!",
  ["g3:08194860"] = "¡Oh! ¡Pues vuelve cuando quieras\noír mi historia!",
  ["g3:0819488e"] = "¡Hola, {PLAYER}!\\p¿Has vuelto para saber más cosas\nde mi POKéMON?\\p¿No?\n¡Qué pena!",
  ["g3:081948d2"] = "¡No tienes sitio para esto!",
  ["g3:081948e6"] = "El PRESIDENTE habla mucho\nde los POKéMON.",
  ["g3:08194910"] = "¡Escuchemos con atención a otros\nENTRENADORES!",
  ["g3:0819493d"] = "¡Si presumen, haz tú lo mismo!",
  ["g3:08194960"] = "A nuestro PRESIDENTE le encantan\nsus POKéMON.\\pPero los POKéMON a quien más\nquieren es a DALIA, creo.",
  ["g3:081949cb"] = "¡Hola! ¿Tienes un {STR_VAR_1}?\\p¿Quieres cambiarlo por\nmi {STR_VAR_2}?",
  ["g3:081949fd"] = "¡Qué pena!",
  ["g3:08194a0d"] = "Éste no es un {STR_VAR_1}.\\p¡Si consigues uno, cámbiamelo!",
  ["g3:08194a44"] = "¡Gracias!",
  ["g3:08194a4f"] = "¿Cómo está mi viejo {STR_VAR_2}?\\p¡Mi {STR_VAR_1} está fenomenal!",
  ["g3:08194a77"] = "Hay gente mala que utiliza a los\nPOKéMON para cometer sus actos\\ldelictivos.\\pEl TEAM ROCKET trafica con\nPOKéMON raros.\\pY prescinde de aquellos POKéMON\nque no son muy populares o útiles.",
  ["g3:08194b65"] = "Creo que los POKéMON pueden ser\nbuenos o malos. Todo depende del\\lENTRENADOR.",
  ["g3:08194c8e"] = "¡Te daré un pequeño consejo!\\p¡La electricidad es muy potente!\\p¡Pero no afecta a los POKéMON\ndel tipo TIERRA!",
  ["g3:08194cfa"] = "¡La MEDALLA TRUENO aumenta la\nVELOCIDAD de tus POKéMON!\\p¡Y permite volar a tus POKéMON\ncuando quieran!\\p¡Tú eres muy especial!\n¡Toma esto!",
  ["g3:08194d87"] = "¡{PLAYER} recibió la MT34\nde manos de LT. SURGE!",
  ["g3:08194da8"] = "¡MT34 contiene ONDA VOLTIO!\\p¡Enséñaselo a un POKéMON\neléctrico!",
  ["g3:08194de3"] = "¡Más vale que le hagas sitio!",
  ["g3:08194e03"] = "¡Guau!\\p¡Tú sí que eres fuerte!\\p¡Anda, toma la MEDALLA TRUENO!",
  ["g3:08194e57"] = "¡Cuando estaba en el ejército,\nel LT. SURGE era muy estricto!",
  ["g3:08194ea5"] = "¡Alto!\n¡Eres genial!",
  ["g3:08194ebd"] = "No es fácil abrir esta puerta...\\p¡El LT. SURGE siempre fue muy\ncauteloso en el ejército!",
  ["g3:08194f1f"] = "¡No es que yo sea muy fuerte,\npero soy muy bueno con la\\lelectricidad!",
  ["g3:08194f6f"] = "¡Qué paliza!",
  ["g3:08194f76"] = "¡Vale, hablaré!\\p¡LT. SURGE dijo que ocultaría los\nbotones de la puerta dentro de\\lalgo!",
  ["g3:08194fbd"] = "¡Este lugar no es para niños!\n¡Por muy fuerte que seas!",
  ["g3:08194ff1"] = "¡Uuuaa!\n¡Me dejas a cuadros!",
  ["g3:08195004"] = "LT. SURGE colocó cerraduras\ndobles en el GIMNASIO.\\p¡Las puso por todos sitios!\n¡Te daré una pista!\\p¡Tras abrir la 1.ª cerradura, la\n2.ª está al lado!",
  ["g3:081950b4"] = "¡Hola, aspirante al título!\\pEl LT. SURGE tiene un mote. La\ngente le llama: ¡Rayo americano!\\p¡Es un experto en POKéMON\neléctricos!\\p¡Los POKéMON voladores y los\nacuáticos están en peligro! ¡Ten\\lcuidado con la parálisis!\\p¡El LT. SURGE es muy cuidadoso!\\p¡Descifra un código y llegarás a\nél!",
  ["g3:081951ec"] = "¡Uau!\n¡Vaya pelea tan eléctrica!",
  ["g3:0819520b"] = "LÍDER del GIMNASIO POKéMON\nde CARMÍN: LT. SURGE\\pENTRENADOR GANADOR:\n{RIVAL}",
  ["g3:08195248"] = "LÍDER del GIMNASIO POKéMON\nde CARMÍN: LT. SURGE\\pENTRENADORES GANADORES:\n{RIVAL} y {PLAYER}",
  ["g3:08195289"] = "¡No, aquí sólo hay basura!",
  ["g3:081952a8"] = "¡Oye! ¡Hay un botón debajo de la\nbasura!\\p¡Púlsalo!\nAbierto primer cierre eléctrico.",
  ["g3:08195330"] = "Abierto segundo cierre eléctrico.\\p¡Abierta la puerta mecánica!",
  ["g3:0819536c"] = "¡No! Aquí sólo hay basura.\\p¡Las cerraduras eléctricas fueron\nreajustadas!",
  ["g3:081953af"] = "¡Mi PIDGEY volará al norte,\na CIUDAD AZAFRÁN, para llevar\\luna carta!",
  ["g3:081953ee"] = "PIDGEY: ¡Pid, pid!",
  ["g3:08195400"] = "Querido PIPPI:\nEspero verte pronto.\\pDicen que en CIUDAD AZAFRÁN\ntienen problemas con el TEAM\\lROCKET.\\pLa CIUDAD CARMÍN parece segura.",
  ["g3:08195471"] = "Me gustaría mandarme CARTAS\ncon mucha gente.\\pHe mandado a mi PIDGEY a la\nSALA UNIÓN para que intercambie\\lCARTAS por mí.",
  ["g3:081954dd"] = "¡Hola! Éste es el CENTRO\nCOMERCIAL de AZULONA.\\pEl tablero de la derecha es un\nplano de las tiendas.",
  ["g3:08195537"] = "PB: PUESTO DE INFORMACIÓN\\pP1: TIENDA DE ENTRENADORES\\pP2: VIDEOJUEGOS\\pP3: REGALOS\\pP4: FARMACIA\\pÚLTIMO PISO: DISTRIBUIDORES",
  ["g3:081955b3"] = "PB: PUESTO DE INFORMACIÓN",
  ["g3:0819560f"] = "Para viajes largos deberías\ncomprar REVIVIR.",
  ["g3:08195638"] = "Objetos de máxima calidad para los\nENTRENADORES.\\pP1: TIENDA DE LOS ENTRENADORES",
  ["g3:0819566b"] = "Tenemos un cliente habitual, LANCE,\nque suele comprar capas.\\pLa verdad es que debe de tener\nun montón iguales en su casa...",
  ["g3:081956e9"] = "¡Los POKéMON capturados tienen un\nN.º IDENTIDAD y un EO, el nombre\\pdel ENTRENADOR ORIGINAL\nque lo atrapó!",
  ["g3:08195769"] = "¡Muy bien!\\p¡Mi compañero va a cambiarme su\nKANGASKHAN por mi GRAVELER!",
  ["g3:081957b0"] = "¡Un GRAVELER!\\p¡Me gustan los GRAVELER!\n¡Los colecciono!\\p¿Qué?\\p¡GRAVELER se transformó en otro\nPOKéMON!",
  ["g3:08195823"] = "¡Puedes identificar a los POKéMON\nque hayas cambiado por su N.º ID!",
  ["g3:08195863"] = "¡Es una SUPER NINTENDO!",
  ["g3:08195875"] = "Un juego de rol.\n¡Genial! ¡Pero no tengo tiempo!",
  ["g3:08195897"] = "¡Un juego de deportes!\n¡A mi padre le gustan!",
  ["g3:081958b8"] = "¡Un juego de puzzles!\n¡Parece muy adictivo!",
  ["g3:081958d8"] = "¡Un juego de lucha!\n¡Parece muy difícil!",
  ["g3:081958f6"] = "P2: VIDEOJUEGOS",
  ["g3:08195907"] = "¡Rojo y Verde!\n¡Dos juegos de POKéMON!",
  ["g3:08195928"] = "¡Hola! ¡Ya me he acabado\nPOKéMON!\\p¿Tú no? ¿Quieres que te enseñe\nun movimiento?\\pHe pensado en CONTADOR.\\p¡No te voy a enseñar el que acabo\nde aprender, claro!",
  ["g3:081959cc"] = "¿No te interesa? Bueno, vuelve\nsi cambias de opinión.",
  ["g3:08195a08"] = "¿A qué POKéMON quieres que\nle enseñe CONTADOR?",
  ["g3:08195a31"] = "¿Estás usando el movimiento\nCONTADOR que le enseñé\\la tu POKéMON?",
  ["g3:08195a68"] = "¡Compraré un POKé MUÑECO\npara mi novia!\\pSeguro que es el último grito\nen regalos.",
  ["g3:08195ac9"] = "¡Me han contado una cosa!\\p¡Puedes huir de un POKéMON\nsalvaje si le distraes con un\\lPOKé MUÑECO!",
  ["g3:08195b5b"] = "¡Dilo con un regalo!\\pP3: REGALOS\\p¡Evolución Especial!\n¡Diversas PIEDRAS elementales\\len venta!",
  ["g3:08195bba"] = "¡Los dispositivos de mejora de los\nPOKéMON sólo se venden aquí!\\pMÁS PS aumenta los PS básicos\nde un POKéMON.\\pUsa CALCIO para aumentar las\nhabilidades ESPECIALES.\\pZINC aumenta la DEF. ESP.\nde un POKéMON.\\pUsa CARBURANTE para aumentar\nla VELOCIDAD.",
  ["g3:08195ca0"] = "¡He venido a por dispositivos de\nmejora de los POKéMON!\\pLas PROTEÍNAS aumentan la potencia\ndel ATAQUE.\\pEl HIERRO aumenta la DEFENSA.",
  ["g3:08195d14"] = "P4: FARMACIA",
  ["g3:08195d5f"] = "¿Qué bebida quieres darle?",
  ["g3:08195d75"] = "¡Yay!\\p¡AGUA!\\p¡Gracias!\n¡Tómala, toda tuya!",
  ["g3:08195dad"] = "¡{PLAYER} recibió la {STR_VAR_2}\nde manos de la chica!",
  ["g3:08195dd4"] = "¡MT16 contiene PANTALLA LUZ!\\pReduce la fuerza de los AT. ESP.\ndel rival.",
  ["g3:08195e33"] = "¡Genial!\\p¡Un REFRESCO!\\p¡Gracias!\n¡Tómala, toda tuya!",
  ["g3:08195e68"] = "¡MT20 contiene VELO SAGRADO!\\pEvita los problemas de estado\na tus POKéMON.",
  ["g3:08195ebf"] = "¡Genial!\\p¡LIMONADA!\\p¡Gracias!\n¡Tómala, toda tuya!",
  ["g3:08195ef4"] = "¡La MT33 contiene REFLEJO!\\pReduce la fuerza de los ataques\nfísicos del rival.",
  ["g3:08195f4f"] = "¡No tienes sitio para esto!",
  ["g3:08195f6e"] = "¡No, gracias!\n¡Ya no tengo tanta sed!",
  ["g3:08195f98"] = "Mi hermana es ENTRENADORA,\n¡de verdad!\\p¡Pero es tan infantil que me vuelve\nloco!",
  ["g3:08195fef"] = "¡Tengo sed!\n¡Me gustaría beber algo!",
  ["g3:08196017"] = "ÚLTIMO PISO:\nDISTRIBUIDORES",
  ["g3:08196038"] = "¡Un distribuidor!\n¡A ver el menú!",
  ["g3:0819605e"] = "¡Vaya, no tengo suficiente dinero!",
  ["g3:08196076"] = "¡Una lata de {STR_VAR_1}!",
  ["g3:0819608e"] = "¡No tienes sitio para más cosas!",
  ["g3:081960ae"] = "¡No tengo sed!",
  ["g3:081960bb"] = "MEOWTH: ¡Meow!",
  ["g3:081960c9"] = "No deberías gastarte el dinero\nen latas.\\pToma, prueba esto.",
  ["g3:08196109"] = "No hay nada que calme la sed\nmejor que el TÉ.\\pEs lo mejor que hay.",
  ["g3:08196148"] = "¡Mis queridos POKéMON me\nacompañan!\\p¡Y MEOWTH hasta trae dinero a\ncasa!",
  ["g3:08196188"] = "Hola, encanto.\n¿Te gustó el TÉ?\\pAh, te quería preguntar si eres\nde PUEBLO PALETA.\\pEs que allí hay una chica, DALIA,\nque toma TÉ a diario.\\pSuele comprarlo en el CENTRO\nCOMERCIAL de AZULONA.",
  ["g3:0819625b"] = "CLEFAIRY: ¡Iry! ¡Cleclecle!",
  ["g3:08196272"] = "NIDORAN♀: ¡Nidor! ¡Nidoorr!",
  ["g3:08196287"] = "MANSIÓN AZULONA\nSuite presidencial",
  ["g3:081962a7"] = "Sala de reuniones de GAME FREAK",
  ["g3:081962bf"] = "¿Yo?\n¡Soy el programador!",
  ["g3:081962d7"] = "¡Soy el diseñador gráfico!\n¡Yo te dibujé!",
  ["g3:081962fb"] = "¡Yo escribí la historia!\n¿A que es guapa ERIKA?\\p¡También me gusta mucho MISTY!\n¡Y también me gusta SABRINA!",
  ["g3:08196356"] = "¿Sabes?\\p¡Soy el diseñador del juego!\\p¡Completar tu POKéDEX es difícil,\npero no te rindas!\\p¡Cuando termines ven a decírmelo!",
  ["g3:081963cd"] = "¡Uauu! ¡Genial!\n¡Has completado tu POKéDEX!\\l¡Enhorabuena!",
  ["g3:0819640c"] = "¡Es el programa del juego!\n¡No lo toques, no vaya a ser que\\lse estropee!",
  ["g3:0819644b"] = "¡Alguien está jugando en lugar\nde trabajar!",
  ["g3:08196478"] = "¡Es el guión del juego!\n¡No leas el final!",
  ["g3:081964a8"] = "Sala de desarrollo de GAME FREAK",
  ["g3:081964c4"] = "¡LO SÉ TODO!",
  ["g3:081964d7"] = "Ya lo dice la pizarra, no hay nada\nque no sepa.\\p¡Yo lo sé todo sobre el mundo de\nlos POKéMON de tu GAME BOY\\lADVANCE!\\p¡Reúnete con tus amigos y cambia\nPOKéMON!",
  ["g3:08196591"] = "¡{PLAYER} obtuvo un EEVEE!",
  ["g3:081965c2"] = "Temario POKéMON\\pEl Conector inalámbrico de GBA.",
  ["g3:081965f4"] = "¿Qué capítulo quieres leer?",
  ["g3:08196617"] = "El CLUB INALÁMBRICO POKéMON\nestá en el piso de arriba de los\\lCENTROS POKéMON.\\pVisita uno para conectarte con tus\namigos usando el Conector\\linalámbrico de GBA.",
  ["g3:08196695"] = "Para conectarte sólo con un amigo,\nve a la ZONA DIRECTA.\\pEs el mostrador de la derecha\ndel CLUB INALÁMBRICO POKéMON.\\pEntra con tu amigo en el CENTRO\nde CAMBIO o en el COLISEO.",
  ["g3:0819673c"] = "Para conectarte y comunicarte con\ncualquiera, ve a la SALA UNIÓN.\\pEs el mostrador de la izquierda\ndel CLUB INALÁMBRICO POKéMON.\\pEntra en la SALA UNIÓN y disfruta\ndel encuentro con otros\\lENTRENADORES.",
  ["g3:081967e3"] = "Es un informe sobre las MT.\\p...\\pHay un total de 50 MT.\\pY siete MO, que pueden usarse\nuna y otra vez.\\pSILPH S.A.",
  ["g3:0819685b"] = "¡La POKé FLAUTA despierta a los\nPOKéMON con un sonido que sólo\\lellos pueden oír!",
  ["g3:081968c2"] = "¡He pedaleado cuesta arriba por el\nCAMINO de BICIS desde FUCSIA!\\p¡Qué agotamiento!",
  ["g3:08196913"] = "¡Si tuviera una BICICLETA,\niría por el CAMINO de BICIS!",
  ["g3:08196940"] = "¡Hola!\\pEn la puerta de al lado puedes\ncambiar tus FICHAS por grandes\\lpremios.",
  ["g3:08196984"] = "¡Éste es el CASINO ROCKET!\\p¿Necesitas FICHAS?\n¿Quieres comprar más?",
  ["g3:081969dc"] = "¿No?\n¡Ven a jugar cuando quieras!",
  ["g3:081969fb"] = "¡No tienes MONEDERO!",
  ["g3:08196a26"] = "¡Vaya!\nTu MONEDERO está lleno.",
  ["g3:08196a46"] = "¡No tienes dinero para las FICHAS!",
  ["g3:08196a62"] = "¡Gracias!\n¡Toma las FICHAS!",
  ["g3:08196a82"] = "Escucha y calla.\\pDicen que este lugar lo dirige\nel TEAM ROCKET.",
  ["g3:08196ac7"] = "¡Creo que estas máquinas están\ntrucadas!",
  ["g3:08196af3"] = "¡Oye!\n¿Quieres jugar?",
  ["g3:08196b0d"] = "¡{PLAYER} obtuvo 10 FICHAS\nde manos del hombre!",
  ["g3:08196b30"] = "¡No necesitas mis FICHAS!",
  ["g3:08196b49"] = "La suerte viene y se va.\nHay pocas cosas seguras.",
  ["g3:08196b7b"] = "¡Me lo estoy pasando genial!\nAunque pierda, las tragaperras\\lson estupendas.",
  ["g3:08196bad"] = "¡Oye!\\p¡Aún te queda mucho por hacer,\naspirante al título!\\p¡ERIKA es la LÍDER del GIMNASIO\nde AZULONA!\\p¡Y usa POKéMON del tipo PLANTA!\\pPuede parecer muy dócil, ¡pero ten\nmucho cuidado!\\p¡No te confíes!",
  ["g3:08196ca1"] = "¡Te ofrecen raros POKéMON que\npueden ser cambiados por tus\\lFICHAS!\\p¡Y yo aquí, sin ganar!",
  ["g3:08196cfe"] = "¡Los juegos dan miedo!\n¡Es tan fácil enviciarse!",
  ["g3:08196d2b"] = "¿Qué?\n¿Quieres algunas FICHAS?",
  ["g3:08196d47"] = "¡{PLAYER} obtuvo 20 FICHAS\nde manos del chico encantador!",
  ["g3:08196d6f"] = "¡Tienes muchas FICHAS!",
  ["g3:08196d87"] = "¡Vaya! ¡Necesito más FICHAS\npara los POKéMON que quiero!",
  ["g3:08196db7"] = "¿Qué? ¿Me estás echando?\n¡Aquí tienes algunas FICHAS!",
  ["g3:08196df8"] = "¡{PLAYER} obtuvo 20 FICHAS\nde manos del hombre!",
  ["g3:08196e1b"] = "¡Ya tienes tus propias FICHAS!",
  ["g3:08196e40"] = "¡El truco está en mirar atentamente\nlas pantallas!",
  ["g3:08196e69"] = "¡Yo protejo este cartel!\n¡Lárgate de aquí!",
  ["g3:08196e95"] = "¡Vale, vale!",
  ["g3:08196e9b"] = "¡Nuestra GUARIDA podría ser\ndescubierta!\\p¡Voy a decírselo al JEFE!",
  ["g3:08196edc"] = "¡Oye!\\p¿¡Hay un botón detrás del cartel!?\n¡Vamos a pulsarlo!",
  ["g3:08196f0d"] = "¡Se requiere un MONEDERO!",
  ["g3:08196f26"] = "¡Vaya!\n¡Olvidé el MONEDERO!",
  ["g3:08196f46"] = "¡Una máquina tragaperras!\n¿Quieres jugar?",
  ["g3:08196f64"] = "NO FUNCIONA\nEstá rota.",
  ["g3:08196f81"] = "ESTAMOS COMIENDO\nMáquina reservada.",
  ["g3:08196fa0"] = "¡Unas llaves!\nYa vendrán a por ellas.",
  ["g3:08196fc1"] = "¡Quiero el PORYGON tan mono\nque tienen!\\p¡Pero es difícil ganar a las\ntragaperras!",
  ["g3:08196fff"] = "¡He ganado mucho hoy!\n¡Ojalá fuera todos los días igual!",
  ["g3:0819703e"] = "¡Se requiere un MONEDERO!",
  ["g3:08197057"] = "Canjea tus FICHAS por premios.",
  ["g3:0819707a"] = "¿Qué premio quieres?",
  ["g3:0819709d"] = "Bien, ¿quieres {STR_VAR_1}?",
  ["g3:081970b2"] = "Muy bien, ¿entonces quieres\nuna MT de {STR_VAR_2}?",
  ["g3:081970d5"] = "Perdón, necesitas más FICHAS.",
  ["g3:08197260"] = "¡Reconozco mi derrota!\\pEres muy fuerte.\\pTe voy a dar la MEDALLA ARCOIRIS.",
  ["g3:081972b8"] = "¿Estás estudiando a los POKéMON?\nAdmito que me has impresionado.\\pNo coleccionaría POKéMON si\nfueran feos.",
  ["g3:08197327"] = "La MEDALLA ARCOIRIS hará que los\nPOKéMON de nivel inferior a 50 te\\lobedezcan.\\pY permitirá que los POKéMON usen\nFUERZA siempre que quieras.\\p¡Ah, llévate esto también!",
  ["g3:081973ba"] = "¡{PLAYER} recibió la MT19\nde manos de ERIKA!",
  ["g3:081973d7"] = "La MT19 contiene GIGADRENADO.\\pLa mitad del daño que produce es\nusado para curar a tus POKéMON.\\pNo me digas que no es estupenda.",
  ["g3:0819745d"] = "Deberías hacerle sitio a esto.",
  ["g3:0819747c"] = "¿Sabes una cosa de este GIMNASIO?\\p¡Es sólo para chicas!",
  ["g3:081974c4"] = "¡Eres demasiado fuerte!",
  ["g3:081974d6"] = "¡Eeeh!\n¡Espero que ERIKA acabe contigo!",
  ["g3:081974fa"] = "Ah, hola.\nEstaba empezando a aburrirme.",
  ["g3:0819751c"] = "¡Oh! ¡Mi maquillaje!",
  ["g3:08197527"] = "¡Los POKéMON del tipo PLANTA\nson difíciles para los acuáticos!\\p¡Y tienen ventaja sobre los del\ntipo ROCA y los del tipo TIERRA!",
  ["g3:08197595"] = "Pero ¿tú no has estado ya por\naquí?",
  ["g3:081975bb"] = "¡Estoy impresionada!",
  ["g3:081975d1"] = "Ah, estabas buscando a ERIKA,\nno a mí.",
  ["g3:0819760b"] = "¡Mira mis POKéMON del tipo\nPLANTA!\\p¡Son tan fáciles de entrenar!...",
  ["g3:08197660"] = "¡No!",
  ["g3:08197664"] = "¡En nuestro GIMNASIO sólo luchamos\ncon POKéMON del tipo PLANTA!\\p¡Y también los usamos para hacer\nadornos florales!",
  ["g3:081976c5"] = "¡Aquí no pueden entrar los POKéMON\ndel tipo FUEGO o del tipo BICHO!",
  ["g3:081976ff"] = "¡Oh!\n¡Cómo eres!",
  ["g3:08197708"] = "¡ERIKA, nuestra LÍDER, puede\nparecer muy tranquila, pero es muy\\lhábil!",
  ["g3:08197747"] = "Encantada de conocerte. A mí\nme encanta entrenar POKéMON.",
  ["g3:0819777a"] = "¡Oh!\n¡Espléndido!",
  ["g3:08197788"] = "Voy a tener una cita a ciegas.\n¡Y debo aprender buenos modales!",
  ["g3:081977e5"] = "¡Éste es el GIMNASIO de AZULONA!\\p¡Las encantadoras chicas que hay\naquí son muy fuertes!",
  ["g3:08197832"] = "¡Me has ganado!",
  ["g3:0819783e"] = "¡No he traído a mis mejores\nPOKéMON! ¡Ya verás la próxima\\lvez!",
  ["g3:08197874"] = "LÍDER del GIMNASIO POKéMON\nde AZULONA: ERIKA\\pENTRENADOR GANADOR:\n{RIVAL}",
  ["g3:081978ab"] = "LÍDER del GIMNASIO POKéMON\nde AZULONA: ERIKA\\pENTRENADORES GANADORES:\n{RIVAL} y {PLAYER}",
  ["g3:081978e6"] = "¡Hola!\\pAhora estamos descansando.",
  ["g3:08197915"] = "Suelo visitar la FARMACIA, porque\nmis POKéMON son débiles.",
  ["g3:08197952"] = "¡Psss!\nHay un sótano debajo del CASINO.",
  ["g3:0819798a"] = "Oye...\\pEl hombre de esa mesa lo perdió\ntodo en las tragaperras.",
  ["g3:081979c1"] = "¡Venga! ¡Ríete!\n¡Estoy arruinado!\\p¡No más tragaperras para mí!\n¡Yo me largo!\\p¡Toma esto!\n¡Ya no lo necesito!",
  ["g3:08197a38"] = "¡{PLAYER} recibió un MONEDERO\nde manos del hombre!",
  ["g3:08197a5e"] = "¡No tienes sitio para esto!",
  ["g3:08197a72"] = "Pensaba que iba a recuperarme...",
  ["g3:08197a9f"] = "¡Jejeje!\\p¡He ganado una pasta!\n¡Bravo!",
  ["g3:08197ad3"] = "¡JEFE!\\p¡Acabamos de enviar 2.000\nPOKéMON a modo de premio!",
  ["g3:08197b20"] = "¡No toques el cartel del CASINO!\\p¡No hay ningún botón secreto\ndetrás!",
  ["g3:08197b77"] = "¿POKéMON?\nNo, éste es un hotel para gente.\\p¡Está completo!",
  ["g3:08197bbe"] = "Estoy de vacaciones con mi\nhermano y con mi novio.\\p¡AZULONA es una bonita ciudad!",
  ["g3:08197c0c"] = "¿Por qué trajo a su hermano?",
  ["g3:08197c30"] = "¡Mi hermana me trajo de\nvacaciones!",
  ["g3:08197c6b"] = "¡Ésta es la ZONA del SAFARI!",
  ["g3:08197d50"] = "¡{PLAYER} obtuvo 30 SAFARI BALLS\ndel recepcionista!",
  ["g3:08197d80"] = "¡Te avisaremos cuando se agoten\ntus SAFARI BALLS o tu tiempo!\\p¡Que te vaya muy bien!",
  ["g3:08197de9"] = "¡Bien!\n¡Vuelve cuando quieras!",
  ["g3:08197e02"] = "¡Vaya!\n¡No tienes suficiente dinero!",
  ["g3:08197e1a"] = "¿Ya te vas de la ZONA del\nSAFARI?",
  ["g3:08197e48"] = "Devuelve las SAFARI BALLS\nque te sobren.",
  ["g3:08197e7a"] = "¡Buena suerte!",
  ["g3:08197e85"] = "¿Te ha ido bien?\n¡Vuelve cuando quieras!",
  ["g3:08197eb0"] = "¡Hola!\n¿Es tu primera vez aquí?",
  ["g3:08197ee3"] = "La ZONA del SAFARI tiene 4 ZONAS.\\pCada zona tiene diferentes tipos de\nPOKéMON, y algunos son raros.\\p¡Usa las SAFARI BALLS para\natraparlos!\\p¡También podrás usar CEBO\ny ROCAS para atraerlos!\\p¡Si tiras CEBO, será difícil que\nescapen, pero te costará más\\latraparlos!\\p¡Si tiras ROCAS, será fácil que\nescapen, pero te costará menos\\latraparlos!\\p¡Cuando se te acabe el tiempo\no las SAFARI BALLS, el juego\\lse dará por terminado!",
  ["g3:0819809e"] = "¡Oye, tú vienes mucho por aquí!",
  ["g3:081980bc"] = "¿Tienes alguna bandera de la ZONA\ndel SAFARI?\\p¿Tienes cartas? ¿Y calendarios?",
  ["g3:08198134"] = "¿Has probado VELOCIDAD X?\n¡Da más velocidad a los POKéMON\\len combate!",
  ["g3:0819816b"] = "Al GUARDA le pusimos de mote:\nSLOWPOKE.\\p¡Se parecen un montón; todo\nel día sin hacer nada!",
  ["g3:081981c2"] = "¡SLOWPOKE sabe mucho sobre los\nPOKéMON!\\p¡Tiene hasta varios fósiles de\nPOKéMON raros y extintos!",
  ["g3:0819822a"] = "SLOWPOKE vino, pero no conseguí\nentenderle nada.\\pCreo que no sabe articular bien.",
  ["g3:08198285"] = "SLOWPOKE ha organizado\nun concurso.\\pIntenta llegar al último rincón\nde la ZONA del SAFARI.\\pSi lo consigues, ganarás un premio\nrealmente útil.",
  ["g3:08198444"] = "¡Ejem!\n¡Has demostrado tu valor!\\p¡Aquí tienes la MEDALLA ALMA!",
  ["g3:08198481"] = "¡Si los POKéMON son INTOXICADOS\nsufrirán más y más durante el\\lcombate!\\p¡Y lo seguirán haciendo una vez\nque acabe la lucha!\\p¡El veneno aterroriza a todo\nel mundo!",
  ["g3:0819850e"] = "¡Ahora que tienes la MEDALLA ALMA,\nla DEFENSA de tus POKéMON\\laumentará!\\p¡Y podrás hacer SURF siempre\nque quieras!\\p¡Ah!\n¡Llévate esto también!",
  ["g3:0819858f"] = "¡{PLAYER} obtuvo la MT06\nde manos de KOGA!",
  ["g3:081985ab"] = "¡La MT06 contiene TÓXICO!\\p¡Es una técnica secreta de hace\nmás de 400 años!",
  ["g3:0819860d"] = "¡Hazle sitio a esto!",
  ["g3:08198629"] = "La fuerza no es la clave con los\nPOKéMON, ¿sabes?\\p¡La estrategia es lo importante!\\p¡Te enseñaré cómo la estrategia\npuede vencer a la fuerza!",
  ["g3:081986b4"] = "¡Extraordinario!",
  ["g3:081986c9"] = "¿Mezclarás fuerza e inteligencia?\n¡Buena táctica!\\p¡Es asombroso lo que sabes\ncon lo joven que eres!",
  ["g3:0819871e"] = "¡Quería ser un ninja y por eso\nvine a este GIMNASIO!",
  ["g3:08198779"] = "¡Vaya, he perdido!",
  ["g3:08198787"] = "¡Seguiré entrenándome con KOGA,\nmi maestro ninja!",
  ["g3:081987e8"] = "¡A ver si superas mis técnicas\nespeciales!",
  ["g3:08198812"] = "¡Me has dejado alucinado!",
  ["g3:08198825"] = "¡Me gustan los ataques de sueño\ny veneno porque perduran tras\\lel combate!",
  ["g3:08198866"] = "¡Alto ahí!\\p¿Te han agobiado nuestros muros\ninvisibles?",
  ["g3:081988b6"] = "¡Buaaa!\n¡Qué bien luchas!",
  ["g3:081988cb"] = "¡Impresionante!\\pOye, una cosa: mira bien entre\nlos huecos de los muros invisibles.",
  ["g3:0819891f"] = "¡También estudio técnicas ninja\ncon el maestro KOGA!\\p¡Los ninja llevan mucho tiempo\nusando animales!",
  ["g3:0819897f"] = "¡Auuuu!",
  ["g3:08198985"] = "¡Me queda mucho por aprender!",
  ["g3:081989a1"] = "¡El maestro KOGA desciende\nde una gran familia de ninjas!\\p¿Y tú de qué familia desciendes?",
  ["g3:081989ea"] = "Eres más fuerte de lo que\npensaba...",
  ["g3:08198a10"] = "¡Donde hay luz hay sombras!\\p¡Luz o sombra!\n¿Cuál eliges?",
  ["g3:08198a5e"] = "¡Hola, aspirante al título!\\p¡El GIMNASIO FUCSIA está lleno de\nmuros invisibles!\\p¡Podría parecer que KOGA está\ncerca, pero hay muros invisibles\\lque lo protegen!\\p¡Busca huecos entre los muros\npara llegar hasta él!",
  ["g3:08198b1d"] = "¡Es increíble lo terribles que\npueden ser los ninjas!",
  ["g3:08198b4b"] = "LÍDER del GIMNASIO POKéMON\nde FUCSIA: KOGA\\pENTRENADOR GANADOR:\n{RIVAL}",
  ["g3:08198b81"] = "LÍDER del GIMNASIO POKéMON\nde FUCSIA: KOGA\\pENTRENADORES GANADORES:\n{RIVAL} y {PLAYER}",
  ["g3:08198bbb"] = "¡El GUARDA de la ZONA del SAFARI\nes ya mayor, pero sigue en activo!\\p¡Y lleva dentadura postiza!",
  ["g3:08198c1f"] = "¿Mmm?\n¿Conoces a BILL?\\p¡Es mi nieto!\\p¡Le gustaba coleccionar cosas\ndesde niño!",
  ["g3:08198c7b"] = "¡BILL registra los datos de sus\nPOKéMON en su PC!\\p¿Te los ha enseñado?",
  ["g3:08198cb7"] = "No puedes ganar sólo con\nun POKéMON fuerte.\\pEs difícil, pero conviene\nentrenarlos a todos por igual.",
  ["g3:08198d2e"] = "Hay un estrecho camino al oeste\nde CIUDAD VERDE.\\pLleva al CG de la LIGA POKéMON.\nEl CG gobierna a todos los\\lENTRENADORES.",
  ["g3:08198d9b"] = "Visita la ZONA del SAFARI si estás\nestudiando a los POKéMON.\\p¡Allí encontrarás todo tipo de\nPOKéMON raros!",
  ["g3:08198df9"] = "GUARDA: ¡Fii, fuff, fefifu!\\pA fof, a fif ee afahi fo.\n¡Eeff fi fui!",
  ["g3:08198e3f"] = "¡Ah fafee, oo foo!\n¡Eef ee afafi fo!",
  ["g3:08198e63"] = "¿Ah?\n¡Fai fou fee, fa foo if afee!",
  ["g3:08198e84"] = "¡{PLAYER} le dio los DIENTES\nde ORO al GUARDA!",
  ["g3:08198eaa"] = "¡El GUARDA se puso los dientes!",
  ["g3:08198eca"] = "GUARDA: ¡Gracias, majo!\n¡Menos mal!\\pNo había quien me entendiera,\nvamos, ¡no me entendía ni yo!\\p¡Me daba vergüenza hasta ir\na trabajar!\\p¡Te daré algo por las molestias!",
  ["g3:08198f96"] = "GUARDA: ¡Gracias, maja!\n¡Menos mal!\\pNo había quien me entendiera,\nvamos, ¡no me entendía ni yo!\\p¡Me daba vergüenza hasta ir\na trabajar!\\p¡Te daré algo por las molestias!",
  ["g3:08199068"] = "¡{PLAYER} recibió la MO04\nde manos del GUARDA!",
  ["g3:0819908a"] = "GUARDA: ¡La MO04 enseña FUERZA!\\pTus POKéMON podrán mover rocas\nsiempre que quieras.\\p¿Encontraste la CASA SECRETA\nen la ZONA del SAFARI?",
  ["g3:0819913c"] = "Fotos y fósiles de POKéMON.",
  ["g3:08199167"] = "¡Viejos objetos de los POKéMON!",
  ["g3:0819918e"] = "¡Soy el hermano mayor del GURÚ\nPESCADOR!\\p¡Me encanta pescar!\\p¿Y a ti, te gusta pescar?",
  ["g3:08199207"] = "¡Fenomenal!\n¡Me gusta tu estilo!\\p¡Toma esto y pesca, anda!",
  ["g3:0819925e"] = "¡{PLAYER} recibió una CAÑA BUENA\nde manos del hermano del GURÚ\\lPESCADOR!",
  ["g3:08199296"] = "¡La pesca es una forma de vida!\n¡Es un arte!\\pCon una CAÑA VIEJA de nada, lo\nmáximo que se puede pescar es\\lun MAGIKARP, ¿no?\\pPero con una CAÑA BUENA se pueden\npescar POKéMON mucho mejores.",
  ["g3:08199337"] = "Oh...\nEstoy tan decepcionado...",
  ["g3:08199354"] = "¡Hola, {PLAYER}!\\p¿Cómo va esa pesca?",
  ["g3:0819937e"] = "¡Oh, no!\\p¡Tenía un regalo para ti, pero no\ntienes sitio!",
  ["g3:081993b9"] = "Eh... Ah, hola.\nSoy el QUITA-MOVIMIENTOS.\\pPuedo hacer que los POKéMON\nolviden sus movimientos.\\p¿Quieres que me ocupe de los\ntuyos?",
  ["g3:08199421"] = "¿Qué POKéMON debería olvidar\nalgún movimiento?",
  ["g3:08199445"] = "¿Qué movimiento debería olvidar?",
  ["g3:08199465"] = "Parece que {STR_VAR_1} sólo sabe\nun movimiento...",
  ["g3:08199485"] = "Ajá.\n¿{STR_VAR_2} de {STR_VAR_1}?\\l¿Ése quieres? ¿De verdad?",
  ["g3:081994b1"] = "¡Ha salido de perlas!\\p{STR_VAR_1} ha olvidado\ncompletamente {STR_VAR_2}.",
  ["g3:081994ea"] = "Vuelve por aquí si quieres que tus\nPOKéMON olviden algún movimiento.",
  ["g3:0819951f"] = "¿Cómo? Un HUEVO no puede saber\nningún movimiento.",
  ["g3:081995fa"] = "¡Me has machacado!\n¡He quedado reducido a nada!\\p¡Has ganado la MEDALLA VOLCÁN!",
  ["g3:08199652"] = "¡LLAMARADA es lo máximo en la\ntécnica de las quemaduras!\\p¡No la malgastes con los POKéMON\nacuáticos!",
  ["g3:0819969e"] = "¡Ja!\\p¡La MEDALLA VOLCÁN mejora las\nhabilidades ESPECIALES de tus\\lPOKéMON!\\p¡Mira, también te daré esto!",
  ["g3:081996ff"] = "¡{PLAYER} recibió la MT38\nde manos de BLAINE!",
  ["g3:0819971d"] = "¡La MT38 contiene LLAMARADA!\\p¡Enseña este ataque a los POKéMON\ndel tipo FUEGO!\\p¡CHARMELEON o PONYTA serían\nlas mejores apuestas!",
  ["g3:08199789"] = "¡Hazle sitio a esto!",
  ["g3:081997a5"] = "¿Sabes el calor que puede dar el\naliento de fuego de un POKéMON?",
  ["g3:081997d6"] = "¡Ay!\n¡Quema, quema!",
  ["g3:081997ea"] = "Fuego o, para ser más preciso,\ncombustión...\\p¡Bla, bla, bla, bla!...",
  ["g3:0819983f"] = "Yo era ladrón, pero me hice\nhonrado cuando me convertí\\len ENTRENADOR.",
  ["g3:08199870"] = "¡Me rindo!",
  ["g3:0819987d"] = "¡No puedo evitar robar los POKéMON\nde otras personas!",
  ["g3:081998bd"] = "¡No puedes ganar!\n¡Soy un experto en POKéMON!",
  ["g3:081998ed"] = "¡Au!\n¡Tanta teoría para nada!",
  ["g3:08199911"] = "¡Mis teorías son muy complicadas\npara ti!",
  ["g3:08199948"] = "¡Me encanta usar POKéMON\ndel tipo FUEGO!",
  ["g3:08199973"] = "¡No hay quien pueda contigo!",
  ["g3:08199986"] = "¡Ojalá hubiera un POKéMON ladrón!\n¡Me encantaría utilizarlo!",
  ["g3:081999b7"] = "¡Ya sé por qué BLAINE se hizo\nENTRENADOR!",
  ["g3:081999db"] = "¡Auuuuuuuuuu!",
  ["g3:081999df"] = "BLAINE se perdió en la montaña,\ny se hizo de noche...\\p¡Pero apareció un feroz pájaro\nPOKéMON...!\\p¡E iluminó el camino a BLAINE\npara que pudiera bajar!",
  ["g3:08199a7f"] = "¡He estado en muchos GIMNASIOS,\npero éste es mi preferido!",
  ["g3:08199ab9"] = "¡Vaya!\n¡Eso quema!",
  ["g3:08199ac9"] = "¡A nosotros, los seguidores de los\nPOKéMON de fuego, nos gustan\\lPONYTA y NINETALES!",
  ["g3:08199afc"] = "El fuego es débil contra el H2O.",
  ["g3:08199b16"] = "¡Oh!\n¡Esto se acabó!",
  ["g3:08199b27"] = "¡El agua apaga el fuego!\\p¡Pero el fuego derrite a los\nPOKéMON de hielo!",
  ["g3:08199b81"] = "¡Hola, aspirante al título!\\p¡BLAINE es un profesional\nde los POKéMON de fuego!\\p¡Bájale los humos con agua!\\p¡Más vale que lleves\nANTIQUEMAR!",
  ["g3:08199c0c"] = "¡{PLAYER}, has ganado a esa\nantorcha con patas!",
  ["g3:08199c29"] = "LÍDER del GIMNASIO POKéMON\nde CANELA: BLAINE\\pENTRENADOR GANADOR:\n{RIVAL}",
  ["g3:08199c62"] = "LÍDER del GIMNASIO POKéMON\nde CANELA: BLAINE\\pENTRENADORES GANADORES:\n{RIVAL} y {PLAYER}",
  ["g3:08199c9f"] = "¡POKéACERTIJO!\\p¡Responde bien y abrirás la puerta\na la siguiente habitación!\\p¡Responde mal y lucharás contra\nun ENTRENADOR!\\pSi prefieres reservar tus POKéMON\npara el LÍDER del GIMNASIO...\\p¡Hazlo bien!\n¡Vamos allá!",
  ["g3:08199d5a"] = "¿Evoluciona CATERPIE y\nse transforma en METAPOD?",
  ["g3:08199d79"] = "¿Hay 9 MEDALLAS oficiales\nde la LIGA POKéMON?",
  ["g3:08199da9"] = "¿Evoluciona POLIWAG 3 veces?",
  ["g3:08199dc6"] = "¿Afectan los movimientos del tipo\nELÉCTRICO a los POKéMON\\ldel tipo TIERRA?",
  ["g3:08199e00"] = "¿Son distintos los POKéMON del\nmismo tipo y del mismo nivel?",
  ["g3:08199e36"] = "¿Contiene la MT28 TUMBAPIEDRA?",
  ["g3:08199e4f"] = "¡Respuesta correcta!\\p¡Adelante!",
  ["g3:08199e79"] = "¡Mal!\n¡Lo siento!",
  ["g3:08199e8a"] = "Una foto de BLAINE\ny el SR. FUJI...\\pAparecen juntos con una sonrisa\nde oreja a oreja.",
  ["g3:08199ee5"] = "Aquí estudiamos a los POKéMON.\\pLa gente suele traernos POKéMON\nraros para analizarlos.",
  ["g3:08199f41"] = "¡Una foto del fundador del\nLABORATORIO, el DR. FUJI!",
  ["g3:08199f6a"] = "LABORATORIO POKéMON\nSala de reuniones",
  ["g3:08199f83"] = "LABORATORIO POKéMON\nSala de I + D",
  ["g3:08199f9a"] = "LABORATORIO POKéMON\nSala de pruebas",
  ["g3:08199fb3"] = "¡Encontré este fósil tan raro\nen el MT. MOON!\\p¡Creo que es un POKéMON\nprehistórico y raro!",
  ["g3:0819a015"] = "EEVEE puede evolucionar\ny convertirse en tres tipos\\lde POKéMON.",
  ["g3:0819a04a"] = "¡Hay un correo electrónico!\\p...\\pLos 3 legendarios pájaros POKéMON\nson ARTICUNO, ZAPDOS y MOLTRES.\\pDesconocemos sus guaridas.\\pPensamos explorar la cueva\nque hay cerca de la CELESTE.\\pDe: EQUIPO de INVESTIGACIÓN\nPOKéMON...",
  ["g3:0819a128"] = "¡Un bote de ámbar!",
  ["g3:0819a137"] = "¡Tac-tac-tac! Voy a enseñarte\nun movimiento estupendo.\\pEnséñaselo a un POKéMON,\nverás qué guay es.\\pSe llama METRÓNOMO, no me\ndigas que no suena bien...",
  ["g3:0819a1cb"] = "Te lo digo, es el no va más.",
  ["g3:0819a1ea"] = "¿A qué POKéMON quieres que\nle enseñe METRÓNOMO?",
  ["g3:0819a20e"] = "¡Tac-tac-tac!\n¡Ése es el sonido de un METRÓNOMO!\\p¡Lleva al POKéMON a usar ataques\nque no conoce!",
  ["g3:0819a282"] = "¡Hola!\\p¡Soy un científico muy importante!\nMucho, sí, sí.\\p¡Y me dedico a estudiar fósiles\nde POKéMON raros!\\p¿Tienes algún fósil para mí?",
  ["g3:0819a314"] = "¡No!\n¡Qué pena!",
  ["g3:0819a34f"] = "¿Dónde estabas?\\p¡Tu fósil ha revivido!\n¡Sabía que era un {STR_VAR_1}!",
  ["g3:0819a39e"] = "¡{PLAYER} recibió {STR_VAR_1}\nde manos del científico!",
  ["g3:0819a3d4"] = "¡Oh! ¡Es un {STR_VAR_2}!\\p¡Es un fósil de {STR_VAR_1},\nun POKéMON ya extinto!\\p¡Mi máquina recuperadora\nhará que este POKéMON reviva!",
  ["g3:0819a4ab"] = "¡Tardaré un poco!\\p¡Date un paseo mientras tanto!",
  ["g3:0819a4e1"] = "¡Eh!\n¡Has venido a molestarme!",
  ["g3:0819a4f8"] = "Quería entrar en el GIMNASIO\nde CANELA, pero la puerta\\lestá cerrada a cal y canto.\\pDebe de haber una llave por\nalgún sitio.\\p¿Estará en la mansión quemada\nesa?\\pDicen que está habitada por un\namigo del LÍDER del GIMNASIO.",
  ["g3:0819a5be"] = "¿Tienes muchos amigos?\\pEstá muy bien que te conectes\ncon ellos, por supuesto.\\pPero si visitas la SALA UNIÓN\nde vez en cuando, puede que\\lhagas nuevos amigos.\\pCreo que merecería la pena que\nfueras a la SALA UNIÓN.",
  ["g3:0819a6b1"] = "Los POKéMON pueden seguir\naprendiendo técnicas aunque hayas\\lcancelado su evolución.\\pLa evolución puede esperar hasta\nque hayan aprendido nuevos\\lmovimientos.",
  ["g3:0819a725"] = "BILL: ¡Eh, llevo la tira\nesperando!\\l¿Nos vamos a ISLA PRIMA?",
  ["g3:0819a766"] = "¿Todavía no?",
  ["g3:0819a785"] = "Venga, pues vamos.",
  ["g3:0819a7a0"] = "¿No tienes ATAQUE X?\\p¡Es estupendo para luchar!",
  ["g3:0819a7f1"] = "¡Está bien tener más objetos!",
  ["g3:0819a837"] = "¡Hola, aspirante al título!\\pEn la LIGA POKéMON tendrás que\nluchar contra todos los miembros\\ldel ALTO MANDO, uno tras otro.\\p¡Si pierdes, tendrás que volver\na empezar!\\p¡Eso es todo!\n¡A por ellos!",
  ["g3:0819a8d8"] = "¡Ahora lucharás contra todos los\ndel ALTO MANDO, sin excepción!\\p¡Si ganas, se abrirá una puerta\ny pasarás al siguiente ENTRENADOR!\\l¡Buena suerte!",
  ["g3:0819a943"] = "Lo siento, pero has perdido\nel tiempo viniendo hasta aquí.\\pLORELEI, del ALTO MANDO,\nno está, como puedes comprobar.\\pAsí que la LIGA POKéMON está\ncerrada de momento.",
  ["g3:0819a9e7"] = "Los POKéMON de tipo FANTASMA\nde AGATHA son escalofriantemente\\lfuertes.\\pYo me puse a criar a mis POKéMON\ndel tipo LUCHA con todas las ganas\\ldel mundo...\\pY me planté ante AGATHA convencido\nde que podría ganar... y no quiero\\lni contarte la paliza que me dio.\\pAdemás, ¡no sabes el genio que\ntiene la señora!\\p¡Como empiece a gritar, lo llevas\nclaro!",
  ["g3:0819ab16"] = "Yo creo que lo de ser del ALTO\nMANDO se lleva en la sangre.\\pPor lo que sé, un primo de LANCE\nes también LÍDER de un GIMNASIO\\lde por ahí.",
  ["g3:0819ab9b"] = "¡Mi hija está tan metida en sí\nmisma que tiene muy pocos amigos!",
  ["g3:0819abd7"] = "A mi hija le gusta imitar a la\ngente.\\p¡Y por eso la gente de por aquí\nle llama la COPIONA!",
  ["g3:0819ac4b"] = "CHANSEY: ¡Chaan! ¡Chaan!",
  ["g3:0819ac60"] = "{PLAYER}: ¡Hola!\n¿Te gustan los POKéMON?\\p{PLAYER}: ¿No?\nOye, te he hecho una pregunta.\\p{PLAYER}: ¿Eh?\nEres un poquito raro, ¿no?\\pCOPIONA: ¿Qué? ¿Que deje\nde imitar? ¡Es mi hobby favorito!",
  ["g3:0819acf1"] = "{PLAYER}: ¡Hola!\n¿Te gustan los POKéMON?\\p{PLAYER}: ¿No?\nOye, te he hecho una pregunta.\\p{PLAYER}: ¿Eh?\nEres un poquito rara, ¿no?\\pCOPIONA: ¿Qué? ¿Que deje\nde imitar? ¡Es mi hobby favorito!",
  ["g3:0819ad85"] = "¡Uauuu!\n¡Un POKé MUÑECO!\\p¿Es para mí?\n¡Gracias!\\p¿Sabes una cosa? Podría\nenseñarte el movimiento MIMÉTICO.",
  ["g3:0819add8"] = "¿No tienes interés en MIMÉTICO?",
  ["g3:0819adee"] = "¡Bien, a mí me encanta!\n¿A qué POKéMON quieres que\\lle enseñe MIMÉTICO?",
  ["g3:0819ae1c"] = "{PLAYER}: ¡Hola!\n¡Gracias por lo de antes!\\p{PLAYER}: ¿Sí?\\p{PLAYER}: ¿Te divierte imitar cada\nuno de mis movimientos?\\pCOPIONA: ¿Verdad?\n¡Es muy divertido!",
  ["g3:0819ae90"] = "{PLAYER}: ¡Hola!\n¡Gracias por lo de antes!\\p{PLAYER}: ¿Sí?\\p{PLAYER}: ¿Te divierte imitar cada\nuno de mis movimientos?\\pCOPIONA: ¿Verdad?\n¡Es muy divertido!",
  ["g3:0819b030"] = "DODUO: ¡Dodu!\\p¡ESPEJO, ESPEJITO! ¿QUIÉN ES\nLA MÁS BELLA DE TODAS?",
  ["g3:0819b071"] = "¡Éste es un POKéMON raro!\n¿Eh? ¡Pero si es un muñeco!",
  ["g3:0819b0a0"] = "¡Un juego de MARIO con un cubo\nen la cabeza!",
  ["g3:0819b0d0"] = "...\\p¡Éstos son mis secretos!\\pHabilidad: imitar.\nHobby: coleccionar muñecos.\\lPOKéMON favorito: ¡CLEFAIRY!",
  ["g3:0819b12c"] = "¡Grrrrr!\\p¡Soy el MAESTRO KARATEKA!\n¡Y aquí yo soy el LÍDER!\\p¿Quieres desafiarnos?\n¡No tendremos piedad!\\p¡Fuaaa!",
  ["g3:0819b193"] = "¡Fuaa!\n¡Arg! ¡Nos has vencido!",
  ["g3:0819b1a7"] = "¡Pues sí, he perdido!\\p¡Pero te suplico que no te lleves\nnuestro emblema como trofeo!\\p¡A cambio te daré un valioso y\nfuerte POKéMON!\\p¡Elige el que quieras!",
  ["g3:0819b24c"] = "¡Hola! ¡Quédate y practica karate\ncon nosotros!",
  ["g3:0819b275"] = "¡Iiiiiiiia!\n¡Quítate los zapatos!",
  ["g3:0819b292"] = "¡Me rindo!",
  ["g3:0819b29d"] = "¡Espera a ver a nuestro MAESTRO!\\p¡Yo soy una birria comparado\ncon él!",
  ["g3:0819b2e0"] = "¡Dicen que eres fuerte!\n¡Demuéstramelo!",
  ["g3:0819b2fd"] = "¡Bien hecho!\n¡Un punto!",
  ["g3:0819b30f"] = "¡Nuestro MAESTRO es un karateka\nprofesional!",
  ["g3:0819b341"] = "¡No me asustas nada!\n¡Rompo rocas para entrenarme!",
  ["g3:0819b396"] = "¡Auch!\n¡No he estado nada ágil!",
  ["g3:0819b3ac"] = "¡Sólo nos asustan los poderes\npsíquicos!",
  ["g3:0819b3df"] = "¡Ehhh!\\p¡No puedes entrar en nuestro DOJO-\nKARATE!",
  ["g3:0819b40f"] = "¡Uuuf!\n¡Me rindo!",
  ["g3:0819b41f"] = "Los mejores luchadores se entrenan\naquí.",
  ["g3:0819b44e"] = "¿Quieres la dura patada de\nHITMONLEE?",
  ["g3:0819b473"] = "¡{PLAYER} obtuvo a {STR_VAR_1}\nde manos del MAESTRO de KARATE!",
  ["g3:0819b49e"] = "¿Quieres el superpuñetazo de\nHITMONCHAN?",
  ["g3:0819b4e1"] = "Oye, la avaricia rompe el saco...",
  ["g3:0819b4f8"] = "¡Hay enemigos por todas partes!",
  ["g3:0819b50f"] = "¡Que pase lo que tenga que pasar!",
  ["g3:0819b52e"] = "DOJO-KARATE",
  ["g3:0819b602"] = "¡Estoy impresionada!\nAcepto mi derrota.\\p¡Admito que no he sido lo bastante\nfuerte y por eso he perdido!\\p¡Has ganado la MEDALLA PANTANO!",
  ["g3:0819b685"] = "Todo el mundo tiene poderes\nmentales, pero la gente no lo\\lsabe.\\pLa mente es muy poderosa, pero\nno todo el mundo la aprovecha.",
  ["g3:0819b6fa"] = "¡Con la MEDALLA PANTANO, todo\nPOKéMON con nivel inferior a 70 te\\lobedecerá!\\p¡Los POKéMON más fuertes\nsuelen desobedecer las órdenes\\len combate!\\p¡No entrenes demasiado a tus\nPOKéMON para evitar este\\lproblema!\\p¡Espera, llévate esta MT!",
  ["g3:0819b7d3"] = "¡{PLAYER} obtuvo la MT04\nde manos de SABRINA!",
  ["g3:0819b7f2"] = "¡La MT04 contiene PAZ MENTAL!\\pHace concentrarse a los POKéMON\npara que aumente su AT. ESP. \\ly su DEF. ESP.",
  ["g3:0819b849"] = "¡Tu mochila está llena de otros\nobjetos!",
  ["g3:0819b86a"] = "¡SABRINA es más joven que yo,\npero la respeto!",
  ["g3:0819b8a8"] = "¡No ha sido suficiente!",
  ["g3:0819b8b9"] = "¡En una pelea de iguales, ganará\nquien tenga más voluntad!\\p¡Si quieres ganar a SABRINA,\npiensa sólo en ganar!",
  ["g3:0819b936"] = "¿Te asusta nuestro poder oculto?",
  ["g3:0819b957"] = "¡Jamás lo hubiera pensado!",
  ["g3:0819b96d"] = "¡Los POKéMON psíquicos temen sólo\na los bichos y a los fantasmas!",
  ["g3:0819b998"] = "Los POKéMON acaban pareciéndose\na sus ENTRENADORES.\\p¡Pues tus POKéMON parecen fuertes!",
  ["g3:0819b9ec"] = "¡Lo sabía!",
  ["g3:0819b9f7"] = "¡Debo enseñarles mejores técnicas\na mis POKéMON!\\p¡Sobre todo del tipo PSÍQUICO!",
  ["g3:0819ba45"] = "Sabes que tu fuerza no bastará\npara ganar en el mundo de los\\lPOKéMON, ¿no?",
  ["g3:0819ba9e"] = "¡No me lo puedo creer!",
  ["g3:0819bab4"] = "¡SABRINA ganó al MAESTRO de\nKARATE de la puerta de al lado!",
  ["g3:0819bae8"] = "¡Tú y yo!\nNuestros POKéMON deben luchar.",
  ["g3:0819bb0d"] = "¡He perdido al final!",
  ["g3:0819bb1f"] = "Sabía que esto iba a pasar.",
  ["g3:0819bb49"] = "¡SABRINA es joven, pero es nuestra\nLÍDER!\\p¡No llegarás a ella fácilmente!",
  ["g3:0819bba1"] = "¡No he podido concentrarme!",
  ["g3:0819bbb3"] = "En AZAFRÁN había dos\nGIMNASIOS POKéMON.\\p¡El DOJO-KARATE de aquí al lado\nperdió su condición de GIMNASIO\\lcuando los machacamos!",
  ["g3:0819bc57"] = "¡El GIMNASIO POKéMON de AZAFRÁN\nes famoso por sus médiums!\\p¡Quieres ver a SABRINA!\n¡Lo sé!",
  ["g3:0819bcbc"] = "¡Arrrgg!",
  ["g3:0819bcc4"] = "¡Tienes razón! ¡Usé la telepatía\npara leer tu mente!",
  ["g3:0819bcf6"] = "¡Hola, aspirante al título!\\p¡Los POKéMON de SABRINA usan el\npoder de la mente, no la fuerza!\\p¡Los POKéMON del tipo LUCHA\nson débiles contra los de tipo\\lPSÍQUICO!\\p¡Se debilitan casi antes de poder\nprepararse!",
  ["g3:0819bdbb"] = "¿Poder mental?\\p¡Si yo lo tuviera me haría rico en\nlas tragaperras!",
  ["g3:0819bdfe"] = "LÍDER del GIMNASIO POKéMON\nde AZAFRÁN: SABRINA\\pENTRENADOR GANADOR:\n{RIVAL}",
  ["g3:0819be37"] = "LÍDER del GIMNASIO POKéMON\nde AZAFRÁN: SABRINA\\pENTRENADORES GANADORES:\n{RIVAL} y {PLAYER}",
  ["g3:0819be74"] = "Gracias por escribir.\n¡Espero verte pronto!\\p¡Oye!\n¡No mires mi carta!",
  ["g3:0819bec3"] = "PIDGEY: ¡Pid, pid!",
  ["g3:0819bed5"] = "¡La COPIONA es muy mona!\n¡Voy a darle un POKé MUÑECO!",
  ["g3:0819bf07"] = "Recibí MÁS PP como regalo.\\p¡Sirve para aumentar los PP de\nun movimiento de un POKéMON!\\pCreo que voy a usarlo con un\nmovimiento potente, que tenga\\lpocos PP.",
  ["g3:0819bf8f"] = "¡MÁX. REPEL dura más que el\nSUPERREPEL; mantiene alejados\\lmás tiempo a los POKéMON débiles!",
  ["g3:0819bff1"] = "¡REVIVIR es caro, pero hace\nrevivir a los POKéMON debilitados!",
  ["g3:0819c023"] = "La velocidad de crecimiento de los\nPOKéMON varía de una especie a\\lotra.",
  ["g3:0819c058"] = "SILPH S.A. es muy famosa.\\p¡Por eso el TEAM ROCKET tiene\ntanto interés en ella!",
  ["g3:0819c0b4"] = "¡Sería estupendo que el ALTO\nMANDO viniera y machacara al TEAM\\lROCKET!",
  ["g3:0819c102"] = "¡El TEAM ROCKET se ha ido!\n¡Ahora podemos salir sin peligro!\\l¡Bien!",
  ["g3:0819c142"] = "¡Eh, espera! ¡No digas nada!\\p¿Tú no querías esto?",
  ["g3:0819c16c"] = "¡{PLAYER} recibió la MT29\nde manos del SR. PSÍQUICO!",
  ["g3:0819c18f"] = "MT29 contiene PSÍQUICO.\\p¡Puede reducir las habilidades\nespeciales del objetivo!",
  ["g3:0819c1fc"] = "¿Dónde piensas poner esto?\n¡No te queda sitio!",
  ["g3:0819c22b"] = "¿Mm?\nTú...",
  ["g3:0819c235"] = "¿Tú no eras...?\\p¡Sí!\n¡Tú eres {PLAYER}!\\p¡Estábamos hablando de ti\nahora mismo!\\p¡Estábamos diciendo que había\nalguien que se salía ENTRENANDO\\lPOKéMON!\\p¡Y ese alguien eres tú!\n¡Eres guay!\\p¡Nos ha entrado tanta emoción\nque hemos decidido crear tu CLUB\\lde FANS!\\p¡Esperamos que sigas luchando\ny enseñándonos lo guay que eres!\\p¡Así seguro que te salen muchos\nmás fans como yo!",
  ["g3:0819c390"] = "¡Pienso animarte siempre!\\p¡A la bim, a la bam, a la bim,\nbom, bam! ¡{PLAYER}, {PLAYER}, y\\lnadie más! ¡A la bim, bom, bam!",
  ["g3:0819c3bd"] = "¡Pienso apoyarte siempre, {PLAYER}!\\p¡Enséñale al mundo de lo que\neres capaz cuando te lo propones!",
  ["g3:0819c420"] = "Lo siento.\nYo era tu fan...\\pPero has perdido mucho tirón...\\pÚltimamente, quien parte la pana\nes {STR_VAR_1}, la verdad...",
  ["g3:0819c4a5"] = "¡Hola, {PLAYER}!\\p¡Últimamente todo el mundo está\nrevolucionado contigo!\\pY lo entiendo, eres muy fuerte...\\pPero ¿sabes qué pasa?\\pQue me hice fan de {STR_VAR_1}\ny no es plan de echarme atrás\\lahora, ¿no?",
  ["g3:0819c55c"] = "A mí me parece que no hay nada\nmás guay que ver luchar a los\\lENTRENADORES.\\p¿No te parece?",
  ["g3:0819c5a9"] = "¡Madre mía, pero si es {PLAYER}!\n¡Guau, qué pasada!\\p¡Qué guay, qué guay!\n¡Qué emoción!\\p¿Me firmas un autógrafo?\n¡Fírmame en los pantalones,\\lno pasa nada!",
  ["g3:0819c600"] = "¡Yo siempre llevo pantalones\ncortos, como tú!\\p¡Ya llueva, nieve, o ventee!\\p¡Yo iré con pantalón corto,\ncomo tú!\\p¡Venga, debes ir a por todas!\\p¡Yo confío en ti y no me pienso\nquitar los pantalones cortos!\\l¡Pantalones cortos al poder!",
  ["g3:0819c6ba"] = "¡BROCK es mi héroe!\nNo hay otro como él.\\p¡Lo admiro tanto que le he\npedido a mi madre que me borde\\lsu nombre en los pantalones, je!",
  ["g3:0819c73a"] = "Eh... Yo soy fan de BROCK.\\pY aunque fuera su único seguidor,\nno lo abandonaría nunca.\\p¡Pongo a mis pantalones cortos\ncomo testigo!",
  ["g3:0819c7c8"] = "BROCK es la caña, punto.\\p¡Ya me gustaría a mí ser como él!",
  ["g3:0819c81e"] = "{PLAYER}, he tenido el placer\nde verte luchar.\\pY me he visto de joven. Ah, qué\ndulces y lejanos recuerdos...\\pSigue por el camino que llevas.\nPienso seguirte siempre.",
  ["g3:0819c8c1"] = "He viajado por mil sitios y puedo\ndecir que ningún ENTRENADOR\\lte llega a la suela del zapato.\\p¡Confía en tus posibilidades\ny sigue luchando!\\p¡Di que vas a seguir luchando!\n¡Muy bien, joven!",
  ["g3:0819c986"] = "¿Mm?\n¿Y tú quién eres?\\p¿Vienes a apuntarte al CLUB?",
  ["g3:0819c9d5"] = "Anda, así que eres {PLAYER}...\nTodo el mundo habla de ti\\lúltimamente.\\pLa verdad es que tienes pinta\nde ser fuerte, sí, sí.\\pPero para mí..., no sé,\nte veo un poco verde todavía.",
  ["g3:0819ca7c"] = "Todos los que estamos aquí somos\nfans de ENTRENADORES POKéMON.\\pLa imagen que dan cuando luchan...\n¡Son supercarismáticos!\\pNo sé, si ganas más combates,\n¡igual acabamos hablando todos\\lde ti!",
  ["g3:0819cb32"] = "¡Eh, que es {PLAYER}!\n¡Es {PLAYER}!\\p¡Yo quiero llegar a ser como\n{PLAYER}!",
  ["g3:0819cb62"] = "Todo el mundo ha dejado de ser\nfan de {PLAYER}...\\p¡Me da igual, así me tiene sólo\na mí!\\p¡{PLAYER}, {PLAYER}, {PLAYER}!",
  ["g3:0819cbd3"] = "¿Sabes qué?\n¡Me encantaría ser como SABRINA!\\p¡Y dominar los poderes psíquicos,\ncomo ella!",
  ["g3:0819cc2b"] = "No pienso dejar nunca a SABRINA.\n¡Aunque sea su única fan!.\\pMi sueño es llegar a ser como\nella; dulce, pero guay a la vez.\\p¡Y dominar los poderes psíquicos,\ncomo ella!",
  ["g3:0819ccc2"] = "¿Llegaré a ser buena ENTRENADORA\nalgún día?",
  ["g3:0819ccf3"] = "¡Qué pasada, qué pasada!\n¡Qué guay, qué guay!\\p¿Mm?...\nNo, no lo digo por ti.\\pLo digo por tu forma de luchar.\nEs guay.",
  ["g3:0819cd4e"] = "¡Eh, {PLAYER}!\\pCreo que soy el único fan que\ntienes.\\pPero oye, tiene su lado positivo,\nte evitas mucho estrés.\\p¡Sigue como hasta ahora!",
  ["g3:0819cdda"] = "Qué guay es {STR_VAR_1}, ¿verdad?\nMe gusta hasta su forma de hablar.\\p¡Me encantaría que viniera alguna\nvez por aquí!",
  ["g3:0819ce3a"] = "¿Será posible?\n¡Todo el mundo es fan tuyo!\\pO sea, ¿que soy el único fan\nde {STR_VAR_1}?\\pBueno, en realidad, ¿qué más\nme da?",
  ["g3:0819cedf"] = "¡No me lo puedo creer!\n¿Eres {PLAYER}, en serio?\\pTengo que decirte que me encanta\nla forma de luchar que tienes.\\pEspero que no cambies nunca.\n¡Soy tu fan más fan!",
  ["g3:0819cf6d"] = "¡No me lo puedo creer!\n¡Pero si es {PLAYER}!\\pQuería decirte que estoy un poco\nchafada, porque soy tu única fan.\\pPero bueno, pienso animarte\nde todas formas.\\p¡Viva {PLAYER}!",
  ["g3:0819d01f"] = "Quien ha estado en boca de todos\núltimamente es {STR_VAR_1}.\\pLucha de una manera...\nComo a mí me gusta, vaya.",
  ["g3:0819d075"] = "¡Anda, pero si es {PLAYER}!\\pSe ve que está de moda hablar\nde ti.\\p¡Yo me he quedado más sola\nque la una animando a {STR_VAR_1}!",
  ["g3:0819d0e3"] = "¡Guay, guay y guay!\n¡{PLAYER}, eres realmente guay!\\p¡De tanto verte, he decidido\nconvertirme en ENTRENADORA!",
  ["g3:0819d148"] = "Soy tu única fan...\nY... me encuentro tan sola...\\p¿Por qué no te esfuerzas un poco\npara que se fijen en ti?",
  ["g3:0819d1ae"] = "La verdad es que {STR_VAR_1}\nimpone... A mí me encanta.\\p¿Soy yo la única que percibe el\naura de solemnidad que le rodea?",
  ["g3:0819d211"] = "Yo confío profundamente\nen {STR_VAR_1}.\\pMe da igual ser la única.\\pMientras tenga a mi ídolo\n{STR_VAR_1}, no me sentiré sola.",
  ["g3:0819d2b4"] = "¡Guau!\\p¡Tu forma de luchar es ejemplar!\\p¡Espero que nunca dejes de tener\néxito! ¡Ánimo!",
  ["g3:0819d31f"] = "¡No te entretengas mirando cómo\nlucha el resto! ¡Lucha tú!\\pMi MAESTRO me echó del DOJO\ncomo el que no quiere la cosa...\\pPero, me da igual, yo voy a seguir\nsiendo tu fan.\\p¡No pienso dejar de serlo!",
  ["g3:0819d3d2"] = "¡Hiyah! Sólo tengo respeto por\nun ENTRENADOR.\\pPor mi MAESTRO. No hay nadie\ncomo él sobre el DOJO.\\pDeberías hacerte su fan, como yo.\n¡Hiyah!",
  ["g3:0819d477"] = "¡Hiyah! Tengo un respeto enorme\npor mi MAESTRO.\\lEs el mejor sobre el DOJO.\\pNo pienso ser fan de nadie más.\\pVoy a ir diciendo por ahí lo bueno\nque es.\\p¡Hiyah!",
  ["g3:0819d52c"] = "¿Piensas ir al BOSQUE VERDE?\n¡Ten cuidado!\\l¡Es un auténtico laberinto!",
  ["g3:0819d58b"] = "¡Puede que RATTATA sea pequeño,\npero su mordisco es muy potente!\\p¿Tienes alguno?",
  ["g3:0819d5e7"] = "Un POKéMON debilitado no puede\nluchar.\\p¡Pero puede usar movimientos\ncomo el de CORTAR!",
  ["g3:0819d64f"] = "¡Hola! ¿Te acuerdas de mí?\n¡Soy AYUDANTE del PROF. OAK!\\p¡Si ya tienes 10 tipos de POKéMON,\nse supone que debería darte MO05!\\pDime, {PLAYER}. ¿Tienes ya al menos\n10 tipos de POKéMON?",
  ["g3:0819d74e"] = "¡Bien! ¡Has logrado {STR_VAR_3} tipos\nde POKéMON!\\p¡Enhorabuena!\n¡Aquí tienes!",
  ["g3:0819d7a1"] = "¡{PLAYER} obtuvo la MO05\nde manos del AYUDANTE!",
  ["g3:0819d7c1"] = "El DESTELLO de la MO ilumina hasta\nlas más oscuras mazmorras.",
  ["g3:0819d81e"] = "Si un POKéMON aprende DESTELLO,\npodrás cruzar el TÚNEL ROCA.",
  ["g3:0819d85c"] = "Muchos POKéMON sólo viven\nen bosques y cuevas.\\p¡Tienes que mirar por todas partes\npara conseguirlos todos!",
  ["g3:0819d8d0"] = "¿Has visto los arbustos que hay\njunto al camino?\\pPuedes cortarlos con un movimiento\nespecial de los POKéMON.",
  ["g3:0819d93b"] = "¿Sabes que se puede cancelar\nla evolución de un POKéMON?\\pCuando un POKéMON esté\nevolucionando puedes pararlo\\ly dejarlo como está.",
  ["g3:0819d9d4"] = "Tengo 6 POKé BALLS en mi cinturón.\\pPuedes llevar 6 POKéMON como\nmucho.",
  ["g3:0819da3a"] = "El TEAM ROCKET ataca a los\nciudadanos de CELESTE...\\p¡El TEAM ROCKET siempre sale\nen las noticias!",
  ["g3:0819dc07"] = "¿No? ¡Pues lo hacía como favor!",
  ["g3:0819dc3e"] = "Mmmm... Tienes demasiados POKéMON.\nNo queda sitio para éste...",
  ["g3:0819dc78"] = "¡No tienes suficiente dinero!",
  ["g3:0819dc9a"] = "HOMBRE: ¡Que sepas que no acepto\ndevoluciones!",
  ["g3:0819dcdb"] = "¡Si tienes demasiados POKéMON,\nguárdalos en el PC!",
  ["g3:0819dd54"] = "Un periódico...",
  ["g3:0819dd66"] = "Esta GUARDERÍA es mía.\\p¿Quieres que cuide de alguno\nde tus POKéMON?",
  ["g3:0819ddb2"] = "Vuelve en otro momento.",
  ["g3:0819ddbe"] = "¿Qué POKéMON quieres que cuide?",
  ["g3:0819dddc"] = "Vale...\nVuelve cuando quieras.",
  ["g3:0819ddf9"] = "Muy bien, cuidaré de {STR_VAR_1}\nun rato.",
  ["g3:0819de24"] = "Vuelve dentro de un rato.",
  ["g3:0819de3c"] = "¿Ya de vuelta?\\pTu {STR_VAR_1} aún necesita de mis\ncuidados.",
  ["g3:0819deaf"] = "¡Gracias!\n¡Aquí está tu POKéMON!",
  ["g3:0819decf"] = "¡{PLAYER} recuperó a {STR_VAR_1}!",
  ["g3:0819def5"] = "Sólo tienes un POKéMON contigo.",
  ["g3:0819df1d"] = "Si me dejas ese POKéMON, no\npodrás entablar combates.",
  ["g3:0819df56"] = "¡Tu {STR_VAR_1} ha crecido mucho!\\p¡Su nivel ha subido {STR_VAR_2}!\\p¿No soy genial?",
  ["g3:0819dfc2"] = "¡No tienes sitio para este POKéMON!",
  ["g3:0819e001"] = "No tienes suficiente dinero.",
  ["g3:0819e04b"] = "Estoy de guardia. ¡Uauu!\n¡Qué sed tengo!\\pEspera. La ruta está cerrada.",
  ["g3:0819e09b"] = "Mmm, ese TÉ que llevas ahí...\nTiene una pinta buenísima...",
  ["g3:0819e0c1"] = "¿Cómo? ¿Que me lo puedo tomar?\n¡Vaya, gracias!\\l... ...\\lGlug, glug...\\l... ...\\lGulp...\\lSi quieres ir a CIUDAD AZAFRÁN...\\lPor mí puedes pasar.\\pLe daré un poco de TÉ a mis\ncompañeros.",
  ["g3:0819e16d"] = "¡Oye! ¡Gracias por las bebidas!",
  ["g3:0819e181"] = "Estoy de guardia. ¡Uauu!\n¡Qué sed tengo!\\pEspera. La ruta está cerrada.",
  ["g3:0819e1d1"] = "Mmm, ese TÉ que llevas ahí...\nTiene una pinta buenísima...",
  ["g3:0819e1f7"] = "¿Cómo? ¿Que me lo puedo tomar?\n¡Vaya, gracias!\\l... ...\\lGlug, glug...\\l... ...\\lGulp...\\lSi quieres ir a CIUDAD AZAFRÁN...\\lPor mí puedes pasar.\\pLe daré un poco de TÉ a mis\ncompañeros.",
  ["g3:0819e2a3"] = "¡Oye! ¡Gracias por las bebidas!",
  ["g3:0819e2b7"] = "Estoy de guardia. ¡Uauu!\n¡Qué sed tengo!\\pEspera. La ruta está cerrada.",
  ["g3:0819e307"] = "Mmm, ese TÉ que llevas ahí...\nTiene una pinta buenísima...",
  ["g3:0819e32d"] = "¿Cómo? ¿Que me lo puedo tomar?\n¡Vaya, gracias!\\l... ...\\lGlug, glug...\\l... ...\\lGulp...\\lSi quieres ir a CIUDAD AZAFRÁN...\\lPor mí puedes pasar.\\pLe daré un poco de TÉ a mis\ncompañeros.",
  ["g3:0819e3d9"] = "¡Oye! ¡Gracias por las bebidas!",
  ["g3:0819e3ed"] = "Estoy de guardia. ¡Uauu!\n¡Qué sed tengo!\\pEspera. La ruta está cerrada.",
  ["g3:0819e43d"] = "Mmm, ese TÉ que llevas ahí...\nTiene una pinta buenísima...",
  ["g3:0819e463"] = "¿Cómo? ¿Que me lo puedo tomar?\n¡Vaya, gracias!\\l... ...\\lGlug, glug...\\l... ...\\lGulp...\\lSi quieres ir a CIUDAD AZAFRÁN...\\lPor mí puedes pasar.\\pLe daré un poco de TÉ a mis\ncompañeros.",
  ["g3:0819e50f"] = "¡Oye! ¡Gracias por las bebidas!",
  ["g3:0819e523"] = "¡Los POKéMON de ciertos elementos\nson más o menos fuertes que otros!",
  ["g3:0819e5d2"] = "¡Dicen que hay fantasmas en\nPUEBLO LAVANDA!",
  ["g3:0819e5fb"] = "¡Hola! ¿Te acuerdas de mí?\n¡Soy AYUDANTE del PROF. OAK!\\p¡Si ya tienes 20 tipos de POKéMON,\nse supone que debería darte\\lPIEDRAETERNA!\\pDime, {PLAYER}. ¿Tienes ya al menos\n20 tipos de POKéMON?",
  ["g3:0819e733"] = "¡Bien! ¡Has logrado {STR_VAR_3} tipos\nde POKéMON!\\p¡Enhorabuena!\n¡Aquí tienes!",
  ["g3:0819e786"] = "¡{PLAYER} obtuvo la\nPIEDRAETERNA de manos\\ldel AYUDANTE!",
  ["g3:0819e7af"] = "Si dejas evolucionar a los\nPOKéMON, tu POKéDEX\\lse verá beneficiada.\\pAunque habrá algún caso en el\nque no quieras que evolucionen.\\pPara evitarlo, dale al POKéMON\nque quieras una PIEDRAETERNA.\\pSegún dice el PROFESOR,\nel POKéMON que la lleve,\\lno evolucionará.",
  ["g3:0819e8a6"] = "Cuando atrapas a muchos POKéMON,\n¿A que es difícil darles motes?\\pEn PUEBLO LAVANDA hay un hombre\nque evalúa los motes de los\\lPOKéMON.\\p¡Y te ayudará a renombrarlos!",
  ["g3:0819e97b"] = "Si quieres ir a PUEBLO LAVANDA,\nve por el TÚNEL ROCA.\\pPodrás tomar el TÚNEL ROCA desde\nCIUDAD CELESTE.",
  ["g3:0819e9e5"] = "¡Hola! ¿Te acuerdas de mí?\n¡Soy AYUDANTE del PROF. OAK!\\p¡Si ya tienes {STR_VAR_1} tipos de POKéMON,\nse supone que debería darte\\l{STR_VAR_2}!\\pDime, {PLAYER}. ¿Tienes ya al menos\n{STR_VAR_1} tipos de POKéMON?",
  ["g3:0819eae4"] = "¡Bien! ¡Has logrado {STR_VAR_3} tipos\nde POKéMON!\\p¡Enhorabuena!\n¡Aquí tienes!",
  ["g3:0819eb37"] = "¡{PLAYER} obtuvo {STR_VAR_2}\nde manos del AYUDANTE!",
  ["g3:0819eb59"] = "En el suelo hay objetos que no se\npueden ver.\\pEl BUSCAOBJETOS detectará\nlos objetos que tengas cerca.\\p¡Pero no puede señalar dónde están\nexactamente!\\p¡Tú tendrás que encontrarlos!",
  ["g3:0819ec8a"] = "Has usado los prismáticos...\\p¡Un gran POKéMON está durmiendo\nen el camino!",
  ["g3:0819ecd9"] = "Has usado los prismáticos...\\p¡Qué vista tan bonita!",
  ["g3:0819ed1f"] = "Has usado los prismáticos...\\p¡Puedes ir de CIUDAD CELESTE\na PUEBLO LAVANDA por el TÚNEL\\lROCA!",
  ["g3:0819eda7"] = "Desde arriba se ve una vista\npreciosa.",
  ["g3:0819ede1"] = "Las cenizas de mis POKéMON están\nguardadas en la TORRE POKéMON.\\pPuedes quedarte con mi MT. Ya no\nla necesito...",
  ["g3:0819ee40"] = "Las cenizas de mis POKéMON están\nguardadas en la TORRE POKéMON.\\pPuedes quedarte con mi MT. Ya no\nla necesito...",
  ["g3:0819ee9f"] = "¡{PLAYER} obtuvo la MT27\nde manos de la chica!",
  ["g3:0819eec6"] = "¡La MT27 es un ataque que se\nllama RETROCESO!\\pSi tratas bien a tus POKéMON,\naumentará sus efectos en\\lcombate.",
  ["g3:0819ef3f"] = "¡No tienes sitio para esto!",
  ["g3:0819ef5d"] = "Has usado los prismáticos...\\p¡Un hombre está pescando!",
  ["g3:0819efa0"] = "Has usado los prismáticos...\\p¡Es la TORRE POKéMON!",
  ["g3:0819efe0"] = "¡Soy hermano del GURÚ PESCADOR!\\p¡Simplemente me encanta pescar!\\p¿Te gusta pescar?",
  ["g3:0819f05b"] = "¡Fenomenal!\n¡Me gusta tu estilo!\\p¡Toma esto y pesca, anda!",
  ["g3:0819f0b2"] = "¡{PLAYER} obtuvo una SUPERCAÑA\ndel hermano del GURÚ PESCADOR!",
  ["g3:0819f0eb"] = "¡La pesca es una forma de vida!\n¡Es un arte!\\p¡En el mar, en los ríos, da igual,\nhay que pescar el más grande!\\pA ver, tengo que pedirte algo.\\pSi consigues un MAGIKARP con\nesa CAÑA, me gustaría que me\\llo enseñaras.\\pPescar me gusta tanto como ver\nMAGIKARP enormes.",
  ["g3:0819f1fa"] = "Oh...\nEstoy tan decepcionado...",
  ["g3:0819f217"] = "¡Hola, {PLAYER}!\\p¡Utiliza la SUPERCAÑA en todo tipo\nde aguas! Puedes pescar diferentes\\ltipos de POKéMON.\\p¡Pesca siempre que puedas!\\p¡Y no te olvides de traerme\nun MAGIKARP gigante!",
  ["g3:0819f2db"] = "¡Hola, {PLAYER}!\n¡Anda, un MAGIKARP!\\p¡Deja, deja que lo vea!",
  ["g3:0819f31b"] = "¡Guaaaau, {STR_VAR_2} cm!\\p¡Tienes una forma muy peculiar\nde entender el arte de la pesca!\\pToma esto, por favor.",
  ["g3:0819f395"] = "Espero que me traigas piezas aún\nmejores.",
  ["g3:0819f3cb"] = "¿Mmm?\n¿{STR_VAR_2} cm?\\p¡Pero si tiene el mismo tamaño\nque el anterior!",
  ["g3:0819f40a"] = "Mmm...\nEste mide {STR_VAR_2} cm de largo...\\p¡Pero si el de antes medía {STR_VAR_3} cm!",
  ["g3:0819f468"] = "Eh... me parece a mí que eso\nno es un MAGIKARP.",
  ["g3:0819f494"] = "¡Oh, no!\\p¡Tenía un regalo para ti, pero no\ntienes sitio!",
  ["g3:0819f4cf"] = "¡Madre mía, es el MAGIKARP más\ngrande que he visto en mi vida!\\p¡{STR_VAR_3} cm!",
  ["g3:0819f50c"] = "Es una especie de cuadro y\nestá en blanco.\\pTiene casillas para anotar cosas.",
  ["g3:0819f560"] = "¿Estás trabajando en la POKéDEX?\\pUn AYUDANTE del PROF. OAK\nse ha pasado por aquí.",
  ["g3:0819f5ab"] = "¡Hola! ¿Te acuerdas de mí?\n¡Soy AYUDANTE del PROF. OAK!\\p¡Si ya tienes {STR_VAR_1} tipos de POKéMON,\nse supone que debería darte\\l{STR_VAR_2}!\\pDime, {PLAYER}. ¿Tienes ya al menos\n{STR_VAR_1} tipos de POKéMON?",
  ["g3:0819f6aa"] = "¡Bien! ¡Has logrado {STR_VAR_3} tipos\nde POKéMON!\\p¡Enhorabuena!\n¡Aquí tienes!",
  ["g3:0819f6fd"] = "¡{PLAYER} obtuvo {STR_VAR_2}\nde manos del AYUDANTE!",
  ["g3:0819f71f"] = "REPARTIR EXP. es un objeto\nque puede llevar un POKéMON.\\pDará puntos de EXPERIENCIA\nal POKéMON que lo lleve, aunque\\lno luche.",
  ["g3:0819f79c"] = "Has usado los prismáticos...\\pUn pájaro grande y brillante vuela\nhacia el mar.",
  ["g3:0819f7f8"] = "Has usado los prismáticos...\\p¡Parece que hay una pequeña isla!",
  ["g3:0819f851"] = "¡Oh!\n¡Has encontrado mi escondite!\\pPor favor, no le digas a nadie que\nestoy aquí, ¡te ayudaré!",
  ["g3:0819f8c0"] = "¡{PLAYER} obtuvo la MO02\nde manos de la chica!",
  ["g3:0819f8e0"] = "MO02 es VOLAR. Ésta te llevará\nde vuelta a cualquier ciudad.\\p¡Úsala bien!",
  ["g3:0819f92d"] = "No tienes sitio para esto.",
  ["g3:0819f94f"] = "FEAROW: ¡Fea, row, row!",
  ["g3:0819f95f"] = "¡Los peatones no pueden andar\npor el CAMINO de BICIS!",
  ["g3:0819f98b"] = "El CAMINO de BICIS va cuesta\nabajo junto al mar. ¡Es estupendo!",
  ["g3:0819f9cc"] = "¡Perdona!\n¡Espera!",
  ["g3:0819f9e8"] = "¿Cómo has llegado hasta aquí?\n¡Bien hecho!",
  ["g3:0819fa07"] = "¡Voy a darme una vuelta con mi\nnovia!",
  ["g3:0819fa41"] = "¡Vamos a pedalear juntos!",
  ["g3:0819fa6f"] = "Has usado los prismáticos...\\p¡Es el CENTRO COMERCIAL\nde CIUDAD AZULONA!",
  ["g3:0819fab9"] = "Has usado los prismáticos...\\p¡Hay un largo camino sobre\nel agua!",
  ["g3:0819fb0e"] = "¡Hola! ¿Te acuerdas de mí?\n¡Soy AYUDANTE del PROF. OAK!\\p¡Si atrapaste 40 tipos de POKéMON,\nse supone que debería darte\\lMON. AMULETO!\\pDime, {PLAYER}. ¿Tienes ya al menos\n40 tipos de POKéMON?",
  ["g3:0819fc15"] = "¡Bien! ¡Has logrado {STR_VAR_3} tipos\nde POKéMON!\\p¡Enhorabuena!\n¡Aquí tienes!",
  ["g3:0819fc68"] = "¡{PLAYER} obtuvo MON. AMULETO\nde manos del AYUDANTE!",
  ["g3:0819fc93"] = "Una MONEDA AMULETO es un objeto\nque puede llevar un POKéMON.\\pSi gana el POKéMON que la tenga,\nconseguirás más dinero.",
  ["g3:0819fd0c"] = "¡Necesitas una BICI para ir\npor el CAMINO de BICIS!",
  ["g3:0819fd3a"] = "Desde aquí todo el CAMINO\nde BICIS va cuesta arriba.",
  ["g3:0819fd60"] = "¡Perdona!",
  ["g3:0819fd6b"] = "Has usado los prismáticos...\\p¡PUEBLO PALETA está al oeste!",
  ["g3:0819fdb3"] = "Has usado los prismáticos...\\p¡Hay gente nadando!",
  ["g3:0819fdfa"] = "¡Hola! Soy un POKéMON...\n¡No, no lo soy!\\p¡Llámame BILL!\n¡Soy un auténtico POKéMANÍACO!\\p¿No me crees?\n¡Hablo en serio!\\p¡Arruiné un experimento y me\nmezclé con un POKéMON!\\p¿Qué me dices?\n¡Ayúdame a salir!",
  ["g3:0819fee6"] = "¡Hola! Soy un POKéMON...\n¡No, no lo soy!\\p¡Llámame BILL!\n¡Soy un auténtico POKéMANÍACO!\\p¿No me crees?\n¡Estoy en serio!\\p¡Arruiné un experimento y me\nmezclé con un POKéMON!\\p¿Qué me dices?\n¡Ayúdame a salir!",
  ["g3:0819ffd3"] = "¡Cuando esté en el TELETRANSPORTE\nvete a mi PC y ejecuta la\\lSeparación Celular!",
  ["g3:081a0035"] = "¿¡No!?\n¡Debes ayudarme!\\p¡Tengo graves problemas!\\p¿Qué dices, jefe?\n¿Por favor? ¿OK?\\l¡Muy bien!",
  ["g3:081a00b6"] = "¿¡No!?\n¡Debes ayudarme!\\p¡Tengo graves problemas!\\p¿Qué dices, eh?\n¿Por favor? ¿OK?\\l¡Muy bien!",
  ["g3:081a013b"] = "BILL: ¡Yuuju!\n¡Gracias! ¡Te debo una!\\pHas venido a ver mi colección de\nPOKéMON, ¿no?\\p¡Bien hecho!\\pTe lo agradezco...\n¡Toma esto como recompensa!",
  ["g3:081a01e4"] = "BILL: ¡Yuuju!\n¡Gracias! ¡Te debo una!\\pHas venido a ver mi colección de\nPOKéMON, ¿no?\\p¡Bien hecho!\\pTe lo agradezco...\n¡Toma esto como recompensa!",
  ["g3:081a028e"] = "¡{PLAYER} obtuvo un TICKET\nde BARCO de manos de BILL!",
  ["g3:081a02b4"] = "Llevas demasiadas cosas.",
  ["g3:081a02cf"] = "El crucero S.S. ANNE, está\nen CIUDAD CARMÍN.\\p¡Sus pasajeros son ENTRENADORES!\\pMe invitaron a su fiesta, pero yo\nlas odio.\\p¿Por qué no vas tú en mi lugar?",
  ["g3:081a03ab"] = "BILL: Mira, tengo algunos POKéMON\nmuy raros en mi PC.",
  ["g3:081a0402"] = "¡En el monitor del PC aparece el\nTELETRANSPORTE!",
  ["g3:081a042d"] = "¡{PLAYER} inició el Separador\nCelular del TELETRANSPORTE!",
  ["g3:081a045b"] = "¡Es la lista de los POKéMON\nfavoritos de BILL!",
  ["g3:081a0479"] = "¿Qué POKéMON te gustaría ver?",
  ["g3:081a049b"] = "Ahora no lo aparento, pero cuando\nera más joven...\\pIba volando de aquí para allá,\ndesafiando a los ENTRENADORES\\lcon los que me encontraba.\\pAhora, me conformo recordando\nviejos tiempos y viendo combates.",
  ["g3:081a0567"] = "Alrededor de la caja hay\ncorriente...",
  ["g3:081a0598"] = "¡Hola!\n¿Qué tal?\\p¿Sabes una cosa? En el sótano\nhay una sala secreta.\\pY te está esperando {STR_VAR_1}.\\pTú querías luchar con {STR_VAR_1},\n¿no?",
  ["g3:081a064e"] = "Oh...\nNo vas a luchar...\\pVale, vale...\\pBueno, vuelve si cambias\nde opinión.",
  ["g3:081a06ab"] = "¡Hola!\n¿Vas a luchar por mí?\\pEntonces ha merecido la pena\nmover la caja.\\pPero... hay un pequeño\nproblema.\\pLa construcción de esta sala\ndeja un poco que desear.\\p¿Te parece que sólo participen\ntres POKéMON por cada lado?",
  ["g3:081a0788"] = "¡Bien! ¿Quieres guardar la partida\nantes de luchar?",
  ["g3:081a07c4"] = "¡Muy bien!\n¡Pues a por todas!",
  ["g3:081a07ec"] = "El combate ha acabado en empate.",
  ["g3:081a0807"] = "¿Habéis empatado?\\pCon todo, ha sido un espectáculo\napasionante.\\p¿Qué digo?\n¡Apasionante y con mucha miga!",
  ["g3:081a088c"] = "¡Bravo!\\p¡Bravo, bravísimo!\n¡Qué combate, señores!\\p¡Me he emocionado y todo!\\p¡Qué manera de usar las técnicas,\ncon qué seguridad y destreza!\\p¡Qué pulso!\n¡Fuerza contra fuerza!\\p¡Sí, señor!\n¡Magnífico, colosal, apoteósico!",
  ["g3:081a0971"] = "Vaya...\nSé que estás triste...\\pPero no te desanimes, esa tristeza\nte hará más fuerte.\\pÚsala, aprende de ella, ¡apóyate\nen ella para seguir adelante!\\p¡No te olvides de esta derrota\ny entrénate el doble!",
  ["g3:081a0a4f"] = "Los POKéMON tienen su propia\npersonalidad, como cualquiera.\\pMi PIKACHU, por ejemplo, tiene\nuna naturaleza ACTIVA, y realmente\\lno para.",
  ["g3:081a0acc"] = "Bueno, ya lo tengo todo para\nexplorar las RUINAS.",
  ["g3:081a0b09"] = "Tengo que pescar en ISLA SÉTIMA.\\pEs la que me falta para completar\nmi ruta por ARCHI7.\\pPero antes, voy a hacerme con\nunas cuantas POKé BALLS.",
  ["g3:081a0b98"] = "En la isla, ocurren distintas cosas\nsegún las conexiones.\\p¿Que qué son las conexiones?\\pEso tendrás que descubrirlo sin\nayuda de nadie.",
  ["g3:081a0c1f"] = "¿Has venido a bordo del SURCAMAR?\\pCreo que en total hay diez barcos\nrápidos de esos.\\pPero no sé las rutas que cubren.",
  ["g3:081a0ca5"] = "Si te sientes con fuerzas, deberías\nvisitar la TORRE DESAFÍO.",
  ["g3:081a0cde"] = "BILL: ¡Eh, oye!\n¡CELIO!",
  ["g3:081a0cf7"] = "CELIO: ¡Hombre, BILL!\n¡No puedo creerme que estés aquí!",
  ["g3:081a0d27"] = "BILL: ¡Pues claro, hombre!\n¿Qué tal van tus investigaciones?\\pEh..., ay, perdona...",
  ["g3:081a0d72"] = "{PLAYER}, éste es mi amigo CELIO.\nEs un flipado de los ordenadores.",
  ["g3:081a0dac"] = "BILL: CELIO, te presento\na {PLAYER}, aspirante a ganar\\lla LIGA POKéMON.",
  ["g3:081a0de8"] = "BILL: CELIO, te presento\na {PLAYER}, ¡ha ganado la LIGA\\lPOKéMON!",
  ["g3:081a0e17"] = "CELIO: ¡Anda, fíjate tú!\\pYo la verdad es que soy un negado\npara los combates.\\pPero oye, me alegro de conocerte.",
  ["g3:081a0e90"] = "BILL: Bueno, cuéntame, cuéntame,\n¿qué tal va la máquina esa en la\\lque estabas trabajando?",
  ["g3:081a0ecc"] = "CELIO: Va bien, va bien, pero es\nque estamos en el quinto pino\\py no hay forma de conectar los PCs\nde aquí con tu PC, BILL.",
  ["g3:081a0f40"] = "BILL: ¿Ah, no? Mmm, ¿me dejas\nque eche un vistazo?\\pUn segundo... Oye, pues yo creo\nque podemos conseguir que\\lfuncione. ¿Me dejas que te ayude?",
  ["g3:081a0fb1"] = "{PLAYER}, ¿te importa esperarme\nun momento?\\pO, mejor, ¿me haces un favor?\\pCerca de aquí está ISLA SECUNDA\ny hay un tipo que lleva los\\lRECREATIVOS.\\pLa cosa es que le encantan\nlas rocas raras y las gemas.\\pComo ves, los dos tenemos\nnuestras manías, por eso estamos\\len contacto.\\p¿Te importaría acercarle\neste METEORITO?",
  ["g3:081a10ee"] = "{PLAYER} obtuvo el METEORITO\nde manos de BILL.",
  ["g3:081a1113"] = "CELIO: {PLAYER}, toma, llévate esto\nsi vas a ir a ISLA SECUNDA.",
  ["g3:081a1150"] = "CELIO: Es un TICKET para el ferry\nque conecta las islas.\\pCon él podrás viajar entre las\nISLAS PRIMA, SECUNDA y TERA.\\p¡Ah, y llévate esto también!",
  ["g3:081a11ec"] = "¡{PLAYER} obtuvo una página más\ndel MAPA!",
  ["g3:081a1218"] = "¡{PLAYER} obtuvo el MAPA!",
  ["g3:081a1230"] = "BILL: ¡Bueno, después nos vemos!\n¡Dale recuerdos de mi parte!",
  ["g3:081a1266"] = "Mmm...\\p¿Y si intentamos ponerlo de otra\nforma?...",
  ["g3:081a128c"] = "¡Eh, {PLAYER}!\\p¿Has visto? ¡Hemos conseguido\nla conexión con el PC!\\pPero aún tengo que enseñarle\nun par de cosas a CELIO.\\p¿Por qué no te das un paseo\nmientras?",
  ["g3:081a1321"] = "CELIO: Siento haber entretenido\ntanto a BILL.\\pY siento también haber sido tan\nmal anfitrión.",
  ["g3:081a1390"] = "Los servicios habituales del PC\nno están disponibles...",
  ["g3:081a13b8"] = "BILL: ¡Anda, {PLAYER}!\n¿Qué tal?",
  ["g3:081a13cb"] = "BILL: ¿Qué has estado haciendo\ntanto tiempo? ¿Qué tal, bien?\\p¡Nosotros ya lo tenemos! ¡Los PCs\nestán a punto y van de maravilla!",
  ["g3:081a1431"] = "CELIO: La verdad es que ha sido\nmás rápido de lo que pensaba.\\pBILL es un cerebrito.",
  ["g3:081a1470"] = "BILL: ¡Qué va, hombre! ¡Si todo\nestaba prácticamente hecho!\\pCELIO, el mérito es tuyo.\nSabes un montón.",
  ["g3:081a14e1"] = "CELIO: ¿Tú crees?\nBueno, pues vale. Je.",
  ["g3:081a14fb"] = "BILL: Bueno, pues ya está.\nPor mi parte, yo he acabado.\\lVámonos ya de vuelta a KANTO.\\pCELIO, nos vemos.",
  ["g3:081a1574"] = "CELIO: {PLAYER}, siento mucho que\nhayas tenido que marcharte sin\\lnadie que te acompañara.\\pTe prometo que te enseñaré\nla isla en otra ocasión.",
  ["g3:081a15ec"] = "CELIO: ¡Hola!\n¡Siempre estás de aquí para allá!\\p¿Que qué tal voy?\\pPues haciendo unos retoques\na la MÁQUINA de REDES.\\p¡Espero que la uses antes que\nnadie cuando esté lista, {PLAYER}!",
  ["g3:081a169b"] = "CELIO: {PLAYER}, ¿qué tal\nte ha ido?\\p¿De verdad? ¿Has atrapado más\nPOKéMON?\\pPues ¿sabes qué? A lo mejor puedo\nayudarte.",
  ["g3:081a1723"] = "En este momento estoy modificando\nla MÁQUINA de REDES.\\pEstoy ajustándola para que puedan\nhacerse intercambios a grandes\\ldistancias.\\pCuando acabe, podrás recibir\nexóticos POKéMON de ENTRENADORES\\lque están muy lejos de aquí.",
  ["g3:081a17df"] = "Pero falta un pequeño detalle.\\pPara que funcione la conexión,\nse necesita una gema especial.\\pParece ser que se encuentra\nen ISLA PRIMA, pero yo aún\\lno he encontrado ninguna.\\pAverigua dónde estará...",
  ["g3:081a1896"] = "Durante mis investigaciones\ntambién he intentado encontrar\\lla gema.\\pY al final, ni tengo gema ni\nhe avanzado nada en mis estudios...\\pSi acudiera a BILL, seguro que\navanzaría en mis investigaciones.\\pPero en esta ocasión, quiero hacer\nlas cosas por mí mismo.",
  ["g3:081a197e"] = "¡Ahí va!\n¡Pero si es...!",
  ["g3:081a198d"] = "{PLAYER} le entregó el RUBÍ\na CELIO.",
  ["g3:081a19aa"] = "¡Muchas gracias!\n¡{PLAYER}, eres increíble!\\p... ... ... ... ... ...\\pEh...\n¿Puedo pedirte un favor enorme?",
  ["g3:081a1a08"] = "No es ninguna cosa rara...,\nno te preocupes.\\lEs que necesito que me ayudes.",
  ["g3:081a1a3f"] = "Mientras estudiaba las gemas,\ndescubrí algo importante.\\pHay otra que forma pareja\ncon este RUBÍ.\\pY se supone que está en\nARCHI7.\\p{PLAYER}, necesito que vayas\na buscarla, por favor.\\p{PLAYER}, ¿me dejas un segundo\nel TICKET del ferry y el MAPA?",
  ["g3:081a1b56"] = "{PLAYER} devolvió el TRI-TICKET\ny recibió el IRIS-TICKET.",
  ["g3:081a1b8e"] = "¡Y obtuviste una página más\ndel MAPA!",
  ["g3:081a1bb7"] = "Éste es mi TICKET para el ferry.\\pCon él, podrás viajar entre las\nislas de ARCHI7.\\p{PLAYER}, tienes que ayudarme,\npor favor.",
  ["g3:081a1c2d"] = "{PLAYER} le entregó el ZAFIRO\na CELIO.",
  ["g3:081a1c4e"] = "CELIO: Así que ésta es la\ncompañera del RUBÍ...\\p{PLAYER}, has debido de pasar por\nmil historias para conseguirla, ¿no?\\pNo hace falta que me digas nada,\nsé que no habrá sido nada fácil.\\p¡Muchas gracias!\\pAhora me toca a mí hacer algo\npor ti. Dame algo de tiempo.",
  ["g3:081a1d45"] = "Muy bien, a ver...",
  ["g3:081a1d59"] = "¡Ya está!\n¡He conseguido establecer conexión\\lcon AREDIA!",
  ["g3:081a1d7d"] = "¡{PLAYER}!\n¡{PLAYER}, lo he conseguido!\\p¡He conseguido establecer conexión\ncon ENTRENADORES de la región\\lde HOENN!\\p¡Por fin funciona completamente\nla MÁQUINA de REDES!\\p{PLAYER}, te lo debo todo a ti.\\pGracias a ti, mi sueño se ha hecho\nrealidad...",
  ["g3:081a1e39"] = "No...\nNo estoy llorando, no...\\pYa está, ya se me pasa...\\p{PLAYER}, ¿a que vas a intentar\nconseguir exóticos POKéMON, eh?\\p¡Que tengas mucha suerte!",
  ["g3:081a1ebd"] = "CELIO: ¡Hola!\\p{PLAYER}, últimamente se habla\nmucho sobre ti...",
  ["g3:081a1ef3"] = "{PLAYER}, ¿qué POKéMON te gusta\nmás?\\pBILL es un POKéMANÍACO,\na él le gustan todos.\\pCreo que el primero que atrapó\nfue un ABRA.",
  ["g3:081a1f7c"] = "A todo esto, {PLAYER}, tú eres\nde PUEBLO PALETA, ¿no?\\pMe han comentado que es un sitio\nmuy tranquilo y agradable.\\pBILL es de CIUDAD TRIGAL,\ndonde aún viven sus amigos.\\pDicen que es una ciudad muy\nalegre y animada.\\pLa verdad es que me gustaría\nir algún día.",
  ["g3:081a2076"] = "{PLAYER}, ¿hay algo que te siente\nmal?\\pCreo que BILL no tolera muy bien\nla leche. Le da dolor de estómago.",
  ["g3:081a20d5"] = "¡Eh, tú no eres de aquí!\n¿De dónde vienes?\\p¿PUEBLO PALETA?...\n¡No me suena de nada!",
  ["g3:081a212d"] = "En esta isla hay un volcán enorme.\\pHace poco entró en erupción.\nAhora sería buen momento\\lpara hacer escalada.",
  ["g3:081a218d"] = "Ojalá pudiera intercambiar POKéMON\ncon mi chico, que vive muy lejos\\lde aquí...",
  ["g3:081a21d0"] = "¡He podido intercambiar POKéMON\ncon mi chico!\\l¡Con lo lejos que está!\\pTodo el mundo dice que os\nlo debemos a CELIO y a ti.\\p¡Así que gracias!",
  ["g3:081a223f"] = "MÁQUINA de REDES\nNivel de conexión: 0\\pSistema de Almacenamiento\nde POKéMON, no disponible...",
  ["g3:081a2286"] = "MÁQUINA de REDES\nNivel de conexión: 1\\pConexión establecida con la región\nde KANTO.",
  ["g3:081a22cb"] = "MÁQUINA de REDES\nNivel de conexión: 2\\pConexión establecida con las\nregiones de KANTO y HOENN.",
  ["g3:081a231b"] = "¡Obtuviste el TRI-TICKET!",
  ["g3:081a2332"] = "Cuando hace buen día, salgo\na contemplar el volcán.\\pEs lo que hago siempre.",
  ["g3:081a2380"] = "Mmm, no consigo acordarme...\n¿Cuándo fue la última vez que\\lentró en erupción el MT. ASCUAS?",
  ["g3:081a23b8"] = "La gente joven siempre quiere irse\na las grandes ciudades.\\p¡Yo, desde luego, de aquí\nno me muevo!",
  ["g3:081a2408"] = "¿Dónde se habrá metido PEDRITA\nhoy?\\pSiempre me trae la comida\na tiempo, pero hoy...",
  ["g3:081a2465"] = "¡Oye, sí, tú!\n¿Conoces a PEDRITA?\\p¿La has visto por algún sitio?\nNo tengo ni idea de dónde se habrá\\lmetido, pero tarda un montón.\\pEs una monada de niña, espero\nque no le haya pasado nada...\\p¡Como le haya pasado algo a mi\nPEDRITA!\\p¡Por favor, ayúdame a buscarla!\n¿Irías a ISLA TERA a ver si está?",
  ["g3:081a259a"] = "¿Y éstos son los RECREATIVOS?\n¡POR FAVOR!\\pQué birria...\\p¿No se supone que hemos quedado\naquí? ¿Dónde está la gente?\\p¡Eh, tú! ¿Hay otra ISLA TERA\npor ahí o es ésta la única?",
  ["g3:081a2658"] = "¡Vaya empanada mental que tienes,\nchaval!\\p¡Esto es ISLA SECUNDA!\\p¡Anda, pon en marcha la moto\ny tira!",
  ["g3:081a26d5"] = "Eh...\nAh, vale.\\pEh...\n¡Me he liado con tanta isla!",
  ["g3:081a270c"] = "¿Será posible?\n¡El gamberro ese me ha rayado\\lel suelo!",
  ["g3:081a2743"] = "Por favor, tienes que ir a ISLA\nTERA.\\pSi le pasara algo a mi PEDRITA...\\pMi casa está en ISLA TERA, es la\ndel tejado rojo.\\pYo no quiero moverme de aquí,\nno vaya a ser que aparezca en\\lalgún momento.\\pPor eso te pido que me ayudes.",
  ["g3:081a285c"] = "Lo siento.\nEn este momento no se puede jugar\\la nada.",
  ["g3:081a288a"] = "Vuelve dentro de un tiempo.",
  ["g3:081a28b2"] = "¡¿Has rescatado a PEDRITA?!\n¡No sabes cómo te lo agradezco!\\p¡PEDRITA, cielo, perdóname!\\p¡Papá no sabía que estuvieras\nasustada y no te atrevieras\\la volver!",
  ["g3:081a2931"] = "PEDRITA: No asa nada, api.\n{PLAYER}, es amigui.",
  ["g3:081a296a"] = "¿Cómo?\n¿Que es para mí?\\p¿Y cómo sabes que me gustan\nlas rocas raras y las gemas?\\pDesde luego, has dado en el clavo.",
  ["g3:081a29f7"] = "{PLAYER} le entregó el METEORITO\nal papá de PEDRITA.",
  ["g3:081a2a24"] = "¡Ah, que lo envía BILL!\n¡Dale las gracias de mi parte!\\pNo tengo palabras para agradecerte\ntodo lo que has hecho.\\lMe gustaría darte esto.",
  ["g3:081a2a9a"] = "¡{PLAYER} obtuvo una PIEDRA LUNAR\nde manos del papá de PEDRITA!",
  ["g3:081a2aca"] = "En la MOCHILA no cabe nada\nmás...",
  ["g3:081a2af5"] = "Bueno, ya podemos poner en marcha\nlos RECREATIVOS.\\pVente con algún amigo para jugar\na algo.",
  ["g3:081a2b53"] = "¡Eh, eh!\\p¡Ede guay, tú hace aggo guay!",
  ["g3:081a2b88"] = "Soy el TUTOR de MOVIMIENTOS.\\pMe sé todos los movimientos que\naprenden los POKéMON. Todos,\\ltoditos, todos. Y puedo enseñar.\\pTambién soy EXPERTO en SETAS.\\pSi me traes dos MINI SETAS o una\nSETA GRANDE, le enseñaré un\\lmovimiento a uno de tus POKéMON.",
  ["g3:081a2c63"] = "Sniff, sniff...\n¡Mmm! ¡Hueles a SETA!\\p¿Quieres que le enseñe un\nmovimiento a uno de tus POKéMON?",
  ["g3:081a2cc3"] = "¿Qué POKéMON quieres que lo\naprenda?",
  ["g3:081a2ce1"] = "¿Qué movimiento quieres que\naprenda?",
  ["g3:081a2cfc"] = "Perdona...\\pParece que no puedo enseñar ningún\nmovimiento a ese POKéMON...",
  ["g3:081a2d43"] = "Pues tendrás que darme una SETA\no un par de ellas.\\l¿Qué me das?",
  ["g3:081a2d85"] = "{PLAYER} entregó dos MINI SETAS\na cambio de la lección.",
  ["g3:081a2db3"] = "{PLAYER} entregó una SETA GRANDE\na cambio de la lección.",
  ["g3:081a2de0"] = "Si quieres que le enseñe un\nmovimiento a algún POKéMON,\\ltráeme una SETA o dos.",
  ["g3:081a2e20"] = "¿Eh? No puedo enseñar\nabsolutamente ningún movimiento\\la un HUEVO...",
  ["g3:081a2e59"] = "¿Conoces ya los RECREATIVOS?\\pLo suyo es ir al menos con\nun amigo. Si no, es un rollo.",
  ["g3:081a2ebe"] = "ISLA SECUNDA tiene muy pocos\nhabitantes.\\pEn el mismo cabo vive una señora\nmayor.\\pLleva allí ni se sabe...",
  ["g3:081a2f3e"] = "PEDRITA: ¡Hola, {PLAYER}!\n¡Iempre edes guay!\\p¡He hecho comidita pada ti,\n{PLAYER}!",
  ["g3:081a2f92"] = "Hay rocas raras y gemas.",
  ["g3:081a2fb5"] = "Eh, ¿te has enterado?\\pAhora podemos estar en red\ncon los PCs de KANTO.\\p¡No sé quién lo habrá organizado,\npero me parece una idea estupenda!",
  ["g3:081a303b"] = "Es imposible hacer SURF\nentre las islas de esta zona.\\pHay corrientes y remolinos.",
  ["g3:081a30a3"] = "¡Vamos a MACHACAR BAYAS!\n¿Que sería un desperdicio de BAYAS\\ldices?...\\p¡Pero si el BOSQUE BAYA está hasta\narriba!",
  ["g3:081a3114"] = "¿De verdad?\\p¿Seguro que el CENTRO COMERCIAL\nde AZULONA es mucho mayor que\\lesta tienda?",
  ["g3:081a315c"] = "A veces compro medicinas aquí.\\pPero hay mucha gente que cura a\nlos POKéMON con BAYAS del BOSQUE\\lBAYA.\\pHombre, yo lo entiendo; las BAYAS\nson gratis y nunca se acaban.",
  ["g3:081a31f0"] = "Los MOTORISTAS han estado a punto\nde destrozar la TIENDA POKéMON.\\pMenos mal que se han ido.",
  ["g3:081a3245"] = "¡Urrrrrrrrgggg!...\n¡Fffwaaaaah!\\p¡Nada!... ¡No hay manera!\n¡No consigo doblar la cuchara\\lcon la mente!\\pA ver si va a resultar que no\ntengo poderes psíquicos...",
  ["g3:081a32ca"] = "¿Sabes algo de la LÍDER del\nGIMNASIO de AZAFRÁN?\\pUsa POKéMON del tipo PSÍQUICO,\n¿no?\\pYo la admiro, la verdad.\\pHe oído que es guay y, además,\nmuy mona.",
  ["g3:081a3379"] = "Me compré esta casa porque\nquería vivir en un sitio tranquilo.\\pHoy, creo que voy a ir a pescar.",
  ["g3:081a33db"] = "Que no se te ocurra ir nunca al\nBOSQUE BAYA sin compañía.\\p¡Está lleno de fantasmas!",
  ["g3:081a342f"] = "¡Mi padre me cuenta unas historias\nque no se las cree ni él!\\l¡Y no me deja salir a jugar!",
  ["g3:081a3469"] = "¿Yo?\nNo, yo no soy PEDRITA.\\pYo creo que se ha ido al BOSQUE\nBAYA.\\pSe dedica a recoger BAYAS para\nhacer la comida.",
  ["g3:081a34db"] = "Creo que voy a irme a jugar\ncon PEDRITA.",
  ["g3:081a3505"] = "¿Ya?\n¡Toma!\\pEstamos usando GOLPE CUERPO para\nver quién machaca antes a quién.\\pSi te metieras en la pelea, no\ntendrías nada que hacer...\\p¿Quieres que le enseñe GOLPE\nCUERPO a alguno de tus POKéMON?",
  ["g3:081a35c7"] = "¡Venga, otra vez!\n¡Toma!",
  ["g3:081a35da"] = "¿A qué POKéMON quieres que\nle enseñe GOLPE CUERPO?",
  ["g3:081a3609"] = "¡Uauuu!",
  ["g3:081a3627"] = "En la CUEVA GLACIADA hay un\nPOKéMON raro del tipo HIELO.\\pAquí viene mucha gente para\nverlo.",
  ["g3:081a3697"] = "¿Cómo? ¿Un HUEVO POKéMON?\nNi idea...\\pEh..., sí, espera, los ENCARGADOS\nde la GUARDERÍA comentaron algo\\lsobre eso.\\pDijeron que habían encontrado\nHUEVOS en la propia GUARDERÍA.",
  ["g3:081a3734"] = "¡Pero bueno!\\p¿Que aún no ha llegado el nuevo\nDIARIO POKéMON a esta isla?",
  ["g3:081a3802"] = "¡Hala, qué golpe!\n¡Qué fuerza tienes!",
  ["g3:081a3826"] = "LORELEI: No me puedo quitar una\ncosa de la cabeza...\\pSi ocurriera algo a la isla en la\nque nací...\\pNo me enteraría si estuviera\nen la LIGA POKéMON.\\pEntonces, sería responsable\nde lo ocurrido, ¿no?",
  ["g3:081a390c"] = "LORELEI: ¿Que tú has solucionado\ntodos los problemas?\\pQué maravilla...\\pEntonces, no tengo que quedarme\naquí todo el tiempo...\\p¡Gracias!\\p¡En ese caso, me volveré a la\nLIGA POKéMON!",
  ["g3:081a39d8"] = "No sé qué pasará dentro de un\ntiempo, así que...\\pHaré lo que tenga que hacer\naquí y ahora.",
  ["g3:081a3a42"] = "¡Qué cantidad de MUÑECOS POKéMON\nde peluche!",
  ["g3:081a3a60"] = "En esta isla nació y creció una\nENTRENADORA fuerte y poderosa\\lcomo pocas.\\pSeguro que la conoces, se llama\nLORELEI y es del ALTO MANDO.\\pYo le enseñé muchas cosas sobre\nlos POKéMON cuando aún era un\\lcomino.",
  ["g3:081a3b14"] = "En realidad, ARCHI7 está\nen una zona cálida.\\pPero hay una excepción de la que\nquiero hablarte.\\pLa CUEVA GLACIADA es un lugar\nfrío por el POKéMON que la habita.",
  ["g3:081a3bba"] = "Voy a preparar una comida para\nuna persona muy importante.",
  ["g3:081a3bfd"] = "¿Quieres atrapar a todos los\nPOKéMON que te encuentres?\\p¡Qué increíble!... ¡Oye, pues\navísame si atrapas alguno fuerte!",
  ["g3:081a3cac"] = "Que no comprara nada de cena hoy,\nque no me preocupara.\\pEso fue lo que me dijo mi marido\nal irse a pescar esta mañana.\\pNo sé yo si me puedo fiar mucho\nteniendo en cuenta la hora\\lque es...",
  ["g3:081a3d5e"] = "El PRADO ha pertenecido a nuestra\nfamilia durante generaciones.\\pTendría que haber aprovechado\npara construir una mansión gigante.\\pMejor eso, a tener a la gentuza\npisoteándolo a sus anchas.",
  ["g3:081a3e02"] = "Llevo diez años buscando\nlas RUINAS.\\pNo, mucho más, ¡llevo veinte!\\pCreo que en esta isla hay algo\nraro.",
  ["g3:081a3e87"] = "Tú ya sabes que hay POKéMON que\nevolucionan durante el intercambio,\\l¿no?\\p¿Y sabes que algunos necesitan un\nobjeto concreto para evolucionar\\ldurante el intercambio?",
  ["g3:081a3f30"] = "{RIVAL}: ¡Eh, {PLAYER}!\n¿Qué tal llevas la POKéDEX?\\pParece imposible conseguir todos\nlos POKéMON paseando sólo por\\lesta zona, ¿eh?\\pA lo mejor hay otros POKéMON\nlejos de aquí...\\p... ... ... ... ... ... ... ... ...\\pDesde luego, si yo no lo consigo,\ntampoco vas a conseguirlo tú.\\pBueno, tampoco voy a obsesionarme\nmucho con el tema.\\pSeguiré coleccionando POKéMON\na mi ritmo y los entrenaré.\\pEso es lo que voy a hacer.\nNo merece la pena estar aquí,\\lcreo que me voy a casa.\\pPues eso.\n¡Nos vemos!",
  ["g3:081a412e"] = "Aquí la gente joven no encuentra\nnada de su interés.\\pPero éste es un lugar único por la\nnaturaleza y la historia que tiene.\\pRelájate y disfruta de la estancia.",
  ["g3:081a41ca"] = "¡Juega con los POKéMON y vivirás\nmucho tiempo!\\pMira a AGATHA, por ejemplo.\\pEs el miembro de más edad\ndel ALTO MANDO.\\p¡A mí me anima a superarme\ndía a día!",
  ["g3:081a4271"] = "Debería escribir alguna CARTA...",
  ["g3:081a42a0"] = "CONSU: ¿Mmm?\n¿No te conozco de algo?\\pBueno, da igual.\\pMe aburro como una ostra, ¿tienes\nun segundito para mí?\\l¿Sabes lo que me gustaría hacer?",
  ["g3:081a4315"] = "Me gustaría ver algún POKéMON,\nuno de esos {STR_VAR_1} adorables.\\p¡Y quiero verlo ahora!\nEnséñame uno, anda.",
  ["g3:081a437a"] = "CONSU: Estoy hasta el gorro.\n¡Llevo esperándote un montón!\\pPor esta vez, te perdono,\npero no me falles la próxima.",
  ["g3:081a43f7"] = "CONSU: Hola.\\p¡Anda, ése debe de ser el \n{STR_VAR_1} que atrapaste para mí!\\pJa, ja, ja...\nOs parecéis un poco...\\pMuchísimas gracias.\\p... ... ... ... ... ...\nEh... ¿pasa algo?\\pPuedes irte.\\p... ... ... ... ... ...\nAh, vale, de acuerdo.\\p¡SEBASTIÁN!\n¡Ven aquí ahora mismo!",
  ["g3:081a450b"] = "MAYORDOMO: Sí, señora.",
  ["g3:081a4521"] = "CONSU: Muéstrale lo agradecida\nque estoy.",
  ["g3:081a4566"] = "MAYORDOMO: Como desee, señora.",
  ["g3:081a458e"] = "MAYORDOMO: Gracias de verdad por\nhaber agradado a la Señora CONSU.\\pAcepte esto como agradecimiento.",
  ["g3:081a45e8"] = "MAYORDOMO: Desafortunadamente,\nparece que tiene la MOCHILA llena.",
  ["g3:081a461b"] = "Vaya...\nQué pena.",
  ["g3:081a4632"] = "CONSU: Espero que te vaya \nmuy bien.",
  ["g3:081a4657"] = "MAYORDOMO: La Señora CONSU\ntiene una sonrisa deslumbrante.\\pEspero que no se le borre.",
  ["g3:081a46c6"] = "He perfeccionado el último\nmovimiento de este tipo...\\pBueno, y ahora, ¿a quién se lo\nenseño?\\pMmmm...\\pEse {STR_VAR_1} tuyo...",
  ["g3:081a4737"] = "No, no...\nMe he equivocado...",
  ["g3:081a4751"] = "¡Anda, éste es!\n¡Éste es el POKéMON!\\p¡Este {STR_VAR_1} se merece\naprender mi último movimiento!\\p¿Te parece bien?\\p¿Quieres que le enseñe\nmi {STR_VAR_2} a tu {STR_VAR_1}?",
  ["g3:081a47e5"] = "¿Cómo, que no?\n¡No me lo puedo creer!",
  ["g3:081a4814"] = "¿Quieres?\\pPues voy a enseñarle\nmi {STR_VAR_2} a tu {STR_VAR_1}.\\p¡Allá voy!",
  ["g3:081a4865"] = "Qué emoción...\\pNo pensé que llegara a enseñar\nal final el movimiento...",
  ["g3:081a48b3"] = "¡Espero que lo uses bien y\nle saques el mayor partido!",
  ["g3:081a48f3"] = "Qué emoción...\\pQué tranquilidad.\nYa he transmitido todo lo que sé.\\pQué satisfacción cumplir con el\ndeber...",
  ["g3:081a4972"] = "Ahora que sabes lo que yo, siento\nuna tranquilidad enorme.\\p¡Me siento hasta más joven!\n¡Es como si me hubiera quitado\\laños de encima!",
  ["g3:081a49e9"] = "¡Hera, hera, HERACROSS!\n¡Es muy grande, es el mejor!\\l¡Hera, hera, HERACROSS!",
  ["g3:081a4a3f"] = "¡Aaaaaaah!\n¡Tienes un HERACROSS!\\pPorfa, porfa, ¿puedo ver cuánto\nmide?",
  ["g3:081a4a88"] = "¡Guau, {STR_VAR_2} cm!\n¡Nunca he visto nada igual!\\l¡Toma, te mereces este premio!",
  ["g3:081a4ad9"] = "Me encantaría ver un HERACROSS\nmucho más grande que ése.\\p¡Es que me alucinan los HERACROSS\ngrandes!",
  ["g3:081a4b39"] = "¿Mmm? {STR_VAR_2} cm...\n¡Pero si es lo mismo que antes!",
  ["g3:081a4b7a"] = "Vaya, {STR_VAR_2} cm sólo...\nEl HERACROSS de antes era mayor.\\pMedía {STR_VAR_3} cm, ése ha sido el\nHERACROSS más grande que me\\lhas traído hasta ahora.",
  ["g3:081a4bef"] = "¡No, no y no!\\pHERACROSS es mucho mejor,\nes más guay y se ve más fuerte.\\l¡Y tiene un cuerno chulísimo!",
  ["g3:081a4c47"] = "Tienes la MOCHILA hasta arriba.\nNo hay sitio para mi premio.",
  ["g3:081a4c6e"] = "El mayor HERACROSS que he\nmedido hasta ahora alcanzaba:\\p¡{STR_VAR_3} cm!",
  ["g3:081a4cb9"] = "Es una especie de cuadro y\nestá en blanco.\\pTiene casillas para anotar cosas.",
  ["g3:081a4d0d"] = "Yo mido 1'70.\\pLo sé, porque mi vecina me midió.",
  ["g3:081a4d72"] = "¡A bailar el baile de CHANSEY,\na bailar!\\p¡Baila tú también!\n¡A bailar, a bailar!",
  ["g3:081a4daf"] = "¿Quieres bailar?",
  ["g3:081a4dc8"] = "¡Venga, baila!",
  ["g3:081a4dd8"] = "{PLAYER} bailó el baile de CHANSEY.",
  ["g3:081a4df5"] = "¡Ja, ja, ja!\\p¡Ahora estáis más animados!\n¡Qué bien!",
  ["g3:081a4e26"] = "CHANSEY: ¡Chansi, chansi!",
  ["g3:081a5075"] = "{PLAYER} encendió el PC.",
  ["g3:081a508a"] = "¿A qué PC quieres acceder?",
  ["g3:081a50a7"] = "Accedió al PC de alguien.",
  ["g3:081a50be"] = "Acceso al Sistema de\nAlmacenamiento de POKéMON\\lconcedido.",
  ["g3:081a50dd"] = "Accedió al PC de {PLAYER}.",
  ["g3:081a50ef"] = "Accedió al PC de BILL.",
  ["g3:081a5190"] = "¡Vuelve cuando quieras!",
  ["g3:081a51f6"] = "¡Obtuviste {STR_VAR_2}!",
  ["g3:081a5207"] = "La MOCHILA está llena...",
  ["g3:081a5218"] = "{PLAYER} puso {STR_VAR_2}\nen el {STR_VAR_3}.",
  ["g3:081a5231"] = "¡{PLAYER} encontró {STR_VAR_2}!",
  ["g3:081a5242"] = "¡Mala suerte!\nLa MOCHILA está llena...",
  ["g3:081a52f0"] = "¡Obtuviste {STR_VAR_2}!",
  ["g3:081a532f"] = "Se envió {STR_VAR_2} al PC.",
  ["g3:081a535c"] = "¿A qué piso quieres ir?",
  ["g3:081a5420"] = "{PLAYER} encendió el PC.",
  ["g3:081a5483"] = "¡Éste es el CENTRO POKéMON!\\pNosotros curamos a los POKéMON\ndebilitados.\\p¿Quieres que nos ocupemos de los\nPOKéMON de tu equipo?",
  ["g3:081a54e1"] = "Muy bien. Ten un poco de\npaciencia. Será sólo un momento.",
  ["g3:081a5511"] = "¡Vuelve cuando quieras!",
  ["g3:081a552b"] = "Gracias por esperar.\\pMisión cumplida. Somos especialistas\nen devolver la forma a los\\lPOKéMON.",
  ["g3:081a561a"] = "Lo siento, pero el CLUB\nINALÁMBRICO POKéMON no está\\ldisponible todavía.",
  ["g3:081a56a7"] = "¿Quieres darle un mote a tu\n{STR_VAR_1}?",
  ["g3:081a572a"] = "Sólo pueden pasar los\nENTRENADORES expertos.\\p¡Aún no tienes la {STR_VAR_1}!",
  ["g3:081a5776"] = "Las reglas son las reglas.\n¡No puedes pasar!",
  ["g3:081a579d"] = "¡Oh! ¡Ésa es la {STR_VAR_1}!\n¡Puedes pasar!",
  ["g3:081a57c1"] = "¡Sólo podrás entrar aquí si tienes\nla {STR_VAR_1}!\\p¡Aún no tienes la {STR_VAR_1}!\\p¡Debes tenerla para acceder\na la LIGA POKéMON!",
  ["g3:081a58a7"] = "Veamos...\n¡Oh! ¡Atrapaste solamente {STR_VAR_3} tipos\\lde POKéMON!\\pNecesitas {STR_VAR_1} tipos si quieres\n{STR_VAR_2}.",
  ["g3:081a5909"] = "¡Ah! Ya veo.\\pCuando tengas {STR_VAR_1} tipos, vuelve\na por {STR_VAR_2}.",
  ["g3:081a594d"] = "¡Oh! Ya veo que no tienes sitio\npara {STR_VAR_2}.",
  ["g3:081a597b"] = "¡Busco un {STR_VAR_1}!\\p¿Quieres cambiarlo por\n{STR_VAR_2}?",
  ["g3:081a59b6"] = "¿No?\nPues vale...",
  ["g3:081a59c6"] = "¿Qué?\n¡Ése no es {STR_VAR_1}!",
  ["g3:081a59da"] = "¡Muchas gracias!",
  ["g3:081a59e7"] = "¿No es estupendo mi {STR_VAR_2}?",
  ["g3:081a59fe"] = "¡Hola!\\p¿Quieres cambiar tu {STR_VAR_1}\npor {STR_VAR_2}?",
  ["g3:081a5a4e"] = "Vale, si no quieres...",
  ["g3:081a5a6a"] = "¿Qué?\nÉste no es {STR_VAR_1}.\\pCuando tengas uno piensa en mí.",
  ["g3:081a5a9d"] = "¡Gracias!",
  ["g3:081a5aa5"] = "¿Qué tal va el {STR_VAR_2} que te\nenvié, más fuerte?",
  ["g3:081a5ad6"] = "¡Hola! ¿Tienes un {STR_VAR_1}?\\p¿Quieres cambiarlo por\nmi {STR_VAR_2}?",
  ["g3:081a5b08"] = "¡Qué pena!",
  ["g3:081a5b18"] = "Éste no es un {STR_VAR_1}.\\p¡Si consigues uno, te lo cambio!",
  ["g3:081a5b4a"] = "¡Gracias, contigo da gusto!",
  ["g3:081a5b60"] = "¿Cómo está mi viejo {STR_VAR_2}?\n¡Mi {STR_VAR_1} está fenomenal!",
  ["g3:081a5b88"] = "¡Bingo! ¡La LLAVE MAGNÉTICA\nabrió la puerta!",
  ["g3:081a5bad"] = "¡Caray!\n¡Necesito una LLAVE MAGNÉTICA!",
  ["g3:081a5bc6"] = "Accedes al PC del PROF. OAK.\\pAccedes al Sistema de Evaluación\nde la POKéDEX.",
  ["g3:081a5c03"] = "¿Quieres evaluar tu POKéDEX?",
  ["g3:081a5c2e"] = "Cerrado el enlace al PC del PROF.\nOAK.",
  ["g3:081a5cdf"] = "La puerta está abierta...",
  ["g3:081a5cf1"] = "{STR_VAR_2} fue enviado al PC\nde alguien.\\pSe ha guardado en la CAJA\n“{STR_VAR_1}”.",
  ["g3:081a5d31"] = "{STR_VAR_2} fue enviado al PC\nde BILL.\\pSe ha guardado en la CAJA\n“{STR_VAR_1}”.",
  ["g3:081a5d6e"] = "La CAJA “{STR_VAR_3}” del PC\nde alguien estaba llena.\\p{STR_VAR_2} fue enviado a la CAJA\n“{STR_VAR_1}”.",
  ["g3:081a5db1"] = "La CAJA “{STR_VAR_3}” del PC\nde BILL estaba llena.\\p{STR_VAR_2} fue enviado a la CAJA\n“{STR_VAR_1}”.",
  ["g3:081a5df1"] = "¡{PLAYER} obtuvo\nel {STR_VAR_1}!",
  ["g3:081a5e31"] = "¡No queda sitio para más POKéMON!\\p¡Las CAJAS POKéMON están llenas!",
  ["g3:081a5e89"] = "Primero, deberías devolverles\nla forma a tus POKéMON.",
  ["g3:081a5ec0"] = "Tus POKéMON están de nuevo\nen forma.\\pVen a vernos cuando la energía\nde tus POKéMON, los PS, estén\\lbajos de nivel.\\pCuando vayas a hacer un largo\nviaje, conviene que compres\\lPOCIONES en la TIENDA POKéMON.\\p¡Demuestra lo que vales!",
  ["g3:081a5f9b"] = "Tus POKéMON están de nuevo\nen forma.\\p¡Esperamos que te vaya bien!",
  ["g3:081a5fdf"] = "MAMÁ: ¡{PLAYER}!\n¡Hola, cielo!\\p¡Tienes cara de haber aprendido\nbastante!\\p¡Descansa un poco, criatura!",
  ["g3:081a6046"] = "MAMÁ: ¡Muy bien! ¡Tú y tus\nPOKéMON estáis en plena forma!\\pMe ha dicho el PROF. OAK que la\nenergía de los POKéMON se mide\\lpor PS.\\pSi tus POKéMON pierden los PS,\npuedes recuperarlos en cualquier\\lCENTRO POKéMON.\\pPara viajes largos, los ENTRENA-\nDORES más espabilados compran\\punas cuantas POCIONES en la\nTIENDA POKéMON.\\p¡Demuestra a todos quien eres,\ncariño! ¡Cuídate mucho, tesoro!",
  ["g3:081a6211"] = "¡Hola! ¿Puedo ayudarte en algo?",
  ["g3:081a6393"] = "Gracias por acceder al sistema\ndel REGALO MISTERIOSO.",
  ["g3:081a63c4"] = "¡El {STR_VAR_1} se ha marchado!",
  ["g3:081a641b"] = "¡Muy bien!\n¡Todos a bordo del SURCAMAR\\lVELOCE {STR_VAR_1}!",
  ["g3:081a6448"] = "¡Artic!",
  ["g3:081a644f"] = "Este movimiento sólo se puede\naprender una vez, ¿vale?",
  ["g3:081a6c51"] = "OAK: ¡Encantado de verte!\n¿Cómo va tu POKéDEX?\\p¡Déjame que le eche un vistazo!",
  ["g3:081a71aa"] = "A ver cómo llevas la POKéDEX\nNACIONAL:\\pPOKéMON avistados: {STR_VAR_1}\nPOKéMON atrapados: {STR_VAR_2}",
  ["g3:081a71ee"] = "¡Estoy deseando ver cómo completas\nla POKéDEX NACIONAL!",
  ["g3:081a722f"] = "¡Por fin!\\p¡Ya has completado la POKéDEX!\\p¡Magnífico!\n¡De verdad, no era tarea fácil!",
  ["g3:081a7291"] = "¡Guuuaaaaauuuuu!",
  ["g3:081a72ad"] = "¡Gracias, {PLAYER}!\nGracias de verdad.\\l¡Has hecho mi sueño realidad!",
  ["g3:081a72f2"] = "OAK: ¡Hola!\\p¿Qué tal llevas la POKéDEX?\\pA ver...\\pLa verdad es que sé cómo es, pero\nme gusta verla de todas formas.\\pA ver, a ver...",
  ["g3:081a929b"] = "CORTE",
  ["g3:081a92c1"] = ",",
  ["g3:081b146a"] = "DIARIO POKéMON\\pÚltima hora sobre BROCK, LÍDER\ndel GIMNASIO de PLATEADA.\\pSegún fuentes cercanas, BROCK\ncasi nunca se ríe, ¡pero una vez\\lque empieza, no para!",
  ["g3:081b14e8"] = "DIARIO POKéMON\\pÚltima hora sobre MISTY, LÍDER\ndel GIMNASIO de CELESTE.\\pSegún fuentes cercanas, MISTY\nadora a LORELEI, del ALTO MANDO.",
  ["g3:081b1558"] = "DIARIO POKéMON\\pÚltima hora sobre LT. SURGE, LÍDER\ndel GIMNASIO de CARMÍN.\\pSegún fuentes cercanas, LT. SURGE\nera piloto cuando vivía en Estados\\lUnidos.\\pY se valía de la electricidad\ngenerada por sus POKéMON\\lpara poner en marcha su avión.",
  ["g3:081b161b"] = "DIARIO POKéMON\\pÚltima hora sobre ERIKA, LÍDER\ndel GIMNASIO de AZULONA.\\pSegún fuentes cercanas, es fácil\nver a ERIKA echándose una siesta\\len el GIMNASIO de AZULONA.",
  ["g3:081b16a8"] = "DIARIO POKéMON\\pÚltima hora sobre KOGA, LÍDER\ndel GIMNASIO de FUCSIA.\\pSegún fuentes cercanas, KOGA\ntiene grandes conocimientos\\lde medicina.\\pIncluso elabora las medicinas\nque sus POKéMON necesitan.",
  ["g3:081b1753"] = "DIARIO POKéMON\\pÚltima hora sobre SABRINA, LÍDER\ndel GIMNASIO de AZAFRÁN.\\pSegún fuentes cercanas, SABRINA\nse comunica en combate con sus\\lPOKéMON, sin necesidad de hablar.",
  ["g3:081b17e9"] = "DIARIO POKéMON\\pÚltima hora sobre BLAINE, LÍDER\ndel GIMNASIO de CANELA.\\pSegún fuentes cercanas, BLAINE\nsólo se quita las gafas de sol\\lcuando contesta a preguntas.",
  ["g3:081b187f"] = "DIARIO POKéMON\\pÚltima hora sobre LORELEI,\nmiembro del ALTO MANDO.\\pSegún fuentes cercanas, LORELEI\nguarda un gran secreto.\\pLo que sí se conoce de ella es\nsu estilo de lucha elegante, único\\ly calculador.",
  ["g3:081b1913"] = "DIARIO POKéMON\\pÚltima hora sobre BRUNO,\nmiembro del ALTO MANDO.\\pSegún fuentes cercanas, BRUNO\nse unió al ALTO MANDO para luchar\\lcontra los mejores ENTRENADORES.",
  ["g3:081b19a8"] = "DIARIO POKéMON\\pÚltima hora sobre AGATHA,\nmiembro del ALTO MANDO.\\pSegún fuentes cercanas, AGATHA\ny el PROF. OAK estuvieron\\penfrentados durante su formación\ncomo ENTRENADORES.",
  ["g3:081b1a31"] = "DIARIO POKéMON\\pÚltima hora sobre LANCE,\nmiembro del ALTO MANDO.\\pSegún fuentes cercanas, quien fundó\nel clan de los maestros del tipo\\lDRAGÓN fue el abuelo de LANCE.",
  ["g3:081b1ab9"] = "DIARIO POKéMON\\pÚltima hora sobre el PROF.\nOAK, el investigador de POKéMON.\\pSegún dicen, el PROF. OAK vive\ncon su nieta DALIA y {RIVAL}.",
  ["g3:081b1b3d"] = "Un DIARIO POKéMON de hace\nunos años...\\p¡Especial sobre el CONCURSO\ndel DIARIO POKéMON!\\p¡La campeona de la edición de\nprimavera del CONCURSO POKéMON\\les DALIA OAK, de PUEBLO PALETA!",
  ["g3:081b1bd1"] = "DIARIO POKéMON\\pÚltima hora sobre el SR. FUJI,\nde la CASA POKéMON.\\pNota del editor: el tímido\nSR. FUJI no ha querido contestar\\la nuestras preguntas.\\pCon todo, hay que decir que es una\npersona muy querida en PUEBLO\\lLAVANDA.",
  ["g3:081b1c8b"] = "Mmm...\nQué curioso...",
  ["g3:081b1c9f"] = "¡Eh, mira, mira!",
  ["g3:081b1caf"] = "¡Mira lo que pone aquí, léelo!",
  ["g3:081b1cc1"] = "PISTAS ENTRENADOR\\p¡Pulsa START para abrir el MENÚ!",
  ["g3:081b1cec"] = "Es básico leer lo que pone en los\ncarteles, ¿no te parece?",
  ["g3:081b1d0b"] = "¡Mira, mira!\\pHe copiado lo que ponía en uno\nde los carteles de PISTAS\\lENTRENADOR.",
  ["g3:081b1d51"] = "PISTAS ENTRENADOR\\p¡Pulsa START para abrir el MENÚ!",
  ["g3:081b1e07"] = "No tienes suficiente dinero.",
  ["g3:081b1e24"] = "¿Cómo quieres que salga la foto?",
  ["g3:081b1e42"] = "A ver...\nUna sonrisita para la cámara...\\p¡Foto va!",
  ["g3:081b1e7d"] = "¡Ya se han revelado las fotos!\n¡Échale un vistazo a tu FICHA\\lde ENTRENADOR!",
  ["g3:081b1eb3"] = "Je, je... He coleccionado\nun montón de CROMOS. ¡Me gustaría\\lque los viera todo el mundo!",
  ["g3:081b1ef8"] = "¡Hola, me alegro de verte por\naquí! ¡Estupendo, estupendo!\\pMira, mira, ¿ves, ves?\nÉstos son mis CROMOS.\\l¡Mira cuántos tengo!\\pSé que quieres alguno.\nSe te nota.\\pTe daré un CROMO si me cuentas\nalgo sorprendente sobre ti.\\p¿Qué me dices?",
  ["g3:081b1fef"] = "Vamos a cotillear un poco. Si me\ncuentas algo, te doy un CROMO.",
  ["g3:081b2025"] = "¡Anda, mira a quién tenemos aquí!\n¡Lo más cotilla de la zona!\\p¿De qué vienes a hablarme?",
  ["g3:081b206e"] = "¡Guau, has entrado en el HALL\nde la FAMA!\\p¡Qué guay!\nToma, te lo has ganado.",
  ["g3:081b20cf"] = "¡Guau, has entrado en el HALL\nde la FAMA más de una vez!\\p¡Impresionante!\nToma, te lo has ganado.",
  ["g3:081b2133"] = "¡Guau, has entrado en el HALL\nde la FAMA muchas veces!\\l¡Es impresionante! \\p¡La LIGA POKéMON es tuya!\nToma, te lo has ganado.",
  ["g3:081b21c4"] = "¡Venga ya! ¿De verdad has entrado\ntantas veces en el HALL de la\\lFAMA?\\p¡Eres la repera!\nToma, te lo has ganado a pulso.",
  ["g3:081b2242"] = "Se ha puesto el CROMO del\nHALL de la FAMA en tu FICHA\\lde ENTRENADOR.",
  ["g3:081b227c"] = "Mmm...\\pVuelve cuando tengas un tema\nmás interesante, ¿vale?",
  ["g3:081b22b0"] = "No puede ser...\\p¡Eres una leyenda viva! ¡Ya no\nme quedan CROMOS que darte!",
  ["g3:081b2308"] = "Anda, ¿hay HUEVOS POKéMON?\n¡No lo sabía!\\p¡Qué bueno! ¡Es genial!\nToma, anda, te lo mereces.",
  ["g3:081b2372"] = "¿Has conseguido que se abrieran\ntodos esos HUEVOS?\\l¡Deben de encantarte!\\p¡Me parece alucinante, sí, sí!\nToma, anda, te lo mereces.",
  ["g3:081b23e0"] = "¡Guau, has conseguido que se\nabrieran un montón de HUEVOS!\\p¡Eres una máquina con los HUEVOS,\nsí, sí! Toma, anda, te lo mereces.",
  ["g3:081b2448"] = "¡Qué pasada!... ¿De verdad que\nhas conseguido que se abrieran\\ltantos HUEVOS?\\p¡Lo tuyo con los HUEVOS no es\nnormal! ¡Qué barbaridad!\\p¡Me dejas sin palabras! Toma,\nno tengo más remedio que dártelo.",
  ["g3:081b24ea"] = "Se ha puesto el CROMO de los\nHUEVOS en tu FICHA de ENTRENADOR.",
  ["g3:081b251b"] = "Mmm...\\pVuelve cuando tengas un tema\nmás interesante, ¿vale?",
  ["g3:081b254f"] = "No puede ser...\\p¡Eres una leyenda viva! ¡Ya no\nme quedan CROMOS que darte!",
  ["g3:081b25a7"] = "Oye, te ha ido bien luchando\ncon tus amigos, ¿eh?\\p¡Eres muy fuerte, sí, sí!\nToma, anda, te lo mereces.",
  ["g3:081b2609"] = "Oye, te ha ido muy bien luchando\ncon tus amigos, ¿eh?\\p¡Eres realmente fuerte, sí, sí!\nToma, anda, te lo mereces.",
  ["g3:081b267b"] = "Oye, te ha ido más que bien\nluchando con tus amigos, ¿eh?\\p¿Y no se han enfadado contigo?\nToma, anda, te lo mereces.",
  ["g3:081b26f6"] = "¡Alucinante!... ¡Has ganado\nmuchísimas veces!\\p¡No sé lo que me entra de pensar\nlo fuerte que eres!\\p¡Eres invencible! Toma, no tengo\nmás remedio que dártelo.",
  ["g3:081b27a6"] = "Se ha puesto el CROMO\nde la VICTORIA en tu FICHA\\lde ENTRENADOR.",
  ["g3:081b27db"] = "Mmm...\\pVuelve cuando tengas un tema\nmás interesante, ¿vale?",
  ["g3:081b280f"] = "No puede ser...\\p¡Eres una leyenda viva! ¡Ya no\nme quedan CROMOS que darte!",
  ["g3:081bc311"] = "Éste es el CLUB del CABLE\nPOKéMON.\\p¿Qué podemos hacer por ti?",
  ["g3:081bc409"] = "Para un COMBATE DOBLE, necesitas\ntener al menos dos POKéMON.",
  ["g3:081bc442"] = "Para intercambiar POKéMON,\nnecesitas tener al menos dos.",
  ["g3:081bc47c"] = "Los POKéMON que tengan BAYAS\n{STR_VAR_1} no se pueden intercambiar.",
  ["g3:081bc4ac"] = "Espera unos instantes.\nPulsa el Botón B para cancelar.",
  ["g3:081bc590"] = "Adelante.",
  ["g3:081bc59e"] = "Te voy a llevar a tu sala.",
  ["g3:081bc5c0"] = "Uno de los jugadores no está listo\npara realizar la conexión.\\pVuelve cuando todos estéis listos.",
  ["g3:081bc615"] = "Error de conexión... Comprueba el\ncable Game Link, apaga la consola\\l(OFF) y vuelve a encenderla (ON).",
  ["g3:081bc64e"] = "Los demás jugadores parecen haber\nseleccionado opciones diferentes.",
  ["g3:081bc68a"] = "Vuelve cuando quieras.",
  ["g3:081bc6a1"] = "El número de jugadores no es\ncorrecto.",
  ["g3:081bc6ca"] = "No se puede jugar al modo de\ncombate INDIVIDUAL con {STR_VAR_1}\\ljugadores.",
  ["g3:081bc700"] = "No se puede jugar al modo de\ncombate DOBLE con {STR_VAR_1} jugadores.",
  ["g3:081bc736"] = "Se necesitan cuatro jugadores para\njugar a este modo de combate.",
  ["g3:081bc76b"] = "Confirma el número de jugadores\ny vuelve a empezar.",
  ["g3:081bc8ad"] = "Puedes comenzar el combate.",
  ["g3:081bc8da"] = "Puedes comenzar el intercambio.",
  ["g3:081bc918"] = "Se van a sobrescribir los datos\nde la FICHA de ENTRENADOR.",
  ["g3:081bc943"] = "¡Vuelve cuando quieras!",
  ["g3:081bc95c"] = "Lo siento mucho.\\pAún no podemos realizar\nintercambios con ENTRENADORES\\lde otra región...",
  ["g3:081bc9c0"] = "El otro ENTRENADOR no está listo.",
  ["g3:081bc9e0"] = "Tienes al menos un POKéMON\nque no se puede enviar.",
  ["g3:081bcb81"] = "Para usar el MACHACABAYAS,\nnecesitas al menos una BAYA.",
  ["g3:081bcbc3"] = "Para entrar en la SALA UNIÓN,\ndebes tener al menos dos POKéMON.",
  ["g3:081bcc00"] = "Los POKéMON que tienen BAYAS\n{STR_VAR_1} no pueden entrar en la\\lSALA UNIÓN.",
  ["g3:081bcc3a"] = "Ésta es la SALA UNIÓN del CLUB\nINALÁMBRICO POKéMON.\\pVaya, tu Conector inalámbrico\nde GBA no está bien conectado...\\pVuelve más tarde.",
  ["g3:081bccca"] = "¡Parece que {STR_VAR_1} está jugando\nahora mismo! ¡Conéctate!",
  ["g3:081bccff"] = "Si quieres te explico las reglas.\\p¿De qué juego te hablo?",
  ["g3:081bcd4d"] = "“SALTO POKéMON”\\pConsigue que a tus POKéMON no les\natrape la LIANA usando el Botón A.\\pSólo pueden participar los POKéMON\nque midan unos 70 cm o menos.\\pA los POKéMON que naden despacio,\ncaven o vuelen no se les dará muy\\lbien lo de saltar.\\pPor ello, estos POKéMON no deben\nparticipar.\\pSi todos saltan a la vez,\npueden ocurrir cosas estupendas.",
  ["g3:081bce73"] = "“DODRIO A POR BAYAS”\\pDile a DODRIO que pille las BAYAS\nque pueda con los tres picos que\\ltiene.\\pPulsa derecha, izquierda o arriba\nen el {PLUS} Panel de Control para\\lque se mueva.\\pPara poder jugar a este juego,\nhay que tener un DODRIO.",
  ["g3:081bcf2e"] = "Si quieres jugar a un juego,\ndíselo a mi compañero.",
  ["g3:081bcf69"] = "¡Hola! ¡Gracias al sistema de\ncomunicación inalámbrica,\\lpodrás jugar a juegos!\\p¿Puedes esperar un segundo?",
  ["g3:081bcfd1"] = "¡Bueno, hasta otra!",
  ["g3:081bcfe8"] = "El Conector inalámbrico de GBA\nno está conectado.\\p¡Vuelve cuando lo tengas!",
  ["g3:081bd02d"] = "¿A qué juego quieres jugar?",
  ["g3:081bd059"] = "¿Con qué POKéMON quieres\nparticipar?",
  ["g3:081bd080"] = "¡Muy bien! ¡Pues adelante!\n¡A por todas!",
  ["g3:081bd0cf"] = "Creo que no tienes POKéMON\naptos para participar...\\p¿Quieres que te diga cuáles son\nlos que pueden participar?",
  ["g3:081bd14b"] = "En “SALTO POKéMON” pueden\nparticipar los POKéMON que midan\\lunos 70 cm o menos.\\pTampoco pueden participar los\nPOKéMON que no pueden saltar.\\pEs decir, los POKéMON que sólo\nnadan, cavan o vuelan.\\pBueno, pues ya lo sabes.",
  ["g3:081bd213"] = "“DODRIO A POR BAYAS”...\nYo creo que el nombre lo explica\\ltodo, ¿no?\\pPara jugar a este juego debes\ntener al menos un DODRIO.",
  ["g3:081bd28d"] = "Ésta es la ZONA DIRECTA del CLUB\nINALÁMBRICO POKéMON.\\pAquí puedes comunicarte\ndirectamente con tus amigos.\\p¿En qué sala quieres entrar?",
  ["g3:081bd317"] = "¿Quieres cambiar POKéMON?",
  ["g3:081bd338"] = "¿Qué modo de combate quieres?",
  ["g3:081bd362"] = "¿Quieres usar el MACHACABAYAS?",
  ["g3:081bd390"] = "Hay tres modos de combate.\\pEl COMBATE INDIVIDUAL es para dos\nENTRENADORES con uno o más\\lPOKéMON cada uno.\\pCada ENTRENADOR puede usar un\nPOKéMON cada vez.\\pEl COMBATE DOBLE es para dos\nENTRENADORES con dos o más\\lPOKéMON cada uno.\\pCada ENTRENADOR usará dos\nPOKéMON cada vez.\\pEl COMBATE MULTIJUGADOR es para\ncuatro ENTRENADORES con uno o más\\lPOKéMON cada uno.\\pCada ENTRENADOR puede usar un\nPOKéMON cada vez.",
  ["g3:081bd51b"] = "Un jugador debe ser LÍDER.\\pY el otro, “UNIRSE\nal GRUPO”.",
  ["g3:081bd582"] = "Un jugador debe ser LÍDER\ndel GRUPO.\\pY los otros, “UNIRSE\nal GRUPO”.",
  ["g3:081bd5f1"] = "Un jugador debe ser LÍDER\ndel GRUPO.\\pY los otros, “UNIRSE\nal GRUPO”.",
  ["g3:081bd65b"] = "Ésta es la SALA UNIÓN del CLUB\nINALÁMBRICO POKéMON.\\pAquí puedes comunicarte\ndirectamente con ENTRENADORES\\la los que puede que no conozcas.\\p¿Quieres entrar en la SALA?",
  ["g3:081bd706"] = "Los ENTRENADORES de la SALA UNIÓN\nserán los jugadores que tengas\\lcerca y hayan entrado en la SALA.\\p¡Aquí se pueden hacer muchas\ncosas, empezando por saludarse\\ly celebrar el encuentro!\\pPuedes registrar dos POKéMON\nde nivel no superior a 30 para\\lentablar combates de 1 contra 1.\\pTambién puedes participar en chats;\npodéis ser de 2 a 5 jugadores.\\pY, por supuesto, puedes registrar\nPOKéMON para realizar intercambios.\\p¿Quieres entrar en la SALA?",
  ["g3:081bd86a"] = "Espero que disfrutes en la SALA\nUNIÓN.",
  ["g3:081bd898"] = "¡Hola!\nMe llamo TEALA.\\pEs la primera vez que vienes, ¿no?\\pTe voy a explicar cómo funciona\nel sistema de comunicación\\linalámbrica.\\pPrimero, te enseñaré esta planta\nde nuestro CENTRO POKéMON.\\pPor aquí, por favor.",
  ["g3:081bd966"] = "En el primer piso de los CENTROS\nPOKéMON hay dos salas.\\pPrimero te hablaré de la sala de\nla izquierda: la SALA UNIÓN.\\pEn ella puedes conectarte con los\nENTRENADORES que también\\phayan entrado en la SALA UNIÓN\ny estén cerca de ti.\\pCon ellos, podrás chatear, luchar\ny realizar intercambios.\\pAhora, la sala de la derecha:\nla ZONA DIRECTA.\\pEn ella puedes realizar\nintercambios o enfrentarte a tus\\lamigos en combates POKéMON.\\pSi el Conector inalámbrico de GBA\nno estuviera conectado, puedes\\pconectarte a tus amigos con un\ncable Game Link de Game Boy\\lAdvance.\\pPara ello hay que ir a la ZONA\nDIRECTA.\\pEspero que disfrutes del sistema\nde comunicación inalámbrica.",
  ["g3:081bdbf8"] = "Te voy a explicar cómo funciona\nel CLUB INALÁMBRICO POKéMON.\\pÉste es el piso de arriba y tiene\ndos salas.\\pPrimero te hablaré de la sala de\nla izquierda: la SALA UNIÓN.\\pEn ella puedes conectarte con los\nENTRENADORES que también\\phayan entrado en la SALA UNIÓN\ny estén cerca de ti.\\pCon ellos, podrás chatear, luchar\ny realizar intercambios.\\pAhora, la sala de la derecha:\nla ZONA DIRECTA.\\pEn ella puedes realizar\nintercambios o enfrentarte a tus\\lamigos en combates POKéMON.\\pSi no encontraras a tus amigos\nen la SALA UNIÓN ni en la ZONA\\lDIRECTA, acercad las consolas.\\pSi el Conector inalámbrico de GBA\nno estuviera conectado, puedes\\pconectarte a tus amigos con un\ncable Game Link de Game Boy\\lAdvance.\\pPara ello hay que ir a la ZONA\nDIRECTA.\\pEspero que disfrutes del sistema\nde comunicación inalámbrica.",
  ["g3:081bdedf"] = "Espero que disfrutes del sistema\nde comunicación inalámbrica.",
  ["g3:081bdf94"] = "Parece que puedes CORTAR\neste árbol.\\p¿Usas CORTE?",
  ["g3:081bdfd7"] = "{STR_VAR_1} usó {STR_VAR_2}.",
  ["g3:081bdfe3"] = "Parece que puedes CORTAR\neste árbol.",
  ["g3:081be09d"] = "Parece que se puede romper esta\nroca. ¿Usas GOLPE ROCA?",
  ["g3:081be0e2"] = "Es una roca muy dura, pero un\nPOKéMON podría hacerla añicos.",
  ["g3:081be19a"] = "Es una roca enorme, pero un\nPOKéMON podría moverla.\\p¿Usas FUERZA?",
  ["g3:081be1fa"] = "{STR_VAR_1} usó FUERZA.\\pLa FUERZA de {STR_VAR_1} logró\ndesplazar la roca a un lado.",
  ["g3:081be244"] = "Es una roca enorme, pero un\nPOKéMON podría apartarla.",
  ["g3:081be284"] = "Usar FUERZA ha permitido desplazar\nla roca a un lado.",
  ["g3:081bef88"] = "Hola, me alegro de verte.\\pEh, he dicho hola...\nQué borde... ya podrías\\lcontestar.\\pVenga, cuéntame algo, anda.\\p¡Dime al menos cuál es tu perfil!",
  ["g3:081bf017"] = "Cuéntame alguna cosa sobre ti.\nDime cuál es tu perfil.",
  ["g3:081bf053"] = "El perfil puede hacerse con\npalabras o frases.\\pHay muchas palabras y frases\npara elegir, y están divididas\\lpor grupos.\\pSelecciona primero un grupo\ny después el elemento que quieras.\\pEs mucho más fácil de lo que\nparece. Inténtalo, anda.",
  ["g3:081bf166"] = "¿Cuál es tu perfil?",
  ["g3:081bf17b"] = "Venga, anda, enséñame tu perfil...",
  ["g3:081bf1b2"] = "Ah, ¿y no lo cambias?\n¡Pues hay que ver cómo eres!",
  ["g3:081bf1e8"] = "¡Hola otra vez!",
  ["g3:081bf1fb"] = "¿Quieres cambiar tu perfil?",
  ["g3:081bf222"] = "Me gustaría saber cuál tienes\nahora.",
  ["g3:081bf252"] = "Vale, pues déjalo como está.\\pA mí también me gusta.",
  ["g3:081bf28e"] = "Mmmm...\\pLa verdad es que te pega, da idea\nde cómo eres.\\p¡Ahora nos conocemos mejor!\n¡Vamos a llevarnos bien siempre!",
  ["g3:081bf30d"] = "Eso ya lo he oído antes...\\pMi primo, que vive lejos de aquí,\nlo decía con frecuencia, creo.",
  ["g3:081bf36a"] = "¡A ver si la próxima vez\nme cuentas más sobre ti!",
  ["g3:081bf555"] = "Soy el ENCARGADO de la GUARDERÍA.\\pAyudo a los ENTRENADORES a cuidar\nde sus preciosos POKéMON.\\pSi quieres que me encargue del\ntuyo, ve a hablar con mi mujer.",
  ["g3:081bf5e3"] = "¡Ah, eres tú!\\p¡Hemos cuidado de tu POKéMON\ny vaya sorpresa que nos hemos\\lllevado!\\p¡Tu POKéMON ha tenido un HUEVO!\\pNo sabemos cómo ha sucedido,\npero es de tu POKéMON, seguro.\\p¿Lo quieres?",
  ["g3:081bf69a"] = "¡Ah, eres tú! Me alegro de verte.\nTu {STR_VAR_1} está estupendamente.",
  ["g3:081bf6cf"] = "Muy bien, entonces me seguiré\nocupando de él. ¡Gracias!",
  ["g3:081bf6f0"] = "No tienes sitio para él...\nVuelve cuando lo tengas.",
  ["g3:081bf72a"] = "¡El ENCARGADO de la GUARDERÍA\nle dio el HUEVO a {PLAYER}!",
  ["g3:081bf755"] = "Cuídalo bien.",
  ["g3:081bf789"] = "¡Ah, eres tú! Tu {STR_VAR_1} y el\n{STR_VAR_2} están muy bien.",
  ["g3:081bf7b6"] = "Yo me lo quedaría, pero\ntú lo quieres, ¿verdad?",
  ["g3:081bf7e4"] = "Soy la ENCARGADA de la GUARDERÍA.\\pPodemos ocuparnos de tus POKéMON.\\p¿Quieres que cuidemos de alguno?",
  ["g3:081bf839"] = "¿Qué POKéMON quieres que\ncuidemos?",
  ["g3:081bf860"] = "Estupendo, nos ocuparemos de tu\n{STR_VAR_1} cuanto sea necesario.\\pVuelve cuando quieras.",
  ["g3:081bf89f"] = "Podemos cuidar a dos de tus\nPOKéMON.\\p¿Quieres que cuidemos de otro más?",
  ["g3:081bf8f6"] = "Mi marido te estaba buscando.",
  ["g3:081bf916"] = "Muy bien.\nVuelve cuando quieras.",
  ["g3:081bf932"] = "No tienes bastante dinero.",
  ["g3:081bf94f"] = "¿Quieres llevarte el otro también?",
  ["g3:081bf976"] = "Muy bien.\nVuelve cuando quieras.",
  ["g3:081bf988"] = "¡Ah, eres tú! Me alegro de verte.\nTodo ha ido de maravilla...",
  ["g3:081bf9cc"] = "Tu {STR_VAR_1} ha crecido\nestos niveles: ¡{STR_VAR_2}!",
  ["g3:081bf9ef"] = "Tu equipo POKéMON está lleno.\nHaz un hueco y vuelve a verme.",
  ["g3:081bfa67"] = "¡Perfecto!\nAquí tienes a tu POKéMON.",
  ["g3:081bfa85"] = "{PLAYER} recogió a {STR_VAR_1} de\nla GUARDERÍA POKéMON.",
  ["g3:081bfaad"] = "Anda, pero si sólo tienes un\nPOKéMON...\\pVuelve cuando tengas alguno más.",
  ["g3:081bfae8"] = "¿Quieres recoger un POKéMON?",
  ["g3:081bfb09"] = "Si me dejas ese POKéMON, no\npodrás entablar combates.\\pVuelve en otra ocasión.",
  ["g3:081bfeac"] = "Lo siento, pero todas las CAJAS\nde tu PC están llenas.",
  ["g3:081c147a"] = "¡Nos vimos en el BOSQUE VERDE!",
  ["g3:081c149d"] = "¡Hola!\n¡Me gustan los pantalones cortos!\\p¡Son muy cómodos!",
  ["g3:081c14f3"] = "Estabas mirándome ¿verdad?",
  ["g3:081c1521"] = "¿Entrenas POKéMON?\n¡Pues luchemos!",
  ["g3:081c155d"] = "¡Esa mirada tuya fue de lo más\nmisteriosa!",
  ["g3:081c1588"] = "¡Oye!\n¡No llevas pantalón corto!",
  ["g3:081c15c5"] = "Lucharé contigo junto a los\nPOKéMON que yo mismo he criado.",
  ["g3:081c15f9"] = "¡Eh!\n¡Me has empujado!",
  ["g3:081c160f"] = "A mí me encanta buscar POKéMON\nhongo en el MT. MOON.",
  ["g3:081c163c"] = "¡Tu eres la pesadilla que nos\ndio la paliza!",
  ["g3:081c166d"] = "Perdona, ¿no ves que es una\nconversación privada?\\pPues ¿qué haces con la antena\npuesta?",
  ["g3:081c16e2"] = "Estoy intentando encontrar un buen\nejemplar, que no sea un POKéMON\\lBICHO, pero...",
  ["g3:081c1723"] = "¿Qué? ¿Qué quieres, luchar\nconmigo de nuevo?",
  ["g3:081c1746"] = "¿Yo?\nPues vale. ¡Vamos!",
  ["g3:081c176b"] = "Eh, ¡qué de tiempo!\n¿Eres más fuerte?",
  ["g3:081c1793"] = "Se te dan bien los POKéMON, pero\n¿qué tal en química?",
  ["g3:081c17cd"] = "¡Muy bien!\n¡Luchemos otra vez!",
  ["g3:081c17f1"] = "¡Necesitas una buena estrategia!\\p¿Te queda claro?",
  ["g3:081c1834"] = "Tengo muchos NIDORAN.\nNo quiero que evolucionen, pero...",
  ["g3:081c1873"] = "¡Me gusta el colegio y los\nPOKéMON!",
  ["g3:081c18aa"] = "¡MEOWTH y PERSIAN son ideales,\nideales totales, meow, meow, meow!",
  ["g3:081c18dc"] = "Debemos de dar una imagen algo\ntonta, pero ¡lo importante es que\\lyo quiero luchar!",
  ["g3:081c191f"] = "¡Soy un jugador errante!\n¡Y voy a ganar!",
  ["g3:081c1955"] = "¿Qué POKéMON es mono, redondo\ny blando?\\pLo sabes, ¿no?",
  ["g3:081c199c"] = "¡Mi bici sigue yendo como\nuna moto!",
  ["g3:081c19bc"] = "Bueno, esta vez no me voy\na andar con tonterías.",
  ["g3:081c19e5"] = "TITA: ¡Ahora somos más fuertes!",
  ["g3:081c1a0d"] = "LIN: ¡Ya somos mucho más fuertes!",
  ["g3:081c1a2e"] = "¿Vamos a luchar de nuevo?\n¡Pues esta vez, olvídate!",
  ["g3:081c1a5d"] = "Tú eras quien tenía esos POKéMON\ntan bonitos...",
  ["g3:081c1a9b"] = "Quiero tomar el TÚNEL ROCA\npara ir a LAVANDA.\\p¡Pero cada dos por tres se cruza\nalguien en mi camino!...",
  ["g3:081c1afb"] = "¡No te andes con contemplaciones!\n¡Hay que ir a por todas!",
  ["g3:081c1b37"] = "¡Qué bien! ¡Me estaba aburriendo\notra vez!",
  ["g3:081c1b5e"] = "¡Jaja! ¡A ver lo fuerte que estás!",
  ["g3:081c1b83"] = "Cada día me levanto temprano para\nentrenar a mis POKéMON capullo.",
  ["g3:081c1bbe"] = "¡Esta vez gano yo!",
  ["g3:081c1bdc"] = "¡Adelante de nuevo, mis geniales\nPOKéMON BICHO!",
  ["g3:081c1bfa"] = "Aquí estás otra vez...\n¿Eres como los POKéMANÍACOS?\\l¿Quieres ver mi colección?",
  ["g3:081c1c4f"] = "¡A-a-a-achís!\n¡No puedo dejar de estornudar!",
  ["g3:081c1c76"] = "¡Hola!\n¿Te llegué a enseñar mis POKéMON?",
  ["g3:081c1c9a"] = "He vuelto a ir al GIMNASIO\nPOKéMON.\\pPero he perdido, como siempre...",
  ["g3:081c1cd3"] = "¡Me encanta el aire de montaña!\n¡Es tan bueno! ¡Me encanta!",
  ["g3:081c1d14"] = "Me está empezando a dar vueltas la\ncabeza. Llevo mucho escalando...",
  ["g3:081c1d50"] = "¡Gana, pierde o empata!\n¡Pero lucha de nuevo!",
  ["g3:081c1d79"] = "¡Competir es lo más!\n¡Yo no me canso de competir!",
  ["g3:081c1db5"] = "¿Luchamos otra vez?\n¡Vamos allá, pero no hagas\\ltrampas!",
  ["g3:081c1de1"] = "¡Eh, tú!\\p¡Cuidado!\n¡Estoy colocando unos cables!",
  ["g3:081c1e1f"] = "¡Soy un nuevo ENTRENADOR!\n¡Pero creo que no tengo problema\\lpara ganar!",
  ["g3:081c1e57"] = "¡Ja, ja, ja!\n¡No he perdido nunca!\\p¡Y si he perdido alguna vez,\nno me acuerdo!",
  ["g3:081c1e9f"] = "Nunca he ganado...\\p¿Será mi destino?",
  ["g3:081c1ee2"] = "¡Soy el mejor de mi clase!\n¡Me entreno día y noche!",
  ["g3:081c1f1d"] = "¡Cuidado con esos cables!",
  ["g3:081c1f40"] = "¡Mis POKéMON ya deberían estar\nlistos! ¡Esta vez hay que ganar!",
  ["g3:081c1f9d"] = "¡Bien!\n¡Ha picado algo!\\l¡Esta vez seguro que es bueno!",
  ["g3:081c1fd8"] = "¡Aquí estás otra vez!\n¡Pescar requiere tiempo!",
  ["g3:081c2008"] = "Sigo sin PIEDRA LUNAR...\n¿Tienes tú una?",
  ["g3:081c203b"] = "¡Soy un experto en electricidad!\\pPero de los POKéMON de agua\nsé poca cosa...",
  ["g3:081c209c"] = "¡El PESCADOR LOCO contra alguien\nque no tiene idea sobre POKéMON!\\l¡Lucha, venga!",
  ["g3:081c20d4"] = "A mí me encanta pescar, pero no\nes nada fácil que piquen, ¿sabes?",
  ["g3:081c2134"] = "¿No sabes cómo pescar?\\p¡Te lo explicaré cuando acabe\ncontigo!",
  ["g3:081c216b"] = "ARE: Voy a ganar y a pedirle a\nAGA que se case conmigo.",
  ["g3:081c219b"] = "AGA: Oye, ARE, estoy aburrida\nde esperar...\\pSi ganamos, ¡me caso contigo!",
  ["g3:081c21ee"] = "¡Mis pájaros POKéMON se acuerdan\nde ti!",
  ["g3:081c220c"] = "Quiero ser la mejor ENTRENADORA\nsiendo todavía pequeña.",
  ["g3:081c223c"] = "¡Guau!\n¡Qué chulas son tus MEDALLAS!",
  ["g3:081c225b"] = "Mis simpáticos POKéMON quieren\nvolver a verte.",
  ["g3:081c2299"] = "Me he gastado mis ahorros\ncomprando más CARBURANTE.",
  ["g3:081c22ca"] = "¡Esta vez no pienso perder!\n¡El viento sopla en mi dirección!",
  ["g3:081c2306"] = "Has vuelto...\\pPor supuesto que lucharé\notra vez contigo.",
  ["g3:081c2340"] = "¿No te acuerdas de que luchamos\nen otra ocasión?",
  ["g3:081c236b"] = "¿Qué miras?",
  ["g3:081c2383"] = "¡Me encantan los pájaros POKéMON!",
  ["g3:081c23c1"] = "He usado mis MT para enseñarles\nbuenos movimientos a mis POKéMON.",
  ["g3:081c23ef"] = "Mis pájaros POKéMON deberían\nluchar bien esta vez.",
  ["g3:081c2425"] = "¿Usas MT con tus POKéMON?\nTenerlas en la MOCHILA sin más\\lno sirve para nada.",
  ["g3:081c2461"] = "¿Has enseñado a VOLAR a tus\npájaros POKéMON?\\pDeberías hacerlo y disfrutar de\nla maravillosa vista.",
  ["g3:081c24cb"] = "¿Llegaste a oír hablar de los\nmisteriosos seres alados?",
  ["g3:081c2505"] = "¡No me apetece luchar,\npero lo haré!",
  ["g3:081c2531"] = "¡Eh, me acuerdo de ti!\\p¡Venga, venga!\n¡Vamos, vamos! ¡Adelante!",
  ["g3:081c2572"] = "Aquí estás otra vez, ¿eh?\n¡Bueno, así pasaré el rato!",
  ["g3:081c259e"] = "¡Nos gusta pedalear por aquí\nporque hay mucho espacio!",
  ["g3:081c25d6"] = "¿Quieres pelear con tus POKéMON?\n¡Pues vale, vamos allá!",
  ["g3:081c25fb"] = "LENA: TEA, a ver si ganamos.",
  ["g3:081c261b"] = "TEA: LENA, ¡vamos allá!\n¡Tenemos que ganar!",
  ["g3:081c2650"] = "¡Déjame probar los POKéMON\nque me han enviado!",
  ["g3:081c268d"] = "¡Creo que puedo contigo!\n¡Voy a intentar vencerte!",
  ["g3:081c26d3"] = "Cuando silbo, acuden varios\npájaros POKéMON.\\p¡Son monísimos!",
  ["g3:081c2717"] = "Mis pájaros están temblando.\n¡Ya te conocen!",
  ["g3:081c2753"] = "¡Oh!\n¡Mira qué encanto!\\l¡Anda, yo a ti te conozco!",
  ["g3:081c279d"] = "¡Cuido POKéMON porque sigo\nviviendo sola!",
  ["g3:081c27e7"] = "¡Oye! ¡Ven aquí!\n¡Mira esto!",
  ["g3:081c2814"] = "¡Mira, colega, si pierdes contra\nmí, todo tu dinero será mío!",
  ["g3:081c2846"] = "¿Qué mola?\n¡Cambiar POKéMON, claro!",
  ["g3:081c287d"] = "¿Quieres jugar con mis POKéMON\notra vez?",
  ["g3:081c28a1"] = "TINA: ¡Volvemos a vernos!\\p¿Luchamos para que aprenda\nmi hermano?",
  ["g3:081c28ec"] = "TIN: Mi hermana es la más fuerte.",
  ["g3:081c2913"] = "¿Qué quieres?",
  ["g3:081c2925"] = "¡Bonita BICI!\n¡Dámela ahora mismo!",
  ["g3:081c2944"] = "¡Baja de ahí y lucha, enclenque!\n¡Te vas a enterar!",
  ["g3:081c297b"] = "¡Oye! ¡Me has golpeado!\n¡Ahora tendrás que luchar conmigo!",
  ["g3:081c29b0"] = "¡Tengo hambre y sigo sin estar\nde humor!",
  ["g3:081c29eb"] = "¡Eh, vamos a echar otro rato!",
  ["g3:081c2a19"] = "JOEL: ¿Vienes para comprobar que\nnuestro amor no conoce límites?",
  ["g3:081c2a53"] = "LIZ: ¡A veces, pienso en todo\nlo que nos queremos y se me pone\\lla carne de gallina!",
  ["g3:081c2a88"] = "¡Ya te dije que no compensaba\nluchar con niños!",
  ["g3:081c2ac4"] = "¿Y tú qué quieres?",
  ["g3:081c2af0"] = "¿Qué vas, de paseo?",
  ["g3:081c2b06"] = "¡Somos los MOTORISTAS!\n¡Las estrellas de la autopista!",
  ["g3:081c2b2c"] = "Mis VOLTORB van a darte\nun calambrazo.",
  ["g3:081c2b5e"] = "¡Mi POKéMON no evoluciona!\nNo acabo de entender por qué.",
  ["g3:081c2b9c"] = "¡Necesito un poco de ejercicio\ny bajar peso!",
  ["g3:081c2bda"] = "¡Sé rebelde!",
  ["g3:081c2be6"] = "¡Tienes una BICI muy guay!\n¿Cómo se conduce?",
  ["g3:081c2c10"] = "¡Lárgate!\n¡Estoy agotado!",
  ["g3:081c2c2b"] = "Compruebo siempre las zonas de\nhierba en busca de nuevos POKéMON.\\pPero no siempre encuentro...",
  ["g3:081c2c7b"] = "¡Cucu, cucu! ¿Ha mejorado\nel reclamo de mi pájaro?",
  ["g3:081c2ca8"] = "¡Es mi césped!\n¡Fuera de aquí!\\p¡No quiero volver a verte por\naquí!",
  ["g3:081c2cee"] = "Estaba a punto de darme un baño.",
  ["g3:081c2d19"] = "¡Alto!\n¡Oye, que te va a dar algo!",
  ["g3:081c2d4b"] = "¡Me gusta nadar!\nSeguro que a ti también.",
  ["g3:081c2d7d"] = "¿Qué hay más allá del horizonte?\n¿Lo sabes?",
  ["g3:081c2da7"] = "¡He buceado en busca de POKéMON,\npero sigo sin ver nada!",
  ["g3:081c2de9"] = "¡Miro al mar para olvidar!\\pQuiero olvidarme de cuando perdí\ncontigo.",
  ["g3:081c2e4a"] = "¡Me encanta el POKéMON con\nel que estás haciendo SURF.\\p¿Me lo darás si gano?",
  ["g3:081c2e9d"] = "¡Nadar es genial! ¡Pero no me\ngusta quemarme al sol!",
  ["g3:081c2ec0"] = "¡Estas aguas son traicioneras!\n¡No deberías volver por aquí!",
  ["g3:081c2efc"] = "He venido nadando hasta aquí,\npero ya me he cansado.\\p¿De verdad tenemos que luchar\notra vez?",
  ["g3:081c2f41"] = "CATI: Ya sabes que mi hermano\nacaba de hacerse ENTRENADOR.\\pVamos a luchar para que mejore\nsu técnica, ¿vale?",
  ["g3:081c2fae"] = "TEC: Mi hermana mayor me ha\nenseñado mucho sobre POKéMON.\\p¿Soy mejor ahora?",
  ["g3:081c2ff3"] = "El agua es poco profunda aquí.\nHay mucha gente nadando.",
  ["g3:081c302e"] = "¿Te da envidia que esté de\nvacaciones en las ISLAS ESPUMA?",
  ["g3:081c305f"] = "¡Me gusta flotar en el agua\nrodeada de peces!",
  ["g3:081c3095"] = "¿Tú también estabas de vacaciones?",
  ["g3:081c30b0"] = "¡Mira que cuerpazo tengo!\\p¡Estoy mejor que antes!",
  ["g3:081c30ed"] = "¿Por qué te has subido a un\nPOKéMON? ¿Aún no sabes nadar?",
  ["g3:081c312c"] = "¡He venido sobre uno de mis\npájaros POKéMON!",
  ["g3:081c3149"] = "¡Mi novio me dio unas perlas\nmuy grandes!\\p¡Y ahora están más grandes aún!",
  ["g3:081c3185"] = "Vine nadando desde ISLA\nCANELA. Fue agotador.",
  ["g3:081c31c4"] = "En ISLA CANELA, al oeste, hay\nun LABORATORIO POKéMON.\\pMi papi trabaja allí.",
  ["g3:081c3208"] = "¿Quieres saber si los peces pican?",
  ["g3:081c3231"] = "¡Tengo una gran red!\n¿Quieres probarla otra vez?",
  ["g3:081c3264"] = "¡El mar limpia mi cuerpo y mi\nalma!",
  ["g3:081c3298"] = "¡He conseguido a mi POKéMON\nen el mar, y aquí lo entreno!",
  ["g3:081c32d3"] = "¡Ahora estoy en otro encuentro\nde triatlón!",
  ["g3:081c32fd"] = "¡Ah!\n¡Siente el sol y el viento!",
  ["g3:081c331d"] = "¡Eh!\n¡Siempre asustas a los peces!",
  ["g3:081c3356"] = "¡Quédate conmigo hasta que lo\nconsiga!",
  ["g3:081c3378"] = "ÍA: ¿Cómo, que quieres luchar otra\nvez? IGOR, ¿cómo lo ves?",
  ["g3:081c33ae"] = "IGOR: Mi hermana es un pelín vaga,\n¡pero si hay que luchar, hay que\\lluchar!",
  ["g3:081c33e7"] = "¡No pienso perder!",
  ["g3:081c3404"] = "¡Mi padre me llevó a una gran\nfiesta en el S.S. ANNE, en\\lCIUDAD CARMÍN!",
  ["g3:081c3445"] = "Soy un buen chico.\n¡Y tengo novia!\\p¡Verás cómo se queda cuando\nme vea luchar esta vez!",
  ["g3:081c349c"] = "¡Hola!\n¡Mi chico es genial!\\l¡Y hoy me encuentro en forma!",
  ["g3:081c34d4"] = "¡Sabía que tendría que luchar\ncontigo otra vez!",
  ["g3:081c350a"] = "Mi amigo tiene unos POKéMON\nmuy monos. ¡Qué envidia!",
  ["g3:081c353b"] = "¡Acabo de bajar del MT. MOON,\npero estoy listo!",
  ["g3:081c357e"] = "¡Hay un POKéMANÍACO viviendo\nen el cabo!\\p¿Has visto la colección que tiene?",
  ["g3:081c35bc"] = "¿Vas a ver a BILL otra vez?\n¡Pues luchemos primero!",
  ["g3:081c35ee"] = "¡Vi tu hazaña desde la hierba!",
  ["g3:081c360e"] = "¡Muy bien, voy a acabar contigo!",
  ["g3:081c3624"] = "Siempre estás de aquí para allá...\n¿No te cansas?",
  ["g3:081c3657"] = "Se ve que te encanta venir\nal PUENTE PEPITA.",
  ["g3:081c3685"] = "Aunque perdí cuando luchamos,\nestuvo guay, ¿verdad?",
  ["g3:081c36da"] = "Éste es el PUENTE PEPITA.\\pYa nos has machacado a todos,\nasí que ya te puedes marchar...\\pAunque... no me importaría\nvolver a enfrentarme a ti.",
  ["g3:081c3773"] = "Se me pasa el tiempo volando\ncuando estoy disfrutando del agua,\\ldel vaivén de las olas...",
  ["g3:081c37b5"] = "Hace un tiempo espléndido,\nno lo estropees.",
  ["g3:081c37e7"] = "Está empezando a dolerme la piel\npor las quemaduras.",
  ["g3:081c3807"] = "El MT. ASCUAS hace una sombra\ngigante.",
  ["g3:081c3835"] = "Tengo la sensación de que esta vez\nte voy a ganar.",
  ["g3:081c386a"] = "¡Eh, eh, un momento!\n¡Sé que he pescado algo grande!",
  ["g3:081c389f"] = "¿Me ayudas a entrenarme otra vez?",
  ["g3:081c38ca"] = "No me pierdo ni un día de\nentrenamiento.",
  ["g3:081c38fa"] = "Cada mañana, antes de desayunar,\nrodeo a nado la isla.\\l¡Lo hago hasta tres veces!",
  ["g3:081c3943"] = "¡Para luchar hay que llevar ropa\nadecuada! ¡Vaya pintas tienes!",
  ["g3:081c3987"] = "Cuando se está al aire libre,\ntodo sabe mucho mejor.",
  ["g3:081c39c6"] = "He vuelto a comer demasiado,\n¿luchamos para hacer algo\\lde ejercicio?",
  ["g3:081c3a05"] = "PÍA: ¡Mi hermano mayor y yo\nhacemos un equipo increíble!\\p¡Esta vez no perderemos!",
  ["g3:081c3a55"] = "FER: ¡Junto a PÍA no tengo miedo\nde nada!\\p¡Esta vez te vas a enterar!",
  ["g3:081c3aa7"] = "¿Quieres que luchemos de nuevo?",
  ["g3:081c3abf"] = "¿De dónde vienes y adónde vas?",
  ["g3:081c3af2"] = "Estoy deseando nadar sin flotador.",
  ["g3:081c3b1d"] = "¡POKéMON, POKéMON!\n¡A mí me gustan los POKéMON!",
  ["g3:081c3b30"] = "¡No, no, te dije que me dejaras\nen paz!",
  ["g3:081c3b6e"] = "FELI: Ahora somos más fuertes.\n¡Mucho más!",
  ["g3:081c3b99"] = "MATI: ¡Hoy no podrás con nosotras!",
  ["g3:081c3bb7"] = "Hola, ¿estás criando tus POKéMON\nen un buen sitio?",
  ["g3:081c3bf6"] = "¡Voy a alcanzar la victoria con mis\npropias manos!",
  ["g3:081c3c28"] = "¿Cuántas veces tengo que\ndecírtelo? ¡Estoy intentando\\lpintar! ¿Te quieres quitar de ahí?",
  ["g3:081c3c70"] = "No he avanzado nada...\nNo acabo de encontrar el ángulo\\ladecuado.",
  ["g3:081c3cb0"] = "¿Vas a darme otra oportunidad\npara medir mis habilidades contigo?",
  ["g3:081c3cf1"] = "Ya está casi acabada la piscina\nde mis POKéMON.\\pDeberías pasarte para echarle\nun vistazo.",
  ["g3:081c3d47"] = "No hay nadie que corra más rápido\nque yo.",
  ["g3:081c3d73"] = "¡Eh, vamos a pasar un buen rato\nluchando!",
  ["g3:081c3da2"] = "Soy el mayor de los HERMANOS\nPÁJARO.\\pAl que le encantaban los pájaros\npor los picos que tienen.",
  ["g3:081c3e0f"] = "Soy el mediano de los HERMANOS\nPÁJARO.\\pAl que le encantaban los pájaros\npor las alas que tienen.",
  ["g3:081c3e6a"] = "Soy el pequeño de los HERMANOS\nPÁJARO.\\pAl que le encantaban los pájaros\npor las plumas que tienen.",
  ["g3:081c3ed0"] = "Sigo sin tener suerte...\n¡A ver si luchando contigo entro\\len una buena racha!",
  ["g3:081c3f11"] = "Ufff... Ufff...\\pVengo nadando otra vez desde\nel PUERTO de ISLA EXTA sin parar.",
  ["g3:081c3f51"] = "Siempre apareces cuando estoy\ndándome un baño.",
  ["g3:081c3f7b"] = "ALI: ¡Vamos a echarnos otro\ncombate disfrutando de la brisa\\lmarina!",
  ["g3:081c3fb3"] = "ROS: Mi hermanita y yo somos\nmás fuertes que antes.",
  ["g3:081c3fe9"] = "¿Mmm?...\\pMe pareció haber elegido mi casa\ncon TELETRANSPORTE, pero\\lsiempre acabo en el mismo sitio.",
  ["g3:081c4028"] = "He llegado otra vez hasta aquí\ndejándome llevar por un agradable\\laroma.",
  ["g3:081c4057"] = "Estoy practicando en secreto\notra vez.",
  ["g3:081c407f"] = "¿Perdona? ¿Que no te gusta\nla gente que hace natación\\lcomo yo?\\p¡No fastidies!\n¡Vamos a luchar otra vez!",
  ["g3:081c40d9"] = "Ufff...\nMi chico está liado otra vez...",
  ["g3:081c40fa"] = "Oye, dime dónde están las\nmontañas de esta zona, anda.",
  ["g3:081c4138"] = "MARU: ¡Queridos POKéMON!\n¡Vamos a jugar otra vez!",
  ["g3:081c4166"] = "MÍA: ¡Queridos POKéMON!\n¡Vamos a luchar otra vez!",
  ["g3:081c4196"] = "Creo que en este mundo quedan\nmisterios por resolver.",
  ["g3:081c41d4"] = "Yo a ti te conozco...\n¿Qué te trae de nuevo hasta aquí?",
  ["g3:081c4210"] = "Dicen que hay misteriosas piedras\nen esta isla.\\p¿Has descubierto algo desde\nla última vez que nos vimos?",
  ["g3:081c4280"] = "¿Luchar contigo otra vez?\n¡Ahora mismo!",
  ["g3:081c42a0"] = "Yo me conozco bien toda esta\nzona.",
  ["g3:081c42d6"] = "He notado que te acercabas.",
  ["g3:081c42ee"] = "En alguna parte de esta isla,\nhay extraños POKéMON durmiendo.",
  ["g3:081c4327"] = "¡Voy a acabar contigo en un abrir\ny cerrar de ojos!\\p¡No te creas que por volver\nvas a ganarme!",
  ["g3:081c4374"] = "¡Hola, cara de bola!\n¿Tú no eras de mi club de fans?",
  ["g3:081c43ad"] = "Esta isla tiene una extensión muy\nparticular, no es fácil patrullar.",
  ["g3:081c43ec"] = "¡No perdono a quien se pasa con\nlos POKéMON!",
  ["g3:081c4416"] = "ELE: RUS y yo queremos luchar\nde nuevo contigo.",
  ["g3:081c444c"] = "RUS: Cuando estoy con ELE,\ncreo que no voy a perder nunca.\\lAhora lo veremos.",
  ["g3:081c4491"] = "Vamos a luchar de nuevo.\n¡Estoy realmente en forma!",
  ["g3:081c44cb"] = "Da igual que tengas los POKéMON\nmás fuertes...\\p¡Lo importante es saber cómo\ntratarlos!",
  ["g3:081c454e"] = "Yo protejo el medio ambiente\ny él me protege a mí.",
  ["g3:081c458e"] = "La última vez que nos vimos,\nllevabas también esos zapatos\\ltan llamativos.",
  ["g3:081c45c2"] = "¡Debes de ser más fuerte!\n¡Vamos a luchar, anda!",
  ["g3:081c45fb"] = "He recibido la mejor educación\npara tener la fuerza que tengo.\\p¡No pienso perder esta vez!\n¡Ni en broma!",
  ["g3:081c4662"] = "LINO: Mi adorada ABA, ¡vamos\na ganar!",
  ["g3:081c4699"] = "ABA: No defraudaré a mi maestro\nLINO. ¡Tenemos que ganar!",
  ["g3:081c46d3"] = "¿Has descubierto algo de esta\ncámara de piedra?",
  ["g3:081c470a"] = "Dicen que aquí dentro duerme\nun mítico POKéMON.",
  ["g3:081c4739"] = "Mi profe me está enseñando\nnuevas técnicas de pintura.",
  ["g3:081c476a"] = "Hoy, como complemento a la clase,\nhemos venido a visitar la cámara\\lotra vez.",
  ["sFemaleNameChoices[0]"] = "JORO",
  ["sFemaleNameChoices[1]"] = "GUEFO",
  ["sMaleNameChoices[0]"] = "JORO",
  ["sMaleNameChoices[1]"] = "GUEFO",
  ["sMaleNameChoices[2]"] = "FURIO",
  ["sMaleNameChoices[3]"] = "LLAMÍN",
  ["sMaleNameChoices[4]"] = "CANDEL",
  ["sRivalNameChoices[0]"] = "VERTE",
  ["sRivalNameChoices[1]"] = "BOSCO",
  ["sRivalNameChoices[2]"] = "FLOREN",
  ["sRivalNameChoices[3]"] = "SILVIO",
}
